(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("apollonius-argonautica-e", [{"sp": "HDR", "t": "Ἀργοναυτικά"}, {"sp": "HDR", "t": "Βιβλίον Αʹ", "st": "1"}, {"sp": "N", "t": "ἀρχόμενος σέο, Φοῖβε, παλαιγενέων κλέα φωτῶν<br>μνήσομαι, οἳ Πόντοιο κατὰ στόμα καὶ διὰ πέτρας<br>Κυανέας βασιλῆος ἐφημοσύνῃ Πελίαο<br>χρύσειον μετὰ κῶας ἐύζυγον ἤλασαν Ἀργώ.", "st": "1.1"}, {"sp": "N", "t": "τοίην γὰρ Πελίης φάτιν ἔκλυεν, ὥς μιν ὀπίσσω<br>μοῖρα μένει στυγερή, τοῦδ’ ἀνέρος, ὅντιν’ ἴδοιτο<br>δημόθεν οἰοπέδιλον, ὑπ’ ἐννεσίῃσι δαμῆναι.<br>δηρὸν δ’ οὐ μετέπειτα τεὴν κατὰ βάξιν Ἰήσων<br>χειμερίοιο ῥέεθρα κιὼν διὰ ποσσὶν Ἀναύρου<br>ἄλλο μὲν ἐξεσάωσεν ὑπ’ ἰλύος, ἄλλο δ’ ἔνερθεν<br>κάλλιπεν αὖθι πέδιλον ἐνισχόμενον προχοῇσιν.<br>ἵκετο δ’ ἐς Πελίην αὐτοσχεδὸν ἀντιβολήσων<br>εἰλαπίνης, ἣν πατρὶ Ποσειδάωνι καὶ ἄλλοις<br>ῥέζε θεοῖς, Ἥρης δὲ Πελασγίδος οὐκ ἀλέγιζεν.<br>αἶψα δὲ τόνγ’ ἐσιδὼν ἐφράσσατο, καί οἱ ἄεθλον<br>ἔντυε ναυτιλίης πολυκηδέος, ὄφρ’ ἐνὶ πόντῳ<br>ἠὲ καὶ ἀλλοδαποῖσι μετ’ ἀνδράσι νόστον ὀλέσσῃ.", "st": "1.5"}, {"sp": "N", "t": "νῆα μὲν οὖν οἱ πρόσθεν ἐπικλείουσιν ἀοιδοὶ<br>Ἄργον Ἀθηναίης καμέειν ὑποθημοσύνῃσιν.<br>νῦν δ’ ἂν ἐγὼ γενεήν τε καὶ οὔνομα μυθησαίμην<br>ἡρώων, δολιχῆς τε πόρους ἁλός, ὅσσα τ’ ἔρεξαν<br>πλαζόμενοι· Μοῦσαι δ’ ὑποφήτορες εἶεν ἀοιδῆς.", "st": "1.18"}, {"sp": "N", "t": "πρῶτά νυν Ὀρφῆος μνησώμεθα, τόν ῥά ποτ’ αὐτὴ<br>Καλλιόπη Θρήικι φατίζεται εὐνηθεῖσα<br>Οἰάγρῳ σκοπιῆς Πιμπληίδος ἄγχι τεκέσθαι<br>αὐτὰρ τόνγ’ ἐνέπουσιν ἀτειρέας οὔρεσι πέτρας<br>θέλξαι ἀοιδάων ἐνοπῇ ποταμῶν τε ῥέεθρα.<br>φηγοὶ δ’ ἀγριάδες, κείνης ἔτι σήματα μολπῆς,<br>ἀκτῆς Θρηικίης Ζώνης ἔπι τηλεθόωσαι<br>ἑξείης στιχόωσιν ἐπήτριμοι, ἃς ὅγ’ ἐπιπρὸ<br>θελγομένας φόρμιγγι κατήγαγε Πιερίηθεν.<br>Ὀρφέα μὲν δὴ τοῖον ἑῶν ἐπαρωγὸν ἀέθλων<br>Αἰσονίδης Χείρωνος ἐφημοσύνῃσι πιθήσας<br>δέξατο, Πιερίῃ Βιστωνίδι κοιρανέοντα.", "st": "1.23"}, {"sp": "N", "t": "ἤλυθε δ’ Ἀστερίων αὐτοσχεδόν, ὅν ῥα Κομήτης<br>γείνατο δινήεντος ἐφ’ ὕδασιν Ἀπιδανοῖο,<br>Πειρεσιὰς ὄρεος Φυλληίου ἀγχόθι ναίων,<br>ἔνθα μὲν Ἀπιδανός τε μέγας καὶ δῖος Ἐνιπεὺς<br>ἄμφω συμφορέονται, ἀπόπροθεν εἰς ἓν ἰόντες.", "st": "1.35"}, {"sp": "N", "t": "Λάρισαν δ’ ἐπὶ τοῖσι λιπὼν Πολύφημος ἵκανεν<br>Εἰλατίδης, ὃς πρὶν μὲν ἐρισθενέων Λαπιθάων,<br>ὁππότε Κενταύροις Λαπίθαι ἐπὶ θωρήσσοντο,<br>ὁπλότερος πολέμιζε· τότ’ αὖ βαρύθεσκέ οἱ ἤδη<br>γυῖα, μένεν δ’ ἔτι θυμὸς ἀρήιος, ὡς τὸ πάρος περ.", "st": "1.40"}, {"sp": "N", "t": "οὐδὲ μὲν Ἴφικλος Φυλάκῃ ἔνι δηρὸν ἔλειπτο,<br>μήτρως Αἰσονίδαο· κασιγνήτην γὰρ ὄπυιεν<br>Αἴσων Ἀλκιμέδην Φυλακηίδα· τῆς μιν ἀνώγει<br>πηοσύνη καὶ κῆδος ἐνικρινθῆναι ὁμίλῳ.", "st": "1.45"}, {"sp": "N", "t": "οὐδὲ Φεραῖς Ἄδμητος ἐυρρήνεσσιν ἀνάσσων<br>μίμνεν ὑπὸ σκοπιὴν ὄρεος Χαλκωδονίοιο.", "st": "1.49"}, {"sp": "N", "t": "οὐδ’ Ἀλόπῃ μίμνον πολυλήιοι Ἑρμείαο<br>υἱέες εὖ δεδαῶτε δόλους, Ἔρυτος καὶ Ἐχίων,<br>τοῖσι δ’ ἐπὶ τρίτατος γνωτὸς κίε νισσομένοισιν<br>Αἰθαλίδης· καὶ τὸν μὲν ἐπ’ Ἀμφρυσσοῖο ῥοῇσιν<br>Μυρμιδόνος κούρη Φθιὰς τέκεν Εὐπολέμεια·<br>τὼ δ’ αὖτ’ ἐκγεγάτην Μενετηίδος Ἀντιανείρης.", "st": "1.51"}, {"sp": "N", "t": "ἤλυθε δ’ ἀφνειὴν προλιπὼν Γυρτῶνα Κόρωνος<br>Καινεΐδης, ἐσθλὸς μέν, ἑοῦ δ’ οὐ πατρὸς ἀμείνων.<br>Καινέα γὰρ ζῶόν περ ἔτι κλείουσιν ἀοιδοὶ<br>Κενταύροισιν ὀλέσθαι, ὅτε σφέας οἶος ἀπ’ ἄλλων<br>ἤλασ’ ἀριστήων· οἱ δ’ ἔμπαλιν ὁρμηθέντες<br>οὔτε μιν ἐγκλῖναι προτέρω σθένον, οὔτε δαΐξαι·<br>ἀλλ’ ἄρρηκτος ἄκαμπτος ἐδύσετο νειόθι γαίης,<br>θεινόμενος στιβαρῇσι καταΐγδην ἐλάτῃσιν.", "st": "1.57"}, {"sp": "N", "t": "ἤλυθε δ’ αὖ Μόψος Τιταρήσιος, ὃν περὶ πάντων<br>Λητοΐδης ἐδίδαξε θεοπροπίας οἰωνῶν·<br>ἠδὲ καὶ Εὐρυδάμας Κτιμένου πάις· ἄγχι δὲ λίμνης<br>Ξυνιάδος Κτιμένην Δολοπηίδα ναιετάασκεν.", "st": "1.65"}, {"sp": "N", "t": "καὶ μὴν Ἄκτωρ υἷα Μενοίτιον ἐξ Ὀπόεντος<br>ὦρσεν, ἀριστήεσσι σὺν ἀνδράσιν ὄφρα νέοιτο.", "st": "1.69"}, {"sp": "N", "t": "εἵπετο δ’ Εὐρυτίων τε καὶ ἀλκήεις Ἐρυβώτης,<br>υἷες ὁ μὲν Τελέοντος, ὁ δ’ Ἴρου Ἀκτορίδαο·<br>ἤτοι ὁ μὲν Τελέοντος ἐυκλειὴς Ἐρυβώτης,<br>Ἴρου δ’ Εὐρυτίων. σὺν καὶ τρίτος ἦεν Ὀιλεύς,<br>ἔξοχος ἠνορέην καὶ ἐπαΐξαι μετόπισθεν<br>εὖ δεδαὼς δῄοισιν, ὅτε κλίνωσι φάλαγγας.", "st": "1.71"}, {"sp": "N", "t": "αὐτὰρ ἀπ’ Εὐβοίης Κάνθος κίε, τόν ῥα Κάνηθος<br>πέμπεν Ἀβαντιάδης λελιημένον· οὐ μὲν ἔμελλεν<br>νοστήσειν Κήρινθον ὑπότροπος. αἶσα γὰρ ἦεν<br>αὐτὸν ὁμῶς Μόψον τε δαήμονα μαντοσυνάων<br>πλαγχθέντας Λιβύης ἐνὶ πείρασι δῃωθῆναι,<br>ὡς οὐκ ἀνθρώποισι κακὸν μήκιστον ἐπαυρεῖν,<br>ὁππότε κἀκείνους Λιβύῃ ἔνι ταρχύσαντο,<br>τόσσον ἑκὰς Κόλχων, ὅσσον τέ περ ἠελίοιο<br>μεσσηγὺς δύσιές τε καὶ ἀντολαὶ εἰσορόωνται.", "st": "1.77"}, {"sp": "N", "t": "τῷ δ’ ἄρ’ ἐπὶ Κλυτίος τε καὶ Ἴφιτος ἠγερέθοντο,<br>Οἰχαλίης ἐπίουροι, ἀπηνέος Εὐρύτου υἷες,<br>Εὐρύτου, ᾧ πόρε τόξον Ἑκηβόλος· οὐδ’ ἀπόνητο<br>δωτίνης· αὐτῷ γὰρ ἑκὼν ἐρίδηνε δοτῆρι.", "st": "1.86"}, {"sp": "N", "t": "τοῖσι δ’ ἐπ’ Αἰακίδαι μετεκίαθον· οὐ μὲν ἅμ’ ἄμφω,<br>οὐδ’ ὁμόθεν· νόσφιν γὰρ ἀλευάμενοι κατένασθεν<br>Αἰγίνης, ὅτε Φῶκον ἀδελφεὸν ἐξενάριξαν<br>ἀφραδίῃ. Τελαμὼν μὲν ἐν Ἀτθίδι νάσσατο νήσῳ·<br>Πηλεὺς δὲ Φθίῃ ἐνὶ δώματα ναῖε λιασθείς.", "st": "1.90"}, {"sp": "N", "t": "τοῖς δ’ ἐπὶ Κεκροπίηθεν ἀρήιος ἤλυθε Βούτης,<br>παῖς ἀγαθοῦ Τελέοντος, ἐυμμελίης τε Φάληρος.<br>Ἄλκων μιν προέηκε πατὴρ ἑός· οὐ μὲν ἔτ’ ἄλλους<br>γήραος υἷας ἔχεν βιότοιό τε κηδεμονῆας.<br>ἀλλά ἑ τηλύγετόν περ ὁμῶς καὶ μοῦνον ἐόντα<br>πέμπεν, ἵνα θρασέεσσι μεταπρέποι ἡρώεσσιν.<br>Θησέα δ’, ὃς περὶ πάντας Ἐρεχθεΐδας ἐκέκαστο,<br>Ταιναρίην ἀίδηλος ὑπὸ χθόνα δεσμὸς ἔρυκεν,<br>Πειρίθῳ ἑσπόμενον κοινὴν ὁδόν· ἦ τέ κεν ἄμφω<br>ῥηίτερον καμάτοιο τέλος πάντεσσιν ἔθεντο.", "st": "1.95"}, {"sp": "N", "t": "Τῖφυς δ’ Ἁγνιάδης Σιφαέα κάλλιπε δῆμον<br>Θεσπιέων, ἐσθλὸς μὲν ὀρινόμενον προδαῆναι<br>κῦμ’ ἁλὸς εὐρείης, ἐσθλὸς δ’ ἀνέμοιο θυέλλας<br>καὶ πλόον ἠελίῳ τε καὶ ἀστέρι τεκμήρασθαι.<br>αὐτή μιν Τριτωνὶς ἀριστήων ἐς ὅμιλον<br>ὦρσεν Ἀθηναίη, μετὰ δ’ ἤλυθεν ἐλδομένοισιν.<br>αὐτὴ γὰρ καὶ νῆα θοὴν κάμε· σὺν δέ οἱ Ἄργος<br>τεῦξεν Ἀρεστορίδης κείνης ὑποθημοσύνῃσιν.<br>τῶ καὶ πασάων προφερεστάτη ἔπλετο νηῶν,<br>ὅσσαι ὑπ’ εἰρεσίῃσιν ἐπειρήσαντο θαλάσσης.", "st": "1.105"}, {"sp": "N", "t": "Φλίας δ’ αὖτ’ ἐπὶ τοῖσιν Ἀραιθυρέηθεν ἵκανεν,<br>ἔνθ’ ἀφνειὸς ἔναιε Διωνύσοιο ἕκητι,<br>πατρὸς ἑοῦ, πηγῇσιν ἐφέστιος Ἀσωποῖο.", "st": "1.115"}, {"sp": "N", "t": "Ἀργόθεν αὖ Ταλαὸς καὶ Ἀρήιος, υἷε Βίαντος,<br>ἤλυθον ἴφθιμός τε Λεώδοκος, οὓς τέκε Πηρὼ<br>Νηληίς· τῆς δ’ ἀμφὶ δύην ἐμόγησε βαρεῖαν<br>Αἰολίδης σταθμοῖσιν ἐν Ἰφίκλοιο Μελάμπους.", "st": "1.118"}, {"sp": "N", "t": "οὐδὲ μὲν οὐδὲ βίην κρατερόφρονος Ἡρακλῆος<br>πευθόμεθ’ Αἰσονίδαο λιλαιομένου ἀθερίξαι.<br>ἀλλ’ ἐπεὶ ἄιε βάξιν ἀγειρομένων ἡρώων,<br>νεῖον ἀπ’ Ἀρκαδίης Λυρκήιον Ἄργος ἀμείψας<br>τὴν ὁδόν, ᾗ ζωὸν φέρε κάπριον, ὅς ῥ’ ἐνὶ βήσσῃς<br>φέρβετο Λαμπείης, Ἐρυμάνθιον ἂμ μέγα τῖφος,<br>τὸν μὲν ἐνὶ πρώτῃσι Μυκηναίων ἀγορῇσιν<br>δεσμοῖς ἰλλόμενον μεγάλων ἀπεθήκατο νώτων·<br>αὐτὸς δ’ ᾗ ἰότητι παρὲκ νόον Εὐρυσθῆος<br>ὡρμήθη· σὺν καί οἱ Ὕλας κίεν, ἐσθλὸς ὀπάων,<br>πρωθήβης, ἰῶν τε φορεὺς φύλακός τε βιοῖο.", "st": "1.122"}, {"sp": "N", "t": "τῷ δ’ ἐπὶ δὴ θείοιο κίεν Δαναοῖο γενέθλη,<br>Ναύπλιος. ἦ γὰρ ἔην Κλυτονήου Ναυβολίδαο·<br>Ναύβολος αὖ Λέρνου· Λέρνον γε μὲν ἴδμεν ἐόντα<br>Προίτου Ναυπλιάδαο· Ποσειδάωνι δὲ κούρη.<br>πρίν ποτ’ Ἀμυμώνη Δαναῒς τέκεν εὐνηθεῖσα<br>Ναύπλιον, ὃς περὶ πάντας ἐκαίνυτο ναυτιλίῃσιν.", "st": "1.133"}, {"sp": "N", "t": "Ἴδμων δ’ ὑστάτιος μετεκίαθεν, ὅσσοι ἔναιον<br>Ἄργος, ἐπεὶ δεδαὼς τὸν ἑὸν μόρον οἰωνοῖσιν<br>ἤιε, μή οἱ δῆμος ἐυκλείης ἀγάσαιτο.<br>οὐ μὲν ὅγ’ ἦεν Ἄβαντος ἐτήτυμον, ἀλλά μιν αὐτὸς<br>γείνατο κυδαλίμοις ἐναρίθμιον Αἰολίδῃσιν<br>Λητοΐδης· αὐτὸς δὲ θεοπροπίας ἐδίδαξεν<br>οἰωνούς τ’ ἀλέγειν ἠδ’ ἔμπυρα σήματ’ ἰδέσθαι.", "st": "1.139"}, {"sp": "N", "t": "καὶ μὴν Αἰτωλὶς κρατερὸν Πολυδεύκεα Λήδη<br>Κάστορά τ’ ὠκυπόδων ὦρσεν δεδαημένον ἵππων<br>Σπάρτηθεν· τοὺς δ’ ἥγε δόμοις ἔνι Τυνδαρέοιο<br>τηλυγέτους ὠδῖνι μιῇ τέκεν· οὐδ’ ἀπίθησεν<br>νισσομένοις· Ζηνὸς γὰρ ἐπάξια μήδετο λέκτρων.", "st": "1.146"}, {"sp": "N", "t": "οἵ τ’ Ἀφαρητιάδαι Λυγκεὺς καὶ ὑπέρβιος Ἴδας<br>Ἀρήνηθεν ἔβαν, μεγάλῃ περιθαρσέες ἀλκῇ<br>ἀμφότεροι· Λυγκεὺς δὲ καὶ ὀξυτάτοις ἐκέκαστο<br>ὄμμασιν, εἰ ἐτεόν γε πέλει κλέος, ἀνέρα κεῖνον<br>ῥηιδίως καὶ νέρθε κατὰ χθονὸς αὐγάζεσθαι.", "st": "1.151"}, {"sp": "N", "t": "σὺν δὲ Περικλύμενος Νηλήιος ὦρτο νέεσθαι,<br>πρεσβύτατος παίδων, ὅσσοι Πύλῳ ἐξεγένοντο<br>Νηλῆος θείοιο· Ποσειδάων δέ οἱ ἀλκὴν<br>δῶκεν ἀπειρεσίην ἠδ’ ὅττι κεν ἀρήσαιτο<br>μαρνάμενος, τὸ πέλεσθαι ἐνὶ ξυνοχῇ πολέμοιο.", "st": "1.156"}, {"sp": "N", "t": "καὶ μὴν Ἀμφιδάμας Κηφεύς τ’ ἴσαν Ἀρκαδίηθεν,<br>οἳ Τεγέην καὶ κλῆρον Ἀφειδάντειον ἔναιον,<br>υἷε δύω Ἀλεοῦ· τρίτατός γε μὲν ἕσπετ’ ἰοῦσιν<br>Ἀγκαῖος, τὸν μέν ῥα πατὴρ Λυκόοργος ἔπεμπεν,<br>τῶν ἄμφω γνωτὸς προγενέστερος. ἀλλ’ ὁ μὲν ἤδη<br>γηράσκοντ’ Ἀλεὸν λίπετ’ ἂμ πόλιν ὄφρα κομίζοι,<br>παῖδα δ’ ἑὸν σφετέροισι κασιγνήτοισιν ὄπασσεν.<br>βῆ δ’ ὅγε Μαιναλίης ἄρκτου δέρος, ἀμφίτομόν τε<br>δεξιτερῇ πάλλων πέλεκυν μέγαν. ἔντεα γάρ οἱ<br>πατροπάτωρ Ἀλεὸς μυχάτῃ ἐνέκρυψε καλιῇ,<br>αἴ κέν πως ἔτι καὶ τὸν ἐρητύσειε νέεσθαι.", "st": "1.161"}, {"sp": "N", "t": "βῆ δὲ καὶ Αὐγείης, ὃν δὴ φάτις Ἠελίοιο<br>ἔμμεναι· Ἠλείοισι δ’ ὅγ’ ἀνδράσιν ἐμβασίλευεν,<br>ὄλβῳ κυδιόων· μέγα δ’ ἵετο Κολχίδα γαῖαν<br>αὐτόν τ’ Αἰήτην ἰδέειν σημάντορα Κόλχων.", "st": "1.172"}, {"sp": "N", "t": "Ἀστέριος δὲ καὶ Ἀμφίων Ὑπερασίου υἷες<br>Πελλήνης ἀφίκανον Ἀχαιίδος, ἥν ποτε Πέλλης<br>πατροπάτωρ ἐπόλισσεν ἐπ’ ὀφρύσιν Αἰγιαλοῖο.", "st": "1.176"}, {"sp": "N", "t": "Ταίναρον αὖτ’ ἐπὶ τοῖσι λιπὼν Εὔφημος ἵκανεν,<br>τόν ῥα Ποσειδάωνι ποδωκηέστατον ἄλλων<br>Εὐρώπη Τιτυοῖο μεγασθενέος τέκε κούρη.<br>κεῖνος ἀνὴρ καὶ πόντου ἐπὶ γλαυκοῖο θέεσκεν<br>οἴδματος, οὐδὲ θοοὺς βάπτεν πόδας, ἀλλ’ ὅσον ἄκροις<br>ἴχνεσι τεγγόμενος διερῇ πεφόρητο κελεύθῳ.", "st": "1.179"}, {"sp": "N", "t": "καὶ δ’ ἄλλω δύο παῖδε Ποσειδάωνος ἵκοντο·<br>ἤτοι ὁ μὲν πτολίεθρον ἀγαυοῦ Μιλήτοιο<br>νοσφισθεὶς Ἐργῖνος, ὁ δ’ Ἰμβρασίης ἕδος Ἥρης,<br>παρθενίην, Ἀγκαῖος ὑπέρβιος· ἴστορε δ’ ἄμφω<br>ἠμὲν ναυτιλίης ἠδ’ ἄρεος εὐχετόωντο.", "st": "1.185"}, {"sp": "N", "t": "Οἰνεΐδης δ’ ἐπὶ τοῖσιν ἀφορμηθεὶς Καλυδῶνος<br>ἀλκήεις Μελέαγρος ἀνήλυθε, Λαοκόων τε,<br>Λαοκόων Οἰνῆος ἀδελφεός, οὐ μὲν ἰῆς γε<br>μητέρος· ἀλλά ἑ θῆσσα γυνὴ τέκε· τὸν μὲν ἄρ’ Οἰνεὺς<br>ἤδη γηραλέον κοσμήτορα παιδὸς ἴαλλεν·<br>ὧδ’ ἔτι κουρίζων περιθαρσέα δῦνεν ὅμιλον<br>ἡρώων. τοῦ δ’ οὔτιν’ ὑπέρτερον ἄλλον ὀίω,<br>νόσφιν γ’ Ἡρακλῆος, ἐπελθέμεν, εἴ κ’ ἔτι μοῦνον<br>αὖθι μένων λυκάβαντα μετετράφη Αἰτωλοῖσιν.<br>καὶ μήν οἱ μήτρως αὐτὴν ὁδόν, εὖ μὲν ἄκοντι,<br>εὖ δὲ καὶ ἐν σταδίῃ δεδαημένος ἀντιφέρεσθαι,<br>Θεστιάδης Ἴφικλος ἐφωμάρτησε κιόντι.", "st": "1.190"}, {"sp": "N", "t": "σὺν δὲ Παλαιμόνιος Λέρνου πάις Ὠλενίοιο,<br>Λέρνου ἐπίκλησιν, γενεήν γε μὲν Ἡφαίστοιο·<br>τούνεκ’ ἔην πόδα σιφλός· ἀτὰρ δέμας οὔ κέ τις ἔτλη<br>ἠνορέην τ’ ὀνόσασθαι, ὃ καὶ μεταρίθμιος ἦεν<br>πᾶσιν ἀριστήεσσιν, Ἰήσονι κῦδος ἀέξων.", "st": "1.202"}, {"sp": "N", "t": "ἐκ δ’ ἄρα Φωκήων κίεν Ἴφιτος Ὀρνυτίδαο<br>Ναυβόλου ἐκγεγαώς· ξεῖνος δέ οἱ ἔσκε πάροιθεν,<br>ἦμος ἔβη Πυθώδε θεοπροπίας ἐρεείνων<br>ναυτιλίης· τόθι γάρ μιν ἑοῖς ὑπέδεκτο δόμοισιν.", "st": "1.207"}, {"sp": "N", "t": "Ζήτης αὖ Κάλαΐς τε Βορήιοι υἷες ἵκοντο,<br>οὕς ποτ’ Ἐρεχθηὶς Βορέῃ τέκεν Ὠρείθυια<br>ἐσχατιῇ Θρῄκης δυσχειμέρου· ἔνθ’ ἄρα τήνγε<br>Θρηίκιος Βορέης ἀνερέψατο Κεκροπίηθεν<br>Ἰλισσοῦ προπάροιθε χορῷ ἔνι δινεύουσαν.<br>καί μιν ἄγων ἕκαθεν, Σαρπηδονίην ὅθι πέτρην<br>κλείουσιν, ποταμοῖο παρὰ ῥόον Ἐργίνοιο,<br>λυγαίοις ἐδάμασσε περὶ νεφέεσσι καλύψας.<br>τὼ μὲν ἐπ’ ἀκροτάτοισι ποδῶν ἑκάτερθεν ἐρεμνὰς<br>σεῖον ἀειρομένω πτέρυγας, μέγα θάμβος ἰδέσθαι,<br>χρυσείαις φολίδεσσι διαυγέας· ἀμφὶ δὲ νώτοις<br>κράατος ἐξ ὑπάτοιο καὶ αὐχένος ἔνθα καὶ ἔνθα<br>κυάνεαι δονέοντο μετὰ πνοιῇσιν ἔθειραι.", "st": "1.211"}, {"sp": "N", "t": "οὐδὲ μὲν οὐδ’ αὐτοῖο πάις μενέαινεν Ἄκαστος<br>ἰφθίμου Πελίαο δόμοις ἔνι πατρὸς ἑῆος<br>μιμνάζειν, Ἄργος τε θεᾶς ὑποεργὸς Ἀθήνης·<br>ἀλλ’ ἄρα καὶ τὼ μέλλον ἐνικρινθῆναι ὁμίλῳ.", "st": "1.224"}, {"sp": "N", "t": "τόσσοι ἄρ’ Αἰσονίδῃ συμμήστορες ἠγερέθοντο.<br>τοὺς μὲν ἀριστῆας Μινύας περιναιετάοντες<br>κίκλησκον μάλα πάντας, ἐπεὶ Μινύαο θυγατρῶν<br>οἱ πλεῖστοι καὶ ἄριστοι ἀφ’ αἵματος εὐχετόωντο<br>ἔμμεναι· ὧς δὲ καὶ αὐτὸν Ἰήσονα γείνατο μήτηρ<br>Ἀλκιμέδη, Κλυμένης Μινυηίδος ἐκγεγαυῖα.", "st": "1.228"}, {"sp": "N", "t": "αὐτὰρ ἐπεὶ δμώεσσιν ἐπαρτέα πάντ’ ἐτέτυκτο,<br>ὅσσα περ ἐντύνονται ἐπαρτέες ἔνδοθι νῆες,<br>εὖτ’ ἂν ἄγῃ χρέος ἄνδρας ὑπεὶρ ἅλα ναυτίλλεσθαι,<br>δὴ τότ’ ἴσαν μετὰ νῆα δι’ ἄστεος, ἔνθα περ ἀκταὶ<br>κλείονται Παγασαὶ Μαγνήτιδες· ἀμφὶ δὲ λαῶν<br>πληθὺς σπερχομένων ἄμυδις θέεν· οἱ δὲ φαεινοὶ<br>ἀστέρες ὣς νεφέεσσι μετέπρεπον· ὧδε δ’ ἕκαστος<br>ἔννεπεν εἰσορόων σὺν τεύχεσιν ἀίσσοντας·", "st": "1.234"}, {"sp": "N", "t": "“Ζεῦ ἄνα, τίς Πελίαο νόος; πόθι τόσσον ὅμιλον<br>ἡρώων γαίης Παναχαιίδος ἔκτοθι βάλλει;<br>αὐτῆμάρ κε δόμους ὀλοῷ πυρὶ δῃώσειαν<br>Αἰήτεω, ὅτε μή σφιν ἑκὼν δέρος ἐγγυαλίξῃ.<br>ἀλλ’ οὐ φυκτὰ κέλευθα, πόνος δ’ ἄπρηκτος ἰοῦσιν.”", "st": "1.242"}, {"sp": "N", "t": "ὧς φάσαν ἔνθα καὶ ἔνθα κατὰ πτόλιν· αἱ δὲ γυναῖκες<br>πολλὰ μάλ’ ἀθανάτοισιν ἐς αἰθέρα χεῖρας ἄειρον,<br>εὐχόμεναι νόστοιο τέλος θυμηδὲς ὀπάσσαι.<br>ἄλλη δ’ εἰς ἑτέρην ὀλοφύρετο δακρυχέουσα·", "st": "1.247"}, {"sp": "N", "t": "“δειλὴ Ἀλκιμέδη, καὶ σοὶ κακὸν ὀψέ περ ἔμπης<br>ἤλυθεν, οὐδ’ ἐτέλεσσας ἐπ’ ἀγλαΐῃ βιότοιο.<br>Αἴσων αὖ μέγα δή τι δυσάμμορος. ἦ τέ οἱ ἦεν<br>βέλτερον, εἰ τὸ πάροιθεν ἐνὶ κτερέεσσιν ἐλυσθεὶς<br>νειόθι γαίης κεῖτο, κακῶν ἔτι νῆις ἀέθλων.<br>ὡς ὄφελεν καὶ Φρίξον, ὅτ’ ὤλετο παρθένος Ἕλλη,<br>κῦμα μέλαν κριῷ ἅμ’ ἐπικλύσαι· ἀλλὰ καὶ αὐδὴν<br>ἀνδρομέην προέηκε κακὸν τέρας, ὥς κεν ἀνίας<br>Ἀλκιμέδῃ μετόπισθε καὶ ἄλγεα μυρία θείη.”", "st": "1.251"}, {"sp": "N", "t": "αἱ μὲν ἄρ’ ὧς ἀγόρευον ἐπὶ προμολῇσι κιόντων.<br>ἤδη δὲ δμῶές τε πολεῖς δμωαί τ’ ἀγέροντο·<br>μήτηρ δ’ ἀμφ’ αὐτὸν βεβολημένη. ὀξὺ δ’ ἑκάστην<br>δῦνεν ἄχος· σὺν δέ σφι πατὴρ ὀλοῷ ὑπὸ γήραι<br>ἐντυπὰς ἐν λεχέεσσι καλυψάμενος γοάασκεν.<br>αὐτὰρ ὁ τῶν μὲν ἔπειτα κατεπρήυνεν ἀνίας<br>θαρσύνων, δμώεσσι δ’ ἀρήια τεύχε’ ἀείρειν<br>πέφραδεν· οἱ δέ τε σῖγα κατηφέες ἠείροντο.<br>μήτηρ δ’ ὡς τὰ πρῶτ’ ἐπεχεύατο πήχεε παιδί,<br>ὧς ἔχετο κλαίουσ’ ἀδινώτερον, ἠύτε κούρη<br>οἰόθεν ἀσπασίως πολιὴν τροφὸν ἀμφιπεσοῦσα<br>μύρεται, ᾗ οὐκ εἰσὶν ἔτ’ ἄλλοι κηδεμονῆες,<br>ἀλλ’ ὑπὸ μητρυιῇ βίοτον βαρὺν ἡγηλάζει·<br>καί ἑ νέον πολέεσσιν ὀνείδεσιν ἐστυφέλιξεν,<br>τῇ δέ τ’ ὀδυρομένῃ δέδεται κέαρ ἔνδοθεν ἄτῃ,<br>οὐδ’ ἔχει ἐκφλύξαι τόσσον γόον, ὅσσον ὀρεχθεῖ·<br>ὧς ἀδινὸν κλαίεσκεν ἑὸν παῖδ’ ἀγκὰς ἔχουσα<br>Ἀλκιμέδη, καὶ τοῖον ἔπος φάτο κηδοσύνῃσιν·", "st": "1.260"}, {"sp": "N", "t": "“αἴθ’ ὄφελον κεῖν’ ἦμαρ, ὅτ’ ἐξειπόντος ἄκουσα<br>δειλὴ ἐγὼ Πελίαο κακὴν βασιλῆος ἐφετμήν,<br>αὐτίκ’ ἀπὸ ψυχὴν μεθέμεν, κηδέων τε λαθέσθαι,<br>ὄφρ’ αὐτός με τεῇσι φίλαις ταρχύσαο χερσίν,<br>τέκνον ἐμόν· τὸ γὰρ οἶον ἔην ἔτι λοιπὸν ἐέλδωρ<br>ἐκ σέθεν, ἄλλα δὲ πάντα πάλαι θρεπτήρια πέσσω.<br>νῦν γε μὲν ἡ τὸ πάροιθεν Ἀχαιιάδεσσιν ἀγητὴ<br>δμωὶς ὅπως κενεοῖσι λελείψομαι ἐν μεγάροισιν,<br>σεῖο πόθῳ μινύθουσα δυσάμμορος, ᾧ ἔπι πολλὴν<br>ἀγλαΐην καὶ κῦδος ἔχον πάρος, ᾧ ἔπι μούνῳ<br>μίτρην πρῶτον ἔλυσα καὶ ὕστατον. ἔξοχα γάρ μοι<br>Εἰλείθυια θεὰ πολέος ἐμέγηρε τόκοιο.<br>ᾤ μοι ἐμῆς ἄτης· τὸ μὲν οὐδ’ ὅσον, οὐδ’ ἐν ὀνείρῳ<br>ὠισάμην, εἰ Φρίξος ἐμοὶ κακὸν ἔσσετ’ ἀλύξας.”", "st": "1.278"}, {"sp": "N", "t": "ὧς ἥγε στενάχουσα κινύρετο· ταὶ δὲ γυναῖκες<br>ἀμφίπολοι γοάασκον ἐπισταδόν· αὐτὰρ ὁ τήνγε<br>μειλιχίοις ἐπέεσσι παρηγορέων προσέειπεν·", "st": "1.292"}, {"sp": "N", "t": "“μή μοι λευγαλέας ἐνιβάλλεο, μῆτερ, ἀνίας<br>ὧδε λίην, ἐπεὶ οὐ μὲν ἐρητύσεις κακότητος<br>δάκρυσιν, ἀλλ’ ἔτι κεν καὶ ἐπ’ ἄλγεσιν ἄλγος ἄροιο.<br>πήματα γάρ τ’ ἀίδηλα θεοὶ θνητοῖσι νέμουσιν,<br>τῶν μοῖραν κατὰ θυμὸν ἀνιάζουσά περ ἔμπης<br>τλῆθι φέρειν· θάρσει δὲ συνημοσύνῃσιν Ἀθήνης,<br>ἠδὲ θεοπροπίοισιν, ἐπεὶ μάλα δεξιὰ Φοῖβος<br>ἔχρη, ἀτὰρ μετέπειτά γ’ ἀριστήων ἐπαρωγῇ.<br>ἀλλὰ σὺ μὲν νῦν αὖθι μετ’ ἀμφιπόλοισιν ἕκηλος<br>μίμνε δόμοις, μηδ’ ὄρνις ἀεικελίη πέλε νηί·<br>κεῖσε δ’ ὁμαρτήσουσιν ἔται δμῶές τε κιόντι.”", "st": "1.295"}, {"sp": "N", "t": "ἦ, καὶ ὁ μὲν προτέρωσε δόμων ἐξῶρτο νέεσθαι.<br>οἷος δ’ ἐκ νηοῖο θυώδεος εἶσιν Ἀπόλλων<br>Δῆλον ἀν’ ἠγαθέην, ἠὲ Κλάρον, ἢ ὅγε Πυθώ,<br>ἢ Λυκίην εὐρεῖαν, ἐπὶ Ξάνθοιο ῥοῇσιν,<br>τοῖος ἀνὰ πληθὺν δήμου κίεν· ὦρτο δ’ ἀυτὴ<br>κεκλομένων ἄμυδις. τῷ δὲ ξύμβλητο γεραιὴ<br>Ἰφιὰς Ἀρτέμιδος πολιηόχου ἀρήτειρα,<br>καί μιν δεξιτερῆς χειρὸς κύσεν, οὐδέ τι φάσθαι<br>ἔμπης ἱεμένη δύνατο, προθέοντος ὁμίλου·<br>ἀλλ’ ἡ μὲν λίπετ’ αὖθι παρακλιδόν, οἷα γεραιὴ<br>ὁπλοτέρων, ὁ δὲ πολλὸν ἀποπλαγχθεὶς ἐλιάσθη.", "st": "1.306"}, {"sp": "N", "t": "αὐτὰρ ἐπεί ῥα πόληος ἐυδμήτους λίπ’ ἀγυιάς,<br>ἀκτὴν δ’ ἵκανεν Παγασηίδα, τῇ μιν ἑταῖροι<br>δειδέχατ’, Ἀργῴῃ ἄμυδις παρὰ νηὶ μένοντες.<br>στῆ δ’ ἄρ’ ἐπὶ προμολῇς· οἱ δ’ ἀντίοι ἠγερέθοντο.<br>ἐς δ’ ἐνόησαν Ἄκαστον ὁμῶς Ἄργον τε πόληος<br>νόσφι καταβλώσκοντας, ἐθάμβησαν δ’ ἐσιδόντες<br>πασσυδίῃ Πελίαο παρὲκ νόον ἰθύοντας.<br>δέρμα δ’ ὁ μὲν ταύροιο ποδηνεκὲς ἀμφέχετ’ ὤμους<br>Ἄργος Ἀρεστορίδης λάχνῃ μέλαν· αὐτὰρ ὁ καλὴν<br>δίπλακα, τήν οἱ ὄπασσε κασιγνήτη Πελόπεια.<br>ἀλλ’ ἔμπης τὼ μέν τε διεξερέεσθαι ἕκαστα<br>ἔσχετο· τοὺς δ’ ἀγορήνδε συνεδριάασθαι ἄνωγεν.<br>αὐτοῦ δ’ ἰλλομένοις ἐπὶ λαίφεσιν, ἠδὲ καὶ ἱστῷ<br>κεκλιμένῳ μάλα πάντες ἐπισχερὼ ἑδριόωντο.<br>τοῖσιν δ’ Αἴσονος υἱὸς ἐυφρονέων μετέειπεν·", "st": "1.317"}, {"sp": "N", "t": "“ἄλλα μὲν ὅσσα τε νηὶ ἐφοπλίσσασθαι ἔοικεν<br>—πάντα γὰρ εὖ κατὰ κόσμον—ἐπαρτέα κεῖται ἰοῦσιν.<br>τῶ οὐκ ἂν δηναιὸν ἐχοίμεθα τοῖο ἕκητι<br>ναυτιλίης, ὅτε μοῦνον ἐπιπνεύσουσιν ἀῆται.<br>ἀλλά, φίλοι,—ξυνὸς γὰρ ἐς Ἑλλάδα νόστος ὀπίσσω,<br>ξυναὶ δ’ ἄμμι πέλονται ἐς Αἰήταο κέλευθοι—<br>τούνεκα νῦν τὸν ἄριστον ἀφειδήσαντες ἕλεσθε<br>ὄρχαμον ἡμείων, ᾧ κεν τὰ ἕκαστα μέλοιτο,<br>νείκεα συνθεσίας τε μετὰ ξείνοισι βαλέσθαι.”", "st": "1.332"}, {"sp": "N", "t": "ὧς φάτο· πάπτηναν δὲ νέοι θρασὺν Ἡρακλῆα<br>ἥμενον ἐν μέσσοισι· μιῇ δέ ἑ πάντες ἀυτῇ<br>σημαίνειν ἐπέτελλον· ὁ δ’ αὐτόθεν, ἔνθα περ ἧστο,<br>δεξιτερὴν ἀνὰ χεῖρα τανύσσατο φώνησέν τε·", "st": "1.341"}, {"sp": "N", "t": "“μήτις ἐμοὶ τόδε κῦδος ὀπαζέτω. οὐ γὰρ ἔγωγε<br>πείσομαι· ὥστε καὶ ἄλλον ἀναστήσεσθαι ἐρύξω.<br>αὐτός, ὅτις ξυνάγειρε, καὶ ἀρχεύοι ὁμάδοιο.”", "st": "1.345"}, {"sp": "N", "t": "ἦ ῥα μέγα φρονέων, ἐπὶ δ’ ᾔνεον, ὡς ἐκέλευεν<br>Ἡρακλέης· ἀνὰ δ’ αὐτὸς ἀρήιος ὤρνυτ’ Ἰήσων<br>γηθόσυνος, καὶ τοῖα λιλαιομένοις ἀγόρευεν·", "st": "1.348"}, {"sp": "N", "t": "“εἰ μὲν δή μοι κῦδος ἐπιτρωπᾶτε μέλεσθαι,<br>μηκέτ’ ἔπειθ’, ὡς καὶ πρίν, ἐρητύοιτο κέλευθα.<br>νῦν γε μὲν ἤδη Φοῖβον ἀρεσσάμενοι θυέεσσιν<br>δαῖτ’ ἐντυνώμεσθα παρασχεδόν. ὄφρα δ’ ἴωσιν<br>δμῶες ἐμοὶ σταθμῶν σημάντορες, οἷσι μέμηλεν<br>δεῦρο βόας ἀγέληθεν ἐὺ κρίναντας ἐλάσσαι,<br>τόφρα κε νῆ’ ἐρύσαιμεν ἔσω ἁλός, ὅπλα δὲ πάντα<br>ἐνθέμενοι πεπάλαχθε κατὰ κληῖδας ἐρετμά.<br>τείως δ’ αὖ καὶ βωμὸν ἐπάκτιον Ἐμβασίοιο<br>θείομεν Ἀπόλλωνος, ὅ μοι χρείων ὑπέδεκτο<br>σημανέειν δείξειν τε πόρους ἁλός, εἴ κε θυηλαῖς<br>οὗ ἕθεν ἐξάρχωμαι ἀεθλεύων βασιλῆι.”", "st": "1.351"}, {"sp": "N", "t": "ἦ ῥα, καὶ εἰς ἔργον πρῶτος τράπεθ’· οἱ δ’ ἐπανέσταν<br>πειθόμενοι· ἀπὸ δ’ εἵματ’ ἐπήτριμα νηήσαντο<br>λείῳ ἐπὶ πλαταμῶνι, τὸν οὐκ ἐπέβαλλε θάλασσα<br>κύμασι, χειμερίη δὲ πάλαι ἀποέκλυσεν ἅλμη.<br>νῆα δ’ ἐπικρατέως Ἄργου ὑποθημοσύνῃσιν<br>ἔζωσαν πάμπρωτον ἐυστρεφεῖ ἔνδοθεν ὅπλῳ<br>τεινάμενοι ἑκάτερθεν, ἵν’ εὖ ἀραροίατο γόμφοις<br>δούρατα καὶ ῥοθίοιο βίην ἔχοι ἀντιόωσαν.<br>σκάπτον δ’ αἶψα κατ’ εὖρος ὅσον περιβάλλετο χῶρον,<br>ἠδὲ κατὰ πρῴραν εἴσω ἁλὸς ὁσσάτιόν περ<br>ἑλκομένη χείρεσσιν ἐπιδραμέεσθαι ἔμελλεν.<br>αἰεὶ δὲ προτέρω χθαμαλώτερον ἐξελάχαινον<br>στείρης, ἐν δ’ ὁλκῷ ξεστὰς στορέσαντο φάλαγγας·<br>τὴν δὲ κατάντη κλῖναν ἐπὶ πρώτῃσι φάλαγξιν,<br>ὥς κεν ὀλισθαίνουσα δι’ αὐτάων φορέοιτο.<br>ὕψι δ’ ἄρ’ ἔνθα καὶ ἔνθα μεταστρέψαντες ἐρετμὰ<br>πήχυιον προύχοντα περὶ σκαλμοῖσιν ἔδησαν.<br>τῶν δ’ ἐναμοιβαδὶς αὐτοὶ ἐνέσταθεν ἀμφοτέρωθεν,<br>στέρνα θ’ ὁμοῦ καὶ χεῖρας ἐπήλασαν. ἐν δ’ ἄρα Τῖφυς<br>βήσαθ’, ἵν’ ὀτρύνειε νέους κατὰ καιρὸν ἐρύσσαι·<br>κεκλόμενος δ’ ἤυσε μάλα μέγα· τοὶ δὲ παρᾶσσον<br>ᾧ κράτεϊ βρίσαντες ἰῇ στυφέλιξαν ἐρωῇ<br>νειόθεν ἐξ ἕδρης, ἐπὶ δ’ ἐρρώσαντο πόδεσσιν<br>προπροβιαζόμενοι· ἡ δ’ ἕσπετο Πηλιὰς Ἀργὼ<br>ῥίμφα μάλ’· οἱ δ’ ἑκάτερθεν ἐπίαχον ἀίσσοντες.<br>αἱ δ’ ἄρ’ ὑπὸ τρόπιδι στιβαρῇ στενάχοντο φάλαγγες<br>τριβόμεναι περὶ δέ σφιν ἀιδνὴ κήκιε λιγνὺς<br>βριθοσύνῃ, κατόλισθε δ’ ἔσω ἁλός· οἱ δέ μιν αὖθι<br>ἂψ ἀνασειράζοντες ἔχον προτέρωσε κιοῦσαν.<br>σκαλμοῖς δ’ ἀμφὶς ἐρετμὰ κατήρτυον· ἐν δέ οἱ ἱστὸν<br>λαίφεά τ’ εὐποίητα καὶ ἁρμαλιὴν ἐβάλοντο.", "st": "1.363"}, {"sp": "N", "t": "αὐτὰρ ἐπεὶ τὰ ἕκαστα περιφραδέως ἀλέγυναν,<br>κληῖδας μὲν πρῶτα πάλῳ διεμοιρήσαντο,<br>ἄνδρ’ ἐντυναμένω δοιὼ μίαν· ἐκ δ’ ἄρα μέσσην<br>ᾕρεον Ἡρακλῆι καὶ ἡρώων ἄτερ ἄλλων<br>Ἀγκαίῳ, Τεγέης ὅς ῥα πτολίεθρον ἔναιεν.<br>τοῖς μέσσην οἴοισιν ἀπὸ κληῖδα λίποντο<br>αὔτως, οὔτι πάλῳ· ἐπὶ δ’ ἔτρεπον αἰνήσαντες<br>Τῖφυν ἐυστείρης οἰήια νηὸς ἔρυσθαι.", "st": "1.394"}, {"sp": "N", "t": "ἔνθεν δ’ αὖ λάιγγας ἁλὸς σχεδὸν ὀχλίζοντες<br>νήεον αὐτόθι βωμὸν ἐπάκτιον Ἀπόλλωνος,<br>Ἀκτίου Ἐμβασίοιό τ’ ἐπώνυμον· ὦκα δέ τοίγε<br>φιτροὺς ἀζαλέης στόρεσαν καθύπερθεν ἐλαίης.<br>τείως δ’ αὖτ’ ἀγέληθεν ἐπιπροέηκαν ἄγοντες<br>βουκόλοι Αἰσονίδαο δύω βόε. τοὺς δ’ ἐρύσαντο<br>κουρότεροι ἑτάρων βωμοῦ σχεδόν. οἱ δ’ ἄρ’ ἔπειτα<br>χέρνιβά τ’ οὐλοχύτας τε παρέσχεθον. αὐτὰρ Ἰήσων<br>εὔχετο κεκλόμενος πατρώιον Ἀπόλλωνα·", "st": "1.402"}, {"sp": "N", "t": "“κλῦθι ἄναξ, Παγασάς τε πόλιν τ’ Αἰσωνίδα ναίων,<br>ἡμετέροιο τοκῆος ἐπώνυμον, ὅς μοι ὑπέστης<br>Πυθοῖ χρειομένῳ ἄνυσιν καὶ πείραθ’ ὁδοῖο<br>σημανέειν, αὐτὸς γὰρ ἐπαίτιος ἔπλευ ἀέθλων·<br>αὐτὸς νῦν ἄγε νῆα σὺν ἀρτεμέεσσιν ἑταίροις<br>κεῖσέ τε καὶ παλίνορσον ἐς Ἑλλάδα. σοὶ δ’ ἂν ὀπίσσω<br>τόσσων, ὅσσοι κεν νοστήσομεν, ἀγλαὰ ταύρων<br>ἱρὰ πάλιν βωμῷ ἐπιθήσομεν· ἄλλα δὲ Πυθοῖ,<br>ἄλλα δ’ ἐς Ὀρτυγίην ἀπερείσια δῶρα κομίσσω.<br>νῦν δ’ ἴθι, καὶ τήνδ’ ἧμιν, Ἑκηβόλε, δέξο θυηλήν,<br>ἥν τοι τῆσδ’ ἐπίβαθρα χάριν προτεθείμεθα νηὸς<br>πρωτίστην· λύσαιμι δ’, ἄναξ, ἐπ’ ἀπήμονι μοίρῃ<br>πείσματα σὴν διὰ μῆτιν· ἐπιπνεύσειε δ’ ἀήτης<br>μείλιχος, ᾧ κ’ ἐπὶ πόντον ἐλευσόμεθ’ εὐδιόωντες.”", "st": "1.411"}, {"sp": "N", "t": "ἦ, καὶ ἅμ’ εὐχωλῇ προχύτας βάλε. τὼ δ’ ἐπὶ βουσὶν<br>ζωσάσθην, Ἀγκαῖος ὑπέρβιος, Ἡρακλέης τε.<br>ἤτοι ὁ μὲν ῥοπάλῳ μέσσον κάρη ἀμφὶ μέτωπα<br>πλῆξεν, ὁ δ’ ἀθρόος αὖθι πεσὼν ἐνερείσατο γαίῃ·<br>Ἀγκαῖος δ’ ἑτέροιο κατὰ πλατὺν αὐχένα κόψας<br>χαλκείῳ πελέκει κρατεροὺς διέκερσε τένοντας·<br>ἤριπε δ’ ἀμφοτέροισι περιρρηδὴς κεράεσσιν.<br>τοὺς δ’ ἕταροι σφάξαν τε θοῶς, δεῖράν τε βοείας,<br>κόπτον, δαίτρευόν τε, καὶ ἱερὰ μῆρ’ ἐτάμοντο,<br>κὰδ δ’ ἄμυδις τάγε πάντα καλύψαντες πύκα δημῷ<br>καῖον ἐπὶ σχίζῃσιν· ὁ δ’ ἀκρήτους χέε λοιβὰς<br>Αἰσονίδης, γήθει δὲ σέλας θηεύμενος Ἴδμων<br>πάντοσε λαμπόμενον θυέων ἄπο τοῖό τε λιγνὺν<br>πορφυρέαις ἑλίκεσσιν ἐναίσιμον ἀίσσουσαν·<br>αἶψα δ’ ἀπηλεγέως νόον ἔκφατο Λητοΐδαο·", "st": "1.425"}, {"sp": "N", "t": "“ὑμῖν μὲν δὴ μοῖρα θεῶν χρειώ τε περῆσαι<br>ἐνθάδε κῶας ἄγοντας· ἀπειρέσιοι δ’ ἐνὶ μέσσῳ<br>κεῖσέ τε δεῦρό τ’ ἔασιν ἀνερχομένοισιν ἄεθλοι.<br>αὐτὰρ ἐμοὶ θανέειν στυγερῇ ὑπὸ δαίμονος αἴσῃ<br>τηλόθι που πέπρωται ἐπ’ Ἀσίδος ἠπείροιο.<br>ὧδε κακοῖς δεδαὼς ἔτι καὶ πάρος οἰωνοῖσιν<br>πότμον ἐμὸν πάτρης ἐξήιον, ὄφρ’ ἐπιβαίην<br>νηός, ἐυκλείη δὲ δόμοις ἐπιβάντι λίπηται.”", "st": "1.440"}, {"sp": "N", "t": "ὧς ἄρ’ ἔφη· κοῦροι δὲ θεοπροπίης ἀίοντες<br>νόστῳ μὲν γήθησαν, ἄχος δ’ ἕλεν Ἴδμονος αἴσῃ.<br>ἦμος δ’ ἠέλιος σταθερὸν παραμείβεται ἦμαρ,<br>αἱ δὲ νέον σκοπέλοισιν ὑποσκιόωνται ἄρουραι,<br>δειελινὸν κλίνοντος ὑπὸ ζόφον ἠελίοιο,<br>τῆμος ἄρ’ ἤδη πάντες ἐπὶ ψαμάθοισι βαθεῖαν<br>φυλλάδα χευάμενοι πολιοῦ πρόπαρ αἰγιαλοῖο<br>κέκλινθ’ ἑξείης· παρὰ δέ σφισι μυρί’ ἔκειτο<br>εἴδατα, καὶ μέθυ λαρόν, ἀφυσσαμένων προχόῃσιν<br>οἰνοχόων· μετέπειτα δ’ ἀμοιβαδὶς ἀλλήλοισιν<br>μυθεῦνθ’, οἷά τε πολλὰ νέοι παρὰ δαιτὶ καὶ οἴνῳ<br>τερπνῶς ἑψιόωνται, ὅτ’ ἄατος ὕβρις ἀπείη.<br>ἔνθ’ αὖτ’ Αἰσονίδης μὲν ἀμήχανος εἰν ἑοῖ αὐτῷ<br>πορφύρεσκεν ἕκαστα κατηφιόωντι ἐοικώς.<br>τὸν δ’ ἄρ’ ὑποφρασθεὶς μεγάλῃ ὀπὶ νείκεσεν Ἴδας·", "st": "1.448"}, {"sp": "N", "t": "“Αἰσονίδη, τίνα τήνδε μετὰ φρεσὶ μῆτιν ἑλίσσεις;<br>αὔδα ἐνὶ μέσσοισι τεὸν νόον. ἦέ σε δαμνᾷ<br>τάρβος ἐπιπλόμενον, τό τ’ ἀνάλκιδας ἄνδρας ἀτύζει;<br>ἴστω νῦν δόρυ θοῦρον, ὅτῳ περιώσιον ἄλλων<br>κῦδος ἐνὶ πτολέμοισιν ἀείρομαι, οὐδέ μ’ ὀφέλλει<br>Ζεὺς τόσον, ὁσσάτιόν περ ἐμὸν δόρυ, μή νύ τι πῆμα<br>λοίγιον ἔσσεσθαι, μηδ’ ἀκράαντον ἄεθλον<br>Ἴδεω ἑσπομένοιο, καὶ εἰ θεὸς ἀντιόῳτο.<br>τοῖόν μ’ Ἀρήνηθεν ἀοσσητῆρα κομίζεις.”", "st": "1.463"}, {"sp": "N", "t": "ἦ, καὶ ἐπισχόμενος πλεῖον δέπας ἀμφοτέρῃσιν<br>πῖνε χαλίκρητον λαρὸν μέθυ· δεύετο δ’ οἴνῳ<br>χείλεα, κυάνεαί τε γενειάδες· οἱ δ’ ὁμάδησαν<br>πάντες ὁμῶς, Ἴδμων δὲ καὶ ἀμφαδίην ἀγόρευσεν·", "st": "1.472"}, {"sp": "N", "t": "“δαιμόνιε, φρονέεις ὀλοφώια καὶ πάρος αὐτῷ.<br>ἦέ τοι εἰς ἄτην ζωρὸν μέθυ θαρσαλέον κῆρ<br>οἰδάνει ἐν στήθεσσι, θεοὺς δ’ ἀνέηκεν ἀτίζειν;<br>ἄλλοι μῦθοι ἔασι παρήγοροι, οἷσί περ ἀνὴρ<br>θαρσύνοι ἕταρον· σὺ δ’ ἀτάσθαλα πάμπαν ἔειπας,<br>τοῖα φάτις καὶ τοὺς πρὶν ἐπιφλύειν μακάρεσσιν<br>υἷας Ἀλωιάδας, οἷς οὐδ’ ὅσον ἰσοφαρίζεις<br>ἠνορέην· ἔμπης δὲ θοοῖς ἐδάμησαν ὀιστοῖς<br>ἄμφω Λητοΐδαο, καὶ ἴφθιμοί περ ἐόντες.”", "st": "1.476"}, {"sp": "N", "t": "ὧς ἔφατ’· ἐκ δ’ ἐγέλασσεν ἄδην Ἀφαρήιος Ἴδας<br>καί μιν ἐπιλλίζων ἠμείβετο κερτομίοισιν·", "st": "1.485"}, {"sp": "N", "t": "“ἄγρει νυν τόδε σῇσι θεοπροπίῃσιν ἐνίσπες,<br>εἰ καὶ ἐμοὶ τοιόνδε θεοὶ τελέουσιν ὄλεθρον,<br>οἷον Ἀλωιάδῃσι πατὴρ τεὸς ἐγγυάλιξεν.<br>φράζεο δ’ ὅππως χεῖρας ἐμὰς σόος ἐξαλέοιο,<br>χρειὼ θεσπίζων μεταμώνιον εἴ κεν ἁλῴης.”", "st": "1.487"}, {"sp": "N", "t": "Χώετ’ ἐνιπτάζων· προτέρω δέ κε νεῖκος ἐτύχθη,<br>εἰ μὴ δηριόωντας ὁμοκλήσαντες ἑταῖροι<br>αὐτός τ’ Αἰσονίδης κατερήτυεν· ἂν δὲ καὶ Ὀρφεὺς<br>λαιῇ ἀνασχόμενος κίθαριν πείραζεν ἀοιδῆς.", "st": "1.492"}, {"sp": "N", "t": "ἤειδεν δ’ ὡς γαῖα καὶ οὐρανὸς ἠδὲ θάλασσα,<br>τὸ πρὶν ἐπ’ ἀλλήλοισι μιῇ συναρηρότα μορφῇ,<br>νείκεος ἐξ ὀλοοῖο διέκριθεν ἀμφὶς ἕκαστα·<br>ἠδ’ ὡς ἔμπεδον αἰὲν ἐν αἰθέρι τέκμαρ ἔχουσιν<br>ἄστρα σεληναίη τε καὶ ἠελίοιο κέλευθοι·<br>οὔρεά θ’ ὡς ἀνέτειλε, καὶ ὡς ποταμοὶ κελάδοντες<br>αὐτῇσιν νύμφῃσι καὶ ἑρπετὰ πάντ’ ἐγένοντο.<br>ἤειδεν δ’ ὡς πρῶτον Ὀφίων Εὐρυνόμη τε<br>Ὠκεανὶς νιφόεντος ἔχον κράτος Οὐλύμποιο·<br>ὥς τε βίῃ καὶ χερσὶν ὁ μὲν Κρόνῳ εἴκαθε τιμῆς,<br>ἡ δὲ Ῥέῃ, ἔπεσον δ’ ἐνὶ κύμασιν Ὠκεανοῖο·<br>οἱ δὲ τέως μακάρεσσι θεοῖς Τιτῆσιν ἄνασσον,<br>ὄφρα Ζεὺς ἔτι κοῦρος, ἔτι φρεσὶ νήπια εἰδώς,<br>Δικταῖον ναίεσκεν ὑπὸ σπέος· οἱ δέ μιν οὔπω<br>γηγενέες Κύκλωπες ἐκαρτύναντο κεραυνῷ,<br>βροντῇ τε στεροπῇ τε· τὰ γὰρ Διὶ κῦδος ὀπάζει.", "st": "1.496"}, {"sp": "N", "t": "ἦ, καὶ ὁ μὲν φόρμιγγα σὺν ἀμβροσίῃ σχέθεν αὐδῇ.<br>τοὶ δ’ ἄμοτον λήξαντος ἔτι προύχοντο κάρηνα<br>πάντες ὁμῶς ὀρθοῖσιν ἐπ’ οὔασιν ἠρεμέοντες<br>κηληθμῷ· τοῖόν σφιν ἐνέλλιπε θέλκτρον ἀοιδῆς.<br>οὐδ’ ἐπὶ δὴν μετέπειτα κερασσάμενοι Διὶ λοιβάς,<br>ἣ θέμις, ἑστηῶτες ἐπὶ γλώσσῃσι χέοντο<br>αἰθομέναις, ὕπνου δὲ διὰ κνέφας ἐμνώοντο.", "st": "1.512"}, {"sp": "N", "t": "αὐτὰρ ὅτ’ αἰγλήεσσα φαεινοῖς ὄμμασιν Ἠὼς<br>Πηλίου αἰπεινὰς ἴδεν ἄκριας, ἐκ δ’ ἀνέμοιο<br>εὔδιοι ἐκλύζοντο τινασσομένης ἁλὸς ἄκραι,<br>δὴ τότ’ ἀνέγρετο Τῖφυς· ἄφαρ δ’ ὀρόθυνεν ἑταίρους<br>βαινέμεναί τ’ ἐπὶ νῆα καὶ ἀρτύνασθαι ἐρετμά.<br>σμερδαλέον δὲ λιμὴν Παγασήιος ἠδὲ καὶ αὐτὴ<br>Πηλιὰς ἴαχεν Ἀργὼ ἐπισπέρχουσα νέεσθαι.<br>ἐν γάρ οἱ δόρυ θεῖον ἐλήλατο, τό ῥ’ ἀνὰ μέσσην<br>στεῖραν Ἀθηναίη Δωδωνίδος ἥρμοσε φηγοῦ.<br>οἱ δ’ ἀνὰ σέλματα βάντες ἐπισχερὼ ἀλλήλοισιν,<br>ὡς ἐδάσαντο πάροιθεν ἐρεσσέμεν ᾧ ἐνὶ χώρῳ,<br>εὐκόσμως σφετέροισι παρ’ ἔντεσιν ἑδριόωντο.<br>μέσσῳ δ’ Ἀγκαῖος μέγα τε σθένος Ἡρακλῆος<br>ἵζανον· ἄγχι δέ οἱ ῥόπαλον θέτο, καί οἱ ἔνερθεν<br>ποσσὶν ὑπεκλύσθη νηὸς τρόπις.· εἵλκετο δ’ ἤδη<br>πείσματα, καὶ μέθυ λεῖβον ὕπερθ’ ἁλός. αὐτὰρ Ἰήσων<br>δακρυόεις γαίης ἀπὸ πατρίδος ὄμματ’ ἔνεικεν.<br>οἱ δ’, ὥστ’ ἠίθεοι Φοίβῳ χορὸν ἢ ἐνὶ Πυθοῖ<br>ἤ που ἐν Ὀρτυγίῃ, ἢ ἐφ’ ὕδασιν Ἰσμηνοῖο<br>στησάμενοι, φόρμιγγος ὑπαὶ περὶ βωμὸν ὁμαρτῇ<br>ἐμμελέως κραιπνοῖσι πέδον ῥήσσωσι πόδεσσιν·<br>ὧς οἱ ὑπ’ Ὀρφῆος κιθάρῃ πέπληγον ἐρετμοῖς<br>πόντου λάβρον ὕδωρ, ἐπὶ δὲ ῥόθια κλύζοντο·<br>ἀφρῷ δ’ ἔνθα καὶ ἔνθα κελαινὴ κήκιεν ἅλμη<br>δεινὸν μορμύρουσα ἐρισθενέων μένει ἀνδρῶν.<br>στράπτε δ’ ὑπ’ ἠελίῳ φλογὶ εἴκελα νηὸς ἰούσης<br>τεύχεα· μακραὶ δ’ αἰὲν ἐλευκαίνοντο κέλευθοι,<br>ἀτραπὸς ὣς χλοεροῖο διειδομένη πεδίοιο.<br>πάντες δ’ οὐρανόθεν λεῦσσον θεοὶ ἤματι κείνῳ<br>νῆα καὶ ἡμιθέων ἀνδρῶν μένος, οἳ τότ’ ἄριστοι<br>πόντον ἐπιπλώεσκον· ἐπ’ ἀκροτάτῃσι δὲ νύμφαι<br>Πηλιάδες κορυφῇσιν ἐθάμβεον εἰσορόωσαι<br>ἔργον Ἀθηναίης Ἰτωνίδος, ἠδὲ καὶ αὐτοὺς<br>ἥρωας χείρεσσιν ἐπικραδάοντας ἐρετμά.<br>αὐτὰρ ὅγ’ ἐξ ὑπάτου ὄρεος κίεν ἄγχι θαλάσσης<br>Χείρων Φιλλυρίδης, πολιῇ δ’ ἐπὶ κύματος ἀγῇ<br>τέγγε πόδας, καὶ πολλὰ βαρείῃ χειρὶ κελεύων,<br>νόστον ἐπευφήμησεν ἀκηδέα νισσομένοισιν.<br>σὺν καί οἱ παράκοιτις ἐπωλένιον φορέουσα<br>Πηλεΐδην Ἀχιλῆα, φίλῳ δειδίσκετο πατρί.", "st": "1.519"}, {"sp": "N", "t": "οἱ δ’ ὅτε δὴ λιμένος περιηγέα κάλλιπον ἀκτὴν<br>φραδμοσύνῃ μήτι τε δαΐφρονος Ἁγνιάδαο<br>Τίφυος, ὅς ῥ’ ἐνὶ χερσὶν ἐύξοα τεχνηέντως<br>πηδάλι’ ἀμφιέπεσκ’, ὄφρ’ ἔμπεδον ἐξιθύνοι,<br>δή ῥα τότε μέγαν ἱστὸν ἐνεστήσαντο μεσόδμῃ,<br>δῆσαν δὲ προτόνοισι, τανυσσάμενοι ἑκάτερθεν,<br>κὰδ δ’ αὐτοῦ λίνα χεῦαν, ἐπ’ ἠλακάτην ἐρύσαντες.<br>ἐν δὲ λιγὺς πέσεν οὖρος· ἐπ’ ἰκριόφιν δὲ κάλωας<br>ξεστῇσιν περόνῃσι διακριδὸν ἀμφιβαλόντες<br>Τισαίην εὔκηλοι ὑπὲρ δολιχὴν θέον ἄκρην.<br>τοῖσι δὲ φορμίζων εὐθήμονι μέλπεν ἀοιδῇ<br>Οἰάγροιο πάις νηοσσόον εὐπατέρειαν<br>Ἄρτεμιν, ἣ κείνας σκοπιὰς ἁλὸς ἀμφιέπεσκεν<br>ῥυομένη καὶ γαῖαν Ἰωλκίδα· τοὶ δὲ βαθείης<br>ἰχθύες ἀίσσοντες ὕπερθ’ ἁλός, ἄμμιγα παύροις<br>ἄπλετοι, ὑγρὰ κέλευθα διασκαίροντες ἕποντο.<br>ὡς δ’ ὁπότ’ ἀγραύλοιο κατ’ ἴχνια σημαντῆρος<br>μυρία μῆλ’ ἐφέπονται ἄδην κεκορημένα ποίης<br>εἰς αὖλιν, ὁ δέ τ’ εἶσι πάρος σύριγ γι λιγείῃ<br>καλὰ μελιζόμενος νόμιον μέλος, ὧς ἄρα τοίγε<br>ὡμάρτευν· τὴν δ’ αἰὲν ἐπασσύτερος φέρεν οὖρος.", "st": "1.559"}, {"sp": "N", "t": "αὐτίκα δ’ ἠερίη πολυλήιος αἶα Πελασγῶν<br>δύετο, Πηλιάδας δὲ παρεξήμειβον ἐρίπνας<br>αἰὲν ἐπιπροθέοντες· ἔδυνε δὲ Σηπιὰς ἄκρη,<br>φαίνετο δ’ εἰναλίη Σκίαθος, φαίνοντο δ’ ἄπωθεν<br>Πειρεσιαὶ Μάγνησά θ’ ὑπεύδιος ἠπείροιο<br>ἀκτὴ καὶ τύμβος Δολοπήιος· ἔνθ’ ἄρα τοίγε<br>ἑσπέριοι ἀνέμοιο παλιμπνοίῃσιν ἔκελσαν,<br>καί μιν κυδαίνοντες ὑπὸ κνέφας ἔντομα μήλων<br>κεῖαν, ὀρινομένης ἁλὸς οἴδματι· διπλόα δ’ ἀκταῖς<br>ἤματ’ ἐλινύεσκον· ἀτὰρ τριτάτῳ προέηκαν<br>νῆα, τανυσσάμενοι περιώσιον ὑψόθι λαῖφος.<br>τὴν δ’ ἀκτὴν Ἀφέτας Ἀργοῦς ἔτι κικλήσκουσιν.", "st": "1.580"}, {"sp": "N", "t": "ἔνθεν δὲ προτέρωσε παρεξέθεον Μελίβοιαν.<br>[ἀκτήν τ’ αἰγιαλόν τε δυσήνεμον εἰσορόωντες.]<br>ἠῶθεν δ’ Ὁμόλην αὐτοσχεδὸν εἰσορόωντες<br>πόντῳ κεκλιμένην παρεμέτρεον· οὐδ’ ἔτι δηρὸν<br>μέλλον ὑπὲκ ποταμοῖο βαλεῖν Ἀμύροιο ῥέεθρα.<br>κεῖθεν δ’ Εὐρυμενάς τε πολυκλύστους τε φάραγγας<br>Ὄσσης Οὐλύμποιό τ’ ἐσέδρακον· αὐτὰρ ἔπειτα<br>κλίτεα Παλλήναια, Καναστραίην ὑπὲρ ἄκρην,<br>ἤνυσαν ἐννύχιοι πνοιῇ ἀνέμοιο θέοντες.<br>ἦρι δὲ νισσομένοισιν Ἄθω ἀνέτελλε κολώνη<br>Θρηικίη, ἣ τόσσον ἀπόπροθι Λῆμνον ἐοῦσαν,<br>ὅσσον ἐς ἔνδιόν κεν ἐύστολος ὁλκὰς ἀνύσσαι,<br>ἀκροτάτῃ κορυφῇ σκιάει, καὶ ἐσάχρι Μυρίνης.<br>τοῖσιν δ’ αὐτῆμαρ μὲν ἄεν καὶ ἐπὶ κνέφας οὖρος<br>πάγχυ μάλ’ ἀκραής, τετάνυστο δὲ λαίφεα νηός.<br>αὐτὰρ ἅμ’ ἠελίοιο βολαῖς ἀνέμοιο λιπόντος<br>εἰρεσίῃ κραναὴν Σιντηίδα Λῆμνον ἵκοντο.", "st": "1.592"}, {"sp": "N", "t": "ἔνθ’ ἄμυδις πᾶς δῆμος ὑπερβασίῃσι γυναικῶν<br>νηλειῶς δέδμητο παροιχομένῳ λυκάβαντι.<br>δὴ γὰρ κουριδίας μὲν ἀπηνήναντο γυναῖκας<br>ἀνέρες ἐχθήραντες, ἔχον δ’ ἐπὶ ληιάδεσσιν<br>τρηχὺν ἔρον, ἃς αὐτοὶ ἀγίνεον ἀντιπέρηθεν<br>Θρηικίην δῃοῦντες· ἐπεὶ χόλος αἰνὸς ὄπαζεν<br>Κύπριδος, οὕνεκά μιν γεράων ἐπὶ δηρὸν ἄτισσαν.<br>ὦ μέλεαι, ζήλοιό τ’ ἐπισμυγερῶς ἀκόρητοι.<br>οὐκ οἶον σὺν τῇσιν ἑοὺς ἔρραισαν ἀκοίτας<br>ἀμφ’ εὐνῇ, πᾶν δ’ ἄρσεν ὁμοῦ γένος, ὥς κεν ὀπίσσω<br>μήτινα λευγαλέοιο φόνου τίσειαν ἀμοιβήν.<br>οἴη δ’ ἐκ πασέων γεραροῦ περιφείσατο πατρὸς<br>Ὑψιπύλεια Θόαντος, ὃ δὴ κατὰ δῆμον ἄνασσεν·<br>λάρνακι δ’ ἐν κοίλῃ μιν ὕπερθ’ ἁλὸς ἧκε φέρεσθαι,<br>αἴ κε φύγῃ. καὶ τὸν μὲν ἐς Οἰνοίην ἐρύσαντο<br>πρόσθεν, ἀτὰρ Σίκινόν γε μεθύστερον αὐδηθεῖσαν<br>νῆσον, ἐπακτῆρες, Σικίνου ἄπο, τόν ῥα Θόαντι<br>νηιὰς Οἰνοίη νύμφη τέκεν εὐνηθεῖσα.<br>τῇσι δὲ βουκόλιαί τε βοῶν χάλκειά τε δύνειν<br>τεύχεα, πυροφόρους τε διατμήξασθαι ἀρούρας<br>ῥηίτερον πάσῃσιν Ἀθηναίης πέλεν ἔργων,<br>οἷς αἰεὶ τὸ πάροιθεν ὁμίλεον. ἀλλὰ γὰρ ἔμπης<br>ἦ θαμὰ δὴ πάπταινον ἐπὶ πλατὺν ὄμμασι πόντον<br>δείματι λευγαλέῳ, ὁπότε Θρήικες ἴασιν.<br>τῶ καὶ ὅτ’ ἐγγύθι νήσου ἐρεσσομένην ἴδον Ἀργώ,<br>αὐτίκα πασσυδίῃ πυλέων ἔκτοσθε Μυρίνης<br>δήια τεύχεα δῦσαι ἐς αἰγιαλὸν προχέοντο,<br>Θυιάσιν ὠμοβόροις ἴκελαι· φὰν γάρ που ἱκάνειν<br>Θρήικας· ἡ δ’ ἅμα τῇσι Θοαντιὰς Ὑψιπύλεια<br>δῦν’ ἐνὶ τεύχεσι πατρός. ἀμηχανίῃ δ’ ἐχέοντο<br>ἄφθογγοι· τοῖόν σφιν ἐπὶ δέος ᾐωρεῖτο.", "st": "1.609"}, {"sp": "N", "t": "τείως δ’ αὖτ’ ἐκ νηὸς ἀριστῆες προέηκαν<br>Αἰθαλίδην κήρυκα θοόν, τῷπέρ τε μέλεσθαι<br>ἀγγελίας καὶ σκῆπτρον ἐπέτρεπον Ἑρμείαο,<br>σφωιτέροιο τοκῆος, ὅ οἱ μνῆστιν πόρε πάντων<br>ἄφθιτον· οὐδ’ ἔτι νῦν περ ἀποιχομένου Ἀχέροντος<br>δίνας ἀπροφάτους ψυχὴν ἐπιδέδρομε λήθη·<br>ἀλλ’ ἥγ’ ἔμπεδον αἰὲν ἀμειβομένη μεμόρηται,<br>ἄλλοθ’ ὑποχθονίοις ἐναρίθμιος, ἄλλοτ’ ἐς αὐγὰς<br>ἠελίου ζωοῖσι μετ’ ἀνδράσιν. ἀλλὰ τί μύθους<br>Αἰθαλίδεω χρειώ με διηνεκέως ἀγορεύειν;<br>ὅς ῥα τόθ’ Ὑψιπύλην μειλίξατο δέχθαι ἰόντας<br>ἤματος ἀνομένοιο διὰ κνέφας· οὐδὲ μὲν ἠοῖ<br>πείσματα νηὸς ἔλυσαν ἐπὶ πνοιῇ βορέαο.", "st": "1.640"}, {"sp": "N", "t": "Λημνιάδες δὲ γυναῖκες ἀνὰ πτόλιν ἷζον ἰοῦσαι<br>εἰς ἀγορήν· αὐτὴ γὰρ ἐπέφραδεν Ὑψιπύλεια.<br>καί ῥ’ ὅτε δὴ μάλα πᾶσαι ὁμιλαδὸν ἠγερέθοντο,<br>αὐτίκ’ ἄρ’ ἥγ’ ἐνὶ τῇσιν ἐποτρύνουσ’ ἀγόρευεν·", "st": "1.653"}, {"sp": "N", "t": "“Ὦ φίλαι, εἰ δ’ ἄγε δὴ μενοεικέα δῶρα πόρωμεν<br>ἀνδράσιν, οἷά τ’ ἔοικεν ἄγειν ἐπὶ νηὸς ἔχοντας,<br>ἤια, καὶ μέθυ λαρόν, ἵν’ ἔμπεδον ἔκτοθι πύργων<br>μίμνοιεν, μηδ’ ἄμμε κατὰ χρειὼ μεθέποντες<br>ἀτρεκέως γνώωσι, κακὴ δ’ ἐπὶ πολλὸν ἵκηται<br>βάξις· ἐπεὶ μέγα ἔργον ἐρέξαμεν, οὐδέ τι πάμπαν<br>θυμηδὲς καὶ τοῖσι τόγ’ ἔσσεται, εἴ κε δαεῖεν.<br>ἡμετέρη μὲν νῦν τοίη παρενήνοθε μῆτις·<br>ὑμέων δ’ εἴ τις ἄρειον ἔπος μητίσεται ἄλλη,<br>ἐγρέσθω· τοῦ γάρ τε καὶ εἵνεκα δεῦρ’ ἐκάλεσσα.”", "st": "1.657"}, {"sp": "N", "t": "ὧς ἄρ’ ἔφη, καὶ θῶκον ἐφίζανε πατρὸς ἑοῖο<br>λάινον· αὐτὰρ ἔπειτα φίλη τροφὸς ὦρτο Πολυξώ,<br>γήραϊ δὴ ῥικνοῖσιν ἐπισκάζουσα πόδεσσιν,<br>βάκτρῳ ἐρειδομένη, περὶ δὲ μενέαιν’ ἀγορεῦσαι.<br>τῇ καὶ παρθενικαὶ πίσυρες σχεδὸν ἑδριόωντο<br>ἀδμῆτες λευκῇσιν ἐπιχνοαούσῃ ἐθείραις.<br>στῆ δ’ ἄρ’ ἐνὶ μέσσῃ ἀγορῇ, ἀνὰ δ’ ἔσχεθε δειρὴν<br>ἦκα μόλις κυφοῖο μεταφρένου, ὧδέ τ’ ἔειπεν·", "st": "1.667"}, {"sp": "N", "t": "“δῶρα μέν, ὡς αὐτῇ περ ἐφανδάνει Ὑψιπυλείῃ,<br>πέμπωμεν ξείνοισιν, ἐπεὶ καὶ ἄρειον ὀπάσσαι.<br>ὔμμι γε μὴν τίς μῆτις ἐπαύρεσθαι βιότοιο,<br>αἴ κεν ἐπιβρίσῃ Θρήιξ στρατός, ἠέ τις ἄλλος<br>δυσμενέων, ἅ τε πολλὰ μετ’ ἀνθρώποισι πέλονται;<br>ὡς καὶ νῦν ὅδ’ ὅμιλος ἀνωίστως ἐφικάνει.<br>εἰ δὲ τὸ μὲν μακάρων τις ἀποτρέποι, ἄλλα δ’ ὀπίσσω<br>μυρία δηιοτῆτος ὑπέρτερα πήματα μίμνει,<br>εὖτ’ ἂν δὴ γεραραὶ μὲν ἀποφθινύθωσι γυναῖκες,<br>κουρότεραι δ’ ἄγονοι στυγερὸν ποτὶ γῆρας ἵκησθε.<br>πῶς τῆμος βώσεσθε δυσάμμοροι; ἦε βαθείαις<br>αὐτόματοι βόες ὔμμιν ἐνιζευχθέντες ἀρούραις<br>γειοτόμον νειοῖο διειρύσσουσιν ἄροτρον,<br>καὶ πρόκα τελλομένου ἔτεος στάχυν ἀμήσονται;<br>ἦ μὲν ἐγών, εἰ καί με τὰ νῦν ἔτι πεφρίκασιν<br>κῆρες, ἐπερχόμενόν που ὀίομαι εἰς ἔτος ἤδη<br>γαῖαν ἐφέσσεσθαι, κτερέων ἀπὸ μοῖραν ἑλοῦσαν<br>αὔτως, ἣ θέμις ἐστί, πάρος κακότητα πελάσσαι.<br>ὁπλοτέρῃσι δὲ πάγχυ τάδε φράζεσθαι ἄνωγα.<br>νῦν γὰρ δὴ παρὰ ποσσὶν ἐπήβολός ἐστ’ ἀλεωρή,<br>εἴ κεν ἐπιτρέψητε δόμους καὶ ληίδα πᾶσαν<br>ὑμετέρην ξείνοισι καὶ ἀγλαὸν ἄστυ μέλεσθαι.”", "st": "1.675"}, {"sp": "N", "t": "ὧς ἔφατ’· ἐν δ’ ἀγορὴ πλῆτο θρόου. εὔαδε γάρ σφιν<br>μῦθος. ἀτὰρ μετὰ τήνγε παρασχεδὸν αὖτις ἀνῶρτο<br>Ὑψιπύλη, καὶ τοῖον ὑποβλήδην ἔπος ηὔδα·", "st": "1.697"}, {"sp": "N", "t": "“εἰ μὲν δὴ πάσῃσιν ἐφανδάνει ἥδε μενοινή,<br>ἤδη κεν μετὰ νῆα καὶ ἄγγελον ὀτρύναιμι.”", "st": "1.700"}, {"sp": "N", "t": "ἦ ῥα, καὶ Ἰφινόην μετεφώνεεν ἆσσον ἐοῦσαν·<br>“ὄρσο μοι, Ἰφινόη, τοῦδ’ ἀνέρος ἀντιόωσα,<br>ἡμέτερόνδε μολεῖν, ὅστις στόλου ἡγεμονεύει,<br>ὄφρα τί οἱ δήμοιο ἔπος θυμῆρες ἐνίσπω·<br>καὶ δ’ αὐτοὺς γαίης τε καὶ ἄστεος, αἴ κ’ ἐθέλωσιν,<br>κέκλεο θαρσαλέως ἐπιβαινέμεν εὐμενέοντας.”", "st": "1.702"}, {"sp": "N", "t": "ἦ, καὶ ἔλυσ’ ἀγορήν, μετὰ δ’ εἰς ἑὸν ὦρτο νέεσθαι.<br>ὧς δὲ καὶ Ἰφινόη Μινύας ἵκεθ’· οἱ δ’ ἐρέεινον,<br>χρεῖος ὅ τι φρονέουσα μετήλυθεν. ὦκα δὲ τούσγε<br>πασσυδίῃ μύθοισι προσέννεπεν ἐξερέοντας·", "st": "1.708"}, {"sp": "N", "t": "“κούρη τοί μ’ ἐφέηκε Θοαντιὰς ἐνθάδ’ ἰοῦσαν,<br>Ὑψιπύλη, καλέειν νηὸς πρόμον, ὅστις ὄρωρεν,<br>ὄφρα τί οἱ δήμοιο ἔπος θυμῆρες ἐνίσπῃ·<br>καὶ δ’ αὐτοὺς γαίης τε καὶ ἄστεος, αἴ κ’ ἐθέλητε,<br>κέκλεται αὐτίκα νῦν ἐπιβαινέμεν εὐμενέοντας.”", "st": "1.712"}, {"sp": "N", "t": "ὧς ἄρ’ ἔφη· πάντεσσι δ’ ἐναίσιμος ἥνδανε μῦθος.<br>Ὑψιπύλην δ’ εἴσαντο καταφθιμένοιο Θόαντος<br>τηλυγέτην γεγαυῖαν ἀνασσέμεν· ὦκα δὲ τόνγε<br>πέμπον ἴμεν, καὶ δ’ αὐτοὶ ἐπεντύνοντο νέεσθαι.", "st": "1.717"}, {"sp": "N", "t": "αὐτὰρ ὅγ’ ἀμφ’ ὤμοισι θεᾶς Τριτωνίδος ἔργον,<br>δίπλακα πορφυρέην περονήσατο, τήν οἱ ὄπασσεν<br>Παλλάς, ὅτε πρῶτον δρυόχους ἐπεβάλλετο νηὸς<br>Ἀργοῦς, καὶ κανόνεσσι δάε ζυγὰ μετρήσασθαι.<br>τῆς μὲν ῥηίτερόν κεν ἐς ἠέλιον ἀνιόντα<br>ὄσσε βάλοις, ἢ κεῖνο μεταβλέψειας ἔρευθος.<br>δὴ γάρ τοι μέσση μὲν ἐρευθήεσσ’ ἐτέτυκτο,<br>ἄκρα δὲ πορφυρέη πάντῃ πέλεν· ἐν δ’ ἄρ’ ἑκάστῳ<br>τέρματι δαίδαλα πολλὰ διακριδὸν εὖ ἐπέπαστο.", "st": "1.721"}, {"sp": "N", "t": "ἐν μὲν ἔσαν Κύκλωπες ἐπ’ ἀφθίτῳ ἥμενοι ἔργῳ,<br>Ζηνὶ κεραυνὸν ἄνακτι πονεύμενοι· ὃς τόσον ἤδη<br>παμφαίνων ἐτέτυκτο, μιῆς δ’ ἔτι δεύετο μοῦνον<br>ἀκτῖνος, τὴν οἵδε σιδηρείῃς ἐλάασκον<br>σφύρῃσιν, μαλεροῖο πυρὸς ζείουσαν ἀυτμήν.", "st": "1.730"}, {"sp": "N", "t": "ἐν δ’ ἔσαν Ἀντιόπης Ἀσωπίδος υἱέε δοιώ,<br>Ἀμφίων καὶ Ζῆθος· ἀπύργωτος δ’ ἔτι Θήβη<br>κεῖτο πέλας, τῆς οἵγε νέον βάλλοντο δομαίους<br>ἱέμενοι. Ζῆθος μὲν ἐπωμαδὸν ἠέρταζεν<br>οὔρεος ἠλιβάτοιο κάρη, μογέοντι ἐοικώς·<br>Ἀμφίων δ’ ἐπί οἱ χρυσέῃ φόρμιγγι λιγαίνων<br>ἤιε, δὶς τόσση δὲ μετ’ ἴχνια νίσσετο πέτρη", "st": "1.735"}, {"sp": "N", "t": "ἑξείης δ’ ἤσκητο βαθυπλόκαμος Κυθέρεια<br>Ἄρεος ὀχμάζουσα θοὸν σάκος· ἐκ δέ οἱ ὤμου<br>πῆχυν ἔπι σκαιὸν ξυνοχὴ κεχάλαστο χιτῶνος<br>νέρθεν ὑπὲκ μαζοῖο· τὸ δ’ ἀντίον ἀτρεκὲς αὔτως<br>χαλκείῃ δείκηλον ἐν ἀσπίδι φαίνετ’ ἰδέσθαι.", "st": "1.742"}, {"sp": "N", "t": "ἐν δὲ βοῶν ἔσκεν λάσιος νομός· ἀμφὶ δὲ βουσὶν<br>Τηλεβόαι μάρναντο καὶ υἱέες Ἠλεκτρύωνος·<br>οἱ μὲν ἀμυνόμενοι, ἀτὰρ οἵγ’ ἐθέλοντες ἀμέρσαι,<br>ληισταὶ Τάφιοι· τῶν δ’ αἵματι δεύετο λειμὼν<br>ἑρσήεις, πολέες δ’ ὀλίγους βιόωντο νομῆας.", "st": "1.747"}, {"sp": "N", "t": "ἐν δὲ δύω δίφροι πεπονήατο δηριόωντες.<br>καὶ τὸν μὲν προπάροιθε Πέλοψ ἴθυνε, τινάσσων<br>ἡνία, σὺν δέ οἱ ἔσκε παραιβάτις Ἱπποδάμεια·<br>τὸν δὲ μεταδρομάδην ἐπὶ Μυρτίλος ἤλασεν ἵππους,<br>σὺν τῷ δ’ Οἰνόμαος προτενὲς δόρυ χειρὶ μεμαρπὼς<br>ἄξονος ἐν πλήμνῃσι παρακλιδὸν ἀγνυμένοιο<br>πῖπτεν, ἐπεσσύμενος Πελοπήια νῶτα δαΐξαι.", "st": "1.752"}, {"sp": "N", "t": "ἐν καὶ Ἀπόλλων Φοῖβος ὀιστεύων ἐτέτυκτο,<br>βούπαις οὔπω πολλός, ἑὴν ἐρύοντα καλύπτρης<br>μητέρα θαρσαλέως Τιτυὸν μέγαν, ὅν ῥ’ ἔτεκέν γε<br>δῖ’ Ἐλάρη, θρέψεν δὲ καὶ ἂψ ἐλοχεύσατο Γαῖα.", "st": "1.759"}, {"sp": "N", "t": "ἐν καὶ Φρίξος ἔην Μινυήιος ὡς ἐτεόν περ<br>εἰσαΐων κριοῦ, ὁ δ’ ἄρ’ ἐξενέποντι ἐοικώς.<br>κείνους κ’ εἰσορόων ἀκέοις, ψεύδοιό τε θυμόν,<br>ἐλπόμενος πυκινήν τιν’ ἀπὸ σφείων ἐσακοῦσαι<br>βάξιν, ὃ καὶ δηρόν περ ἐπ’ ἐλπίδι θηήσαιο.", "st": "1.763"}, {"sp": "N", "t": "τοῖ’ ἄρα δῶρα θεᾶς Τριτωνίδος ἦεν Ἀθήνης.<br>δεξιτερῇ δ’ ἕλεν ἔγχος ἑκηβόλον, ὅ ῥ’ Ἀταλάντη<br>Μαινάλῳ ἔν ποτέ οἱ ξεινήιον ἐγγυάλιξεν,<br>πρόφρων ἀντομένη· περὶ γὰρ μενέαινεν ἕπεσθαι<br>τὴν ὁδόν· ἀλλὰ γὰρ αὐτὸς ἑκὼν ἀπερήτυε κούρην,<br>δεῖσεν δ’ ἀργαλέας ἔριδας φιλότητος ἕκητι.", "st": "1.768"}, {"sp": "N", "t": "βῆ δ’ ἴμεναι προτὶ ἄστυ, φαεινῷ ἀστέρι ἶσος,<br>ὅν ῥά τε νηγατέῃσιν ἐεργόμεναι καλύβῃσιν<br>νύμφαι θηήσαντο δόμων ὕπερ ἀντέλλοντα,<br>καί σφισι κυανέοιο δι’ ἠέρος ὄμματα θέλγει<br>καλὸν ἐρευθόμενος, γάνυται δέ τε ἠιθέοιο<br>παρθένος ἱμείρουσα μετ’ ἀλλοδαποῖσιν ἐόντος<br>ἀνδράσιν, ᾧ καί μιν μνηστὴν κομέουσι τοκῆες·<br>τῷ ἴκελος πρὸ πόληος ἀνὰ στίβον ἤιεν ἥρως.<br>καί ῥ’ ὅτε δὴ πυλέων τε καὶ ἄστεος ἐντὸς ἔβησαν,<br>δημότεραι μὲν ὄπισθεν ἐπεκλονέοντο γυναῖκες,<br>γηθόσυναι ξείνῳ· ὁ δ’ ἐπὶ χθονὸς ὄμματ’ ἐρείσας<br>νίσσετ’ ἀπηλεγέως, ὄφρ’ ἀγλαὰ δώμαθ’ ἵκανεν<br>Ὑψιπύλης· ἄνεσαν δὲ πύλας προφανέντι θεράπναι<br>δικλίδας, εὐτύκτοισιν ἀρηρεμένας σανίδεσσιν.<br>ἔνθα μιν Ἰφινόη κλισμῷ ἔνι παμφανόωντι<br>ἐσσυμένως καλῆς διὰ παστάδος εἷσεν ἄγουσα<br>ἀντία δεσποίνης· ἡ δ’ ἐγκλιδὸν ὄσσε βαλοῦσα<br>παρθενικὰς ἐρύθηνε παρηίδας· ἔμπα δὲ τόνγε<br>αἰδομένη μύθοισι προσέννεπεν αἱμυλίοισιν·", "st": "1.774"}, {"sp": "N", "t": "“ξεῖνε, τίη μίμνοντες ἐπὶ χρόνον ἔκτοθι πύργων<br>ἧσθ’ αὔτως; ἐπεὶ οὐ μὲν ὑπ’ ἀνδράσι ναίεται ἄστυ,<br>ἀλλὰ Θρηικίης ἐπινάστιοι ἠπείροιο<br>πυροφόρους ἀρόωσι γύας. κακότητα δὲ πᾶσαν<br>ἐξερέω νημερτές, ἵν’ εὖ γνοίητε καὶ αὐτοί.<br>εὖτε Θόας ἀστοῖσι πατὴρ ἐμὸς ἐμβασίλευεν,<br>τηνίκα Θρηικίην, οἵ τ’ ἀντία ναιετάουσιν,<br>δήμου ἀπορνύμενοι λαοὶ πέρθεσκον ἐπαύλους<br>ἐκ νηῶν, αὐτῇσι δ’ ἀπείρονα ληίδα κούραις<br>δεῦρ’ ἄγον· οὐλομένης δὲ θεᾶς πορσύνετο μῆτις<br>Κύπριδος, ἥ τέ σφιν θυμοφθόρον ἔμβαλεν ἄτην.<br>δὴ γὰρ κουριδίας μὲν ἀπέστυγον, ἐκ δὲ μελάθρων,<br>ᾗ ματίῃ εἴξαντες, ἀπεσσεύοντο γυναῖκας·<br>αὐτὰρ ληιάδεσσι δορικτήταις παρίαυον,<br>σχέτλιοι. ἦ μὲν δηρὸν ἐτέτλαμεν, εἴ κέ ποτ’ αὖτις<br>ὀψὲ μεταστρέψωσι νόον· τὸ δὲ διπλόον αἰεὶ<br>πῆμα κακὸν προύβαινεν. ἀτιμάζοντο δὲ τέκνα<br>γνήσι’ ἐνὶ μεγάροις, σκοτίη δ’ ἀνέτελλε γενέθλη.<br>αὔτως δ’ ἀδμῆτές τε κόραι, χῆραί τ’ ἐπὶ τῇσιν<br>μητέρες ἂμ πτολίεθρον ἀτημελέες ἀλάληντο.<br>οὐδὲ πατὴρ ὀλίγον περ ἑῆς ἀλέγιζε θυγατρός,<br>εἰ καὶ ἐν ὀφθαλμοῖσι δαϊζομένην ὁρόῳτο<br>μητρυιῆς ὑπὸ χερσὶν ἀτασθάλου· οὐδ’ ἀπὸ μητρὸς<br>λώβην, ὡς τὸ πάροιθεν, ἀεικέα παῖδες ἄμυνον·<br>οὐδὲ κασιγνήτοισι κασιγνήτη μέλε θυμῷ.<br>ἀλλ’ οἶαι κοῦραι ληίτιδες ἔν τε δόμοισιν<br>ἔν τε χοροῖς ἀγορῇ τε καὶ εἰλαπίνῃσι μέλοντο·<br>εἰσόκε τις θεὸς ἄμμιν ὑπέρβιον ἔμβαλε θάρσος,<br>ἂψ ἀναερχομένους Θρῃκῶν ἄπο μηκέτι πύργοις<br>δέχθαι, ἵν’ ἢ φρονέοιεν ἅπερ θέμις, ἠέ πῃ ἄλλῃ<br>αὐταῖς ληιάδεσσιν ἀφορμηθέντες ἵκοιντο.<br>οἱ δ’ ἄρα θεσσάμενοι παίδων γένος, ὅσσον ἔλειπτο<br>ἄρσεν ἀνὰ πτολίεθρον, ἔβαν πάλιν, ἔνθ’ ἔτι νῦν περ<br>Θρηικίης ἄροσιν χιονώδεα ναιετάουσιν.<br>τῶ ὑμεῖς στρωφᾶσθ’ ἐπιδήμιοι· εἰ δέ κεν αὖθι<br>ναιετάειν ἐθέλοις, καί τοι ἅδοι, ἦ τ’ ἂν ἔπειτα<br>πατρὸς ἐμεῖο Θόαντος ἔχοις γέρας· οὐδέ τί σ’ οἴω<br>γαῖαν ὀνόσσεσθαι· περὶ γὰρ βαθυλήιος ἄλλων<br>νήσων, Αἰγαίῃ ὅσαι εἰν ἁλὶ ναιετάουσιν.<br>ἀλλ’ ἄγε νῦν ἐπὶ νῆα κιὼν ἑτάροισιν ἐνίσπες<br>μύθους ἡμετέρους, μηδ’ ἔκτοθι μίμνε πόληος.”", "st": "1.793"}, {"sp": "N", "t": "Ἴσκεν, ἀμαλδύνουσα φόνου τέλος, οἷον ἐτύχθη<br>ἀνδράσιν· αὐτὰρ ὁ τήνγε παραβλήδην προσέειπεν", "st": "1.834"}, {"sp": "N", "t": "“Ὑψιπύλη, μάλα κεν θυμηδέος ἀντιάσαιμεν<br>χρησμοσύνης, ἣν ἄμμι σέθεν χατέουσιν ὀπάζεις.<br>εἶμι δ’ ὑπότροπος αὖτις ἀνὰ πτόλιν, εὖτ’ ἂν ἕκαστα<br>ἐξείπω κατὰ κόσμον. ἀνακτορίη δὲ μελέσθω<br>σοίγ’ αὐτῇ καὶ νῆσος· ἔγωγε μὲν οὐκ ἀθερίζων<br>χάζομαι, ἀλλά με λυγροὶ ἐπισπέρχουσιν ἄεθλοι.”", "st": "1.836"}, {"sp": "N", "t": "ἦ, καὶ δεξιτερῆς χειρὸς θίγεν· αἶψα δ’ ὀπίσσω<br>βῆ ῥ’ ἴμεν, ἀμφὶ δὲ τόνγε νεήνιδες ἄλλοθεν ἄλλαι<br>μυρίαι εἱλίσσοντο κεχαρμέναι, ὄφρα πυλάων<br>ἐξέμολεν. μετέπειτα δ’ ἐυτροχάλοισιν ἀμάξαις<br>ἀκτὴν εἰσαπέβαν, ξεινήια πολλὰ φέρουσαι,<br>μῦθον ὅτ’ ἤδη πάντα διηνεκέως ἀγόρευσεν,<br>τόν ῥα καλεσσαμένη διεπέφραδεν Ὑψιπύλεια·<br>καὶ δ’ αὐτοὺς ξεινοῦσθαι ἐπὶ σφέα δώματ’ ἄγεσκον<br>ῥηιδίως. Κύπρις γὰρ ἐπὶ γλυκὺν ἵμερον ὦρσεν<br>Ἡφαίστοιο χάριν πολυμήτιος, ὄφρα κεν αὖτις<br>ναίηται μετόπισθεν ἀκήρατος ἀνδράσι Λῆμνος.", "st": "1.842"}, {"sp": "N", "t": "ἔνθ’ ὁ μὲν Ὑψιπύλης βασιλήιον ἐς δόμον ὦρτο<br>Αἰσονίδης· οἱ δ’ ἄλλοι ὅπῃ καὶ ἔκυρσαν ἕκαστος,<br>Ἡρακλῆος ἄνευθεν, ὁ γὰρ παρὰ νηὶ λέλειπτο<br>αὐτὸς ἑκὼν παῦροί τε διακρινθέντες ἑταῖροι.<br>αὐτίκα δ’ ἄστυ χοροῖσι καὶ εἰλαπίνῃσι γεγήθει<br>καπνῷ κνισήεντι περίπλεον· ἔξοχα δ’ ἄλλων<br>ἀθανάτων Ἥρης υἷα κλυτὸν ἠδὲ καὶ αὐτὴν<br>Κύπριν ἀοιδῇσιν θυέεσσί τε μειλίσσοντο.<br>ἀμβολίη δ’ εἰς ἦμαρ ἀεὶ ἐξ ἤματος ἦεν<br>ναυτιλίης· δηρὸν δ’ ἂν ἐλίνυον αὖθι μένοντες,<br>εἰ μὴ ἀολλίσσας ἑτάρους ἀπάνευθε γυναικῶν<br>Ἡρακλέης τοίοισιν ἐνιπτάζων μετέειπεν·", "st": "1.853"}, {"sp": "N", "t": "“δαιμόνιοι, πάτρης ἐμφύλιον αἷμ’ ἀποέργει<br>ἡμέας; ἦε γάμων ἐπιδευέες ἐνθάδ’ ἔβημεν<br>κεῖθεν, ὀνοσσάμενοι πολιήτιδας; αὖθι δ’ ἕαδεν<br>ναίοντας λιπαρὴν ἄροσιν Λήμνοιο ταμέσθαι;<br>οὐ μὰν εὐκλειεῖς γε σὺν ὀθνείῃσι γυναιξὶν<br>ἐσσόμεθ’ ὧδ’ ἐπὶ δηρὸν ἐελμένοι· οὐδέ τι κῶας<br>αὐτόματον δώσει τις ἑλὼν θεὸς εὐξαμένοισιν.<br>ἴομεν αὖτις ἕκαστοι ἐπὶ σφέα· τὸν δ’ ἐνὶ λέκτροις<br>Ὑψιπύλης εἰᾶτε πανήμερον, εἰσόκε Λῆμνον<br>παισὶν ἐσανδρώσῃ, μεγάλη τέ ἑ βάξις ἵκηται.”", "st": "1.865"}, {"sp": "N", "t": "ὧς νείκεσσεν ὅμιλον· ἐναντία δ’ οὔ νύ τις ἔτλη<br>ὄμματ’ ἀνασχεθέειν, οὐδὲ προτιμυθήσασθαι·<br>ἀλλ’ αὔτως ἀγορῆθεν ἐπαρτίζοντο νέεσθαι<br>σπερχόμενοι. ταὶ δέ σφιν ἐπέδραμον, εὖτ’ ἐδάησαν.<br>ὡς δ’ ὅτε λείρια καλὰ περιβρομέουσι μέλισσαι<br>πέτρης ἐκχύμεναι σιμβληίδος, ἀμφὶ δὲ λειμὼν<br>ἑρσήεις γάνυται, ταὶ δὲ γλυκὺν ἄλλοτε ἄλλον<br>καρπὸν ἀμέργουσιν πεποτημέναι· ὧς ἄρα ταίγε<br>ἐνδυκὲς ἀνέρας ἀμφὶ κινυρόμεναι προχέοντο,<br>χερσί τε καὶ μύθοισιν ἐδεικανόωντο ἕκαστον,<br>εὐχόμεναι μακάρεσσιν ἀπήμονα νόστον ὀπάσσαι.<br>ὧς δὲ καὶ Ὑψιπύλη ἠρήσατο χεῖρας ἑλοῦσα<br>Αἰσονίδεω, τὰ δέ οἱ ῥέε δάκρυα χήτει ἰόντος·", "st": "1.875"}, {"sp": "N", "t": "“Νίσσεο, καὶ σὲ θεοὶ σὺν ἀπηρέσιν αὖτις ἑταίροις<br>χρύσειον βασιλῆι δέρος κομίσειαν ἄγοντα<br>αὔτως, ὡς ἐθέλεις καί τοι φίλον. ἥδε δὲ νῆσος<br>σκῆπτρά τε πατρὸς ἐμεῖο παρέσσεται, ἢν καὶ ὀπίσσω<br>δή ποτε νοστήσας ἐθέλῃς ἄψορρον ἱκέσθαι.<br>ῥηιδίως δ’ ἂν ἑοῖ καὶ ἀπείρονα λαὸν ἀγείραις<br>ἄλλων ἐκ πολίων· ἀλλ’ οὐ σύγε τήνδε μενοινὴν<br>σχήσεις, οὔτ’ αὐτὴ προτιόσσομαι ὧδε τελεῖσθαι.<br>μνώεο μὴν ἀπεών περ ὁμῶς καὶ νόστιμος ἤδη<br>Ὑψιπύλης· λίπε δ’ ἧμιν ἔπος, τό κεν ἐξανύσαιμι<br>πρόφρων, ἢν ἄρα δή με θεοὶ δώωσι τεκέσθαι.”", "st": "1.888"}, {"sp": "N", "t": "τὴν δ’ αὖτ’ Αἴσονος υἱὸς ἀγαιόμενος προσέειπεν·<br>“Ὑψιπύλη, τὰ μὲν οὕτω ἐναίσιμα πάντα γένοιτο<br>ἐκ μακάρων· τύνη δ’ ἐμέθεν πέρι θυμὸν ἀρείω<br>ἴσχαν’, ἐπεὶ πάτρην μοι ἅλις Πελίαο ἕκητι<br>ναιετάειν· μοῦνόν με θεοὶ λύσειαν ἀέθλων.<br>εἰ δ’ οὔ μοι πέπρωται ἐς Ἑλλάδα γαῖαν ἱκέσθαι<br>τηλοῦ ἀναπλώοντι, σὺ δ’ ἄρσενα παῖδα τέκηαι,<br>πέμπε μιν ἡβήσαντα Πελασγίδος ἔνδον Ἰωλκοῦ<br>πατρί τ’ ἐμῷ καὶ μητρὶ δύης ἄκος, ἢν ἄρα τούσγε<br>τέτμῃ ἔτι ζώοντας, ἵν’ ἄνδιχα τοῖο ἄνακτος<br>σφοῖσιν πορσύνωνται ἐφέστιοι ἐν μεγάροισιν.”", "st": "1.899"}, {"sp": "N", "t": "ἦ, καὶ ἔβαιν’ ἐπὶ νῆα παροίτατος· ὧς δὲ καὶ ἄλλοι<br>βαῖνον ἀριστῆες· λάζοντο δὲ χερσὶν ἐρετμὰ<br>ἐνσχερὼ ἑζόμενοι· πρυμνήσια δέ σφισιν Ἄργος<br>λῦσεν ὑπὲκ πέτρης ἁλιμυρέος. ἔνθ’ ἄρα τοίγε<br>κόπτον ὕδωρ δολιχῇσιν ἐπικρατέως ἐλάτῃσιν.<br>ἑσπέριοι δ’ Ὀρφῆος ἐφημοσύνῃσιν ἔκελσαν<br>νῆσον ἐς Ἠλέκτρης Ἀτλαντίδος, ὄφρα δαέντες<br>ἀρρήτους ἀγανῇσι τελεσφορίῃσι θέμιστας<br>σωότεροι κρυόεσσαν ὑπεὶρ ἅλα ναυτίλλοιντο.<br>τῶν μὲν ἔτ’ οὐ προτέρω μυθήσομαι· ἀλλὰ καὶ αὐτὴ<br>νῆσος ὁμῶς κεχάροιτο καὶ οἳ λάχον ὄργια κεῖνα<br>δαίμονες ἐνναέται, τὰ μὲν οὐ θέμις ἄμμιν ἀείδειν.", "st": "1.910"}, {"sp": "N", "t": "κεῖθεν δ’ εἰρεσίῃ Μέλανος διὰ βένθεα πόντου<br>ἱέμενοι τῇ μὲν Θρῃκῶν χθόνα, τῇ δὲ περαίην<br>Ἴμβρον ἔχον καθύπερθε· νέον γε μὲν ἠελίοιο<br>δυομένου Χερόνησον ἐπὶ προύχουσαν ἵκοντο.<br>ἔνθα σφιν λαιψηρὸς ἄη νότος, ἱστία δ’ οὔρῳ<br>στησάμενοι κούρης Ἀθαμαντίδος αἰπὰ ῥέεθρα<br>εἰσέβαλον· πέλαγος δὲ τὸ μὲν καθύπερθε λέλειπτο<br>ἦρι, τὸ δ’ ἐννύχιοι Ῥοιτειάδος ἔνδοθεν ἀκτῆς<br>μέτρεον, Ἰδαίην ἐπὶ δεξιὰ γαῖαν ἔχοντες.<br>Δαρδανίην δὲ λιπόντες ἐπιπροσέβαλλον Ἀβύδῳ,<br>Περκώτην δ’ ἐπὶ τῇ καὶ Ἀβαρνίδος ἠμαθόεσσαν<br>ἠιόνα ζαθέην τε παρήμειβον Πιτύειαν.<br>καὶ δὴ τοίγ’ ἐπὶ νυκτὶ διάνδιχα νηὸς ἰούσης<br>δίνῃ πορφύροντα διήνυσαν Ἑλλήσποντον.", "st": "1.922"}, {"sp": "N", "t": "ἔστι δέ τις αἰπεῖα Προποντίδος ἔνδοθι νῆσος<br>τυτθὸν ἀπὸ Φρυγίης πολυληίου ἠπείροιο<br>εἰς ἅλα κεκλιμένη, ὅσσον τ’ ἐπιμύρεται ἰσθμὸς<br>χέρσῳ ἐπιπρηνὴς καταειμένος· ἐν δέ οἱ ἀκταὶ<br>ἀμφίδυμοι, κεῖνται δ’ ὑπὲρ ὕδατος Αἰσήποιο.<br>Ἄρκτων μιν καλέουσιν ὄρος περιναιετάοντες·<br>καὶ τὸ μὲν ὑβρισταί τε καὶ ἄγριοι ἐνναίουσιν<br>Γηγενέες, μέγα θαῦμα περικτιόνεσσιν ἰδέσθαι.<br>ἓξ γὰρ ἑκάστῳ χεῖρες ὑπέρβιοι ἠερέθονται,<br>αἱ μὲν ἀπὸ στιβαρῶν ὤμων δύο, ταὶ δ’ ὑπένερθεν<br>τέσσαρες αἰνοτάτῃσιν ἐπὶ πλευρῇς ἀραρυῖαι.<br>ἰσθμὸν δ’ αὖ πεδίον τε Δολίονες ἀμφενέμοντο<br>ἀνέρες· ἐν δ’ ἥρως Αἰνήιος υἱὸς ἄνασσεν<br>Κύζικος, ὃν κούρη δίου τέκεν Εὐσώροιο<br>Αἰνήτη. τοὺς δ’ οὔτι καὶ ἔκπαγλοί περ ἐόντες<br>Γηγενέες σίνοντο, Ποσειδάωνος ἀρωγῇ·<br>τοῦ γὰρ ἔσαν τὰ πρῶτα Δολίονες ἐκγεγαῶτες.<br>ἔνθ’ Ἀργὼ προύτυψεν ἐπειγομένη ἀνέμοισιν<br>Θρηικίοις, Καλὸς δὲ λιμὴν ὑπέδεκτο θέουσαν.<br>κεῖσε καὶ εὐναίης ὀλίγον λίθον ἐκλύσαντες<br>Τίφυος ἐννεσίῃσιν ὑπὸ κρήνῃ ἐλίποντο,<br>κρήνῃ ὑπ’ Ἀρτακίῃ· ἕτερον δ’ ἕλον, ὅστις ἀρήρει,<br>βριθύν· ἀτὰρ κεῖνόν γε θεοπροπίαις Ἑκάτοιο<br>Νηλεΐδαι μετόπισθεν Ἰάονες ἱδρύσαντο<br>ἱερόν, ἣ θέμις ἦεν, Ἰησονίης ἐν Ἀθήνης.", "st": "1.936"}, {"sp": "N", "t": "τοὺς δ’ ἄμυδις φιλότητι Δολίονες ἠδὲ καὶ αὐτὸς<br>Κύζικος ἀντήσαντες ὅτε στόλον ἠδὲ γενέθλην<br>ἔκλυον, οἵτινες εἶεν, ἐυξείνως ἀρέσαντο,<br>καί σφεας εἰρεσίῃ πέπιθον προτέρωσε κιόντας<br>ἄστεος ἐν λιμένι πρυμνήσια νηὸς ἀνάψαι,<br>ἔνθ’ οἵγ’ Ἐκβασίῳ βωμὸν θέσαν Ἀπόλλωνι<br>εἱσάμενοι παρὰ θῖνα, θυηπολίης τ’ ἐμέλοντο.<br>δῶκεν δ’ αὐτὸς ἄναξ λαρὸν μέθυ δευομένοισιν<br>μῆλά θ’ ὁμοῦ· δὴ γάρ οἱ ἔην φάτις, εὖτ’ ἂν ἵκωνται<br>ἀνδρῶν ἡρώων θεῖος στόλος, αὐτίκα τόνγε<br>μείλιχον ἀντιάαν, μηδὲ πτολέμοιο μέλεσθαι.<br>ἶσόν που κἀκείνῳ ἐπισταχύεσκον ἴουλοι,<br>οὐδέ νύ πω παίδεσσιν ἀγαλλόμενος μεμόρητο·<br>ἀλλ’ ἔτι οἱ κατὰ δώματ’ ἀκήρατος ἦεν ἄκοιτις<br>ὠδίνων, Μέροπος Περκωσίου ἐκγεγαυῖα,<br>Κλείτη ἐυπλόκαμος, τὴν μὲν νέον ἐξέτι πατρὸς<br>θεσπεσίοις ἕδνοισιν ἀνήγαγεν ἀντιπέρηθεν.<br>ἀλλὰ καὶ ὧς θάλαμόν τε λιπὼν καὶ δέμνια νύμφης<br>τοῖς μέτα δαῖτ’ ἀλέγυνε, βάλεν δ’ ἀπὸ δείματα θυμοῦ.<br>ἀλλήλους δ’ ἐρέεινον ἀμοιβαδίς· ἤτοι ὁ μέν σφεων<br>πεύθετο ναυτιλίης ἄνυσιν, Πελίαό τ’ ἐφετμάς·<br>οἱ δὲ περικτιόνων πόλιας καὶ κόλπον ἅπαντα<br>εὐρείης πεύθοντο Προποντίδος· οὐ μὲν ἐπιπρὸ<br>ἠείδει καταλέξαι ἐελδομένοισι δαῆναι.<br>ἠοῖ δ’ εἰσανέβαν μέγα Δίνδυμον, ὄφρα καὶ αὐτοὶ<br>θηήσαιντο πόρους κείνης ἁλός· ἐκ δ’ ἄρα τοίγε<br>νῆα Χυτοῦ λιμένος προτέρω ἐξήλασαν ὅρμον·<br>ἥδε δ’ Ἰησονίη πέφαται ὁδός, ἥνπερ ἔβησαν.", "st": "1.961"}, {"sp": "N", "t": "Γηγενέες δ’ ἑτέρωθεν ἀπ’ οὔρεος ἀίξαντες<br>φράξαν ἀπειρεσίοιο Χυτοῦ στόμα νειόθι πέτρῃς<br>πόντιον, οἷά τε θῆρα λοχώμενοι ἔνδον ἐόντα.<br>ἀλλὰ γὰρ αὖθι λέλειπτο σὺν ἀνδράσιν ὁπλοτέροισιν<br>Ἡρακλέης, ὃς δή σφι παλίντονον αἶψα τανύσσας<br>τόξον ἐπασσυτέρους πέλασε χθονί· τοὶ δὲ καὶ αὐτοὶ<br>πέτρας ἀμφιρρῶγας ἀερτάζοντες ἔβαλλον.<br>δὴ γάρ που κἀκεῖνα θεὰ τρέφεν αἰνὰ πέλωρα<br>Ἥρη, Ζηνὸς ἄκοιτις, ἀέθλιον Ἡρακλῆι.<br>σὺν δὲ καὶ ὧλλοι δῆθεν ὑπότροποι ἀντιόωντες,<br>πρίν περ ἀνελθέμεναι σκοπιήν, ἥπτοντο φόνοιο<br>γηγενέων ἥρωες ἀρήιοι, ἠμὲν ὀιστοῖς<br>ἠδὲ καὶ ἐγχείῃσι δεδεγμένοι, εἰσόκε πάντας<br>ἀντιβίην ἀσπερχὲς ὀρινομένους ἐδάιξαν.<br>ὡς δ’ ὅτε δούρατα μακρὰ νέον πελέκεσσι τυπέντα<br>ὑλοτόμοι στοιχηδὸν ἐπὶ ῥηγμῖνι βάλωσιν,<br>ὄφρα νοτισθέντα κρατεροὺς ἀνεχοίατο γόμφους·<br>ὧς οἱ ἐνὶ ξυνοχῇ λιμένος πολιοῖο τέταντο<br>ἑξείης, ἄλλοι μὲν ἐς ἁλμυρὸν ἀθρόοι ὕδωρ<br>δύπτοντες κεφαλὰς καὶ στήθεα, γυῖα δ’ ὕπερθεν<br>χέρσῳ τεινάμενοι· τοὶ δ’ ἔμπαλιν, αἰγιαλοῖο<br>κράατα μὲν ψαμάθοισι, πόδας δ’ εἰς βένθος ἔρειδον,<br>ἄμφω ἅμ’ οἰωνοῖσι καὶ ἰχθύσι κύρμα γενέσθαι.", "st": "1.989"}, {"sp": "N", "t": "ἥρωες δ’, ὅτε δή σφιν ἀταρβὴς ἔπλετ’ ἄεθλος,<br>δὴ τότε πείσματα νηὸς ἐπὶ πνοιῇς ἀνέμοιο<br>λυσάμενοι προτέρωσε διὲξ ἁλὸς οἶδμα νέοντο.<br>ἡ δ’ ἔθεεν λαίφεσσι πανήμερος· οὐ μὲν ἰούσης<br>νυκτὸς ἔτι ῥιπὴ μένεν ἔμπεδον, ἀλλὰ θύελλαι<br>ἀντίαι ἁρπάγδην ὀπίσω φέρον, ὄφρ’ ἐπέλασσαν<br>αὖτις ἐυξείνοισι Δολίοσιν ἐκ δ’ ἄρ’ ἔβησαν<br>αὐτονυχί· ἱερὴ δὲ φατίζεται ἥδ’ ἔτι πέτρη,<br>ᾗ πέρι πείσματα νηὸς ἐπεσσύμενοι ἐβάλοντο.<br>οὐδέ τις αὐτὴν νῆσον ἐπιφραδέως ἐνόησεν<br>ἔμμεναι· οὐδ’ ὑπὸ νυκτὶ Δολίονες ἂψ ἀνιόντας<br>ἥρωας νημερτὲς ἐπήισαν· ἀλλά που ἀνδρῶν<br>Μακριέων εἴσαντο Πελασγικὸν ἄρεα κέλσαι.<br>τῶ καὶ τεύχεα δύντες ἐπὶ σφίσι χεῖρας ἄειραν.<br>σὺν δ’ ἔλασαν μελίας τε καὶ ἀσπίδας ἀλλήλοισιν<br>ὀξείῃ ἴκελοι ῥιπῇ πυρός, ἥ τ’ ἐνὶ θάμνοις<br>αὐαλέοισι πεσοῦσα κορύσσεται· ἐν δὲ κυδοιμὸς<br>δεινός τε ζαμενής τε Δολιονίῳ πέσε δήμῳ.<br>οὐδ’ ὅγε δηιοτῆτος ὑπὲρ μόρον αὖτις ἔμελλεν<br>οἴκαδε νυμφιδίους θαλάμους καὶ λέκτρον ἱκέσθαι.<br>ἀλλά μιν Αἰσονίδης τετραμμένον ἰθὺς ἑοῖο<br>πλῆξεν ἐπαΐξας στῆθος μέσον, ἀμφὶ δὲ δουρὶ<br>ὀστέον ἐρραίσθη· ὁ δ’ ἐνὶ ψαμάθοισιν ἐλυσθεὶς<br>μοῖραν ἀνέπλησεν. τὴν γὰρ θέμις οὔποτ’ ἀλύξαι<br>θνητοῖσιν· πάντῃ δὲ περὶ μέγα πέπταται ἕρκος.<br>ὧς τὸν ὀιόμενόν που ἀδευκέος ἔκτοθεν ἄτης<br>εἶναι ἀριστήων αὐτῇ ὑπὸ νυκτὶ πέδησεν<br>μαρνάμενον κείνοισι· πολεῖς δ’ ἐπαρηγόνες ἄλλοι<br>ἔκταθεν· Ἡρακλέης μὲν ἐνήρατο Τηλεκλῆα<br>ἠδὲ Μεγαβρόντην· Σφόδριν δ’ ἐνάριξεν Ἄκαστος·<br>Πηλεὺς δὲ Ζέλυν εἷλεν ἀρηίθοόν τε Γέφυρον.<br>αὐτὰρ ἐυμμελίης Τελαμὼν Βασιλῆα κατέκτα.<br>Ἴδας δ’ αὖ Προμέα, Κλυτίος δ’ Ὑάκινθον ἔπεφνεν,<br>Τυνδαρίδαι δ’ ἄμφω Μεγαλοσσάκεα Φλογίον τε.<br>Οἰνεΐδης δ’ ἐπὶ τοῖσιν ἕλεν θρασὺν Ἰτυμονῆα<br>ἠδὲ καὶ Ἀρτακέα, πρόμον ἀνδρῶν· οὓς ἔτι πάντας<br>ἐνναέται τιμαῖς ἡρωίσι κυδαίνουσιν.<br>οἱ δ’ ἄλλοι εἴξαντες ὑπέτρεσαν, ἠύτε κίρκους<br>ὠκυπέτας ἀγεληδὸν ὑποτρέσσωσι πέλειαι.<br>ἐς δὲ πύλας ὁμάδῳ πέσον ἀθρόοι· αἶψα δ’ ἀυτῆς<br>πλῆτο πόλις στονόεντος ὑποτροπίῃ πολέμοιο.<br>ἠῶθεν δ’ ὀλοὴν καὶ ἀμήχανον εἰσενόησαν<br>ἀμπλακίην ἄμφω· στυγερὸν δ’ ἄχος εἷλεν ἰδόντας<br>ἥρωας Μινύας Αἰνήιον υἷα πάροιθεν<br>Κύζικον ἐν κονίῃσι καὶ αἵματι πεπτηῶτα.<br>ἤματα δὲ τρία πάντα γόων, τίλλοντό τε χαίτας<br>αὐτοὶ ὁμῶς λαοί τε Δολίονες. αὐτὰρ ἔπειτα<br>τρὶς περὶ χαλκείοις σὺν τεύχεσι δινηθέντες<br>τύμβῳ ἐνεκτερέιξαν, ἐπειρήσαντό τ’ ἀέθλων,<br>ἣ θέμις, ἂμ πεδίον λειμώνιον, ἔνθ’ ἔτι νῦν περ<br>ἀγκέχυται τόδε σῆμα καὶ ὀψιγόνοισιν ἰδέσθαι.<br>οὐδὲ μὲν οὐδ’ ἄλοχος Κλείτη φθιμένοιο λέλειπτο<br>οὗ πόσιος μετόπισθε· κακῷ δ’ ἐπὶ κύντερον ἄλλο<br>ἤνυσεν, ἁψαμένη βρόχον αὐχένι. τὴν δὲ καὶ αὐταὶ<br>νύμφαι ἀποφθιμένην ἀλσηίδες ὠδύραντο·<br>καί οἱ ἀπὸ βλεφάρων ὅσα δάκρυα χεῦαν ἔραζε,<br>πάντα τάγε κρήνην τεῦξαν θεαί, ἣν καλέουσιν<br>Κλείτην, δυστήνοιο περικλεὲς οὔνομα νύμφης.<br>αἰνότατον δὴ κεῖνο Δολιονίῃσι γυναιξὶν<br>ἀνδράσι τ’ ἐκ Διὸς ἦμαρ ἐπήλυθεν· οὐδὲ γὰρ αὐτῶν<br>ἔτλη τις πάσσασθαι ἐδητύος, οὐδ’ ἐπὶ δηρὸν<br>ἐξ ἀχέων ἔργοιο μυληφάτου ἐμνώοντο·<br>ἀλλ’ αὔτως ἄφλεκτα διαζώεσκον ἔδοντες.<br>ἔνθ’ ἔτι νῦν, εὖτ’ ἄν σφιν ἐτήσια χύτλα χέωνται<br>Κύζικον ἐνναίοντες Ἰάονες, ἔμπεδον αἰεὶ<br>πανδήμοιο μύλης πελάνους ἐπαλετρεύουσιν.", "st": "1.1012"}, {"sp": "N", "t": "ἐκ δὲ τόθεν τρηχεῖαι ἀνηέρθησαν ἄελλαι<br>ἤμαθ’ ὁμοῦ νύκτας τε δυώδεκα, τοὺς δὲ καταῦθι<br>ναυτίλλεσθαι ἔρυκον. ἐπιπλομένῃ δ’ ἐνὶ νυκτὶ<br>ὧλλοι μέν ῥα πάρος δεδμημένοι εὐνάζοντο<br>ὕπνῳ ἀριστῆες πύματον λάχος· αὐτὰρ Ἄκαστος<br>Μόψος τ’ Ἀμπυκίδης ἀδινὰ κνώσσοντας ἔρυντο.<br>ἡ δ’ ἄρ’ ὑπὲρ ξανθοῖο καρήατος Αἰσονίδαο<br>πωτᾶτ’ ἀλκυονὶς λιγυρῇ ὀπὶ θεσπίζουσα<br>λῆξιν ὀρινομένων ἀνέμων· συνέηκε δὲ Μόψος<br>ἀκταίης ὄρνιθος ἐναίσιμον ὄσσαν ἀκούσας.<br>καὶ τὴν μὲν θεὸς αὖτις ἀπέτραπεν, ἷζε δ’ ὕπερθεν<br>νηίου ἀφλάστοιο μετήορος ἀίξασα.<br>τὸν δ’ ὅγε κεκλιμένον μαλακοῖς ἐνὶ κώεσιν οἰῶν.<br>κινήσας ἀνέγειρε παρασχεδόν, ὧδέ τ’ ἔειπεν·", "st": "1.1078"}, {"sp": "N", "t": "“Αἰσονίδη, χρειώ σε τόδ’ ἱερὸν εἰσανιόντα<br>Δινδύμου ὀκριόεντος ἐύθρονον ἱλάξασθαι<br>μητέρα συμπάντων μακάρων· λήξουσι δ’ ἄελλαι<br>ζαχρηεῖς· τοίην γὰρ ἐγὼ νέον ὄσσαν ἄκουσα<br>ἀλκυόνος ἁλίης, ἥ τε κνώσσοντος ὕπερθεν<br>σεῖο πέριξ τὰ ἕκαστα πιφαυσκομένη πεπότηται.<br>ἐκ γὰρ τῆς ἄνεμοί τε θάλασσά τε νειόθι τε χθὼν<br>πᾶσα πεπείρανται νιφόεν θ’ ἕδος Οὐλύμποιο·<br>καί οἱ, ὅτ’ ἐξ ὀρέων μέγαν οὐρανὸν εἰσαναβαίνῃ,<br>Ζεὺς αὐτὸς Κρονίδης ὑποχάζεται. ὧς δὲ καὶ ὧλλοι<br>ἀθάνατοι μάκαρες δεινὴν θεὸν ἀμφιέπουσιν.”", "st": "1.1092"}, {"sp": "N", "t": "ὧς φάτο· τῷ δ’ ἀσπαστὸν ἔπος γένετ’ εἰσαΐοντι.<br>ὤρνυτο δ’ ἐξ εὐνῆς κεχαρημένος· ὦρσε δ’ ἑταίρους<br>πάντας ἐπισπέρχων, καί τέ σφισιν ἐγρομένοισιν<br>Ἀμπυκίδεω Μόψοιο θεοπροπίας ἀγόρευεν.<br>αἶψα δὲ κουρότεροι μὲν ἀπὸ σταθμῶν ἐλάσαντες<br>ἔνθεν ἐς αἰπεινὴν ἄναγον βόας οὔρεος ἄκρην.<br>οἱ δ’ ἄρα λυσάμενοι Ἱερῆς ἐκ πείσματα πέτρης<br>ἤρεσαν ἐς λιμένα Θρηίκιον· ἂν δὲ καὶ αὐτοὶ<br>βαῖνον, παυροτέρους ἑτάρων ἐν νηὶ λιπόντες.<br>τοῖσι δὲ Μακριάδες σκοπιαὶ καὶ πᾶσα περαίη<br>Θρηικίης ἐνὶ χερσὶν ἑαῖς προυφαίνετ’ ἰδέσθαι·<br>φαίνετο δ’ ἠερόεν στόμα Βοσπόρου ἠδὲ κολῶναι<br>Μυσίαι· ἐκ δ’ ἑτέρης ποταμοῦ ῥόος Αἰσήποιο<br>ἄστυ τε καὶ πεδίον Νηπήιον Ἀδρηστείης.<br>ἔσκε δέ τι στιβαρὸν στύπος ἀμπέλου ἔντροφον ὕλῃ,<br>πρόχνυ γεράνδρυον· τὸ μὲν ἔκταμον, ὄφρα πέλοιτο<br>δαίμονος οὐρείης ἱερὸν βρέτας· ἔξεσε δ’ Ἄργος<br>εὐκόσμως, καὶ δή μιν ἐπ’ ὀκριόεντι κολωνῷ<br>ἵδρυσαν φηγοῖσιν ἐπηρεφὲς ἀκροτάτῃσιν,<br>αἵ ῥά τε πασάων πανυπέρταται ἐρρίζωνται.<br>βωμὸν δ’ αὖ χέραδος παρενήνεον· ἀμφὶ δὲ φύλλοις<br>στεψάμενοι δρυΐνοισι θυηπολίης ἐμέλοντο<br>Μητέρα Δινδυμίην πολυπότνιαν ἀγκαλέοντες,<br>ἐνναέτιν Φρυγίης, Τιτίην θ’ ἅμα Κύλληνόν τε,<br>οἳ μοῦνοι πολέων μοιρηγέται ἠδὲ πάρεδροι<br>Μητέρος Ἰδαίης κεκλήαται, ὅσσοι ἔασιν<br>δάκτυλοι Ἰδαῖοι Κρηταιέες, οὕς ποτε νύμφη<br>Ἀγχιάλη Δικταῖον ἀνὰ σπέος ἀμφοτέρῃσιν<br>δραξαμένη γαίης Οἰαξίδος ἐβλάστησεν.<br>πολλὰ δὲ τήνγε λιτῇσιν ἀποστρέψαι ἐριώλας<br>Αἰσονίδης γουνάζετ’ ἐπιλλείβων ἱεροῖσιν<br>αἰθομένοις· ἄμυδις δὲ νέοι Ὀρφῆος ἀνωγῇ<br>σκαίροντες βηταρμὸν ἐνόπλιον ὠρχήσαντο,<br>καὶ σάκεα ξιφέεσσιν ἐπέκτυπον, ὥς κεν ἰωὴ<br>δύσφημος πλάζοιτο δι’ ἠέρος, ἣν ἔτι λαοὶ<br>κηδείῃ βασιλῆος ἀνέστενον. ἔνθεν ἐσαιεὶ<br>ῥόμβῳ καὶ τυπάνῳ Ῥείην Φρύγες ἱλάσκονται.<br>ἡ δέ που εὐαγέεσσιν ἐπὶ φρένα θῆκε θυηλαῖς<br>ἀνταίη δαίμων· τὰ δ’ ἐοικότα σήματ’ ἔγεντο.<br>δένδρεα μὲν καρπὸν χέον ἄσπετον, ἀμφὶ δὲ ποσσὶν<br>αὐτομάτη φύε γαῖα τερείνης ἄνθεα ποίης.<br>θῆρες δ’ εἰλυούς τε κατὰ ξυλόχους τε λιπόντες<br>οὐρῇσιν σαίνοντες ἐπήλυθον. ἡ δὲ καὶ ἄλλο<br>θῆκε τέρας· ἐπεὶ οὔτι παροίτερον ὕδατι νᾶεν<br>Δίνδυμον· ἀλλά σφιν τότ’ ἀνέβραχε διψάδος αὔτως<br>ἐκ κορυφῆς ἄλληκτον· Ἰησονίην δ’ ἐνέπουσιν<br>κεῖνο ποτὸν κρήνην περιναιέται ἄνδρες ὀπίσσω.<br>καὶ τότε μὲν δαῖτ’ ἀμφὶ θεᾶς θέσαν οὔρεσιν Ἄρκτων,<br>μέλποντες Ῥείην πολυπότνιαν· αὐτὰρ ἐς ἠὼ<br>ληξάντων ἀνέμων νῆσον λίπον εἰρεσίῃσιν.", "st": "1.1103"}, {"sp": "N", "t": "ἔνθ’ ἔρις ἄνδρα ἕκαστον ἀριστήων ὀρόθυνεν,<br>ὅστις ἀπολλήξειε πανύστατος. ἀμφὶ γὰρ αἰθὴρ<br>νήνεμος ἐστόρεσεν δίνας, κατὰ δ’ εὔνασε πόντον.<br>οἱ δὲ γαληναίῃ πίσυνοι ἐλάασκον ἐπιπρὸ<br>νῆα βίῃ· τὴν δ’ οὔ κε διὲξ ἁλὸς ἀίσσουσαν<br>οὐδὲ Ποσειδάωνος ἀελλόποδες κίχον ἵπποι.<br>ἔμπης δ’ ἐγρομένοιο σάλου ζαχρηέσιν αὔραις,<br>αἳ νέον ἐκ ποταμῶν ὑπὸ δείελον ἠερέθονται,<br>τειρόμενοι καὶ δὴ μετελώφεον· αὐτὰρ ὁ τούσγε<br>πασσυδίῃ μογέοντας ἐφέλκετο κάρτεϊ χειρῶν<br>Ἡρακλέης, ἐτίνασσε δ’ ἀρηρότα δούρατα νηός.<br>ἀλλ’ ὅτε δὴ Μυσῶν λελιημένοι ἠπείροιο<br>Ῥυνδακίδας προχοὰς μέγα τ’ ἠρίον Αἰγαίωνος<br>τυτθὸν ὑπὲκ Φρυγίης παρεμέτρεον εἰσορόωντες,<br>δὴ τότ’ ἀνοχλίζων τετρηχότος οἴδματος ὁλκοὺς<br>μεσσόθεν ἆξεν ἐρετμόν. ἀτὰρ τρύφος ἄλλο μὲν αὐτὸς<br>ἄμφω χερσὶν ἔχων πέσε δόχμιος, ἄλλο δὲ πόντος<br>κλύζε παλιρροθίοισι φέρων. ἀνὰ δ’ ἕζετο σιγῇ<br>παπταίνων· χεῖρες γὰρ ἀήθεον ἠρεμέουσαι.", "st": "1.1153"}, {"sp": "N", "t": "ἦμος δ’ ἀγρόθεν εἶσι φυτοσκάφος ἤ τις ἀροτρεὺς<br>ἀσπασίως εἰς αὖλιν ἑήν, δόρποιο χατίζων,<br>αὐτοῦ δ’ ἐν προμολῇ τετρυμένα γούνατ’ ἔκαμψεν<br>αὐσταλέος κονίῃσι, περιτριβέας δέ τε χεῖρας<br>εἰσορόων κακὰ πολλὰ ἑῇ ἠρήσατο γαστρί·<br>τῆμος ἄρ’ οἵγ’ ἀφίκοντο Κιανίδος ἤθεα γαίης<br>ἀμφ’ Ἀργανθώνειον ὄρος προχοάς τε Κίοιο.<br>τοὺς μὲν ἐυξείνως Μυσοὶ φιλότητι κιόντας<br>δειδέχατ’, ἐνναέται κείνης χθονός, ἤιά τέ σφιν<br>μῆλά τε δευομένοις μέθυ τ’ ἄσπετον ἐγγυάλιξαν.<br>ἔνθα δ’ ἔπειθ’ οἱ μὲν ξύλα κάγκανα, τοὶ δὲ λεχαίην<br>φυλλάδα λειμώνων φέρον ἄσπετον ἀμήσαντες,<br>στόρνυσθαι· τοὶ δ’ ἀμφὶ πυρήια δινεύεσκον·<br>οἱ δ’ οἶνον κρητῆρσι κέρων, πονέοντό τε δαῖτα,<br>Ἐκβασίῳ ῥέξαντες ὑπὸ κνέφας Ἀπόλλωνι.", "st": "1.1172"}, {"sp": "N", "t": "αὐτὰρ ὁ δαίνυσθαι ἑτάροις οἷς εὖ ἐπιτείλας<br>βῆ ῥ’ ἴμεν εἰς ὕλην υἱὸς Διός, ὥς κεν ἐρετμὸν<br>οἷ αὐτῷ φθαίη καταχείριον ἐντύνασθαι.<br>εὗρεν ἔπειτ’ ἐλάτην ἀλαλήμενος, οὔτε τι πολλοῖς<br>ἀχθομένην ὄζοις, οὐδὲ μέγα τηλεθόωσαν,<br>ἀλλ’ οἷον ταναῆς ἔρνος πέλει αἰγείροιο·<br>τόσση ὁμῶς μῆκός τε καὶ ἐς πάχος ἦεν ἰδέσθαι.<br>ῥίμφα δ’ ὀιστοδόκην μὲν ἐπὶ χθονὶ θῆκε φαρέτρην<br>αὐτοῖσιν τόξοισιν, ἔδυ δ’ ἀπὸ δέρμα λέοντος.<br>τὴν δ’ ὅγε χαλκοβαρεῖ ῥοπάλῳ δαπέδοιο τινάξας<br>νειόθεν ἀμφοτέρῃσι περὶ στύπος ἔλλαβε χερσίν,<br>ἠνορέῃ πίσυνος· ἐν δὲ πλατὺν ὦμον ἔρεισεν<br>εὖ διαβάς· πεδόθεν δὲ βαθύρριζόν περ ἐοῦσαν<br>προσφὺς ἐξήειρε σὺν αὐτοῖς ἔχμασι γαίης.<br>ὡς δ’ ὅταν ἀπροφάτως ἱστὸν νεός, εὖτε μάλιστα<br>χειμερίη ὀλοοῖο δύσις πέλει Ὠρίωνος,<br>ὑψόθεν ἐμπλήξασα θοὴ ἀνέμοιο κατάιξ<br>αὐτοῖσι σφήνεσσιν ὑπὲκ προτόνων ἐρύσηται·<br>ὧς ὅγε τὴν ἤειρεν. ὁμοῦ δ’ ἀνὰ τόξα καὶ ἰοὺς<br>δέρμα θ’ ἑλὼν ῥόπαλόν τε παλίσσυτος ὦρτο νέεσθαι.", "st": "1.1187"}, {"sp": "N", "t": "τόφρα δ’ Ὕλας χαλκέῃ σὺν κάλπιδι νόσφιν ὁμίλου<br>δίζητο κρήνης ἱερὸν ῥόον, ὥς κέ οἱ ὕδωρ<br>φθαίη ἀφυσσάμενος ποτιδόρπιον, ἄλλα τε πάντα<br>ὀτραλέως κατὰ κόσμον ἐπαρτίσσειεν ἰόντι.<br>δὴ γάρ μιν τοίοισιν ἐν ἤθεσιν αὐτὸς ἔφερβεν,<br>νηπίαχον τὰ πρῶτα δόμων ἐκ πατρὸς ἀπούρας,<br>δίου Θειοδάμαντος, ὃν ἐν Δρυόπεσσιν ἔπεφνεν<br>νηλειῶς, βοὸς ἀμφὶ γεωμόρου ἀντιόωντα.<br>ἤτοι ὁ μὲν νειοῖο γύας τέμνεσκεν ἀρότρῳ<br>Θειοδάμας ἀνίῃ βεβολημένος· αὐτὰρ ὁ τόνγε<br>βοῦν ἀρότην ἤνωγε παρασχέμεν οὐκ ἐθέλοντα.<br>ἵετο γὰρ πρόφασιν πολέμου Δρυόπεσσι βαλέσθαι<br>λευγαλέην, ἐπεὶ οὔτι δίκης ἀλέγοντες ἔναιον.<br>ἀλλὰ τὰ μὲν τηλοῦ κεν ἀποπλάγξειεν ἀοιδῆς.<br>αἶψα δ’ ὅγε κρήνην μετεκίαθεν, ἣν καλέουσιν<br>Πηγὰς ἀγχίγυοι περιναιέται. οἱ δέ που ἄρτι<br>νυμφάων ἵσταντο χοροί· μέλε γάρ σφισι πάσαις,<br>ὅσσαι κεῖσ’ ἐρατὸν νύμφαι ῥίον ἀμφενέμοντο,<br>Ἄρτεμιν ἐννυχίῃσιν ἀεὶ μέλπεσθαι ἀοιδαῖς.<br>αἱ μέν, ὅσαι σκοπιὰς ὀρέων λάχον ἢ καὶ ἐναύλους,<br>αἵγε μὲν ὑλήωροι ἀπόπροθεν ἐστιχόωντο,<br>ἡ δὲ νέον κρήνης ἀνεδύετο καλλινάοιο<br>νύμφη ἐφυδατίη· τὸν δὲ σχεδὸν εἰσενόησεν<br>κάλλεϊ καὶ γλυκερῇσιν ἐρευθόμενον χαρίτεσσιν.<br>πρὸς γάρ οἱ διχόμηνις ἀπ’ αἰθέρος αὐγάζουσα<br>βάλλε σεληναίη. τὴν δὲ φρένας ἐπτοίησεν<br>Κύπρις, ἀμηχανίῃ δὲ μόλις συναγείρατο θυμόν.<br>αὐτὰρ ὅγ’ ὡς τὰ πρῶτα ῥόῳ ἔνι κάλπιν ἔρεισεν<br>λέχρις ἐπιχριμφθείς, περὶ δ’ ἄσπετον ἔβραχεν ὕδωρ<br>χαλκὸν ἐς ἠχήεντα φορεύμενον, αὐτίκα δ’ ἥγε<br>λαιὸν μὲν καθύπερθεν ἐπ’ αὐχένος ἄνθετο πῆχυν<br>κύσσαι ἐπιθύουσα τέρεν στόμα· δεξιτερῇ δὲ<br>ἀγκῶν’ ἔσπασε χειρί, μέσῃ δ’ ἐνικάββαλε δίνῃ.", "st": "1.1207"}, {"sp": "N", "t": "τοῦ δ’ ἥρως ἰάχοντος ἐπέκλυεν οἶος ἑταίρων<br>Εἰλατίδης Πολύφημος, ἰὼν προτέρωσε κελεύθου,<br>δέκτο γὰρ Ἡρακλῆα πελώριον, ὁππόθ’ ἵκοιτο.<br>βῆ δὲ μεταΐξας Πηγέων σχεδόν, ἠύτε τις θὴρ<br>ἄγριος, ὅν ῥά τε γῆρυς ἀπόπροθεν ἵκετο μήλων,<br>λιμῷ δ’ αἰθόμενος μετανίσσεται, οὐδ’ ἐπέκυρσεν<br>ποίμνῃσιν· πρὸ γὰρ αὐτοὶ ἐνὶ σταθμοῖσι νομῆες<br>ἔλσαν· ὁ δὲ στενάχων βρέμει ἄσπετον, ὄφρα κάμῃσιν·<br>ὧς τότ’ ἄρ’ Εἰλατίδης μεγάλ’ ἔστενεν, ἀμφὶ δὲ χῶρον<br>φοίτα κεκληγώς· μελέη δέ οἱ ἔπλετο φωνή.<br>αἶψα δ’ ἐρυσσάμενος μέγα φάσγανον ὦρτο δίεσθαι,<br>μήπως ἢ θήρεσσιν ἕλωρ πέλοι, ἠέ μιν ἄνδρες<br>μοῦνον ἐόντ’ ἐλόχησαν, ἄγουσι δὲ ληίδ’ ἑτοίμην.<br>ἔνθ’ αὐτῷ ξύμβλητο κατὰ στίβον Ἡρακλῆι<br>γυμνὸν ἐπαΐσσων παλάμῃ ξίφος· εὖ δέ μιν ἔγνω<br>σπερχόμενον μετὰ νῆα διὰ κνέφας. αὐτίκα δ’ ἄτην<br>ἔκφατο λευγαλέην, βεβαρημένος ἄσθματι θυμόν·", "st": "1.1240"}, {"sp": "N", "t": "“δαιμόνιε, στυγερόν τοι ἄχος πάμπρωτος ἐνίψω.<br>οὐ γὰρ Ὕλας κρήνηνδε κιὼν σόος αὖτις ἱκάνει.<br>ἀλλά ἑ ληιστῆρες ἐνιχρίμψαντες ἄγουσιν,<br>ἢ θῆρες σίνονται· ἐγὼ δ’ ἰάχοντος ἄκουσα.”", "st": "1.1257"}, {"sp": "N", "t": "ὧς φάτο· τῷ δ’ ἀίοντι κατὰ κροτάφων ἅλις ἱδρὼς<br>κήκιεν, ἐν δὲ κελαινὸν ὑπὸ σπλάγχνοις ζέεν αἷμα.<br>χωόμενος δ’ ἐλάτην χαμάδις βάλεν, ἐς δὲ κέλευθον<br>τὴν θέεν, ᾗ πόδες αὐτὸν ὑπέκφερον ἀίσσοντα.<br>ὡς δ’ ὅτε τίς τε μύωπι τετυμμένος ἔσσυτο ταῦρος<br>πίσεά τε προλιπὼν καὶ ἑλεσπίδας, οὐδὲ νομήων<br>οὐδ’ ἀγέλης ὄθεται, πρήσσει δ’ ὁδόν, ἄλλοτ’ ἄπαυστος,<br>ἄλλοτε δ’ ἱστάμενος, καὶ ἀνὰ πλατὺν αὐχέν’ ἀείρων<br>ἵησιν μύκημα, κακῷ βεβολημένος οἴστρῳ·<br>ὧς ὅγε μαιμώων ὁτὲ μὲν θοὰ γούνατ’ ἔπαλλεν<br>συνεχέως, ὁτὲ δ’ αὖτε μεταλλήγων καμάτοιο<br>τῆλε διαπρύσιον μεγάλῃ βοάασκεν ἀυτῇ.", "st": "1.1261"}, {"sp": "N", "t": "αὐτίκα δ’ ἀκροτάτας ὑπερέσχεθεν ἄκριας ἀστὴρ<br>ἠῷος, πνοιαὶ δὲ κατήλυθον· ὦκα δὲ Τῖφυς<br>ἐσβαίνειν ὀρόθυνεν, ἐπαύρεσθαί τ’ ἀνέμοιο.<br>οἱ δ’ εἴσβαινον ἄφαρ λελιημένοι· ὕψι δὲ νηὸς<br>εὐναίας ἐρύσαντες ἀνεκρούσαντο κάλωας.<br>κυρτώθη δ’ ἀνέμῳ λίνα μεσσόθι, τῆλε δ’ ἀπ’ ἀκτῆς<br>γηθόσυνοι φορέοντο παραὶ Ποσιδήιον ἄκρην.<br>ἦμος δ’ οὐρανόθεν χαροπὴ ὑπολάμπεται ἠὼς<br>ἐκ περάτης ἀνιοῦσα, διαγλαύσσουσι δ’ ἀταρποί,<br>καὶ πεδία δροσόεντα φαεινῇ λάμπεται αἴγλῃ,<br>τῆμος τούσγ’ ἐνόησαν ἀιδρείῃσι λιπόντες.<br>ἐν δέ σφιν κρατερὸν νεῖκος πέσεν, ἐν δὲ κολῳὸς<br>ἄσπετος, εἰ τὸν ἄριστον ἀποπρολιπόντες ἔβησαν<br>σφωιτέρων ἑτάρων. ὁ δ’ ἀμηχανίῃσιν ἀτυχθεὶς<br>οὔτε τι τοῖον ἔπος μετεφώνεεν, οὔτε τι τοῖον<br>Αἰσονίδης· ἀλλ’ ἧστο βαρείῃ νειόθεν ἄτῃ<br>θυμὸν ἔδων· Τελαμῶνα δ’ ἕλεν χόλος, ὧδέ τ’ ἔειπεν·", "st": "1.1273"}, {"sp": "N", "t": "“ἧσ’ αὔτως εὔκηλος, ἐπεί νύ τοι ἄρμενον ἦεν<br>Ἡρακλῆα λιπεῖν· σέο δ’ ἔκτοθι μῆτις ὄρωρεν,<br>ὄφρα τὸ κείνου κῦδος ἀν’ Ἑλλάδα μή σε καλύψῃ,<br>αἴ κε θεοὶ δώωσιν ὑπότροπον οἴκαδε νόστον.<br>ἀλλὰ τί μύθων ἦδος; ἐπεὶ καὶ νόσφιν ἑταίρων<br>εἶμι τεῶν, οἳ τόνγε δόλον συνετεκτήναντο.”", "st": "1.1290"}, {"sp": "N", "t": "ἦ, καὶ ἐς Ἁγνιάδην Τῖφυν θόρε· τὼ δέ οἱ ὄσσε<br>ὄστλιγγες μαλεροῖο πυρὸς ὣς ἰνδάλλοντο.<br>καί νύ κεν ἂψ ὀπίσω Μυσῶν ἐπὶ γαῖαν ἵκοντο<br>λαῖτμα βιησάμενοι ἀνέμου τ’ ἄλληκτον ἰωήν,<br>εἰ μὴ Θρηικίοιο δύω υἷες Βορέαο<br>Αἰακίδην χαλεποῖσιν ἐρητύεσκον ἔπεσσιν,<br>σχέτλιοι· ἦ τέ σφιν στυγερὴ τίσις ἔπλετ’ ὀπίσσω<br>χερσὶν ὑφ’ Ἡρακλῆος, ὅ μιν δίζεσθαι ἔρυκον.<br>ἄθλων γὰρ Πελίαο δεδουπότος ἂψ ἀνιόντας<br>τήνῳ ἐν ἀμφιρύτῃ πέφνεν, καὶ ἀμήσατο γαῖαν<br>ἀμφ’ αὐτοῖς, στήλας τε δύω καθύπερθεν ἔτευξεν,<br>ὧν ἑτέρη, θάμβος περιώσιον ἀνδράσι λεύσσειν,<br>κίνυται ἠχήεντος ὑπὸ πνοιῇ βορέαο.<br>καὶ τὰ μὲν ὧς ἤμελλε μετὰ χρόνον ἐκτελέεσθαι.<br>τοῖσιν δὲ Γλαῦκος βρυχίης ἁλὸς ἐξεφαάνθη,<br>Νηρῆος θείοιο πολυφράδμων ὑποφήτης·<br>ὕψι δὲ λαχνῆέν τε κάρη καὶ στήθε’ ἀείρας<br>νειόθεν ἐκ λαγόνων στιβαρῇ ἐπορέξατο χειρὶ<br>νηίου ὁλκαίοιο, καὶ ἴαχεν ἐσσυμένοισιν·", "st": "1.1296"}, {"sp": "N", "t": "“τίπτε παρὲκ μεγάλοιο Διὸς μενεαίνετε βουλὴν<br>Αἰήτεω πτολίεθρον ἄγειν θρασὺν Ἡρακλῆα;<br>Ἄργεΐ οἱ μοῖρ’ ἐστὶν ἀτασθάλῳ Εὐρυσθῆι<br>ἐκπλῆσαι μογέοντα δυώδεκα πάντας ἀέθλους,<br>ναίειν δ’ ἀθανάτοισι συνέστιον, εἴ κ’ ἔτι παύρους<br>ἐξανύσῃ· τῶ μή τι ποθὴ κείνοιο πελέσθω.<br>αὔτως δ’ αὖ Πολύφημον ἐπὶ προχοῇσι Κίοιο<br>πέπρωται Μυσοῖσι περικλεὲς ἄστυ καμόντα<br>μοῖραν ἀναπλήσειν Χαλύβων ἐν ἀπείρονι γαίῃ.<br>αὐτὰρ Ὕλαν φιλότητι θεὰ ποιήσατο νύμφη<br>ὃν πόσιν, οἷό περ οὕνεκ’ ἀποπλαγχθέντες ἔλειφθεν.”", "st": "1.1315"}, {"sp": "N", "t": "ἦ, καὶ κῦμ’ ἀλίαστον ἐφέσσατο νειόθι δύψας·<br>ἀμφὶ δέ οἱ δίνῃσι κυκώμενον ἄφρεεν ὕδωρ<br>πορφύρεον, κοίλην δὲ διὲξ ἁλὸς ἔκλυσε νῆα.<br>γήθησαν δ’ ἥρωες· ὁ δ’ ἐσσυμένως ἐβεβήκει<br>Αἰακίδης Τελαμὼν ἐς Ἰήσονα, χεῖρα δὲ χειρὶ<br>ἄκρην ἀμφιβαλὼν προσπτύξατο, φώνησέν τε·", "st": "1.1326"}, {"sp": "N", "t": "“Αἰσονίδη, μή μοί τι χολώσεαι, ἀφραδίῃσιν<br>εἴ τί περ ἀασάμην· πέρι γάρ μ’ ἄχος εἷλεν ἐνισπεῖν<br>μῦθον ὑπερφίαλόν τε καὶ ἄσχετον, ἀλλ’ ἀνέμοισιν<br>δώομεν ἀμπλακίην, ὡς καὶ πάρος εὐμενέοντες.”", "st": "1.1332"}, {"sp": "N", "t": "τὸν δ’ αὖτ’ Αἴσονος υἱὸς ἐπιφραδέως προσέειπεν·<br>“ὦ πέπον, ἦ μάλα δή με κακῷ ἐκυδάσσαο μύθῳ,<br>φὰς ἐνὶ τοῖσιν ἅπασιν ἐνηέος ἀνδρὸς ἀλείτην<br>ἔμμεναι. ἀλλ’ οὐ θήν τοι ἀδευκέα μῆνιν ἀέξω,<br>πρίν περ ἀνιηθείς· ἐπεὶ οὐ περὶ πώεσι μήλων,<br>οὐδὲ περὶ κτεάτεσσι χαλεψάμενος μενέηνας,<br>ἀλλ’ ἑτάρου περὶ φωτός. ἔολπα δέ τοι σὲ καὶ ἄλλῳ<br>ἀμφ’ ἐμεῦ, εἰ τοιόνδε πέλοι ποτέ, δηρίσασθαι.”", "st": "1.1336"}, {"sp": "N", "t": "ἦ ῥα, καὶ ἀρθμηθέντες, ὅπῃ πάρος, ἑδριόωντο.<br>τὼ δὲ Διὸς βουλῇσιν, ὁ μὲν Μυσοῖσι βαλέσθαι<br>μέλλεν ἐπώνυμον ἄστυ πολισσάμενος ποταμοῖο<br>Εἰλατίδης Πολύφημος· ὁ δ’ Εὐρυσθῆος ἀέθλους<br>αὖτις ἰὼν πονέεσθαι. ἐπηπείλησε δὲ γαῖαν<br>Μυσίδ’ ἀναστήσειν αὐτοσχεδόν, ὁππότε μή οἱ<br>ἢ ζωοῦ εὕροιεν Ὕλα μόρον, ἠὲ θανόντος.<br>τοῖο δὲ ῥύσι’ ὄπασσαν ἀποκρίναντες ἀρίστους<br>υἱέας ἐκ δήμοιο, καὶ ὅρκια ποιήσαντο,<br>μήποτε μαστεύοντες ἀπολλήξειν καμάτοιο.<br>τούνεκεν εἰσέτι νῦν περ Ὕλαν ἐρέουσι Κιανοί,<br>κοῦρον Θειοδάμαντος, ἐυκτιμένης τε μέλονται<br>Τρηχῖνος. δὴ γάρ ῥα κατ’ αὐτόθι νάσσατο παῖδας,<br>οὕς οἱ ῥύσια κεῖθεν ἐπιπροέηκαν ἄγεσθαι.", "st": "1.1344"}, {"sp": "N", "t": "Νηῦν δὲ πανημερίην ἄνεμος φέρε νυκτί τε πάσῃ<br>λάβρος ἐπιπνείων· ἀτὰρ οὐδ’ ἐπὶ τυτθὸν ἄητο<br>ἠοῦς τελλομένης, οἱ δὲ χθονὸς εἰσανέχουσαν<br>ἀκτὴν ἐκ κόλποιο μάλ’ εὐρεῖαν ἐσιδέσθαι<br>φρασσάμενοι, κώπῃσιν ἅμ’ ἠελίῳ ἐπέκελσαν", "st": "1.1358"}, {"sp": "HDR", "t": "Βιβλίον Βʹ", "st": "2"}, {"sp": "N", "t": "ἔνθα δ’ ἔσαν σταθμοί τε βοῶν αὖλίς τ’ Ἀμύκοιο,<br>Βεβρύκων βασιλῆος ἀγήνορος, ὅν ποτε νύμφη<br>τίκτε Ποσειδάωνι Γενεθλίῳ εὐνηθεῖσα<br>Βιθυνὶς Μελίη, ὑπεροπληέστατον ἀνδρῶν·<br>ὅς τ’ ἐπὶ καὶ ξείνοισιν ἀεικέα θεσμὸν ἔθηκεν,<br>μήτιν’ ἀποστείχειν, πρὶν πειρήσασθαι ἑοῖο<br>πυγμαχίης· πολέας δὲ περικτιόνων ἐδάιξεν.<br>καὶ δὲ τότε προτὶ νῆα κιών, χρειώ μιν ἐρέσθαι<br>ναυτιλίης, οἵ τ’ εἶεν, ὑπερβασίῃσιν ἄτισσεν,<br>τοῖον δ’ ἐν πάντεσσι παρασχεδὸν ἔκφατο μῦθον·", "st": "2.1"}, {"sp": "N", "t": "“Κέκλυθ’, ἁλίπλαγκτοι, τάπερ ἴδμεναι ὔμμιν ἔοικεν.<br>οὔτινα θέσμιόν ἐστιν ἀφορμηθέντα νέεσθαι<br>ἀνδρῶν ὀθνείων, ὅς κεν Βέβρυξι πελάσσῃ,<br>πρὶν χείρεσσιν ἐμῇσιν ἑὰς ἀνὰ χεῖρας ἀεῖραι.<br>τῶ καί μοι τὸν ἄριστον ἀποκριδὸν οἶον ὁμίλου<br>πυγμαχίῃ στήσασθε καταυτόθι δηρινθῆναι.<br>εἰ δ’ ἂν ἀπηλεγέοντες ἐμὰς πατέοιτε θέμιστας,<br>ἦ κέν τις στυγερῶς κρατερὴ ἐπιέψετ’ ἀνάγκη.”", "st": "2.11"}, {"sp": "N", "t": "ἦ ῥα μέγα φρονέων· τοὺς δ’ ἄγριος εἰσαΐοντας<br>εἷλε χόλος· περὶ δ’ αὖ Πολυδεύκεα τύψεν ὁμοκλή.<br>αἶψα δ’ ἑῶν ἑτάρων πρόμος ἵστατο, φώνησέν τε·", "st": "2.19"}, {"sp": "N", "t": "“ἴσχεο νῦν, μηδ’ ἄμμι κακήν, ὅτις εὔχεαι εἶναι,<br>φαῖνε βίην· θεσμοῖς γὰρ ὑπείξομεν, ὡς ἀγορεύεις.<br>αὐτὸς ἑκὼν ἤδη τοι ὑπίσχομαι ἀντιάασθαι.”", "st": "2.22"}, {"sp": "N", "t": "ὧς φάτ’ ἀπηλεγέως· ὁ δ’ ἐσέδρακεν ὄμμαθ’ ἑλίξας,<br>ὥστε λέων ὑπ’ ἄκοντι τετυμμένος, ὅν τ’ ἐν ὄρεσσιν<br>ἀνέρες ἀμφιπένονται· ὁ δ’ ἰλλόμενός περ ὁμίλῳ<br>τῶν μὲν ἔτ’ οὐκ ἀλέγει, ἐπὶ δ’ ὄσσεται οἰόθεν οἶον<br>ἄνδρα τόν, ὅς μιν ἔτυψε παροίτατος, οὐδ’ ἐδάμασσεν.<br>ἔνθ’ ἀπὸ Τυνδαρίδης μὲν ἐύστιπτον θέτο φᾶρος<br>λεπταλέον, τό ῥά οἵ τις ἑὸν ξεινήιον εἶναι<br>ὤπασε Λημνιάδων· ὁ δ’ ἐρεμνὴν δίπτυχα λώπην<br>αὐτῇσιν περόνῃσι καλαύροπά τε τρηχεῖαν<br>κάββαλε, τὴν φορέεσκεν, ὀριτρεφέος κοτίνοιο.<br>αὐτίκα δ’ ἐγγύθι χῶρον ἑαδότα παπτήναντες<br>ἷζον ἑοὺς δίχα πάντας ἐνὶ ψαμάθοισιν ἑταίρους,<br>οὐ δέμας, οὐδὲ φυὴν ἐναλίγκιοι εἰσοράασθαι.<br>ἀλλ’ ὁ μὲν ἢ ὀλοοῖο Τυφωέος, ἠὲ καὶ αὐτῆς<br>Γαίης εἶναι ἔικτο πέλωρ τέκος, οἷα πάροιθεν<br>χωομένη Διὶ τίκτεν· ὁ δ’ οὐρανίῳ ἀτάλαντος<br>ἀστέρι Τυνδαρίδης, οὗπερ κάλλισται ἔασιν<br>ἑσπερίην διὰ νύκτα φαεινομένου ἀμαρυγαί.<br>τοῖος ἔην Διὸς υἱός, ἔτι χνοάοντας ἰούλους<br>ἀντέλλων, ἔτι φαιδρὸς ἐν ὄμμασιν. ἀλλά οἱ ἀλκὴ<br>καὶ μένος ἠύτε θηρὸς ἀέξετο· πῆλε δὲ χεῖρας<br>πειράζων, εἴθ’ ὡς πρὶν ἐυτρόχαλοι φορέονται,<br>μηδ’ ἄμυδις καμάτῳ τε καὶ εἰρεσίῃ βαρύθοιεν<br>οὐ μὰν αὖτ’ Ἄμυκος πειρήσατο· σῖγα δ’ ἄπωθεν<br>ἑστηὼς εἰς αὐτὸν ἔχ’ ὄμματα, καί οἱ ὀρέχθει<br>θυμὸς ἐελδομένῳ στηθέων ἐξ αἷμα κεδάσσαι.<br>τοῖσι δὲ μεσσηγὺς θεράπων Ἀμύκοιο Λυκωρεὺς<br>θῆκε πάροιθε ποδῶν δοιοὺς ἑκάτερθεν ἱμάντας<br>ὠμούς, ἀζαλέους, περὶ δ’ οἵγ’ ἔσαν ἐσκληῶτες.<br>αὐτὰρ ὁ τόνγ’ ἐπέεσσιν ὑπερφιάλοισι μετηύδα·", "st": "2.25"}, {"sp": "N", "t": "“τῶνδέ τοι ὅν κ’ ἐθέλῃσθα, πάλου ἄτερ ἐγγυαλίξω<br>αὐτὸς ἑκών, ἵνα μή μοι ἀτέμβηαι μετόπισθεν.<br>ἀλλὰ βάλευ περὶ χειρί· δαεὶς δέ κεν ἄλλῳ ἐνίσποις,<br>ὅσσον ἐγὼ ῥινούς τε βοῶν περίειμι ταμέσθαι<br>ἀζαλέας, ἀνδρῶν τε παρηίδας αἵματι φύρσαι.”", "st": "2.55"}, {"sp": "N", "t": "ὧς ἔφατ’· αὐτὰρ ὅγ’ οὔτι παραβλήδην ἐρίδηνεν.<br>ἦκα δὲ μειδήσας, οἵ οἱ παρὰ ποσσὶν ἔκειντο,<br>τοὺς ἕλεν ἀπροφάτως· τοῦ δ’ ἀντίος ἤλυθε Κάστωρ<br>ἠδὲ Βιαντιάδης Ταλαὸς μέγας· ὦκα δ’ ἱμάντας<br>ἀμφέδεον, μάλα πολλὰ παρηγορέοντες ἐς ἀλκήν.<br>τῷ δ’ αὖτ’ Ἄρητός τε καὶ Ὄρνυτος, οὐδέ τι ᾔδειν<br>νήπιοι ὕστατα κεῖνα κακῇ δήσαντες ἐν αἴσῃ.", "st": "2.60"}, {"sp": "N", "t": "οἱ δ’ ἐπεὶ οὖν ἱμᾶσι διασταδὸν ἠρτύναντο,<br>αὐτίκ’ ἀνασχόμενοι ῥεθέων προπάροιθε βαρείας<br>χεῖρας, ἐπ’ ἀλλήλοισι μένος φέρον ἀντιόωντες.<br>ἔνθα δὲ Βεβρύκων μὲν ἄναξ, ἅ τε κῦμα θαλάσσης<br>τρηχὺ θοὴν ἐπὶ νῆα κορύσσεται, ἡ δ’ ὑπὸ τυτθὸν<br>ἰδρείῃ πυκινοῖο κυβερνητῆρος ἀλύσκει,<br>ἱεμένου φορέεσθαι ἔσω τοίχοιο κλύδωνος,<br>ὧς ὅγε Τυνδαρίδην φοβέων ἕπετ’, οὐδέ μιν εἴα<br>δηθύνειν. ὁ δ’ ἄρ’ αἰὲν ἀνούτατος ἣν διὰ μῆτιν<br>ἀίσσοντ’ ἀλέεινεν· ἀπηνέα δ’ αἶψα νοήσας<br>πυγμαχίην, ᾗ κάρτος ἀάατος, ᾗ τε χερείων,<br>στῆ ῥ’ ἄμοτον καὶ χερσὶν ἐναντία χεῖρας ἔμιξεν.<br>ὡς δ’ ὅτε νήια δοῦρα θοοῖς ἀντίξοα γόμφοις<br>ἀνέρες ὑληουργοὶ ἐπιβλήδην ἐλάοντες<br>θείνωσι σφύρῃσιν, ἐπ’ ἄλλῳ δ’ ἄλλος ἄηται<br>δοῦπος ἄδην· ὧς τοῖσι παρήιά τ’ ἀμφοτέρωθεν<br>καὶ γένυες κτύπεον· βρυχὴ δ’ ὑπετέλλετ’ ὀδόντων<br>ἄσπετος, οὐδ’ ἔλληξαν ἐπισταδὸν οὐτάζοντες,<br>ἔστε περ οὐλοὸν ἆσθμα καὶ ἀμφοτέρους ἐδάμασσεν.<br>στάντε δὲ βαιὸν ἄπωθεν ἀπωμόρξαντο μετώπων<br>ἱδρῶ ἅλις, καματηρὸν ἀυτμένα φυσιόωντε.<br>ἂψ δ’ αὖτις συνόρουσαν ἐναντίοι, ἠύτε ταύρω<br>φορβάδος ἀμφὶ βοὸς κεκοτηότε δηριάασθον.<br>ἔνθα δ’ ἔπειτ’ Ἄμυκος μὲν ἐπ’ ἀκροτάτοισιν ἀερθείς,<br>βουτύπος οἷα, πόδεσσι τανύσσατο, κὰδ δὲ βαρεῖαν<br>χεῖρ’ ἐπὶ οἷ πελέμιξεν· ὁ δ’ ἀίξαντος ὑπέστη,<br>κρᾶτα παρακλίνας, ὤμῳ δ’ ἀνεδέξατο πῆχυν<br>τυτθόν· ὁ δ’ ἄγχ’ αὐτοῖο παρὲκ γόνυ γουνὸς ἀμείβων<br>κόψε μεταΐγδην ὑπὲρ οὔατος, ὀστέα δ’ εἴσω<br>ῥῆξεν· ὁ δ’ ἀμφ’ ὀδύνῃ γνὺξ ἤριπεν· οἱ δ’ ἰάχησαν<br>ἥρωες Μινύαι· τοῦ δ’ ἀθρόος ἔκχυτο θυμός.", "st": "2.67"}, {"sp": "N", "t": "οὐδ’ ἄρα Βέβρυκες ἄνδρες ἀφείδησαν βασιλῆος·<br>ἀλλ’ ἄμυδις κορύνας ἀζηχέας ἠδὲ σιγύννους<br>ἰθὺς ἀνασχόμενοι Πολυδεύκεος ἀντιάασκον.<br>τοῦ δὲ πάρος κολεῶν εὐήκεα φάσγαν’ ἑταῖροι<br>ἔσταν ἐρυσσάμενοι. πρῶτός γε μὲν ἀνέρα Κάστωρ<br>ἤλασ’ ἐπεσσύμενον κεφαλῆς ὕπερ· ἡ δ’ ἑκάτερθεν<br>ἔνθα καὶ ἔνθ’ ὤμοισιν ἐπ’ ἀμφοτέροις ἐκεάσθη.<br>αὐτὸς δ’ Ἰτυμονῆα πελώριον ἠδὲ Μίμαντα,<br>τὸν μὲν ὑπὸ στέρνοιο θοῷ ποδὶ λὰξ ἐπορούσας<br>πλῆξε, καὶ ἐν κονίῃσι βάλεν· τοῦ δ’ ἆσσον ἰόντος<br>δεξιτερῇ σκαιῆς ὑπὲρ ὀφρύος ἤλασε χειρί,<br>δρύψε δέ οἱ βλέφαρον, γυμνὴ δ’ ὑπελείπετ’ ὀπωπή.<br>Ὠρεΐδης δ’ Ἀμύκοιο βίην ὑπέροπλος ὀπάων<br>οὖτα Βιαντιάδαο κατὰ λαπάρην Ταλαοῖο,<br>ἀλλά μιν οὐ κατέπεφνεν, ὅσον δ’ ἐπὶ δέρματι μοῦνον<br>νηδυίων ἄψαυστος ὑπὸ ζώνην θόρε χαλκός.<br>αὔτως δ’ Ἄρητος μενεδήιον Εὐρύτου υἷα<br>Ἴφιτον ἀζαλέῃ κορύνῃ στυφέλιξεν ἐλάσσας,<br>οὔπω κηρὶ κακῇ πεπρωμένον· ἦ τάχ’ ἔμελλεν<br>αὐτὸς δῃώσεσθαι ὑπὸ ξίφεϊ Κλυτίοιο.<br>καὶ τότ’ ἄρ’ Ἀγκαῖος Λυκοόργοιο θρασὺς υἱὸς<br>αἶψα μάλ’ ἀντεταγὼν πέλεκυν μέγαν ἠδὲ κελαινὸν<br>ἄρκτου προσχόμενος σκαιῇ δέρος ἔνθορε μέσσῳ<br>ἐμμεμαὼς Βέβρυξιν· ὁμοῦ δέ οἱ ἐσσεύοντο<br>Αἰακίδαι, σὺν δέ σφιν ἀρήιος ὤρνυτ’ Ἰήσων.<br>ὡς δ’ ὅτ’ ἐνὶ σταθμοῖσιν ἀπείρονα μῆλ’ ἐφόβησαν<br>ἤματι χειμερίῳ πολιοὶ λύκοι ὁρμηθέντες<br>λάθρῃ ἐυρρίνων τε κυνῶν αὐτῶν τε νομήων,<br>μαίονται δ’ ὅ τι πρῶτον ἐπαΐξαντες ἕλωσιν,<br>πόλλ’ ἐπιπαμφαλόωντες ὁμοῦ· τὰ δὲ πάντοθεν αὔτως<br>στείνονται πίπτοντα περὶ σφίσιν· ὧς ἄρα τοίγε<br>λευγαλέως Βέβρυκας ὑπερφιάλους ἐφόβησαν.<br>ὡς δὲ μελισσάων σμῆνος μέγα μηλοβοτῆρες<br>ἠὲ μελισσοκόμοι πέτρῃ ἔνι καπνιόωσιν,<br>αἱ δ’ ἤτοι τείως μὲν ἀολλέες ᾧ ἐνὶ σίμβλῳ<br>βομβηδὸν κλονέονται, ἐπιπρὸ δὲ λιγνυόεντι<br>καπνῷ τυφόμεναι πέτρης ἑκὰς ἀίσσουσιν·<br>ὧς οἵγ’ οὐκέτι δὴν μένον ἔμπεδον, ἀλλ’ ἐκέδασθεν<br>εἴσω Βεβρυκίης, Ἀμύκου μόρον ἀγγελέοντες·<br>νήπιοι, οὐδ’ ἐνόησαν ὃ δή σφισιν ἐγγύθεν ἄλλο<br>πῆμ’ ἀίδηλον ἔην. πέρθοντο γὰρ ἠμὲν ἀλωαὶ<br>ἠδ’ οἶαι τῆμος δῄῳ ὑπὸ δουρὶ Λύκοιο<br>καὶ Μαριανδυνῶν ἀνδρῶν, ἀπεόντος ἄνακτος.<br>αἰεὶ γὰρ μάρναντο σιδηροφόρου περὶ γαίης.<br>οἱ δ’ ἤδη σταθμούς τε καὶ αὔλια δηιάασκον·<br>ἤδη δ’ ἄσπετα μῆλα περιτροπάδην ἐτάμοντο<br>ἥρωες, καὶ δή τις ἔπος μετὰ τοῖσιν ἔειπεν·", "st": "2.98"}, {"sp": "N", "t": "“Φράζεσθ’ ὅττι κεν ᾗσιν ἀναλκείῃσιν ἔρεξαν,<br>εἴ πως Ἡρακλῆα θεὸς καὶ δεῦρ’ ἐκόμισσεν.<br>ἤτοι μὲν γὰρ ἐγὼ κείνου παρεόντος ἔολπα<br>οὐδ’ ἂν πυγμαχίῃ κρινθήμεναι· ἀλλ’ ὅτε θεσμοὺς<br>ἤλυθεν ἐξερέων, αὐτοῖς ἄφαρ οἷς ἀγόρευεν<br>θεσμοῖσιν ῥοπάλῳ μιν ἀγηνορίης λελαθέσθαι.<br>ναὶ μὲν ἀκήδεστον γαίῃ ἔνι τόνγε λιπόντες<br>πόντον ἐπέπλωμεν· μάλα δ’ ἡμέων αὐτὸς ἕκαστος<br>εἴσεται οὐλομένην ἄτην, ἀπάνευθεν ἐόντος.”", "st": "2.145"}, {"sp": "N", "t": "ὧς ἄρ’ ἔφη· τὰ δὲ πάντα Διὸς βουλῇς ἐτέτυκτο.<br>καὶ τότε μὲν μένον αὖθι διὰ κνέφας, ἕλκεά τ’ ἀνδρῶν<br>οὐταμένων ἀκέοντο, καὶ ἀθανάτοισι θυηλὰς<br>ῥέξαντες μέγα δόρπον ἐφώπλισαν· οὐδέ τιν’ ὕπνος<br>εἷλε παρὰ κρητῆρι καὶ αἰθομένοις ἱεροῖσιν.<br>ξανθὰ δ’ ἐρεψάμενοι δάφνῃ καθύπερθε μέτωπα<br>ἀγχιάλῳ, τῇ, ἀκτῇ ἔπι, πρυμνήσι’ ἀνῆπτο,<br>Ὀρφείῃ φόρμιγγι συνοίμιον ὕμνον ἄειδον<br>ἐμμελέως· περὶ δέ σφιν ἰαίνετο νήνεμος ἀκτὴ<br>μελπομένοις· κλεῖον δὲ Θεραπναῖον Διὸς υἷα.", "st": "2.154"}, {"sp": "N", "t": "ἦμος δ’ ἠέλιος δροσερὰς ἐπέλαμψε κολώνας<br>ἐκ περάτων ἀνιών, ἤγειρε δὲ μηλοβοτῆρας,<br>δὴ τότε λυσάμενοι νεάτης ἐκ πείσματα δάφνης,<br>ληίδα τ’ εἰσβήσαντες ὅσην χρεὼ ἦεν ἄγεσθαι,<br>πνοιῇ δινήεντ’ ἀνὰ Βόσπορον ἰθύνοντο.<br>ἔνθα μὲν ἠλιβάτῳ ἐναλίγκιον οὔρεϊ κῦμα<br>ἀμφέρεται προπάροιθεν ἐπαΐσσοντι ἐοικός,<br>αἰὲν ὑπὲρ νεφέων ἠερμένον· οὐδέ κε φαίης<br>φεύξεσθαι κακὸν οἶτον, ἐπεὶ μάλα μεσσόθι νηὸς<br>λάβρον ἐπικρέμαται, καθάπερ νέφος. ἀλλὰ τόγ’ ἔμπης<br>στόρνυται, εἴ κ’ ἐσθλοῖο κυβερνητῆρος ἐπαύρῃ.<br>τῶ καὶ Τίφυος οἵδε δαημοσύνῃσι νέοντο,<br>ἀσκηθεῖς μέν, ἀτὰρ πεφοβημένοι. ἤματι δ’ ἄλλῳ<br>ἀντιπέρην γαίῃ Βιθυνίδι πείσματ’ ἀνῆψαν.", "st": "2.164"}, {"sp": "N", "t": "ἔνθα δ’ ἐπάκτιον οἶκον Ἀγηνορίδης ἔχε Φινεύς,<br>ὃς περὶ δὴ πάντων ὀλοώτατα πήματ’ ἀνέτλη<br>εἵνεκα μαντοσύνης, τήν οἱ πάρος ἐγγυάλιξεν<br>Λητοΐδης· οὐδ’ ὅσσον ὀπίζετο καὶ Διὸς αὐτοῦ<br>χρείων ἀτρεκέως ἱερὸν νόον ἀνθρώποισιν.<br>τῶ καί οἱ γῆρας μὲν ἐπὶ δηναιὸν ἴαλλεν,<br>ἐκ δ’ ἕλετ’ ὀφθαλμῶν γλυκερὸν φάος· οὐδὲ γάνυσθαι<br>εἴα ἀπειρεσίοισιν ὀνείασιν, ὅσσα οἱ αἰεὶ<br>θέσφατα πευθόμενοι περιναιέται οἴκαδ’ ἄγειρον.<br>ἀλλὰ διὰ νεφέων ἄφνω πέλας ἀίσσουσαι<br>Ἅρπυιαι στόματος χειρῶν τ’ ἀπὸ γαμφηλῇσιν<br>συνεχέως ἥρπαζον. ἐλείπετο δ’ ἄλλοτε φορβῆς<br>οὐδ’ ὅσον, ἄλλοτε τυτθόν, ἵνα ζώων ἀκάχοιτο.<br>καὶ δ’ ἐπὶ μυδαλέην ὀδμὴν χέον· οὐδέ τις ἔτλη<br>μὴ καὶ λευκανίηνδε φορεύμενος, ἀλλ’ ἀποτηλοῦ<br>ἑστηώς· τοῖόν οἱ ἀπέπνεε λείψανα δαιτός.<br>αὐτίκα δ’ εἰσαΐων ἐνοπὴν καὶ δοῦπον ὁμίλου<br>τούσδ’ αὐτοὺς παριόντας ἐπήισεν, ὧν οἱ ἰόντων<br>θέσφατον ἐκ Διὸς ἦεν ἑῆς ἀπόνασθαι ἐδωδῆς.<br>ὀρθωθεὶς δ’ εὐνῆθεν, ἀκήριον ἠύτ’ ὄνειρον,<br>βάκτρῳ σκηπτόμενος ῥικνοῖς ποσὶν ᾖε θύραζε,<br>τοίχους ἀμφαφόων· τρέμε δ’ ἅψεα νισσομένοιο<br>ἀδρανίῃ γήραι τε· πίνῳ δέ οἱ αὐσταλέος χρὼς<br>ἐσκλήκει, ῥινοὶ δὲ σὺν ὀστέα μοῦνον ἔεργον.<br>ἐκ δ’ ἐλθὼν μεγάροιο καθέζετο γοῦνα βαρυνθεὶς<br>οὐδοῦ ἐπ’ αὐλείοιο· κάρος δέ μιν ἀμφεκάλυψεν<br>πορφύρεος, γαῖαν δὲ πέριξ ἐδόκησε φέρεσθαι<br>νειόθεν, ἀβληχρῷ δ’ ἐπὶ κώματι κέκλιτ’ ἄναυδος.<br>οἱ δέ μιν ὡς εἴδοντο, περισταδὸν ἠγερέθοντο<br>καὶ τάφον. αὐτὰρ ὁ τοῖσι μάλα μόλις ἐξ ὑπάτοιο<br>στήθεος ἀμπνεύσας μετεφώνεε μαντοσύνῃσιν·", "st": "2.178"}, {"sp": "N", "t": "“κλῦτε, Πανελλήνων προφερέστατοι, εἰ ἐτεὸν δὴ<br>οἵδ’ ὑμεῖς, οὓς δὴ κρυερῇ βασιλῆος ἐφετμῇ<br>Ἁργῴης ἐπὶ νηὸς ἄγει μετὰ κῶας Ἰήσων.<br>ὑμεῖς ἀτρεκέως. ἔτι μοι νόος οἶδεν ἕκαστα<br>ᾗσι θεοπροπίῃσι. χάριν νύ τοι, ὦ ἄνα Λητοῦς<br>υἱέ, καὶ ἀργαλέοισιν ἀνάπτομαι ἐν καμάτοισιν.<br>Ἱκεσίου πρὸς Ζηνός, ὅτις ῥίγιστος ἀλιτροῖς<br>ἀνδράσι, Φοίβου τ’ ἀμφὶ καὶ αὐτῆς εἵνεκεν Ἥρης<br>λίσσομαι, ᾗ περίαλλα θεῶν μέμβλεσθε κιόντες,<br>χραίσμετέ μοι, ῥύσασθε δυσάμμορον ἀνέρα λύμης,<br>μηδέ μ’ ἀκηδείῃσιν ἀφορμήθητε λιπόντες<br>αὔτως. οὐ γὰρ μοῦνον ἐπ’ ὀφθαλμοῖσιν Ἐρινὺς<br>λὰξ ἐπέβη, καὶ γῆρας ἀμήρυτον ἐς τέλος ἕλκω·<br>πρὸς δ’ ἔτι πικρότατον κρέμαται κακὸν ἄλλο κακοῖσιν.<br>ἅρπυιαι στόματός μοι ἀφαρπάζουσιν ἐδωδὴν<br>ἔκποθεν ἀφράστοιο καταΐσσουσαι ὄλεθροι.<br>ἴσχω δ’ οὔτινα μῆτιν ἐπίρροθον. ἀλλά κε ῥεῖα<br>αὐτὸς ἑὸν λελάθοιμι νόον δόρποιο μεμηλώς,<br>ἢ κείνας· ὧδ’ αἶψα διηέριαι ποτέονται.<br>τυτθὸν δ’ ἢν ἄρα δήποτ’ ἐδητύος ἄμμι λίπωσιν,<br>πνεῖ τόδε μυδαλέον τε καὶ οὐ τλητὸν μένος ὀδμῆς·<br>οὔ κέ τις οὐδὲ μίνυνθα βροτῶν ἄνσχοιτο πελάσσας,<br>οὐδ’ εἴ οἱ ἀδάμαντος ἐληλάμενον κέαρ εἴη.<br>ἀλλά με πικρὴ δῆτα καὶ ἄατος ἴσχει ἀνάγκη<br>μίμνειν καὶ μίμνοντα κακῇ ἐνὶ γαστέρι θέσθαι.<br>τὰς μὲν θέσφατόν ἐστιν ἐρητῦσαι Βορέαο<br>υἱέας. οὐδ’ ὀθνεῖοι ἀλαλκήσουσιν ἐόντες,<br>εἰ δὴ ἐγὼν ὁ πρίν ποτ’ ἐπικλυτὸς ἀνδράσι Φινεὺς<br>ὄλβῳ μαντοσύνῃ τε, πατὴρ δέ με γείνατ’ Ἀγήνωρ·<br>τῶν δὲ κασιγνήτην, ὅτ’ ἐνὶ Θρῄκεσσιν ἄνασσον,<br>Κλειοπάτρην ἕδνοισιν ἐμὸν δόμον ἦγον ἄκοιτιν.”", "st": "2.209"}, {"sp": "N", "t": "Ἴσκεν Ἀγηνορίδης· ἀδινὸν δ’ ἕλε κῆδος ἕκαστον<br>ἡρώων, πέρι δ’ αὖτε δύω υἷας Βορέαο.<br>δάκρυ δ’ ὀμορξαμένω σχεδὸν ἤλυθον, ὧδέ τ’ ἔειπεν<br>Ζήτης, ἀσχαλόωντος ἑλὼν χερὶ χεῖρα γέροντος·", "st": "2.240"}, {"sp": "N", "t": "“Ἆ δείλ’, οὔτινά φημι σέθεν σμυγερώτερον ἄλλον<br>ἔμμεναι ἀνθρώπων. τί νύ τοι τόσα κήδε’ ἀνῆπται;<br>ἦ ῥα θεοὺς ὀλοῇσι παρήλιτες ἀφραδίῃσιν<br>μαντοσύνας δεδαώς; τῶ τοι μέγα μηνιόωσιν;<br>ἄμμι γε μὴν νόος ἔνδον ἀτύζεται ἱεμένοισιν<br>χραισμεῖν, εἰ δὴ πρόχνυ γέρας τόδε πάρθετο δαίμων<br>νῶιν. ἀρίζηλοι γὰρ ἐπιχθονίοισιν ἐνιπαὶ<br>ἀθανάτων. οὐδ’ ἂν πρὶν ἐρητύσαιμεν ἰούσας<br>Ἁρπυίας, μάλα περ λελιημένοι, ἔστ’ ἂν ὀμόσσῃς,<br>μὴ μὲν τοῖό γ’ ἕκητι θεοῖς ἀπὸ θυμοῦ ἔσεσθαι.”", "st": "2.244"}, {"sp": "N", "t": "ὧς φάτο· τοῦ δ’ ἰθὺς κενεὰς ὁ γεραιὸς ἀνέσχεν<br>γλήνας ἀμπετάσας, καὶ ἀμείψατο τοῖσδ’ ἐπέεσσιν·", "st": "2.254"}, {"sp": "N", "t": "“σίγα· μή μοι ταῦτα νόῳ ἔνι βάλλεο, τέκνον.<br>ἴστω Λητοῦς υἱός, ὅ με πρόφρων ἐδίδαξεν<br>μαντοσύνας· ἴστω δὲ δυσώνυμος, ἥ μ’ ἔλαχεν, κὴρ<br>καὶ τόδ’ ἐπ’ ὀφθαλμῶν ἀλαὸν νέφος, οἵ θ’ ὑπένερθεν<br>δαίμονες, οἳ μηδ’ ὧδε θανόντι περ εὐμενέοιεν,<br>ὡς οὔ τις θεόθεν χόλος ἔσσεται εἵνεκ’ ἀρωγῆς.”", "st": "2.256"}, {"sp": "N", "t": "τὼ μὲν ἔπειθ’ ὅρκοισιν ἀλαλκέμεναι μενέαινον.<br>αἶψα δὲ κουρότεροι πεπονήατο δαῖτα γέροντι,<br>λοίσθιον Ἁρπυίῃσιν ἑλώριον· ἐγγύθι δ’ ἄμφω<br>στῆσαν, ἵνα ξιφέεσσιν ἐπεσσυμένας ἐλάσειαν.<br>καὶ δὴ τὰ πρώτισθ’ ὁ γέρων ἔψαυεν ἐδωδῆς·<br>αἱ δ’ ἄφαρ ἠύτ’ ἄελλαι ἀδευκέες, ἢ στεροπαὶ ὥς,<br>ἀπρόφατοι νεφέων ἐξάλμεναι ἐσσεύοντο<br>κλαγγῇ μαιμώωσαι ἐδητύος· οἱ δ’ ἐσιδόντες<br>ἥρωες μεσσηγὺς ἀνίαχον· αἱ δ’ ἅμ’ ἀυτῇ<br>πάντα καταβρόξασαι ὑπὲρ πόντοιο φέροντο<br>τῆλε παρέξ· ὀδμὴ δὲ δυσάσχετος αὖθι λέλειπτο.<br>τάων δ’ αὖ κατόπισθε δύω υἷες Βορέαο<br>φάσγαν’ ἐπισχόμενοι ὀπίσω θέον. ἐν γὰρ ἕηκεν<br>Ζεὺς μένος ἀκάματόν σφιν· ἀτὰρ Διὸς οὔ κεν ἑπέσθην<br>νόσφιν, ἐπεὶ ζεφύροιο παραΐσσεσκον ἀέλλας<br>αἰέν. ὅτ’ ἐς Φινῆα καὶ ἐκ Φινῆος ἴοιεν.<br>ὡς δ’ ὅτ’ ἐνὶ κνημοῖσι κύνες δεδαημένοι ἄγρης<br>ἢ αἶγας κεραοὺς ἠὲ πρόκας ἰχνεύοντες<br>θείωσιν, τυτθὸν δὲ τιταινόμενοι μετόπισθεν<br>ἄκρῃς ἐν γενύεσσι μάτην ἀράβησαν ὀδόντας·<br>ὧς Ζήτης Κάλαΐς τε μάλα σχεδὸν ἀίσσοντες<br>τάων ἀκροτάτῃσιν ἐπέχραον ἤλιθα χερσίν.<br>καί νύ κε δή σφ’ ἀέκητι θεῶν διεδηλήσαντο<br>πολλὸν ἑκὰς νήσοισιν ἔπι Πλωτῇσι κιχόντες,<br>εἰ μὴ ἄρ’ ὠκέα Ἶρις ἴδεν, κατὰ δ’ αἰθέρος ἆλτο<br>οὐρανόθεν, καὶ τοῖα παραιφαμένη κατέρυκεν·", "st": "2.262"}, {"sp": "N", "t": "“οὐ θέμις, ὦ υἱεῖς Βορέω, ξιφέεσσιν ἐλάσσαι<br>Ἁρπυίας, μεγάλοιο Διὸς κύνας· ὅρκια δ’ αὐτὴ<br>δώσω ἐγών, ὡς οὔ οἱ ἔτι χρίμψουσιν ἰοῦσαι.”", "st": "2.288"}, {"sp": "N", "t": "ὧς φαμένη λοιβὴν Στυγὸς ὤμοσεν, ἥ τε θεοῖσιν<br>ῥιγίστη πάντεσσιν ὀπιδνοτάτη τε τέτυκται,<br>μὴ μὲν Ἀγηνορίδαο δόμοις ἔτι τάσδε πελάσσαι<br>εἰσαῦτις Φινῆος, ἐπεὶ καὶ μόρσιμον ἦεν.<br>οἱ δ’ ὅρκῳ εἴξαντες ὑπέστρεφον ἂψ ἐπὶ νῆα<br>σώεσθαι. Στροφάδας δὲ μετακλείουσ’ ἄνθρωποι<br>νήσους τοῖό γ’ ἕκητι, πάρος Πλωτὰς καλέοντες.<br>Ἄρπυιαί τ’ Ἶρίς τε διέτμαγεν. αἱ μὲν ἔδυσαν<br>κευθμῶνα Κρήτης Μινωίδος· ἡ δ’ ἀνόρουσεν<br>Οὔλυμπόνδε, θοῇσι μεταχρονίη πτερύγεσσιν.", "st": "2.291"}, {"sp": "N", "t": "τόφρα δ’ ἀριστῆες πινόεν περὶ δέρμα γέροντος<br>πάντῃ φοιβήσαντες ἐπικριδὸν ἱρεύσαντο<br>μῆλα, τά τ’ ἐξ Ἀμύκοιο λεηλασίης ἐκόμισσαν.<br>αὐτὰρ ἐπεὶ μέγα δόρπον ἐνὶ μεγάροισιν ἔθεντο,<br>δαίνυνθ’ ἑζόμενοι· σὺν δέ σφισι δαίνυτο Φινεὺς<br>ἁρπαλέως, οἷόν τ’ ἐν ὀνείρασι θυμὸν ἰαίνων.<br>ἔνθα δ’, ἐπεὶ δόρποιο κορέσσαντ’ ἠδὲ ποτῆτος,<br>παννύχιοι Βορέω μένον υἱέας ἐγρήσσοντες.<br>αὐτὸς δ’ ἐν μέσσοισι παρ’ ἐσχάρῃ ἧστο γεραιὸς<br>πείρατα ναυτιλίης ἐνέπων ἄνυσίν τε κελεύθου·", "st": "2.301"}, {"sp": "N", "t": "“κλῦτέ νυν. οὐ μὲν πάντα πέλει θέμις ὔμμι δαῆναι<br>ἀτρεκές· ὅσσα δ’ ὄρωρε θεοῖς φίλον, οὐκ ἐπικεύσω.<br>ἀασάμην καὶ πρόσθε Διὸς νόον ἀφραδίῃσιν<br>χρείων ἑξείης τε καὶ ἐς τέλος. ὧδε γὰρ αὐτὸς<br>βούλεται ἀνθρώποις ἐπιδευέα θέσφατα φαίνειν<br>μαντοσύνης, ἵνα καί τι θεῶν χατέωσι νόοιο.", "st": "2.311"}, {"sp": "N", "t": "“πέτρας μὲν πάμπρωτον, ἀφορμηθέντες ἐμεῖο,<br>Κυανέας ὄψεσθε δύω ἁλὸς ἐν ξυνοχῇσιν,<br>τάων οὔτινά φημι διαμπερὲς ἐξαλέασθαι.<br>οὐ γάρ τε ῥίζῃσιν ἐρήρεινται νεάτῃσιν,<br>ἀλλὰ θαμὰ ξυνίασιν ἐναντίαι ἀλλήλῃσιν<br>εἰς ἕν, ὕπερθε δὲ πολλὸν ἁλὸς κορθύεται ὕδωρ<br>βρασσόμενον· στρηνὲς δὲ περὶ στυφελῇ βρέμει ἀκτῇ.<br>τῶ νῦν ἡμετέρῃσι παραιφασίῃσι πίθεσθε,<br>εἰ ἐτεὸν πυκινῷ τε νόῳ μακάρων τ’ ἀλέγοντες<br>πείρετε· μηδ’ αὔτως αὐτάγρετον οἶτον ὄλησθε<br>ἀφραδέως, ἢ θύνετ’ ἐπισπόμενοι νεότητι.<br>οἰωνῷ δὴ πρόσθε πελειάδι πειρήσασθαι<br>νηὸς ἄπο προμεθέντες ἐφιέμεν. ἢν δὲ δι’ αὐτῶν<br>πετράων πόντονδε σόη πτερύγεσσι δίηται,<br>μηκέτι δὴν μηδ’ αὐτοὶ ἐρητύεσθε κελεύθου,<br>ἀλλ’ εὖ καρτύναντες ἑαῖς ἐνὶ χερσὶν ἐρετμὰ<br>τέμνεθ’ ἁλὸς στεινωπόν· ἐπεὶ φάος οὔ νύ τι τόσσον<br>ἔσσετ’ ἐν εὐχωλῇσιν, ὅσον τ’ ἐνὶ κάρτεϊ χειρῶν.<br>τῶ καὶ τἆλλα μεθέντες ὀνήιστον πονέεσθαι<br>θαρσαλέως· πρὶν δ’ οὔτι θεοὺς λίσσεσθαι ἐρύκω.<br>εἰ δέ κεν ἀντικρὺ πταμένη μεσσηγὺς ὄληται,<br>ἄψορροι στέλλεσθαι ἐπεὶ πολὺ βέλτερον εἶξαι<br>ἀθανάτοις. οὐ γάρ κε κακὸν μόρον ἐξαλέαισθε<br>πετράων, οὐδ’ εἴ κε σιδηρείη πέλοι Ἀργώ.", "st": "2.317"}, {"sp": "N", "t": "“ὦ μέλεοι, μὴ τλῆτε παρὲξ ἐμὰ θέσφατα βῆναι,<br>εἰ καί με τρὶς τόσσον ὀίεσθ’ Οὐρανίδῃσιν,<br>ὅσσον ἀνάρσιός εἰμι, καὶ εἰ πλεῖον στυγέεσθαι·<br>μὴ τλῆτ’ οἰωνοῖο πάρεξ ἔτι νηὶ περῆσαι.<br>καὶ τὰ μὲν ὥς κε πέλῃ, τὼς ἔσσεται. ἢν δὲ φύγητε<br>σύνδρομα πετράων ἀσκηθέες ἔνδοθι Πόντου,<br>αὐτίκα Βιθυνῶν ἐπὶ δεξιὰ γαῖαν ἔχοντες<br>πλώετε ῥηγμῖνας πεφυλαγμένοι, εἰσόκεν αὖτε<br>Ῥήβαν ὠκυρόην ποταμὸν ἄκρην τε Μέλαιναν<br>γνάμψαντες νήσου Θυνηίδος ὅρμον ἵκησθε.<br>κεῖθεν δ’ οὐ μάλα πουλὺ διὲξ ἁλὸς ἀντιπέραιαν<br>γῆν Μαριανδυνῶν ἐπικέλσετε νοστήσαντες.<br>ἔνθα μὲν εἰς Ἀίδαο καταιβάτις ἐστὶ κέλευθος,<br>ἄκρη τε προβλὴς Ἀχερουσιὰς ὑψόθι τείνει,<br>δινήεις τ’ Ἀχέρων αὐτὴν διὰ νειόθι τέμνων<br>ἄκρην ἐκ μεγάλης προχοὰς ἵησι φάραγγος.<br>ἀγχίμολον δ’ ἐπὶ τῇ πολέας παρανεῖσθε κολωνοὺς<br>Παφλαγόνων, τοῖσίν τ’ Ἐνετήιος ἐμβασίλευσεν<br>πρῶτα Πέλοψ, τοῦ καί περ ἀφ’ αἵματος εὐχετόωνται.", "st": "2.341"}, {"sp": "N", "t": "“ἔστι δέ τις ἄκρη Ἑλίκης κατεναντίον Ἄρκτου,<br>πάντοθεν ἠλίβατος, καί μιν καλέουσι Κάραμβιν,<br>τῆς καὶ ὑπὲρ βορέαο περισχίζονται ἄελλαι·<br>ὧδε μάλ’ ἂμ πέλαγος τετραμμένη αἰθέρι κύρει.<br>τήνδε περιγνάμψαντι πολὺς παρακέκλιται· ἤδη<br>αἰγιαλός· πολέος δ’ ἐπὶ πείρασιν Αἰγιαλοῖο<br>ἀκτῇ ἐπὶ προβλῆτι ῥοαὶ Ἅλυος ποταμοῖο<br>δεινὸν ἐρεύγονται· μετὰ τὸν δ’ ἀγχίροος Ἶρις<br>μειότερος λευκῇσιν ἑλίσσεται εἰς ἅλα δίναις.<br>κεῖθεν δὲ προτέρωσε μέγας καὶ ὑπείροχος ἀγκὼν<br>ἐξανέχει γαίης· ἐπὶ δὲ στόμα Θερμώδοντος<br>κόλπῳ ἐν εὐδιόωντι Θεμισκύρειον ὑπ’ ἄκρην<br>μύρεται, εὐρείης διαειμένος ἠπείροιο.<br>ἔνθα δὲ Δοίαντος πεδίον, σχεδόθεν δὲ πόληες<br>τρισσαὶ Ἀμαζονίδων, μετά τε σμυγερώτατοι ἀνδρῶν<br>τρηχεῖαν Χάλυβες καὶ ἀτειρέα γαῖαν ἔχουσιν,<br>ἐργατίναι· τοὶ δ’ ἀμφὶ σιδήρεα ἔργα μέλονται.<br>ἄγχι δὲ ναιετάουσι πολύρρηνες Τιβαρηνοὶ<br>Ζηνὸς Ἐυξείνοιο Γενηταίην ὑπὲρ ἄκρην.<br>τῇ δ’ ἐπὶ Μοσσύνοικοι ὁμούριοι ὑλήεσσαν<br>ἑξείης ἤπειρον, ὑπωρείας τε νέμονται,<br>δουρατέοις πύργοισιν ἐν οἰκία τεκτήναντες<br>[κάλινα καὶ πύργους εὐπηγέας, οὓς καλέουσιν<br>μόσσυνας· καὶ δ’ αὐτοὶ ἐπώνυμοι ἔνθεν ἔασιν.]<br>τοὺς παραμειβόμενοι λισσῇ ἐπικέλσετε νήσῳ,<br>μήτι παντοίῃ μέγ’ ἀναιδέας ἐξελάσαντες<br>οἰωνούς, οἳ δῆθεν ἀπειρέσιοι ἐφέπουσιν<br>νῆσον ἐρημαίην. τῇ μέν τ’ ἐνὶ νηὸν Ἄρηος<br>λαΐνεον ποίησαν Ἀμαζονίδων βασίλειαι<br>Ὀτρηρή τε καὶ Ἀντιόπη, ὁπότε στρατόωντο.<br>ἔνθα γὰρ ὔμμιν ὄνειαρ ἀδευκέος ἐξ ἁλὸς εἶσιν<br>ἄρρητον· τῶ καί τε φίλα φρονέων ἀγορεύω<br>ἰσχέμεν. ἀλλὰ τίη με πάλιν χρειὼ ἀλιτέσθαι<br>μαντοσύνῃ τὰ ἕκαστα διηνεκὲς ἐξενέποντα;<br>νήσου δὲ προτέρωσε καὶ ἠπείροιο περαίης<br>φέρβονται Φίλυρες· Φιλύρων δ’ ἐφύπερθεν ἔασιν<br>Μάκρωνες· μετὰ δ’ αὖ περιώσια φῦλα Βεχείρων.<br>ἑξείης δὲ Σάπειρες ἐπὶ σφίσι ναιετάουσιν·<br>Βύζηρες δ’ ἐπὶ τοῖσιν ὁμώλακες, ὧν ὕπερ ἤδη<br>αὐτοὶ Κόλχοι ἔχονται ἀρήιοι. ἀλλ’ ἐνὶ νηὶ<br>πείρεθ’, ἕως μυχάτῃ κεν ἐνιχρίμψητε θαλάσσῃ.<br>ἔνθα δ’ ἐπ’ ἠπείροιο Κυταιίδος, ἠδ’ Ἀμαραντῶν<br>τηλόθεν ἐξ ὀρέων πεδίοιό τε Κιρκαίοιο<br>Φᾶσις δινήεις εὐρὺν ῥόον εἰς ἅλα βάλλει.<br>κείνου νῆ’ ἐλάοντες ἐπὶ προχοὰς ποταμοῖο<br>πύργους εἰσόψεσθε Κυταιέος Αἰήταο,<br>ἄλσος τε σκιόειν Ἄρεος, τόθι κῶας ἐπ’ ἄκρης<br>πεπτάμενον φηγοῖο δράκων, τέρας αἰνὸν ἰδέσθαι,<br>ἀμφὶς ὀπιπεύει δεδοκημένος· οὐδέ οἱ ἦμαρ,<br>οὐ κνέφας ἥδυμος ὕπνος ἀναιδέα δάμναται ὄσσε.”", "st": "2.360"}, {"sp": "N", "t": "ὧς ἄρ’ ἔφη· τοὺς δ’ εἶθαρ ἕλεν δέος εἰσαΐοντας.<br>δὴν δ’ ἔσαν ἀμφασίῃ βεβολημένοι· ὀψὲ δ’ ἔειπεν<br>ἥρως Αἴσονος υἱὸς ἀμηχανέων κακότητι·", "st": "2.408"}, {"sp": "N", "t": "“ὦ γέρον, ἤδη μέν τε διίκεο πείρατ’ ἀέθλων<br>ναυτιλίης καὶ τέκμαρ, ὅτῳ στυγερὰς διὰ πέτρας<br>πειθόμενοι Πόντονδε περήσομεν· εἰ δέ κεν αὖτις<br>τάσδ’ ἡμῖν προφυγοῦσιν ἐς Ἑλλάδα νόστος ὀπίσσω<br>ἔσσεται, ἀσπαστῶς κε παρὰ σέο καὶ τὸ δαείην.<br>πῶς ἔρδω, πῶς αὖτε τόσην ἁλὸς εἶμι κέλευθον,<br>νῆις ἐὼν ἑτάροις ἅμα νήισιν; Αἶα δὲ Κολχὶς<br>Πόντου καὶ γαίης ἐπικέκλιται ἐσχατιῇσιν.”", "st": "2.411"}, {"sp": "N", "t": "ὧς φάτο· τὸν δ’ ὁ γεραιὸς ἀμειβόμενος προσέειπεν·<br>“ὦ τέκος, εὖτ’ ἂν πρῶτα φύγῃς ὀλοὰς διὰ πέτρας,<br>θάρσει· ἐπεὶ δαίμων ἕτερον πλόον ἡγεμονεύσει<br>ἐξ Αἴης· μετὰ δ’ Αἶαν ἅλις πομπῆες ἔσονται.<br>ἀλλά, φίλοι, φράζεσθε θεᾶς δολόεσσαν ἀρωγὴν<br>Κύπριδος. ἐκ γὰρ τῆς κλυτὰ πείρατα κεῖται ἀέθλων.<br>καὶ δέ με μηκέτι τῶνδε περαιτέρω ἐξερέεσθε.”", "st": "2.419"}, {"sp": "N", "t": "ὧς φάτ’ Ἀγηνορίδης· ἐπὶ δὲ σχεδὸν υἱέε δοιὼ<br>Θρηικίου Βορέαο κατ’ αἰθέρος ἀίξαντε<br>οὐδῷ ἔπι κραιπνοὺς ἔβαλον πόδας· οἱ δ’ ἀνόρουσαν<br>ἐξ ἑδέων ἥρωες, ὅπως παρεόντας ἴδοντο.<br>Ζήτης δ’ ἱεμένοισιν, ἔτ’ ἄσπετον ἐκ καμάτοιο<br>ἆσθμ’ ἀναφυσιόων, μετεφώνεεν, ὅσσον ἄπωθεν<br>ἤλασαν, ἠδ’ ὡς Ἶρις ἐρύκακε τάσδε δαΐξαι,<br>ὅρκιά τ’ εὐμενέουσα θεὰ πόρεν, αἱ δ’ ὑπέδυσαν<br>δείματι Δικταίης περιώσιον ἄντρον ἐρίπνης.<br>γηθόσυνοι δἤπειτα δόμοις ἔνι πάντες ἑταῖροι<br>αὐτός τ’ ἀγγελίῃ Φινεὺς πέλεν. ὦκα δὲ τόνγε<br>Αἰσονίδης περιπολλὸν ἐυφρονέων προσέειπεν·", "st": "2.426"}, {"sp": "N", "t": "“ἦ ἄρα δή τις ἔην, Φινεῦ, θεός, ὃς σέθεν ἄτης<br>κήδετο λευγαλέης, καὶ δ’ ἡμέας αὖθι πέλασσεν<br>τηλόθεν, ὄφρα τοι υἷες ἀμύνειαν Βορέαο·<br>εἰ δὲ καὶ ὀφθαλμοῖσι φόως πόροι ἦ τ’ ἂν ὀίω<br>γηθήσειν, ὅσον εἴπερ ὑπότροπος οἴκαδ’ ἱκοίμην.”", "st": "2.438"}, {"sp": "N", "t": "ὧς ἔφατ’· αὐτὰρ ὁ τόνγε κατηφήσας προσέειπεν·<br>“Αἰσονίδη, τὸ μὲν οὐ παλινάγρετον, οὐδέ τι μῆχος<br>ἔστ’ ὀπίσω· κενεαὶ γὰρ ὑποσμύχονται ὀπωπαί.<br>ἀντὶ δὲ τοῦ θάνατόν μοι ἄφαρ θεὸς ἐγγυαλίξαι,<br>καί τε θανὼν πάσῃσι μετέσσομαι ἀγλαΐῃσιν.”", "st": "2.443"}, {"sp": "N", "t": "ὧς τώγ’ ἀλλήλοισι παραβλήδην ἀγόρευον.<br>αὐτίκα δ’ οὐ μετὰ δηρὸν ἀμειβομένων ἐφαάνθη<br>Ἠριγενής· τὸν δ’ ἀμφὶ περικτίται ἠγερέθοντο<br>ἀνέρες, οἳ καὶ πρόσθεν ἐπ’ ἤματι κεῖσε θάμιζον,<br>αἰὲν ὁμῶς φορέοντες ἑῆς ἀπὸ μοῖραν ἐδωδῆς.<br>τοῖς ὁ γέρων πάντεσσιν, ὅτις καὶ ἀφαυρὸς ἵκοιτο,<br>ἔχραεν ἐνδυκέως, πολέων δ’ ἀπὸ πήματ’ ἔλυσεν<br>μαντοσύνῃ· τῶ καί μιν ἐποιχόμενοι κομέεσκον.<br>σὺν τοῖσιν δ’ ἵκανε Παραίβιος, ὅς ῥά οἱ ἦεν<br>φίλτατος· ἀσπάσιος δὲ δόμοις ἔνι τούσγ’ ἐνόησεν.<br>πρὶν γὰρ δή νύ ποτ’ αὐτὸς ἀριστήων στόλον ἀνδρῶν<br>Ἑλλάδος ἐξανιόντα μετὰ πτόλιν Αἰήταο<br>πείσματ’ ἀνάψασθαι μυθήσατο Θυνίδι γαίῃ,<br>οἵ τέ οἱ Ἁρπυίας Διόθεν σχήσουσιν ἰούσας.<br>τοὺς μὲν ἔπειτ’ ἐπέεσσιν ἀρεσσάμενος πυκινοῖσιν<br>πέμφ’ ὁ γέρων· οἶον δὲ Παραίβιον αὐτόθι μίμνειν<br>κέκλετ’ ἀριστήεσσι σὺν ἀνδράσιν· αἶψα δὲ τόνγε<br>σφωιτέρων ὀίων ὅτις ἔξοχος, εἰς ἓ κομίσσαι<br>ἧκεν ἐποτρύνας. τοῦ δ’ ἐκ μεγάροιο κιόντος<br>μειλιχίως ἐρέτῃσιν ὁμηγερέεσσι μετηύδα·", "st": "2.448"}, {"sp": "N", "t": "“ὦ φίλοι, οὐκ ἄρα πάντες ὑπέρβιοι ἄνδρες ἔασιν,<br>οὐδ’ εὐεργεσίης ἀμνήμονες. ὡς καὶ ὅδ’ ἀνὴρ<br>τοῖος ἐὼν δεῦρ’ ἦλθεν, ἑὸν μόρον ὄφρα δαείη.<br>εὖτε γὰρ οὖν ὡς πλεῖστα κάμοι καὶ πλεῖστα μογήσαι,<br>δὴ τότε μιν περιπολλὸν ἐπασσυτέρη βιότοιο<br>χρησμοσύνη τρύχεσκεν· ἐπ’ ἤματι δ’ ἦμαρ ὀρώρει<br>κύντερον, οὐδέ τις ἦεν ἀνάπνευσις μογέοντι.<br>ἀλλ’ ὅγε πατρὸς ἑοῖο κακὴν τίνεσκεν ἀμοιβὴν<br>ἀμπλακίης. ὁ γὰρ οἶος ἐν οὔρεσι δένδρεα τέμνων<br>δή ποθ’ ἁμαδρυάδος νύμφης ἀθέριξε λιτάων,<br>ἥ μιν ὀδυρομένη ἀδινῷ μειλίσσετο μύθῳ,<br>μὴ ταμέειν πρέμνον δρυὸς ἥλικος, ᾗ ἔπι πουλὺν<br>αἰῶνα τρίβεσκε διηνεκές· αὐτὰρ ὁ τήνγε<br>ἀφραδέως ἔτμηξεν ἀγηνορίῃ νεότητος.<br>τῷ δ’ ἄρα νηκερδῆ νύμφη πόρεν οἶτον ὀπίσσω<br>αὐτῷ καὶ τεκέεσσιν. ἔγωγε μέν, εὖτ’ ἀφίκανεν,<br>ἀμπλακίην ἔγνων· βωμὸν δ’ ἐκέλευσα καμόντα<br>Θυνιάδος νύμφης, λωφήια ῥέξαι ἐπ’ αὐτῷ<br>ἱερά, πατρῴην αἰτεύμενον αἶσαν ἀλύξαι.<br>ἔνθ’ ἐπεὶ ἔκφυγε κῆρα θεήλατον, οὔποτ’ ἐμεῖο<br>ἐκλάθετ’, οὐδ’ ἀθέρισσε· μόλις δ’ ἀέκοντα θύραζε<br>πέμπω, ἐπεὶ μέμονέν γε παρέμμεναι ἀσχαλόωντι.”", "st": "2.468"}, {"sp": "N", "t": "ὧς φάτ’ Ἀγηνορίδης· ὁ δ’ ἐπισχεδὸν αὐτίκα δοιὼ<br>ἤλυθ’ ἄγων ποίμνηθεν ὄις. ἀνὰ δ’ ἵστατ’ Ἰήσων,<br>ἂν δὲ Βορήιοι υἷες ἐφημοσύνῃσι γέροντος.<br>ὦκα δὲ κεκλόμενοι μαντήιον Ἀπόλλωνα<br>ῥέζον ἐπ’ ἐσχαρόφιν νέον ἤματος ἀνομένοιο.<br>κουρότεροι δ’ ἑτάρων μενοεικέα δαῖτ’ ἀλέγυνον.<br>ἔνθ’ εὖ δαισάμενοι, τοὶ μὲν παρὰ πείσμασι νηός,<br>τοὶ δ’ αὐτοῦ κατὰ δώματ’ ἀολλέες εὐνάζοντο.<br>ἦρι δ’ ἐτήσιαι αὖραι ἐπέχραον, αἵ τ’ ἀνὰ πᾶσαν<br>γαῖαν ὁμῶς τοιῇδε Διὸς πνείουσιν ἀρωγῇ.", "st": "2.490"}, {"sp": "N", "t": "Κυρήνη πέφαταί τις ἕλος πάρα Πηνειοῖο<br>μῆλα νέμειν προτέροισι παρ’ ἀνδράσιν· εὔαδε γάρ οἱ<br>παρθενίη καὶ λέκτρον ἀκήρατον. αὐτὰρ Ἀπόλλων<br>τήνγ’ ἀνερεψάμενος ποταμῷ ἔπι ποιμαίνουσαν<br>τηλόθεν Αἱμονίης, χθονίῃς παρακάτθετο νύμφαις,<br>αἳ Λιβύην ἐνέμοντο παραὶ Μυρτώσιον αἶπος.<br>ἔνθα δ’ Ἀρισταῖον Φοίβῳ τέκεν, ὃν καλέουσιν<br>Ἀγρέα καὶ Νόμιον πολυλήιοι Αἱμονιῆες.<br>τὴν μὲν γὰρ φιλότητι θεὸς ποιήσατο νύμφην<br>αὐτοῦ μακραίωνα καὶ ἀγρότιν· υἷα δ’ ἔνεικεν<br>νηπίαχον Χείρωνος ὑπ’ ἄντροισιν κομέεσθαι.<br>τῷ καὶ ἀεξηθέντι θεαὶ γάμον ἐμνήστευσαν<br>Μοῦσαι, ἀκεστορίην τε θεοπροπίας τ’ ἐδίδαξαν·<br>καί μιν ἑῶν μήλων θέσαν ἤρανον, ὅσσ’ ἐνέμοντο<br>ἂμ πεδίον Φθίης Ἀθαμάντιον ἀμφί τ’ ἐρυμνὴν<br>Ὄθρυν καὶ ποταμοῦ ἱερὸν ῥόον Ἀπιδανοῖο.<br>ἦμος δ’ οὐρανόθεν Μινωίδας ἔφλεγε νήσους<br>Σείριος, οὐδ’ ἐπὶ δηρὸν ἔην ἄκος ἐνναέτῃσιν,<br>τῆμος τόνγ’ ἐκάλεσσαν ἐφημοσύναις Ἑκάτοιο<br>λοιμοῦ ἀλεξητῆρα. λίπεν δ’ ὅγε πατρὸς ἐφετμῇ<br>Φθίην, ἐν δὲ Κέῳ κατενάσσατο, λαὸν ἀγείρας<br>Παρράσιον, τοίπερ τε Λυκάονός εἰσι γενέθλης,<br>καὶ βωμὸν ποίησε μέγαν Διὸς Ἰκμαίοιο,<br>ἱερά τ’ εὖ ἔρρεξεν ἐν οὔρεσιν ἀστέρι κείνῳ<br>Σειρίῳ αὐτῷ τε Κρονίδῃ Διί. τοῖο δ’ ἕκητι<br>γαῖαν ἐπιψύχουσιν ἐτήσιαι ἐκ Διὸς αὖραι<br>ἤματα τεσσαράκοντα· Κέῳ δ’ ἔτι νῦν ἱερῆες<br>ἀντολέων προπάροιθε Κυνὸς ῥέζουσι θυηλάς.", "st": "2.500"}, {"sp": "N", "t": "καὶ τὰ μὲν ὧς ὑδέονται· ἀριστῆες δὲ καταῦθι<br>μίμνον ἐρυκόμενοι· ξεινήια δ’ ἄσπετα Θυνοὶ<br>πᾶν ἦμαρ Φινῆι χαριζόμενοι προΐαλλον.<br>ἐκ δὲ τόθεν μακάρεσσι δυώδεκα δωμήσαντες<br>βωμὸν ἁλὸς ῥηγμῖνι πέρην καὶ ἐφ’ ἱερὰ θέντες,<br>νῆα θοὴν εἴσβαινον ἐρεσσέμεν, οὐδὲ πελείης<br>τρήρωνος λήθοντο μετὰ σφίσιν· ἀλλ’ ἄρα τήνγε<br>δείματι πεπτηυῖαν ἑῇ φέρε χειρὶ μεμαρπὼς<br>Εὔφημος, γαίης δ’ ἀπὸ διπλόα πείσματ’ ἔλυσαν.", "st": "2.528"}, {"sp": "N", "t": "οὐδ’ ἄρ’ Ἀθηναίην προτέρω λάθον ὁρμηθέντες·<br>αὐτίκα δ’ ἐσσυμένως νεφέλης ἐπιβᾶσα πόδεσσιν<br>κούφης, ἥ κε φέροι μιν ἄφαρ βριαρήν περ ἐοῦσαν,<br>σεύατ’ ἴμεν πόντονδε, φίλα φρονέουσ’ ἐρέτῃσιν.<br>ὡς δ’ ὅτε τις πάτρηθεν ἀλώμενος, οἷά τε πολλὰ<br>πλαζόμεθ’ ἄνθρωποι τετληότες, οὐδέ τις αἶα<br>τηλουρός, πᾶσαι δὲ κατόψιοί εἰσι κέλευθοι,<br>σφωιτέρους δ’ ἐνόησε δόμους, ἄμυδις δὲ κέλευθος<br>ὑγρή τε τραφερή τ’ ἰνδάλλεται, ἄλλοτε δ’ ἄλλῃ<br>ὀξέα πορφύρων ἐπιμαίεται ὀφθαλμοῖσιν·<br>ὧς ἄρα καρπαλίμως κούρη Διὸς ἀίξασα<br>θῆκεν ἐπ’ ἀξείνοιο πόδας Θυνηίδος ἀκτῆς.", "st": "2.537"}, {"sp": "N", "t": "οἱ δ’ ὅτε δὴ σκολιοῖο πόρου στεινωπὸν ἵκοντο<br>τρηχείῃς σπιλάδεσσιν ἐεργμένον ἀμφοτέρωθεν,<br>δινήεις δ’ ὑπένερθεν ἀνακλύζεσκεν ἰοῦσαν<br>νῆα ῥόος, πολλὸν δὲ φόβῳ προτέρωσε νέοντο,<br>ἤδη δέ σφισι δοῦπος ἀρασσομένων πετράων<br>νωλεμὲς οὔατ’ ἔβαλλε, βόων δ’ ἁλιμυρέες ἀκταί,<br>δὴ τότ’ ἔπειθ’ ὁ μὲν ὦρτο πελειάδα χειρὶ μεμαρπὼς<br>Εὔφημος πρῴρης ἐπιβήμεναι· οἱ δ’ ὑπ’ ἀνωγῇ<br>Τίφυος Ἁγνιάδαο θελήμονα ποιήσαντο<br>εἰρεσίην, ἵν’ ἔπειτα διὲκ πέτρας ἐλάσειαν,<br>κάρτεϊ ᾧ πίσυνοι. τὰς δ’ αὐτίκα λοίσθιον ἄλλων<br>οἰγομένας ἀγκῶνα περιγνάμψαντες ἴδοντο.<br>σὺν δέ σφιν χύτο θυμός· ὁ δ’ ἀίξαι πτερύγεσσιν<br>Εὔφημος προέηκε πελειάδα· τοὶ δ’ ἅμα πάντες<br>ἤειραν κεφαλὰς ἐσορώμενοι· ἡ δὲ δι’ αὐτῶν<br>ἔπτατο· ταὶ δ’ ἄμυδις πάλιν ἀντίαι ἀλλήλῃσιν<br>ἄμφω ὁμοῦ ξυνιοῦσαι ἐπέκτυπον. ὦρτο δὲ πολλὴ<br>ἅλμη ἀναβρασθεῖσα, νέφος ὥς· αὖε δὲ πόντος<br>σμερδαλέον· πάντῃ δὲ περὶ μέγας ἔβρεμεν αἰθήρ.", "st": "2.549"}, {"sp": "N", "t": "κοῖλαι δὲ σπήλυγγες ὑπὸ σπιλάδας τρηχείας<br>κλυζούσης ἁλὸς ἔνδον ἐβόμβεον· ὑψόθι δ’ ὄχθης<br>λευκὴ καχλάζοντος ἀνέπτυε κύματος ἄχνη.<br>νῆα δ’ ἔπειτα πέριξ εἴλει ῥόος. ἄκρα δ’ ἔκοψαν<br>οὐραῖα πτερὰ ταίγε πελειάδος· ἡ δ’ ἀπόρουσεν<br>ἀσκηθής. ἐρέται δὲ μέγ’ ἴαχον· ἔβραχε δ’ αὐτὸς<br>Τῖφυς ἐρεσσέμεναι κρατερῶς. οἴγοντο γὰρ αὖτις<br>ἄνδιχα. τοὺς δ’ ἐλάοντας ἔχεν τρόμος, ὄφρα μιν αὐτὴ<br>πλημμυρὶς παλίνορσος ἀνερχομένη κατένεικεν<br>εἴσω πετράων. τότε δ’ αἰνότατον δέος εἷλεν<br>πάντας· ὑπὲρ κεφαλῆς γὰρ ἀμήχανος ἦεν ὄλεθρος.<br>ἤδη δ’ ἔνθα καὶ ἔνθα διὰ πλατὺς εἴδετο Πόντος,<br>καί σφισιν ἀπροφάτως ἀνέδυ μέγα κῦμα πάροιθεν<br>κυρτόν, ἀποτμῆγι σκοπιῇ ἴσον· οἱ δ’ ἐσιδόντες<br>ἤμυσαν λοξοῖσι καρήασιν. εἴσατο γάρ ῥα<br>νηὸς ὑπὲρ πάσης κατεπάλμενον ἀμφικαλύψειν.<br>ἀλλά μιν ἔφθη Τῖφυς ὑπ’ εἰρεσίῃ βαρύθουσαν<br>ἀγχαλάσας· τὸ δὲ πολλὸν ὑπὸ τρόπιν ἐξεκυλίσθη,<br>ἐκ δ’ αὐτὴν πρύμνηθεν ἀνείρυσε τηλόθι νῆα<br>πετράων· ὑψοῦ δὲ μεταχρονίη πεφόρητο.<br>Εὔφημος δ’ ἀνὰ πάντας ἰὼν βοάασκεν ἑταίρους,<br>ἐμβαλέειν κώπῃσιν ὅσον σθένος· οἱ δ’ ἀλαλητῷ<br>κόπτον ὕδωρ. ὅσσον δ’ ἂν ὑπείκαθε νηῦς ἐρέτῃσιν,<br>δὶς τόσον ἂψ ἀπόρουσεν· ἐπεγνάμπτοντο δὲ κῶπαι<br>ἠύτε καμπύλα τόξα, βιαζομένων ἡρώων.", "st": "2.568"}, {"sp": "N", "t": "ἔνθεν δ’ αὐτίκ’ ἔπειτα κατηρεφὲς ἔσσυτο κῦμα,<br>ἡ δ’ ἄφαρ ὥστε κύλινδρος ἐπέτρεχε κύματι λάβρῳ<br>προπροκαταΐγδην κοίλης ἁλός. ἐν δ’ ἄρα μέσσαις<br>Πληγάσι δινήεις εἶχεν ῥόος· αἱ δ’ ἑκάτερθεν<br>σειόμεναι βρόμεον· πεπέδητο δὲ νήια δοῦρα.<br>καὶ τότ’ Ἀθηναίη στιβαρῆς ἀντέσπασε πέτρης<br>σκαιῇ, δεξιτερῇ δὲ διαμπερὲς ὦσε φέρεσθαι.<br>ἡ δ’ ἰκέλη πτερόεντι μετήορος ἔσσυτ’ ὀιστῷ.<br>ἔμπης δ’ ἀφλάστοιο παρέθρισαν ἄκρα κόρυμβα<br>νωλεμὲς ἐμπλήξασαι ἐναντίαι. αὐτὰρ Ἀθήνη<br>Οὔλυμπόνδ’ ἀνόρουσεν, ὅτ’ ἀσκηθεῖς ὑπάλυξαν.<br>πέτραι δ’ εἰς ἕνα χῶρον ἐπισχεδὸν ἀλλήλῃσιν<br>νωλεμὲς ἐρρίζωθεν, ὃ δὴ καὶ μόρσιμον ἦεν<br>ἐκ μακάρων, εὖτ’ ἄν τις ἰδὼν διὰ νηὶ περήσῃ.<br>οἱ δέ που ὀκρυόεντος ἀνέπνεον ἄρτι φόβοιο<br>ἠέρα παπταίνοντες ὁμοῦ πέλαγός τε θαλάσσης<br>τῆλ’ ἀναπεπτάμενον. δὴ γὰρ φάσαν ἐξ Ἀίδαο<br>σώεσθαι· Τῖφυς δὲ παροίτατος ἤρχετο μύθων·", "st": "2.593"}, {"sp": "N", "t": "“ἔλπομαι αὐτῇ νηὶ τόγ’ ἔμπεδον ἐξαλέασθαι<br>ἡμέας· οὐδέ τις ἄλλος ἐπαίτιος, ὅσσον Ἀθήνη,<br>ἥ οἱ ἐνέπνευσεν θεῖον μένος, εὖτέ μιν Ἄργος<br>γόμφοισιν συνάρασσε· θέμις δ’ οὐκ ἔστιν ἁλῶναι.<br>Αἰσονίδη, τύνη δὲ τεοῦ βασιλῆος ἐφετμήν,<br>εὖτε διὲκ πέτρας φυγέειν θεὸς ἧμιν ὄπασσεν,<br>μηκέτι δείδιθι τοῖον· ἐπεὶ μετόπισθεν ἀέθλους<br>εὐπαλέας τελέεσθαι Ἀγηνορίδης φάτο Φινεύς.”", "st": "2.611"}, {"sp": "N", "t": "ἦ ῥ’ ἅμα, καὶ προτέρωσε παραὶ Βιθυνίδα γαῖαν<br>νῆα διὲκ πέλαγος σεῦεν μέσον. αὐτὰρ ὁ τόνγε<br>μειλιχίοις ἐπέεσσι παραβλήδην προσέειπεν·<br>“Τῖφυ, τίη μοι ταῦτα παρηγορέεις ἀχέοντι;<br>ἤμβροτον ἀασάμην τε κακὴν καὶ ἀμήχανον ἄτην.<br>χρῆν γὰρ ἐφιεμένοιο καταντικρὺ Πελίαο<br>αὐτίκ’ ἀνήνασθαι τόνδε στόλον, εἰ καὶ ἔμελλον<br>νηλειῶς μελεϊστὶ κεδαιόμενος θανέεσθαι·<br>νῦν δὲ περισσὸν δεῖμα καὶ ἀτλήτους μελεδῶνας<br>ἄγκειμαι, στυγέων μὲν ἁλὸς κρυόεντα κέλευθα<br>νηὶ διαπλώειν, στυγέων δ’, ὅτ’ ἐπ’ ἠπείροιο<br>βαίνωμεν. πάντῃ γὰρ ἀνάρσιοι ἄνδρες ἔασιν.<br>αἰεὶ δὲ στονόεσσαν ἐπ’ ἤματι νύκτα φυλάσσω,<br>ἐξότε τὸ πρώτιστον ἐμὴν χάριν ἠγερέθεσθε,<br>φραζόμενος τὰ ἕκαστα σὺ δ’ εὐμαρέως ἀγορεύεις<br>οἶον ἑῆς ψυχῆς ἀλέγων ὕπερ· αὐτὰρ ἔγωγε<br>εἷο μὲν οὐδ’ ἠβαιὸν ἀτύζομαι· ἀμφὶ δὲ τοῖο<br>καὶ τοῦ ὁμῶς, καὶ σεῖο, καὶ ἄλλων δείδι’ ἑταίρων<br>εἰ μὴ ἐς Ἑλλάδα γαῖαν ἀπήμονας ὔμμε κομίσσω.”", "st": "2.619"}, {"sp": "N", "t": "ὧς φάτ’ ἀριστήων πειρώμενος· οἱ δ’ ὁμάδησαν<br>θαρσαλέοις ἐπέεσσιν. ὁ δὲ φρένας ἔνδον ἰάνθη<br>κεκλομένων, καί ῥ’ αὖτις ἐπιρρήδην μετέειπεν·", "st": "2.638"}, {"sp": "N", "t": "“ὦ φίλοι, ὑμετέρῃ ἀρετῇ ἔνι θάρσος ἀέξω.<br>τούνεκα νῦν οὐδ’ εἴ κε διὲξ Ἀίδαο βερέθρων<br>στελλοίμην, ἔτι τάρβος ἀνάψομαι, εὖτε πέλεσθε<br>ἔμπεδοι ἀργαλέοις ἐνὶ δείμασιν. ἀλλ’ ὅτε πέτρας<br>Πληγάδας ἐξέπλωμεν, ὀίομαι οὐκ ἔτ’ ὀπίσσω<br>ἔσσεσθαι τοιόνδ’ ἕτερον φόβον, εἰ ἐτεόν γε<br>φραδμοσύνῃ Φινῆος ἐπισπόμενοι νεόμεσθα.”", "st": "2.641"}, {"sp": "N", "t": "ὧς φάτο, καὶ τοίων μὲν ἐλώφεον αὐτίκα μύθων,<br>εἰρεσίῃ δ’ ἀλίαστον ἔχον πόνον· αἶψα δὲ τοίγε<br>Ῥήβαν ὠκυρόην ποταμὸν σκόπελόν τε Κολώνης,<br>ἄκρην δ’ οὐ μετὰ δηθὰ παρεξενέοντο Μέλαιναν,<br>τῇ δ’ ἄρ’ ἐπὶ προχοὰς Φυλληίδας, ἔνθα πάροιθεν<br>Διψακὸς υἷ’ Ἀθάμαντος ἑοῖς ὑπέδεκτο δόμοισιν,<br>ὁππόθ’ ἅμα κριῷ φεῦγεν πόλιν Ὀρχομενοῖο·<br>τίκτε δέ μιν νύμφη λειμωνιάς· οὐδέ οἱ ὕβρις<br>ἥνδανεν, ἀλλ’ ἐθελημὸς ἐφ’ ὕδασι πατρὸς ἑοῖο<br>μητέρι συνναίεσκεν ἐπάκτια πώεα φέρβων.<br>τοῦ μέν θ’ ἱερὸν αἶψα, καὶ εὐρείας ποταμοῖο<br>ἠιόνας πεδίον τε, βαθυρρείοντά τε Κάλπην<br>δερκόμενοι παράμειβον, ὁμῶς δ’ ἐπὶ ἤματι νύκτα<br>νήνεμον ἀκαμάτῃσιν ἐπερρώοντ’ ἐλάτῃσιν.<br>οἷον δὲ πλαδόωσαν ἐπισχίζοντες ἄρουραν<br>ἐργατίναι μογέουσι βόες, περὶ δ’ ἄσπετος ἱδρὼς<br>εἴβεται ἐκ λαγόνων τε καὶ αὐχένος· ὄμματα δέ σφιν<br>λοξὰ παραστρωφῶνται ὑπὸ ζυγοῦ· αὐτὰρ ἀυτμὴ<br>αὐαλέη στομάτων ἄμοτον βρέμει· οἱ δ’ ἐνὶ γαίῃ<br>χηλὰς σκηρίπτοντε πανημέριοι πονέονται.<br>τοῖς ἴκελοι ἥρωες ὑπὲξ ἁλὸς εἷλκον ἐρετμά.", "st": "2.648"}, {"sp": "N", "t": "ἦμος δ’ οὔτ’ ἄρ πω φάος ἄμβροτον, οὔτ’ ἔτι λίην<br>ὀρφναίη πέλεται, λεπτὸν δ’ ἐπιδέδρομε νυκτὶ<br>φέγγος, ὅτ’ ἀμφιλύκην μιν ἀνεγρόμενοι καλέουσιν,<br>τῆμος ἐρημαίης νήσου λιμέν’ εἰσελάσαντες<br>Θυνιάδος, καμάτῳ πολυπήμονι βαῖνον ἔραζε.<br>τοῖσι δὲ Λητοῦς υἱός, ἀνερχόμενος Λυκίηθεν<br>τῆλ’ ἐπ’ ἀπείρονα δῆμον Ὑπερβορέων ἀνθρώπων,<br>ἐξεφάνη· χρύσεοι δὲ παρειάων ἑκάτερθεν<br>πλοχμοὶ βοτρυόεντες ἐπερρώοντο κιόντι·<br>λαιῇ δ’ ἀργύρεον νώμα βιόν, ἀμφὶ δὲ νώτοις<br>ἰοδόκη τετάνυστο κατωμαδόν· ἡ δ’ ὑπὸ ποσσὶν<br>σείετο νῆσος ὅλη, κλύζεν δ’ ἐπὶ κύματα χέρσῳ.<br>τοὺς δ’ ἕλε θάμβος ἰδόντας ἀμήχανον· οὐδέ τις ἔτλη<br>ἀντίον αὐγάσσασθαι ἐς ὄμματα καλὰ θεοῖο.<br>στὰν δὲ κάτω νεύσαντες ἐπὶ χθονός· αὐτὰρ ὁ τηλοῦ<br>βῆ ῥ’ ἴμεναι πόντονδε δι’ ἠέρος· ὀψὲ δὲ τοῖον<br>Ὀρφεὺς ἔκφατο μῦθον ἀριστήεσσι πιφαύσκων·", "st": "2.669"}, {"sp": "N", "t": "“εἰ δ’ ἄγε δὴ νῆσον μὲν Ἑωίου Ἀπόλλωνος<br>τήνδ’ ἱερὴν κλείωμεν, ἐπεὶ πάντεσσι φαάνθη<br>ἠῷος μετιών· τὰ δὲ ῥέξομεν οἷα πάρεστιν,<br>βωμὸν ἀναστήσαντες ἐπάκτιον· εἰ δ’ ἂν ὀπίσσω<br>γαῖαν ἐς Αἱμονίην ἀσκηθέα νόστον ὀπάσσῃ,<br>δὴ τότε οἱ κεραῶν ἐπὶ μηρία θήσομεν αἰγῶν.<br>νῦν δ’ αὔτως κνίσῃ λοιβῇσί τε μειλίξασθαι<br>κέκλομαι. ἀλλ’ ἵληθι ἄναξ, ἵληθι φαανθείς.”", "st": "2.686"}, {"sp": "N", "t": "ὧς ἄρ’ ἔφη· καὶ τοὶ μὲν ἄφαρ βωμὸν τετύκοντο<br>χερμάσιν· οἱ δ’ ἀνὰ νῆσον ἐδίνεον, ἐξερέοντες<br>εἴ κέ τιν’ ἢ κεμάδων, ἢ ἀγροτέρων ἐσίδοιεν<br>αἰγῶν, οἷά τε πολλὰ βαθείῃ βόσκεται ὕλῃ.<br>τοῖσι δὲ Λητοΐδης ἄγρην πόρεν· ἐκ δέ νυ πάντων<br>εὐαγέως ἱερῷ ἀνὰ διπλόα μηρία βωμῷ<br>καῖον, ἐπικλείοντες Ἑώιον Ἀπόλλωνα.<br>ἀμφὶ δὲ δαιομένοις εὐρὺν χορὸν ἐστήσαντο,<br>καλὸν Ἰηπαιήον’ Ἰηπαιήονα Φοῖβον<br>μελπόμενοι· σὺν δέ σφιν ἐὺς πάις Οἰάγροιο<br>Βιστονίῃ φόρμιγγι λιγείης ἦρχεν ἀοιδῆς·<br>ὥς ποτε πετραίῃ ὑπὸ δειράδι Παρνησσοῖο<br>Δελφύνην τόξοισι πελώριον ἐξενάριξεν,<br>κοῦρος ἐὼν ἔτι γυμνός, ἔτι πλοκάμοισι γεγηθώς.<br>ἱλήκοις· αἰεί τοι, ἄναξ, ἄτμητοι ἔθειραι,<br>αἰὲν ἀδήλητοι· τὼς γὰρ θέμις. οἰόθι δ’ αὐτὴ<br>Λητὼ Κοιογένεια φίλαις ἐν χερσὶν ἀφάσσει.<br>πολλὰ δὲ Κωρύκιαι νύμφαι, Πλείστοιο θύγατρες,<br>θαρσύνεσκον ἔπεσσιν, Ἰήιε κεκληγυῖαι·<br>ἔνθεν δὴ τόδε καλὸν ἐφύμνιον ἔπλετο Φοίβῳ.", "st": "2.694"}, {"sp": "N", "t": "αὐτὰρ ἐπειδὴ τόνγε χορείῃ μέλψαν ἀοιδῇ,<br>λοιβαῖς εὐαγέεσσιν ἐπώμοσαν, ἦ μὲν ἀρήξειν<br>ἀλλήλοις εἰσαιὲν ὁμοφροσύνῃσι νόοιο,<br>ἁπτόμενοι θυέων· καί τ’ εἰσέτι νῦν γε τέτυκται<br>κεῖσ’ Ὁμονοίης ἱρὸν ἐύφρονος, ὅ ῥ’ ἐκάμοντο<br>αὐτοὶ κυδίστην τότε δαίμονα πορσαίνοντες.", "st": "2.714"}, {"sp": "N", "t": "ἦμος δὲ τρίτατον φάος ἤλυθε, δὴ τότ’ ἔπειτα<br>ἀκραεῖ ζεφύρῳ νῆσον λίπον αἰπήεσσαν.<br>ἔνθεν δ’ ἀντιπέρην ποταμοῦ στόμα Σαγγαρίοιο<br>καὶ Μαριανδυνῶν ἀνδρῶν ἐριθηλέα γαῖαν<br>ἠδὲ Λύκοιο ῥέεθρα καὶ Ἀνθεμοεισίδα λίμνην<br>δερκόμενοι παράμειβον· ὑπὸ πνοιῇ δὲ κάλωες<br>ὅπλα τε νήια πάντα τινάσσετο νισσομένοισιν.<br>ἠῶθεν δ’ ἀνέμοιο διὰ κνέφας εὐνηθέντος<br>ἀσπασίως ἄκρης Ἀχερουσίδος ὅρμον ἵκοντο.<br>ἡ μέν τε κρημνοῖσιν ἀνίσχεται ἠλιβάτοισιν,<br>εἰς ἅλα δερκομένη Βιθυνίδα· τῇ δ’ ὑπὸ πέτραι<br>λισσάδες ἐρρίζωνται ἁλίβροχοι· ἀμφὶ δὲ τῇσιν<br>κῦμα κυλινδόμενον μεγάλα βρέμει· αὐτὰρ ὕπερθεν<br>ἀμφιλαφεῖς πλατάνιστοι ἐπ’ ἀκροτάτῃ πεφύασιν.<br>ἐκ δ’ αὐτῆς εἴσω κατακέκλιται ἤπειρόνδε<br>κοίλη ὕπαιθα νάπη, ἵνα τε σπέος ἔστ’ Ἀίδαο<br>ὕλῃ καὶ πέτρῃσιν ἐπηρεφές, ἔνθεν ἀυτμὴ<br>πηγυλίς, ὀκρυόεντος ἀναπνείουσα μυχοῖο<br>συνεχές, ἀργινόεσσαν ἀεὶ περιτέτροφε πάχνην,<br>ἥ τε μεσημβριόωντος ἰαίνεται ἠελίοιο.<br>σιγὴ δ’ οὔποτε τήνγε κατὰ βλοσυρὴν ἔχει ἄκρην,<br>ἀλλ’ ἄμυδις πόντοιό θ’ ὑπὸ στένει ἠχήεντος,<br>φύλλων τε πνοιῇσι τινασσομένων μυχίῃσιν.<br>ἔνθα δὲ καὶ προχοαὶ ποταμοῦ Ἀχέροντος ἔασιν,<br>ὅς τε διὲξ ἄκρης ἀνερεύγεται εἰς ἅλα βάλλων<br>ἠῴην· κοίλη δὲ φάραγξ κατάγει μιν ἄνωθεν.<br>τὸν μὲν ἐν ὀψιγόνοισι Σοωναύτην ὀνόμηναν<br>Νισαῖοι Μεγαρῆες, ὅτε νάσσεσθαι ἔμελλον<br>γῆν Μαριανδυνῶν. δὴ γάρ σφεας ἐξεσάωσεν<br>αὐτῇσιν νήεσσι, κακῇ χρίμψαντας ἀέλλῃ.<br>τῇ ῥ’ οἵγ’ αὐτίκα νηὶ διὲξ Ἀχερουσίδος ἄκρης<br>εἰσωποὶ ἀνέμοιο νέον λήγοντος ἔκελσαν.", "st": "2.720"}, {"sp": "N", "t": "οὐδ’ ἄρα δηθὰ Λύκον, κείνης πρόμον ἠπείροιο,<br>καὶ Μαριανδυνοὺς λάθον ἀνέρας ὁρμισθέντες<br>αὐθένται Ἀμύκοιο κατὰ κλέος, ὃ πρὶν ἄκουον·<br>ἀλλὰ καὶ ἀρθμὸν ἔθεντο μετὰ σφίσι τοῖο ἕκητι.<br>αὐτὸν δ’ ὥστε θεὸν Πολυδεύκεα δεξιόωντο<br>πάντοθεν ἀγρόμενοι· ἐπεὶ ἦ μάλα τοίγ’ ἐπὶ δηρὸν<br>ἀντιβίην Βέβρυξιν ὑπερφιάλοις πολέμιζον.<br>καὶ δὴ πασσυδίῃ μεγάρων ἔντοσθε Λύκοιο<br>κεῖν’ ἦμαρ φιλότητι, μετὰ πτολίεθρον ἰόντες,<br>δαίτην ἀμφίεπον, τέρποντό τε θυμὸν ἔπεσσιν.<br>Αἰσονίδης μέν οἱ γενεὴν καὶ οὔνομ’ ἑκάστου<br>σφωιτέρων μυθεῖθ’ ἑτάρων, Πελίαό τ’ ἐφετμάς,<br>ἠδ’ ὡς Λημνιάδεσσιν ἐπεξεινοῦντο γυναιξίν,<br>ὅσσα τε Κύζικον ἀμφὶ Δολιονίην ἐτέλεσσαν·<br>Μυσίδα δ’ ὡς ἀφίκοντο Κίον θ’, ὅθι κάλλιπον ἥρω<br>Ἡρακλέην ἀέκοντι νόῳ, Γλαύκοιό τε βάξιν<br>πέφραδε, καὶ Βέβρυκας ὅπως Ἄμυκόν τ’ ἐδάιξαν,<br>καὶ Φινῆος ἔειπε θεοπροπίας τε δύην τε,<br>ἠδ’ ὡς Κυανέας πέτρας φύγον, ὥς τ’ ἀβόλησαν<br>Λητοΐδῃ κατὰ νῆσον. ὁ δ’ ἑξείης ἐνέποντος<br>θέλγετ’ ἀκουῇ θυμόν· ἄχος δ’ ἕλεν Ἡρακλῆι<br>λειπομένῳ, καὶ τοῖον ἔπος πάντεσσι μετηύδα·", "st": "2.752"}, {"sp": "N", "t": "“ὦ φίλοι, οἵου φωτὸς ἀποπλαγχθέντες ἀρωγῆς<br>πείρετ’ ἐς Αἰήτην τόσσον πλόον. εὖ γὰρ ἐγώ μιν<br>Δασκύλου ἐν μεγάροισι καταυτόθι πατρὸς ἐμοῖο<br>οἶδ’ ἐσιδών, ὅτε δεῦρο δι’ Ἀσίδος ἠπείροιο<br>πεζὸς ἔβη ζωστῆρα φιλοπτολέμοιο κομίζων<br>Ἱππολύτης· ἐμὲ δ’ εὗρε νέον χνοάοντα ἰούλους.<br>ἔνθα δ’ ἐπὶ Πριόλαο κασιγνήτοιο θανόντος<br>ἡμετέρου Μυσοῖσιν ὑπ’ ἀνδράσιν, ὅντινα λαὸς<br>οἰκτίστοις ἐλέγοισιν ὀδύρεται ἐξέτι κείνου,<br>ἀθλεύων Τιτίην ἀπεκαίνυτο πυγμαχέοντα<br>καρτερόν, ὃς πάντεσσι μετέπρεπεν ἠιθέοισιν<br>εἶδός τ’ ἠδὲ βίην· χαμάδις δέ οἱ ἤλασ’ ὀδόντας.<br>αὐτὰρ ὁμοῦ Μυσοῖσιν ἐμῷ ὑπὸ πατρὶ δάμασσεν<br>καὶ Φρύγας, οἳ ναίουσιν ὁμώλακας ἧμιν ἀρούρας,<br>φῦλά τε Βιθυνῶν αὐτῇ κτεατίσσατο γαίῃ,<br>ἔστ’ ἐπὶ Ῥηβαίου προχοὰς σκόπελόν τε Κολώνης·<br>Παφλαγόνες τ’ ἐπὶ τοῖς Πελοπήιοι εἴκαθον αὔτως,<br>ὅσσους Βιλλαίοιο μέλαν περιάγνυται ὕδωρ.<br>ἀλλά με νῦν Βέβρυκες ὑπερβασίη τ’ Ἀμύκοιο<br>τηλόθι ναιετάοντος, ἐνόσφισαν, Ἡρακλῆος,<br>δὴν ἀποτεμνόμενοι γαίης ἅλις, ὄφρ’ ἐβάλοντο<br>οὖρα βαθυρρείοντος ὑφ’ εἱαμεναῖς Ὑπίοιο.<br>ἔμπης δ’ ἐξ ὑμέων ἔδοσαν τίσιν· οὐδέ ἕ φημι<br>ἤματι τῷδ’ ἀέκητι θεῶν ἐπελάσσαι ἄρηα,<br>Τυνδαρίδην Βέβρυξιν, ὅτ’ ἀνέρα κεῖνον ἔπεφνεν.<br>τῶ νῦν ἥντιν’ ἐγὼ τῖσαι χάριν ἄρκιός εἰμι,<br>τίσω προφρονέως. ἡ γὰρ θέμις ἠπεδανοῖσιν<br>ἀνδράσιν, εὖτ’ ἄρξωσιν ἀρείονες ἄλλοι ὀφέλλειν.<br>ξυνῇ μὲν πάντεσσιν ὁμόστολον ὔμμιν ἕπεσθαι<br>Δάσκυλον ὀτρυνέω, ἐμὸν υἱέα· τοῖο δ’ ἰόντος,<br>ἦ τ’ ἂν ἐυξείνοισι διὲξ ἁλὸς ἀντιάοιτε<br>ἀνδράσιν, ὄφρ’ αὐτοῖο ποτὶ στόμα Θερμώδοντος.<br>νόσφι δὲ Τυνδαρίδαις Ἀχερουσίδος ὑψόθεν ἄκρης<br>εἵσομαι ἱερὸν αἰπύ· τὸ μὲν μάλα τηλόθι πάντες<br>ναυτίλοι ἂμ πέλαγος θηεύμενοι ἱλάξονται·<br>καί κέ σφιν μετέπειτα πρὸ ἄστεος, οἷα θεοῖσιν,<br>πίονας εὐα·ρότοιο γύας πεδίοιο ταμοίμην.”", "st": "2.774"}, {"sp": "N", "t": "ὧς τότε μὲν δαῖτ’ ἀμφὶ πανήμεροι ἑψιόωντο.<br>ἦρί γε μὴν ἐπὶ νῆα κατήισαν ἐγκονέοντες·<br>καὶ δ’ αὐτὸς σὺν τοῖσι Λύκος κίε, μυρί’ ὀπάσσας<br>δῶρα φέρειν· ἅμα δ’ υἷα δόμων ἔκπεμπε νέεσθαι.", "st": "2.811"}, {"sp": "N", "t": "ἔνθα δ’ Ἀβαντιάδην πεπρωμένη ἤλασε μοῖρα<br>Ἴδμονα, μαντοσύνῃσι κεκασμένον. ἀλλά μιν οὔτι<br>μαντοσύναι ἐσάωσαν, ἐπεὶ χρεὼ ἦγε δαμῆναι·<br>κεῖτο γὰρ εἱαμενῇ δονακώδεος ἐν ποταμοῖο<br>ψυχόμενος λαγόνας τε καὶ ἄσπετον ἰλύι νηδὺν<br>κάπριος ἀργιόδων, ὀλοὸν τέρας, ὅν ῥα καὶ αὐταὶ<br>νύμφαι ἑλειονόμοι ὑπεδείδισαν· οὐδέ τις ἀνδρῶν<br>ἠείδει· οἶος δὲ κατὰ πλατὺ βόσκετο τῖφος.<br>αὐτὰρ ὅγ’ ἰλυόεντος ἀνὰ θρωσμοὺς ποταμοῖο<br>νίσσετ’ Ἀβαντιάδης· ὁ δ’ ἄρ’ ἔκποθεν ἀφράστοιο<br>ὕψι μάλ’ ἐκ δονάκων ἀνεπάλμενος ἤλασε μηρὸν<br>ἀίγδην, μέσσας δὲ σὺν ὀστέῳ ἶνας ἔκερσεν.<br>ὀξὺ δ’ ὅγε κλάγξας οὔδει πέσεν· οἱ δὲ τυπέντος<br>ἀθρόοι ἀντιάχησαν. ὀρέξατο δ’ αἶψ’ ὀλοοῖο<br>Πηλεὺς αἰγανέῃ φύγαδ’ εἰς ἕλος ὁρμηθέντος<br>καπρίου· ἔσσυτο δ’ αὖτις ἐναντίος· ἀλλά μιν Ἴδας<br>οὔτασε, βεβρυχὼς δὲ θοῷ περικάππεσε δουρί.<br>καὶ τὸν μὲν χαμάδις λίπον αὐτόθι πεπτηῶτα·<br>τὸν δ’ ἕταροι ἐπὶ νῆα φέρον ψυχορραγέοντα,<br>ἀχνύμενοι, χείρεσσι δ’ ἑῶν ἐνικάτθαν’ ἑταίρων.", "st": "2.815"}, {"sp": "N", "t": "ἔνθα δὲ ναυτιλίης μὲν ἐρητύοντο μέλεσθαι,<br>ἀμφὶ δὲ κηδείῃ νέκυος μένον ἀσχαλόωντες.<br>ἤματα δὲ τρία πάντα γόων· ἑτέρῳ δέ μιν ἤδη<br>τάρχυον μεγαλωστί· συνεκτερέιζε δὲ λαὸς<br>αὐτῷ ὁμοῦ βασιλῆι Λύκῳ· παρὰ δ’ ἄσπετα μῆλα,<br>ἣ θέμις οἰχομένοισι, ταφήια λαιμοτόμησαν.<br>καὶ δή τοι κέχυται τοῦδ’ ἀνέρος ἐν χθονὶ κείνῃ<br>τύμβος· σῆμα δ’ ἔπεστι καὶ ὀψιγόνοισιν ἰδέσθαι,<br>νηίου ἐκ κοτίνοιο φάλαγξ· θαλέθει δέ τε φύλλοις<br>ἄκρης τυτθὸν ἔνερθ’ Ἀχερουσίδος. εἰ δέ με καὶ τὸ<br>χρειὼ ἀπηλεγέως Μουσέων ὕπο γηρύσασθαι,<br>τόνδε πολισσοῦχον διεπέφραδε Βοιωτοῖσιν<br>Νισαίοισί τε Φοῖβος ἐπιρρήδην ἱλάεσθαι,<br>ἀμφὶ δὲ τήνγε φάλαγγα παλαιγενέος κοτίνοιο<br>ἄστυ βαλεῖν· οἱ δ’ ἀντὶ θεουδέος Αἰολίδαο<br>Ἴδμονος εἰσέτι νῦν Ἀγαμήστορα κυδαίνουσιν.", "st": "2.835"}, {"sp": "N", "t": "τίς γὰρ δὴ θάνεν ἄλλος; ἐπεὶ καὶ ἔτ’ αὖτις ἔχευαν<br>ἥρωες τότε τύμβον ἀποφθιμένου ἑτάροιο.<br>δοιὰ γὰρ οὖν κείνων ἔτι σήματα φαίνεται ἀνδρῶν.<br>Ἁγνιάδην Τῖφυν θανέειν φάτις· οὐδέ οἱ ἦεν<br>μοῖρ’ ἔτι ναυτίλλεσθαι ἑκαστέρω. ἀλλά νυ καὶ τὸν<br>αὖθι μινυνθαδίη πάτρης ἑκὰς εὔνασε νοῦσος,<br>εἰσότ’ Ἀβαντιάδαο νέκυν κτερέιξεν ὅμιλος.<br>ἄτλητον δ’ ὀλοῷ ἐπὶ πήματι κῆδος ἕλοντο.<br>δὴ γὰρ ἐπεὶ καὶ τόνδε παρασχεδὸν ἐκτερέιξαν<br>αὐτοῦ, ἀμηχανίῃσιν ἁλὸς προπάροιθε πεσόντες,<br>ἐντυπὰς εὐκήλως εἰλυμένοι οὔτε τι σίτου<br>μνώοντ’ οὔτε ποτοῖο· κατήμυσαν δ’ ἀχέεσσιν<br>θυμόν, ἐπεὶ μάλα πολλὸν ἀπ’ ἐλπίδος ἔπλετο νόστος.<br>καί νύ κ’ ἔτι προτέρω τετιημένοι ἰσχανόωντο,<br>εἰ μὴ ἄρ’ Ἀγκαίῳ περιώσιον ἔμβαλεν Ἥρη<br>θάρσος, ὃν Ἰμβρασίοισι παρ’ ὕδασιν Ἀστυπάλαια<br>τίκτε Ποσειδάωνι· περιπρὸ γὰρ εὖ ἐκέκαστο<br>ἰθύνειν, Πηλῆα δ’ ἐπεσσύμενος προσέειπεν·", "st": "2.851"}, {"sp": "N", "t": "“Αἰακίδη, πῶς καλὸν ἀφειδήσαντας ἀέθλων<br>γαίῃ ἐν ἀλλοδαπῇ δὴν ἔμμεναι; οὐ μὲν ἄρηος<br>ἴδριν ἐόντα με τόσσον ἄγει μετὰ κῶας Ἰήσων<br>παρθενίης ἀπάνευθεν, ὅσον τ’ ἐπιίστορα νηῶν.<br>τῶ μή μοι τυτθόν γε δέος περὶ νηὶ πελέσθω.<br>ὧς δὲ καὶ ὧλλοι δεῦρο δαήμονες ἄνδρες ἔασιν,<br>τῶν ὅτινα πρύμνης ἐπιβήσομεν, οὔτις ἰάψει<br>ναυτιλίην. ἀλλ’ ὦκα, παραιφάμενος τάδε πάντα,<br>θαρσαλέως ὀρόθυνον ἐπιμνήσασθαι ἀέθλου.”", "st": "2.869"}, {"sp": "N", "t": "ὧς φάτο· τοῖο δὲ θυμὸς ὀρέξατο γηθοσύνῃσιν.<br>αὐτίκα δ’ οὐ μετὰ δηρὸν ἐνὶ μέσσοις ἀγόρευσεν·<br>“δαιμόνιοι, τί νυ πένθος ἐτώσιον ἴσχομεν αὔτως;<br>οἱ μὲν γάρ ποθι τοῦτον, ὃν ἔλλαχον, οἶτον ὄλοντο·<br>ἡμῖν δ’ ἐν γὰρ ἔασι κυβερνητῆρες ὁμίλῳ,<br>καὶ πολέες. τῶ μή τι διατριβώμεθα πείρης·<br>ἀλλ’ ἔγρεσθ’ εἰς ἔργον, ἀπορρίψαντες ἀνίας.”", "st": "2.878"}, {"sp": "N", "t": "τὸν δ’ αὖτ’ Αἴσονος υἱὸς ἀμηχανέων προσέειπεν·<br>“Αἰακίδη, πῇ δ’ οἵδε κυβερνητῆρες ἔασιν;<br>οὓς μὲν γὰρ τὸ πάροιθε δαήμονας εὐχόμεθ’ εἶναι,<br>οἱ δὲ κατηφήσαντες ἐμεῦ πλέον ἀσχαλόωσιν.<br>τῶ καὶ ὁμοῦ φθιμένοισι κακὴν προτιόσσομαι ἄτην,<br>εἰ δὴ μήτ’ ὀλοοῖο μετὰ πτόλιν Αἰήταο<br>ἔσσεται, ἠὲ καὶ αὖτις ἐς Ἑλλάδα γαῖαν ἱκέσθαι<br>πετράων ἔκτοσθε, κατ’ αὐτόθι δ’ ἄμμε καλύψει<br>ἀκλειῶς κακὸς οἶτος, ἐτώσια γηράσκοντας.”", "st": "2.885"}, {"sp": "N", "t": "ὧς ἔφατ’· Ἀγκαῖος δὲ μάλ’ ἐσσυμένως ὑπέδεκτο<br>νῆα θοὴν ἄξειν· δὴ γὰρ θεοῦ ἐτράπεθ’ ὁρμῇ.<br>τὸν δὲ μετ’ Ἐργῖνος καὶ Ναύπλιος Εὔφημός τε<br>ὤρνυντ’, ἰθύνειν λελιημένοι. ἀλλ’ ἄρα τούσγε<br>ἔσχεθον· Ἀγκαίῳ δὲ πολεῖς ᾔνησαν ἑταίρων.", "st": "2.894"}, {"sp": "N", "t": "Ἠῷοι δἤπειτα δυωδεκάτῳ ἐπέβαινον<br>ἤματι· δὴ γάρ σφιν ζεφύρου μέγας οὖρος ἄητο.<br>καρπαλίμως δ’ Ἀχέροντα διεξεπέρησαν ἐρετμοῖς,<br>ἐκ δ’ ἔχεαν πίσυνοι ἀνέμῳ λίνα, πουλὺ δ’ ἐπιπρὸ<br>λαιφέων πεπταμένων τέμνον πλόον εὐδιόωντες.<br>ὦκα δὲ Καλλιχόροιο παρὰ προχοὰς ποταμοῖο<br>ἤλυθον, ἔνθ’ ἐνέπουσι Διὸς Νυσήιον υἷα,<br>Ἰνδῶν ἡνίκα φῦλα λιπὼν κατενάσσατο Θήβας,<br>ὀργιάσαι, στῆσαί τε χοροὺς ἄντροιο πάροιθεν,<br>ᾧ ἐν ἀμειδήτους ἁγίας ηὐλίζετο νύκτας,<br>ἐξ οὗ Καλλίχορον ποταμὸν περιναιετάοντες<br>ἠδὲ καὶ Αὐλίον ἄντρον ἐπωνυμίην καλέουσιν.", "st": "2.899"}, {"sp": "N", "t": "ἔνθεν δὲ Σθενέλου τάφον ἔδρακον Ἀκτορίδαο,<br>ὅς ῥά τ’ Ἀμαζονίδων πολυθαρσέος ἐκ πολέμοιο<br>ἂψ ἀνιὼν—δὴ γὰρ συνανήλυθεν Ἡρακλῆι—<br>βλήμενος ἰῷ κεῖθεν ἐπ’ ἀγχιάλου θάνεν ἀκτῆς.<br>οὐ μέν θην προτέρω ἔτ’ ἐμέτρεον. ἧκε γὰρ αὐτὴ<br>Φερσεφόνη ψυχὴν πολυδάκρυον Ἀκτορίδαο<br>λισσομένην τυτθόν περ ὁμήθεας ἄνδρας ἰδέσθαι.<br>τύμβου δὲ στεφάνης ἐπιβὰς σκοπιάζετο νῆα<br>τοῖος ἐών, οἷος πόλεμόνδ’ ἴεν· ἀμφὶ δὲ καλὴ<br>τετράφαλος φοίνικι λόφῳ ἐπελάμπετο πήληξ.<br>καί ῥ’ ὁ μὲν αὖτις ἔδυνε μέγαν ζόφον· οἱ δ’ ἐσιδόντες<br>θάμβησαν· τοὺς δ’ ὦρσε θεοπροπέων ἐπικέλσαι<br>Ἀμπυκίδης Μόψος λοιβῇσί τε μειλίξασθαι.<br>οἱ δ’ ἀνὰ μὲν κραιπνῶς λαῖφος σπάσαν, ἐκ δὲ βαλόντες<br>πείσματ’ ἐν αἰγιαλῷ Σθενέλου τάφον ἀμφεπένοντο,<br>χύτλα τέ οἱ χεύοντο, καὶ ἥγνισαν ἔντομα μήλων.<br>ἄνδιχα δ’ αὖ χύτλων νηοσσόῳ Ἀπόλλωνι<br>βωμὸν δειμάμενοι μῆρ’ ἔφλεγον ἂν δὲ καὶ Ὀρφεὺς<br>θῆκε λύρην· ἐκ τοῦ δὲ Λύρη πέλει οὔνομα χώρῳ.", "st": "2.911"}, {"sp": "N", "t": "αὐτίκα δ’ οἵγ’ ἀνέμοιο κατασπέρχοντος ἔβησαν<br>νῆ’ ἔπι· κὰδ δ’ ἄρα λαῖφος ἐρυσσάμενοι τανύοντο<br>ἐς πόδας ἀμφοτέρους· ἡ δ’ ἐς πέλαγος πεφόρητο<br>ἐντενές, ἠύτε τίς τε δι’ ἠέρος ὑψόθι κίρκος<br>ταρσὸν ἐφεὶς πνοιῇ φέρεται ταχύς, οὐδὲ τινάσσει<br>ῥιπήν, εὐκήλοισιν ἐνευδιόων πτερύγεσσιν.<br>καὶ δὴ Παρθενίοιο ῥοὰς ἁλιμυρήεντος,<br>πρηυτάτου ποταμοῦ, παρεμέτρεον, ᾧ ἔνι κούρη<br>Λητωίς, ἄγρηθεν ὅτ’ οὐρανὸν εἰσαναβαίνῃ,<br>ὃν δέμας ἱμερτοῖσιν ἀναψύχει ὑδάτεσσιν.<br>νυκτί δ’ ἔπειτ’ ἄλληκτον ἐπιπροτέρωσε θέοντες<br>σήσαμον αἰπεινούς τε παρεξενέοντ’ Ἐρυθίνους,<br>Κρωβίαλον, Κρώμναν τε καὶ ὑλήεντα Κύτωρον.<br>ἔνθεν δ’ αὖτε Κάραμβιν ἅμ’ ἠελίοιο βολῇσιν<br>γνάμψαντες παρὰ πουλὺν ἔπειτ’ ἤλαυνον ἐρετμοῖς<br>αἰγιαλὸν πρόπαν ἦμαρ ὁμῶς καὶ ἐπ’ ἤματι νύκτα.", "st": "2.930"}, {"sp": "N", "t": "αὐτίκα δ’ Ἀσσυρίης ἐπέβαν χθονός, ἔνθα Σινώπην,<br>θυγατέρ’ Ἀσωποῖο, καθίσσατο, καί οἱ ὄπασσεν<br>παρθενίην Ζεὺς αὐτός, ὑποσχεσίῃσι δολωθείς.<br>δὴ γὰρ ὁ μὲν φιλότητος ἐέλδετο· νεῦσε δ’ ὅγ’ αὐτῇ<br>δωσέμεναι, ὅ κεν ᾗσι μετὰ φρεσὶν ἰθύσειεν.<br>ἡ δέ ἑ παρθενίην ᾐτήσατο κερδοσύνῃσιν.<br>ὧς δὲ καὶ Ἀπόλλωνα παρήπαφεν εὐνηθῆναι<br>ἱέμενον, ποταμόν τ’ ἐπὶ τοῖς Ἅλυν· οὐδὲ μὲν ἀνδρῶν<br>τήνγε τις ἱμερτῇσιν ἐν ἀγκοίνῃσι δάμασσεν.<br>ἔνθα δὲ Τρικκαίοιο ἀγαυοῦ Δηιμάχοιο<br>υἷες, Δηιλέων τε καὶ Αὐτόλυκος Φλογίος τε<br>τῆμος ἔθ’, Ἡρακλῆος ἀποπλαγχθέντες, ἔναιον·<br>οἵ ῥα τόθ’, ὡς ἐνόησαν ἀριστήων στόλον ἀνδρῶν,<br>σφᾶς αὐτοὺς νημερτὲς ἐπέφραδον ἀντιάσαντες·<br>οὐδ’ ἔτι μιμνάζειν θέλον ἔμπεδον, ἀλλ’ ἐνὶ νηί,<br>Ἀργέσταο παρᾶσσον ἐπιπνείοντος, ἔβησαν.<br>τοῖσι δ’ ὁμοῦ μετέπειτα θοῇ πεφορημένοι αὔρῃ<br>λεῖπον Ἅλυν ποταμόν, λεῖπον δ’ ἀγχίρροον Ἶριν,<br>ἠδὲ καὶ Ἀσσυρίης πρόχυσιν χθονός· ἤματι δ’ αὐτῷ<br>γνάμψαν Ἀμαζονίδων ἕκαθεν λιμενήοχον ἄκρην.", "st": "2.946"}, {"sp": "N", "t": "ἔνθα ποτὲ προμολοῦσαν Ἀρητιάδα Μελανίππην<br>ἥρως Ἡρακλέης ἐλοχήσατο, καί οἱ ἄποινα<br>Ἱππολύτη ζωστῆρα παναίολον ἐγγυάλιξεν<br>ἀμφὶ κασιγνήτης· ὁ δ’ ἀπήμονα πέμψεν ὀπίσσω.<br>τῆς οἵγ’ ἐν κόλπῳ, προχοαῖς ἔπι Θερμώδοντος,<br>κέλσαν, ἐπεὶ καὶ πόντος ὀρίνετο νισσομένοισιν.<br>τῷ δ’ οὔτις ποταμῶν ἐναλίγκιος, οὐδὲ ῥέεθρα<br>τόσσ’ ἐπὶ γαῖαν ἵησι παρὲξ ἕθεν ἄνδιχα βάλλων.<br>τετράκις εἰς ἑκατὸν δεύοιτό κεν, εἴ τις ἕκαστα<br>πεμπάζοι· μία δ’ οἴη ἐτήτυμος ἔπλετο πηγή.<br>ἡ μέν τ’ ἐξ ὀρέων κατανίσσεται ἤπειρόνδε<br>ὑψηλῶν, ἅ τέ φασιν Ἀμαζόνια κλείεσθαι.<br>ἔνθεν δ’ αἰπυτέρην ἐπικίδναται ἔνδοθι γαῖαν<br>ἀντικρύ· τῶ καί οἱ ἐπίστροφοί εἰσι κέλευθοι·<br>αἰεὶ δ’ ἄλλυδις ἄλλη, ὅπῃ κύρσειε μάλιστα<br>ἠπείρου χθαμαλῆς, εἱλίσσεται· ἡ μὲν ἄπωθεν,<br>ἡ δὲ πέλας· πολέες δὲ πόροι νώνυμνοι ἔασιν,<br>ὅππῃ ὑπεξαφύονται· ὁ δ’ ἀμφαδὸν ἄμμιγα παύροις<br>πόντον ἐς Ἄξεινον κυρτὴν ὑπερεύγεται ἄκρην.<br>καί νύ κε δηθύνοντες Ἀμαζονίδεσσιν ἔμιξαν<br>ὑσμίνην, καὶ δ’ οὔ κεν ἀναιμωτί γ’ ἐρίδηναν—<br>οὐ γὰρ Ἀμαζονίδες μάλ’ ἐπήτιδες, οὐδὲ θέμιστας<br>τίουσαι πεδίον Δοιάντιον ἀμφενέμοντο·<br>ἀλλ’ ὕβρις στονόεσσα καὶ Ἄρεος ἔργα μεμήλει·<br>δὴ γὰρ καὶ γενεὴν ἔσαν Ἄρεος Ἁρμονίης τε<br>νύμφης, ἥ τ’ Ἄρηϊ φιλοπτολέμους τέκε κούρας,<br>ἄλσεος Ἀκμονίοιο κατὰ πτύχας εὐνηθεῖσα—<br>εἰ μὴ ἄρ’ ἐκ Διόθεν πνοιαὶ πάλιν Ἀργέσταο<br>ἤλυθον· οἱ δ’ ἀνέμῳ περιηγέα κάλλιπον ἀκτήν,<br>ἔνθα Θεμισκύρειαι Ἀμαζόνες ὡπλίζοντο.<br>οὐ γὰρ ὁμηγερέες μίαν ἂμ πόλιν, ἀλλ’ ἀνὰ γαῖαν<br>κεκριμέναι κατὰ φῦλα διάτριχα ναιετάασκον·<br>νόσφι μὲν αἵδ’ αὐταί, τῇσιν τότε κοιρανέεσκεν<br>Ἱππολύτη, νόσφιν δὲ Λυκάστιαι ἀμφενέμοντο,<br>νόσφι δ’ ἀκοντοβόλοι Χαδήσιαι. ἤματι δ’ ἄλλῳ<br>νυκτί τ’ ἐπιπλομένῃ Χαλύβων παρὰ γαῖαν ἵκοντο.", "st": "2.966"}, {"sp": "N", "t": "τοῖσι μὲν οὔτε βοῶν ἄροτος μέλει, οὔτε τις ἄλλη<br>φυταλιὴ καρποῖο μελίφρονος· οὐδὲ μὲν οἵγε<br>ποίμνας ἑρσήεντι νομῷ ἔνι ποιμαίνουσιν.<br>ἀλλὰ σιδηροφόρον στυφελὴν χθόνα γατομέοντες<br>ὦνον ἀμείβονται βιοτήσιον, οὐδέ ποτέ σφιν<br>ἠὼς ἀντέλλει καμάτων ἄτερ, ἀλλὰ κελαινῇ<br>λιγνύι καὶ καπνῷ κάματον βαρὺν ὀτλεύουσιν.", "st": "2.1002"}, {"sp": "N", "t": "τοὺς δὲ μετ’ αὐτίκ’ ἔπειτα Γενηταίου Διὸς ἄκρην<br>γνάμψαντες σώοντο παρὲκ Τιβαρηνίδα γαῖαν.<br>ἔνθ’ ἐπεὶ ἄρ κε τέκωνται ὑπ’ ἀνδράσι τέκνα γυναῖκες,<br>αὐτοὶ μὲν στενάχουσιν ἐνὶ λεχέεσσι πεσόντες,<br>κράατα δησάμενοι· ταὶ δ’ εὖ κομέουσιν ἐδωδῇ<br>ἀνέρας, ἠδὲ λοετρὰ λεχώια τοῖσι πένονται.", "st": "2.1009"}, {"sp": "N", "t": "ἱρὸν δ’ αὖτ’ ἐπὶ τοῖσιν ὄρος καὶ γαῖαν ἄμειβον,<br>ᾗ ἔνι Μοσσύνοικοι ἀν’ οὔρεα ναιετάουσιν<br>μόσσυνας, καὶ δ’ αὐτοὶ ἐπώνυμοι ἔνθεν ἔασιν.<br>ἀλλοίη δὲ δίκη καὶ θέσμια τοῖσι τέτυκται.<br>ὅσσα μὲν ἀμφαδίην ῥέζειν θέμις, ἢ ἐνὶ δήμῳ,<br>ἢ ἀγορῇ, τάδε πάντα δόμοις ἔνι μηχανόωνται·<br>ὅσσα δ’ ἐνὶ μεγάροις πεπονήμεθα, κεῖνα θύραζε<br>ἀψεγέως μέσσῃσιν ἐνὶ ῥέζουσιν ἀγυιαῖς.<br>οὐδ’ εὐνῆς αἰδὼς ἐπιδήμιος, ἀλλά, σύες ὣς<br>φορβάδες, οὐδ’ ἠβαιὸν ἀτυζόμενοι παρεόντας,<br>μίσγονται χαμάδις ξυνῇ φιλότητι γυναικῶν.<br>αὐτὰρ ἐν ὑψίστῳ βασιλεὺς μόσσυνι θαάσσων<br>ἰθείας πολέεσσι δίκας λαοῖσι δικάζει,<br>σχέτλιος. ἢν γάρ πού τι θεμιστεύων ἀλίτηται,<br>λιμῷ μιν κεῖν’ ἦμαρ ἐνικλείσαντες ἔχουσιν.", "st": "2.1015"}, {"sp": "N", "t": "τοὺς παρανισσόμενοι καὶ δὴ σχεδὸν ἀντιπέρηθεν<br>νήσου Ἀρητιάδος τέμνον πλόον εἰρεσίῃσιν<br>ἠμάτιοι· λιαρὴ γὰρ ὑπὸ κνέφας ἔλλιπεν αὔρη.<br>ἤδη καί τιν’ ὕπερθεν Ἀρήιον ἀίσσοντα<br>ἐνναέτην νήσοιο δι’ ἠέρος ὄρνιν ἴδοντο,<br>ὅς ῥα τιναξάμενος πτέρυγας κατὰ νῆα θέουσαν<br>ἧκ’ ἐπί οἱ πτερὸν ὀξύ· τὸ δ’ ἐν λαιῷ πέσεν ὤμῳ<br>δίου Ὀιλῆος· μεθέηκε δὲ χερσὶν ἐρετμὸν<br>βλήμενος· οἱ δὲ τάφον πτερόεν βέλος εἰσορόωντες.<br>καὶ τὸ μὲν ἐξείρυσσε παρεδριόων Ἐρυβώτης,<br>ἕλκος δὲ ξυνέδησεν, ἀπὸ σφετέρου κολεοῖο<br>λυσάμενος τελαμῶνα κατήορον· ἐκ δ’ ἐφαάνθη<br>ἄλλος ἐπὶ προτέρῳ πεποτημένος· ἀλλά μιν ἥρως<br>Εὐρυτίδης Κλυτίος—πρὸ γὰρ ἀγκύλα τείνατο τόξα,<br>ἧκε δ’ ἐπ’ οἰωνὸν ταχινὸν βέλος—αὐτὰρ ἔπειτα<br>πλῆξεν· δινηθεὶς δὲ θοῆς πέσεν ἀγχόθι νηός.<br>τοῖσιν δ’ Ἀμφιδάμας μυθήσατο, παῖς Ἀλεοῖο·", "st": "2.1030"}, {"sp": "N", "t": "“νῆσος μὲν πέλας ἧμιν Ἀρητιάς· ἴστε καὶ αὐτοὶ<br>τούσδ’ ὄρνιθας ἰδόντες. ἐγὼ δ’ οὐκ ἔλπομαι ἰοὺς<br>τόσσον ἐπαρκέσσειν εἰς ἔκβασιν. ἀλλά τιν’ ἄλλην<br>μῆτιν πορσύνωμεν ἐπίρροθον, εἴ γ’ ἐπικέλσαι<br>μέλλετε, Φινῆος μεμνημένοι, ὡς ἐπέτελλεν.<br>οὐδὲ γὰρ Ἡρακλέης, ὁπότ’ ἤλυθεν Ἀρκαδίηνδε,<br>πλωίδας ὄρνιθας Στυμφαλίδας ἔσθενε λίμνης<br>ὤσασθαι τόξοισι, τὸ μέν τ’ ἐγὼ αὐτὸς ὄπωπα.<br>ἀλλ’ ὅγε χαλκείην πλατάγην ἐνὶ χερσὶ τινάσσων<br>δούπει ἐπὶ σκοπιῆς περιμήκεος· αἱ δ’ ἐφέβοντο<br>τηλοῦ, ἀτυζηλῷ ὑπὸ δείματι κεκληγυῖαι.<br>τῶ καὶ νῦν τοίην τιν’ ἐπιφραζώμεθα μῆτιν·<br>αὐτὸς δ’ ἂν τὸ πάροιθεν ἐπιφρασθεὶς ἐνέποιμι.<br>ἀνθέμενοι κεφαλῇσιν ἀερσιλόφους τρυφαλείας,<br>ἡμίσεες μὲν ἐρέσσετ’ ἀμοιβαδίς, ἡμίσεες δὲ<br>δούρασί τε ξυστοῖσι καὶ ἀσπίσιν ἄρσετε νῆα.<br>αὐτὰρ πασσυδίῃ περιώσιον ὄρνυτ’ ἀυτὴν<br>ἀθρόοι, ὄφρα κολῳὸν ἀηθείῃ φοβέωνται<br>νεύοντάς τε λόφους καὶ ἐπήορα δούραθ’ ὕπερθεν.<br>εἰ δέ κεν αὐτὴν νῆσον ἱκώμεθα, δὴ τότ’ ἔπειτα<br>σὺν κελάδῳ σακέεσσι πελώριον ὄρσετε δοῦπον.”", "st": "2.1047"}, {"sp": "N", "t": "ὧς ἄρ’ ἔφη· πάντεσσι δ’ ἐπίρροθος ἥνδανε μῆτις.<br>ἀμφὶ δὲ χαλκείας κόρυθας κεφαλῇσιν ἔθεντο<br>δεινὸν λαμπομένας, ἐπὶ δὲ λόφοι ἐσσείοντο<br>φοινίκεοι. καὶ τοὶ μὲν ἀμοιβήδην ἐλάασκον·<br>τοὶ δ’ αὖτ’ ἐγχείῃσι καὶ ἀσπίσι νῆ’ ἐκάλυψαν.<br>ὡς δ’ ὅτε τις κεράμῳ κατερέψεται ἑρκίον ἀνήρ,<br>δώματος ἀγλαΐην τε καὶ ὑετοῦ ἔμμεναι ἄλκαρ,<br>ἄλλῳ δ’ ἔμπεδον ἄλλος ὁμῶς ἐπαμοιβὸς ἄρηρεν·<br>ὧς οἵγ’ ἀσπίσι νῆα συναρτύναντες ἔρεψαν.<br>οἵη δὲ κλαγγὴ δῄου πέλει ἐξ ὁμάδοιο<br>ἀνδρῶν κινυμένων, ὁπότε ξυνίωσι φάλαγγες,<br>τοίη ἄρ’ ὑψόθι νηὸς ἐς ἠέρα κίδνατ’ ἀυτή.<br>οὐδέ τιν’ οἰωνῶν ἔτ’ ἐσέδρακον, ἀλλ’ ὅτε νήσῳ<br>χρίμψαντες σακέεσσιν ἐπέκτυπον, αὐτίκ’ ἄρ’ οἵγε<br>μυρίοι ἔνθα καὶ ἔνθα πεφυζότες ἠερέθοντο.<br>ὡς δ’ ὁπότε Κρονίδης πυκινὴν ἐφέηκε χάλαζαν<br>ἐκ νεφέων ἀνά τ’ ἄστυ καὶ οἰκία, τοὶ δ’ ὑπὸ τοῖσιν<br>ἐνναέται κόναβον τεγέων ὕπερ εἰσαΐοντες<br>ἧνται ἀκήν, ἐπεὶ οὔ σφε κατέλλαβε χείματος ὥρη<br>ἀπροφάτως, ἀλλὰ πρὶν ἐκαρτύναντο μέλαθρον·<br>ὧς πυκινὰ πτερὰ τοῖσιν ἐφίεσαν ἀίσσοντες<br>ὕψι μάλ’ ἂμ πέλαγος περάτης εἰς οὔρεα γαίης.", "st": "2.1068"}, {"sp": "N", "t": "τίς γὰρ δὴ Φινῆος ἔην νόος, ἐνθάδε κέλσαι<br>ἀνδρῶν ἡρώων θεῖον στόλον; ἢ καὶ ἔπειτα<br>ποῖον ὄνειαρ ἔμελλεν ἐελδομένοισιν ἱκέσθαι;", "st": "2.1090"}, {"sp": "N", "t": "υἱῆες Φρίξοιο μετὰ πτόλιν Ὀρχομενοῖο<br>ἐξ Αἴης ἐνέοντο παρ’ Αἰήταο Κυταίου,<br>Κολχίδα νῆ’ ἐπιβάντες, ἵν’ ἄσπετον ὄλβον ἄρωνται<br>πατρός· ὁ γὰρ θνῄσκων ἐπετείλατο τήνδε κέλευθον.<br>καὶ δὴ ἔσαν νήσοιο μάλα σχεδὸν ἤματι κείνῳ.<br>Ζεὺς δ’ ἀνέμου βορέαο μένος κίνησεν ἀῆναι,<br>ὕδατι σημαίνων διερὴν ὁδὸν Ἀρκτούροιο·<br>αὐτὰρ ὅγ’ ἠμάτιος μὲν ἐν οὔρεσι φύλλ’ ἐτίνασσεν<br>τυτθὸν ἐπ’ ἀκροτάτοισιν ἀήσυρος ἀκρεμόνεσσιν·<br>νυκτὶ δ’ ἔβη πόντονδε πελώριος, ὦρσε δὲ κῦμα<br>κεκληγὼς πνοιῇσι· κελαινὴ δ’ οὐρανὸν ἀχλὺς<br>ἄμπεχεν, οὐδέ πῃ ἄστρα διαυγέα φαίνετ’ ἰδέσθαι<br>ἐκ νεφέων, σκοτόεις δὲ περὶ ζόφος ἠρήρειστο.<br>οἱ δ’ ἄρα μυδαλέοι, στυγερὸν τρομέοντες ὄλεθρον,<br>υἱῆες Φρίξοιο φέρονθ’ ὑπὸ κύμασιν αὔτως.<br>ἱστία δ’ ἐξήρπαξ’ ἀνέμου μένος, ἠδὲ καὶ αὐτὴν<br>νῆα διάνδιχ’ ἔαξε τινασσομένην ῥοθίοισιν.<br>ἔνθα δ’ ὑπ’ ἐννεσίῃσι θεῶν πίσυρές περ ἐόντες<br>δούρατος ὠρέξαντο πελωρίου, οἷά τε πολλὰ<br>ῥαισθείσης κεκέδαστο θόοις συναρηρότα γόμφοις.<br>καὶ τοὺς μὲν νῆσόνδε, παρὲξ ὀλίγον θανάτοιο,<br>κύματα καὶ ῥιπαὶ ἀνέμου φέρον ἀσχαλόωντας.<br>αὐτίκα δ’ ἐρράγη ὄμβρος ἀθέσφατος, ὗε δὲ πόντον<br>καὶ νῆσον καὶ πᾶσαν ὅσην κατεναντία νήσου<br>χώρην Μοσσύνοικοι ὑπέρβιοι ἀμφενέμοντο.<br>τοὺς δ’ ἄμυδις κρατερῷ σὺν δούρατι κύματος ὁρμὴ<br>υἱῆας Φρίξοιο μετ’ ἠιόνας βάλε νήσου<br>νύχθ’ ὕπο λυγαίην· τὸ δὲ μυρίον ἐκ Διὸς ὕδωρ<br>λῆξεν ἅμ’ ἠελίῳ· τάχα δ’ ἐγγύθεν ἀντεβόλησαν<br>ἀλλήλοις, Ἄργος δὲ παροίτατος ἔκφατο μῦθον·", "st": "2.1093"}, {"sp": "N", "t": "“Ἀντόμεθα πρὸς Ζηνὸς Ἐποψίου, οἵτινές ἐστε<br>ἀνδρῶν, εὐμενέειν τε καὶ ἀρκέσσαι χατέουσιν.<br>πόντῳ γὰρ τρηχεῖαι ἐπιβρίσασαι ἄελλαι<br>νηὸς ἀεικελίης διὰ δούρατα πάντ’ ἐκέδασσαν,<br>ᾗ ἔνι πείρομεν οἶμον ἐπὶ χρέος ἐμβεβαῶτες.<br>τούνεκα νῦν ὑμέας γουναζόμεθ’, αἴ κε πίθησθε,<br>δοῦναι ὅσον τ’ εἴλυμα περὶ χροός, ἠδὲ κομίσσαι<br>ἀνέρας οἰκτείραντας ὁμήλικας ἐν κακότητι.<br>ἀλλ’ ἱκέτας ξείνους Διὸς εἵνεκεν αἰδέσσασθε<br>Ξεινίου Ἱκεσίου τε· Διὸς δ’ ἄμφω ἱκέται τε<br>καὶ ξεῖνοι· ὁ δέ που καὶ ἐπόψιος ἄμμι τέτυκται.”", "st": "2.1123"}, {"sp": "N", "t": "τὸν δ’ αὖτ’ Αἴσονος υἱὸς ἐπιφραδέως ἐρέεινεν,<br>μαντοσύνας Φινῆος ὀισσάμενος τελέεσθαι·<br>“ταῦτα μὲν αὐτίκα πάντα παρέξομεν εὐμενέοντες.<br>ἀλλ’ ἄγε μοι κατάλεξον ἐτήτυμον, ὁππόθι γαίης<br>ναίετε, καὶ χρέος οἷον ὑπεὶρ ἅλα νεῖσθαι ἀνώγει,<br>αὐτῶν θ’ ὑμείων ὄνομα κλυτόν, ἠδὲ γενέθλην.”", "st": "2.1134"}, {"sp": "N", "t": "τὸν δ’ Ἄργος προσέειπεν ἀμηχανέων κακότητι·<br>“Αἰολίδην Φρίξον τιν’ ἀφ’ Ἑλλάδος Αἶαν ἱκέσθαι<br>ἀτρεκέως δοκέω που ἀκούετε καὶ πάρος αὐτοί,<br>Φρίξον, ὅτις πτολίεθρον ἀνήλυθεν Αἰήταο,<br>κριοῦ ἐπεμβεβαώς, τόν ῥα χρύσειον ἔθηκεν<br>Ἑρμείας· κῶας δὲ καὶ εἰσέτι νῦν κεν ἴδοισθε.<br>τὸν μὲν ἔπειτ’ ἔρρεξεν ἑῇς ὑποθημοσύνῃσιν<br>Φυξίῳ ἐκ πάντων Κρονίδῃ Διί. καί μιν ἔδεκτο<br>Αἰήτης μεγάρῳ, κούρην τέ οἱ ἐγγυάλιξεν<br>Χαλκιόπην ἀνάεδνον ἐυφροσύνῃσι νόοιο.<br>τῶν ἐξ ἀμφοτέρων εἰμὲν γένος. ἀλλ’ ὁ μὲν ἤδη<br>γηραιὸς θάνε Φρίξος ἐν Αἰήταο δόμοισιν·<br>ἡμεῖς δ’ αὐτίκα πατρὸς ἐφετμάων ἀλέγοντες<br>νεύμεθ’ ἐς Ὀρχομενὸν κτεάνων Ἀθάμαντος ἕκητι.<br>εἰ δὲ καὶ οὔνομα δῆθεν ἐπιθύεις δεδαῆσθαι,<br>τῷδε Κυτίσσωρος πέλει οὔνομα, τῷ δέ τε Φρόντις,<br>τῷ δὲ Μέλας· ἐμὲ δ’ αὐτὸν ἐπικλείοιτέ κεν Ἄργον.”", "st": "2.1140"}, {"sp": "N", "t": "ὧς φάτ’· ἀριστῆες δὲ συνηβολίῃ κεχάροντο,<br>καί σφεας ἀμφίεπον περιθαμβέες. αὐτὰρ Ἰήσων<br>ἐξαῦτις κατὰ μοῖραν ἀμείψατο τοῖσδ’ ἐπέεσσιν·", "st": "2.1157"}, {"sp": "N", "t": "“ἦ ἄρα δὴ γνωτοὶ πατρώιοι ἄμμιν ἐόντες<br>λίσσεσθ’ εὐμενέοντας ἐπαρκέσσαι κακότητα.<br>Κρηθεὺς γάρ ῥ’ Ἀθάμας τε κασίγνητοι γεγάασιν.<br>Κρηθῆος δ’ υἱωνὸς ἐγὼ σὺν τοισίδ’ ἑταίροις<br>Ἑλλάδος ἐξ αὐτῆς νέομ’ ἐς πόλιν Αἰήταο.<br>ἀλλὰ τὰ μὲν καὶ ἐσαῦτις ἐνίψομεν ἀλλήλοισιν.<br>νῦν δ’ ἕσσασθε πάροιθεν· ὑπ’ ἐννεσίῃσι δ’ ὀίω<br>ἀθανάτων ἐς χεῖρας ἐμὰς χατέοντας ἱκέσθαι.”", "st": "2.1160"}, {"sp": "N", "t": "ἦ ῥα, καὶ ἐκ νηὸς δῶκέ σφισιν εἵματα δῦναι.<br>πασσυδίῃ δἤπειτα κίον μετὰ νηὸν Ἄρηος,<br>μῆλ’ ἱερευσόμενοι· περὶ δ’ ἐσχάρῃ ἐστήσαντο<br>ἐσσυμένως, ἥ τ’ ἐκτὸς ἀνηρεφέος πέλε νηοῦ<br>στιάων· εἴσω δὲ μέλας λίθος ἠρήρειστο<br>ἱερός, ᾧ ποτε πᾶσαι Ἀμαζόνες εὐχετόωντο.<br>οὐδέ σφιν θέμις ἦεν, ὅτ’ ἀντιπέρηθεν ἵκοιντο,<br>μήλων τ’ ἠδὲ βοῶν τῇδ’ ἐσχάρῃ ἱερὰ καίειν·<br>ἀλλ’ ἵππους δαίτρευον, ἐπηετανὸν κομέουσαι.<br>αὐτὰρ ἐπεὶ ῥέξαντες ἐπαρτέα δαῖτ’ ἐπάσαντο,<br>δὴ τότ ἄρ’ Αἰσονίδης μετεφώνεεν, ἦρχέ τε μύθων·", "st": "2.1168"}, {"sp": "N", "t": "“Ζεὺς ἐτεῇ τὰ ἕκαστ’ ἐπιδέρκεται· οὐδέ μιν ἄνδρες<br>λήθομεν ἔμπεδον, οἵ τε θεουδέες οὐδὲ δίκαιοι.<br>ὡς μὲν γὰρ πατέρ’ ὑμὸν ὑπεξείρυτο φόνοιο<br>μητρυιῆς, καὶ νόσφιν ἀπειρέσιον πόρεν ὄλβον·<br>ὧς δὲ καὶ ὑμέας αὖτις ἀπήμονας ἐξεσάωσεν<br>χείματος οὐλομένοιο. πάρεστι δὲ τῆσδ’ ἐπὶ νηὸς<br>ἔνθα καὶ ἔνθα νέεσθαι, ὅπῃ φίλον, εἴτε μετ’ Αἶαν,<br>εἶτε μετ’ ἀφνειὴν θείου πόλιν Ὀρχομενοῖο.<br>τὴν γὰρ Ἀθηναίη τεχνήσατο, καὶ τάμε χαλκῷ<br>δούρατα Πηλιάδος κορυφῆς πέρι· σὺν δέ οἱ Ἄργος<br>τεῦξεν. ἀτὰρ κείνην γε κακὸν διὰ κῦμ’ ἐκέδασσεν,<br>πρὶν καὶ πετράων σχεδὸν ἐλθεῖν, αἵ τ’ ἐνὶ πόντῳ<br>στεινωπῷ συνίασι πανήμεροι ἀλλήλῃσιν.<br>ἀλλ’ ἄγεθ’ ὧδε καὶ αὐτοὶ ἐς Ἑλλάδα μαιομένοισιν<br>κῶας ἄγειν χρύσειον ἐπίρροθοι ἄμμι πέλεσθε<br>καὶ πλόου ἡγεμονῆες, ἐπεὶ Φρίξοιο θυηλὰς<br>στέλλομαι ἀμπλήσων, Ζηνὸς χόλον Αἰολίδῃσιν.”", "st": "2.1179"}, {"sp": "N", "t": "ἴσκε παρηγορέων· οἱ δ’ ἔστυγον εἰσαΐοντες.<br>οὐ γὰρ ἔφαν τεύξεσθαι ἐνηέος Αἰήταο<br>κῶας ἄγειν κριοῖο μεμαότας, ὧδε δ’ ἔειπεν<br>Ἄργος, ἀτεμβόμενος τοῖον στόλον ἀμφιπένεσθαι·", "st": "2.1196"}, {"sp": "N", "t": "“ὦ φίλοι, ἡμέτερον μὲν ὅσον σθένος, οὔποτ’ ἀρωγῆς<br>σχήσεται, οὐδ’ ἠβαιόν, ὅτε χρειώ τις ἵκηται.<br>ἀλλ’ αἰνῶς ὀλοῇσιν ἀπηνείῃσιν ἄρηρεν<br>Αἰήτης· τῶ καὶ περιδείδια ναυτίλλεσθαι.<br>στεῦται δ’ Ἠελίου γόνος ἔμμεναι· ἀμφὶ δὲ Κόλχων<br>ἔθνεα ναιετάουσιν ἀπείρονα· καὶ δέ κεν Ἄρει<br>σμερδαλέην ἐνοπὴν μέγα τε σθένος ἰσοφαρίζοι.<br>οὐ μὰν οὐδ’ ἀπάνευθεν ἑλεῖν δέρος Αἰήταο<br>ῥηίδιον, τοῖός μιν ὄφις περί τ’ ἀμφί τ’ ἔρυται<br>ἀθάνατος καὶ ἄυπνος, ὃν αὐτὴ Γαῖ’ ἀνέφυσεν<br>Καυκάσου ἐν κνημοῖσι, Τυφαονίη ὅθι πέτρη,<br>ἔνθα Τυφάονά φασι Διὸς Κρονίδαο κεραυνῷ<br>βλήμενον, ὁππότε οἱ στιβαρὰς ἐπορέξατο χεῖρας,<br>θερμὸν ἀπὸ κρατὸς στάξαι φόνον· ἵκετο δ’ αὔτως<br>οὔρεα καὶ πεδίον Νυσήιον, ἔνθ’ ἔτι νῦν περ<br>κεῖται ὑποβρύχιος Σερβωνίδος ὕδασι λίμνης.”", "st": "2.1200"}, {"sp": "N", "t": "ὧς ἄρ’ ἔφη· πολέεσσι δ’ ἐπὶ χλόος εἷλε παρειὰς<br>αὐτίκα, τοῖον ἄεθλον ὅτ’ ἔκλυον. αἶψα δὲ Πηλεὺς<br>θαρσαλέοις ἐπέεσσιν ἀμείψατο, φώνησέν τε·", "st": "2.1216"}, {"sp": "N", "t": "“μηδ’ οὕτως, ἠθεῖε, λίην δειδίσσεο θυμῷ.<br>οὔτε γὰρ ὧδ’ ἀλκὴν ἐπιδευόμεθ’, ὥστε χερείους<br>ἔμμεναι Αἰήταο σὺν ἔντεσι πειρηθῆναι.<br>ἀλλὰ καὶ ἡμέας οἴω ἐπισταμένους πολέμοιο<br>κεῖσε μολεῖν, μακάρων σχεδὸν αἵματος ἐκγεγαῶτας.<br>τῶ εἰ μὴ φιλότητι δέρος χρύσειον ὀπάσσει,<br>οὔ οἱ χραισμήσειν ἐπιέλπομαι ἔθνεα Κόλχων.”", "st": "2.1219"}, {"sp": "N", "t": "ὧς οἵγ’ ἀλλήλοισιν ἀμοιβαδὸν ἠγορόωντο,<br>μέσφ’ αὖτις δόρποιο κορεσσάμενοι κατέδαρθεν.<br>ἦρι δ’ ἀνεγρομένοισιν ἐυκραὴς ἄεν οὖρος·<br>ἱστία δ’ ἤειραν, τὰ δ’ ὑπαὶ ῥιπῆς ἀνέμοιο<br>τείνετο· ῥίμφα δὲ νῆσον ἀποπροέλειπον Ἄρηος.", "st": "2.1226"}, {"sp": "N", "t": "νυκτὶ δ’ ἐπιπλομένῃ Φιλυρηίδα νῆσον ἄμειβον·<br>ἔνθα μὲν Οὐρανίδης Φιλύρῃ Κρόνος, εὖτ’ ἐν Ὀλύμπῳ<br>Τιτήνων ἤνασσεν, ὁ δὲ Κρηταῖον ὑπ’ ἄντρον<br>Ζεὺς ἔτι Κουρήτεσσι μετετρέφετ’ Ἰδαίοισιν,<br>Ῥείην ἐξαπαφὼν παρελέξατο· τοὺς δ’ ἐνὶ λέκτροις<br>τέτμε θεὰ μεσσηγύς· ὁ δ’ ἐξ εὐνῆς ἀνορούσας<br>ἔσσυτο χαιτήεντι φυὴν ἐναλίγκιος ἵππῳ·<br>ἡ δ’ αἰδοῖ χῶρόν τε καὶ ἤθεα κεῖνα λιποῦσα<br>Ὠκεανὶς Φιλύρη εἰς οὔρεα μακρὰ Πελασγῶν<br>ἦλθ’, ἵνα δὴ Χείρωνα πελώριον, ἄλλα μὲν ἵππῳ,<br>ἄλλα θεῷ ἀτάλαντον, ἀμοιβαίῃ τέκεν εὐνῇ.", "st": "2.1231"}, {"sp": "N", "t": "κεῖθεν δ’ αὖ Μάκρωνας ἀπειρεσίην τε Βεχείρων<br>γαῖαν ὑπερφιάλους τε παρεξενέοντο Σάπειρας,<br>Βύζηράς τ’ ἐπὶ τοῖσιν· ἐπιπρὸ γὰρ αἰὲν ἔτεμνον<br>ἐσσυμένως, λιαροῖο φορεύμενοι ἐξ ἀνέμοιο.<br>καὶ δὴ νισσομένοισι μυχὸς διεφαίνετο Πόντου.<br>καὶ δὴ Καυκασίων ὀρέων ἀνέτελλον ἐρίπναι<br>ἠλίβατοι, τόθι γυῖα περὶ στυφελοῖσι πάγοισιν<br>ἰλλόμενος χαλκέῃσιν ἀλυκτοπέδῃσι Προμηθεὺς<br>αἰετὸν ἥπατι φέρβε παλιμπετὲς ἀίσσοντα.<br>τὸν μὲν ἐπ’ ἀκροτάτης ἴδον ἕσπερον ὀξέι ῥοίζῳ<br>νηὸς ὑπερπτάμενον νεφέων σχεδόν· ἀλλὰ καὶ ἔμπης<br>λαίφεα πάντ’ ἐτίναξε, παραιθύξας πτερύγεσσιν.<br>οὐ γὰρ’ ὅγ’ αἰθερίοιο φυὴν ἔχεν οἰωνοῖο,<br>ἶσα δ’ ἐυξέστοις ὠκύπτερα πάλλεν ἐρετμοῖς,<br>δηρὸν δ’. οὐ μετέπειτα πολύστονον ἄιον αὐδὴν<br>ἧπαρ ἀνελκομένοιο Προμηθέος· ἔκτυπε δ’ αἰθὴρ<br>οἰμωγῇ, μέσφ’ αὖτις ἀπ’ οὔρεος ἀίσσοντα<br>αἰετὸν ὠμηστὴν αὐτὴν ὁδὸν εἰσενόησαν.<br>ἐννύχιοι δ’ Ἄργοιο δαημοσύνῃσιν ἵκοντο<br>Φᾶσίν τ’ εὐρὺ ῥέοντα, καὶ ἔσχατα πείρατα πόντου.", "st": "2.1242"}, {"sp": "N", "t": "αὐτίκα δ’ ἱστία μὲν καὶ ἐπίκριον ἔνδοθι κοίλης<br>ἱστοδόκης στείλαντες ἐκόσμεον· ἐν δὲ καὶ αὐτὸν<br>ἱστὸν ἄφαρ χαλάσαντο παρακλιδόν· ὦκα δ’ ἐρετμοῖς<br>εἰσέλασαν ποταμοῖο μέγαν ῥόον· αὐτὰρ ὁ πάντῃ<br>καχλάζων ὑπόεικεν. ἔχον δ’ ἐπ’ ἀριστερὰ χειρῶν<br>Καύκασον αἰπήεντα Κυταιίδα τε πτόλιν Αἴης,<br>ἔνθεν δ’ αὖ πεδίον τὸ Ἀρήιον ἱερά τ’ ἄλση<br>τοῖο θεοῦ, τόθι κῶας ὄφις εἴρυτο δοκεύων<br>πεπτάμενον λασίοισιν ἐπὶ δρυὸς ἀκρεμόνεσσιν.<br>αὐτὸς δ’ Αἰσονίδης χρυσέῳ ποταμόνδε κυπέλλῳ<br>οἴνου ἀκηρασίοιο μελισταγέας χέε λοιβὰς<br>Γαίῃ τ’ ἐνναέταις τε θεοῖς ψυχαῖς τε καμόντων<br>ἡρώων· γουνοῦτο δ’ ἀπήμονας εἶναι ἀρωγοὺς<br>εὐμενέως, καὶ νηὸς ἐναίσιμα πείσματα δέχθαι.<br>αὐτίκα δ’ Ἀγκαῖος τοῖον μετὰ μῦθον ἔειπεν·", "st": "2.1262"}, {"sp": "N", "t": "“Κολχίδα μὲν δὴ γαῖαν ἱκάνομεν ἠδὲ ῥέεθρα<br>Φάσιδος· ὥρη δ’ ἧμιν ἐνὶ σφίσι μητιάασθαι,<br>εἴτ’ οὖν μειλιχίῃ πειρησόμεθ’ Αἰήταο,<br>εἴτε καὶ ἀλλοίη τις ἐπήβολος ἔσσεται ὁρμή.”", "st": "2.1277"}, {"sp": "N", "t": "ὧς ἔφατ’· Ἄργου δ’ αὖτε παρηγορίῃσιν Ἰήσων<br>ὑψόθι νῆ’ ἐκέλευσεν ἐπ’ εὐναίῃσιν ἐρύσσαι<br>δάσκιον εἰσελάσαντας ἕλος· τὸ δ’ ἐπισχεδὸν ἦεν<br>νισσομένων, ἔνθ’ οἵγε διὰ κνέφας ηὐλίζοντο.<br>ἠὼς δ’ οὐ μετὰ δηρὸν ἐελδομένοις ἐφαάνθη.", "st": "2.1281"}, {"sp": "HDR", "t": "Βιβλίον Γʹ", "st": "3"}, {"sp": "N", "t": "εἰ δ’ ἄγε νῦν, Ἐρατώ, παρά θ’ ἵστασο, καί μοι ἔνισπε,<br>ἔνθεν ὅπως ἐς Ἰωλκὸν ἀνήγαγε κῶας Ἰήσων<br>Μηδείης ὑπ’ ἔρωτι. σὺ γὰρ καὶ Κύπριδος αἶσαν<br>ἔμμορες, ἀδμῆτας δὲ τεοῖς μελεδήμασι θέλγεις<br>παρθενικάς· τῶ καί τοι ἐπήρατον οὔνομ’ ἀνῆπται.", "st": "3.1"}, {"sp": "N", "t": "ὧς οἱ μὲν πυκινοῖσιν ἀνωίστως δονάκεσσιν<br>μίμνον ἀριστῆες λελοχημένοι· αἱ δ’ ἐνόησαν<br>Ἥρη Ἀθηναίη τε, Διὸς δ’ αὐτοῖο καὶ ἄλλων<br>ἀθανάτων ἀπονόσφι θεῶν θάλαμόνδε κιοῦσαι<br>βούλευον· πείραζε δ’ Ἀθηναίην πάρος Ἥρη·", "st": "3.6"}, {"sp": "N", "t": "“αὐτὴ νῦν προτέρη, θύγατερ Διός, ἄρχεο βουλῆς.<br>τί χρέος; ἠὲ δόλον τινὰ μήσεαι, ᾧ κεν ἑλόντες<br>χρύσεον Αἰήταο μεθ’ Ἑλλάδα κῶας ἄγοιντο,<br>ἦ καὶ τόνγ’ ἐπέεσσι παραιφάμενοι πεπίθοιεν<br>μειλιχίοις; ἦ γὰρ ὅγ’ ὑπερφίαλος πέλει αἰνῶς.<br>ἔμπης δ’ οὔτινα πεῖραν ἀποτρωπᾶσθαι ἔοικεν.”", "st": "3.11"}, {"sp": "N", "t": "ὧς φάτο· τὴν δὲ παρᾶσσον Ἀθηναίη προσέειπεν·<br>“καὶ δ’ αὐτὴν ἐμὲ τοῖα μετὰ φρεσὶν ὁρμαίνουσαν,<br>Ἤρη, ἀπηλεγέως ἐξείρεαι. ἀλλά τοι οὔπω<br>φράσσασθαι νοέω τοῦτον δόλον, ὅστις ὀνήσει<br>θυμὸν ἀριστήων· πολέας δ’ ἐπεδοίασα βουλάς.”", "st": "3.17"}, {"sp": "N", "t": "ἦ, καὶ ἐπ’ οὔδεος αἵγε ποδῶν πάρος ὄμματ’ ἔπηξαν,<br>ἄνδιχα πορφύρουσαι ἐνὶ σφίσιν· αὐτίκα δ’ Ἥρη<br>τοῖον μητιόωσα παροιτέρη ἔκφατο μῦθον·<br>“δεῦρ’ ἴομεν μετὰ Κύπριν· ἐπιπλόμεναι δέ μιν ἄμφω<br>παιδὶ ἑῷ εἰπεῖν ὀτρύνομεν, αἴ κε πίθηται<br>κούρην Αἰήτεω πολυφάρμακον οἷσι βέλεσσιν<br>θέλξαι ὀιστεύσας ἐπ’ Ἰήσονι. τὸν δ’ ἂν ὀίω<br>κείνης ἐννεσίῃσιν ἐς Ἑλλάδα κῶας ἀνάξειν.”", "st": "3.22"}, {"sp": "N", "t": "ὧς ἄρ’ ἔφη· πυκινὴ δὲ συνεύαδε μῆτις Ἀθήνῃ,<br>καί μιν ἔπειτ’ ἐξαῦτις ἀμείβετο μειλιχίοισιν·", "st": "3.30"}, {"sp": "N", "t": "“Ἥρη, νήιδα μέν με πατὴρ τέκε τοῖο βολάων,<br>οὐδέ τινα χρειὼ θελκτήριον οἶδα πόθοιο.<br>εἰ δέ σοι αὐτῇ μῦθος ἐφανδάνει, ἦ τ’ ἂν ἔγωγε<br>ἑσποίμην· σὺ δέ κεν φαίης ἔπος ἀντιόωσα.”", "st": "3.32"}, {"sp": "N", "t": "ἦ, καὶ ἀναΐξασαι ἐπὶ μέγα δῶμα νέοντο<br>Κύπριδος, ὅ ῥά τέ οἱ δεῖμεν πόσις ἀμφιγυήεις,<br>ὁππότε μιν τὰ πρῶτα παραὶ Διὸς ἦγεν ἄκοιτιν.<br>ἕρκεα δ’ εἰσελθοῦσαι ὑπ’ αἰθούσῃ θαλάμοιο<br>ἔσταν, ἵν’ ἐντύνεσκε θεὰ λέχος Ἡφαίστοιο.<br>ἀλλ’ ὁ μὲν ἐς χαλκεῶνα καὶ ἄκμονας ἦρι βεβήκει,<br>νήσοιο πλαγκτῆς εὐρὺν μυχόν, ᾧ ἔνι πάντα<br>δαίδαλα χάλκευεν ῥιπῇ πυρός· ἡ δ’ ἄρα μούνη<br>ἧστο δόμῳ δινωτὸν ἀνὰ θρόνον, ἄντα θυράων.<br>λευκοῖσιν δ’ ἑκάτερθε κόμας ἐπιειμένη ὤμοις<br>κόσμει χρυσείῃ διὰ κερκίδι, μέλλε δὲ μακροὺς<br>πλέξασθαι πλοκάμους· τὰς δὲ προπάροιθεν ἰδοῦσα<br>ἔσχεθεν, εἴσω τέ σφ’ ἐκάλει, καὶ ἀπὸ θρόνου ὦρτο,<br>εἷσέ τ’ ἐνὶ κλισμοῖσιν· ἀτὰρ μετέπειτα καὶ αὐτὴ<br>ἵζανεν, ἀψήκτους δὲ χεροῖν ἀνεδήσατο χαίτας.<br>τοῖα δὲ μειδιόωσα προσέννεπεν αἱμυλίοισιν·", "st": "3.36"}, {"sp": "N", "t": "“Ἠθεῖαι, τίς δεῦρο νόος χρειώ τε κομίζει<br>δηναιὰς αὔτως; τί δ’ ἱκάνετον, οὔτι πάρος γε<br>λίην φοιτίζουσαι, ἐπεὶ περίεστε θεάων;”", "st": "3.52"}, {"sp": "N", "t": "τὴν δ’ Ἥρη τοίοισιν ἀμειβομένη προσέειπεν·<br>“Κερτομέεις· νῶιν δὲ κέαρ συνορίνεται ἄτῃ.<br>ἤδη γὰρ ποταμῷ ἐνὶ Φάσιδι νῆα κατίσχει<br>Αἰσονίδης, ἠδ’ ἄλλοι ὅσοι μετὰ κῶας ἕπονται.<br>τῶν ἤτοι πάντων μέν, ἐπεὶ πέλας ἔργον ὄρωρεν,<br>δείδιμεν ἐκπάγλως, περὶ δ’ Αἰσονίδαο μάλιστα.<br>τὸν μὲν ἐγών, εἰ καί περ ἐς Ἄιδα ναυτίλληται<br>λυσόμενος χαλκέων Ἰξίονα νειόθι δεσμῶν,<br>ῥύσομαι, ὅσσον ἐμοῖσιν ἐνὶ σθένος ἔπλετο γυίοις,<br>ὄφρα μὴ ἐγγελάσῃ Πελίης κακὸν οἶτον ἀλύξας,<br>ὅς μ’ ὑπερηνορέῃ θυέων ἀγέραστον ἔθηκεν.<br>καὶ δ’ ἄλλως ἔτι καὶ πρὶν ἐμοὶ μέγα φίλατ’ Ἰήσων<br>ἐξότ’ ἐπὶ προχοῇσιν ἅλις πλήθοντος Ἀναύρου<br>ἀνδρῶν εὐνομίης πειρωμένῃ ἀντεβόλησεν<br>θήρης ἐξανιών· νιφετῷ δ’ ἐπαλύνετο πάντα<br>οὔρεα καὶ σκοπιαὶ περιμήκεες, οἱ δὲ κατ’ αὐτῶν<br>χείμαρροι καναχηδὰ κυλινδόμενοι φορέοντο.<br>γρηὶ δέ μ’ εἰσαμένην ὀλοφύρατο, καί μ’ ἀναείρας<br>αὐτὸς ἑοῖς ὤμοισι διὲκ προαλὲς φέρεν ὕδωρ.<br>τῶ νύ μοι ἄλληκτον περιτίεται· οὐδέ κε λώβην<br>τίσειεν Πελίης, εἰ μή σύ γε νόστον ὀπάσσεις.”", "st": "3.55"}, {"sp": "N", "t": "ὧς ηὔδα· Κύπριν δ’ ἐνεοστασίη λάβε μύθων.<br>ἅζετο δ’ ἀντομένην Ἥρην ἕθεν εἰσορόωσα,<br>καί μιν ἔπειτ’ ἀγανοῖσι προσέννεπεν ἥγ’ ἐπέεσσιν·<br>“πότνα θεά, μή τοί τι κακώτερον ἄλλο πέλοιτο<br>Κύπριδος, εἰ δὴ σεῖο λιλαιομένης ἀθερίζω<br>ἢ ἔπος ἠέ τι ἔργον, ὅ κεν χέρες αἵγε κάμοιεν<br>ἠπεδαναί· καὶ μή τις ἀμοιβαίη χάρις ἔστω.”", "st": "3.76"}, {"sp": "N", "t": "ὧς ἔφαθ’· Ἥρη δ’ αὖτις ἐπιφραδέως ἀγόρευσεν·<br>“οὔτι βίης χατέουσαι ἱκάνομεν, οὐδέ τι χειρῶν.<br>ἀλλ’ αὔτως ἀκέουσα τεῷ ἐπικέκλεο παιδὶ<br>παρθένον Αἰήτεω θέλξαι πόθῳ Αἰσονίδαο.<br>εἰ γάρ οἱ κείνη συμφράσσεται εὐμενέουσα,<br>ῥηιδίως μιν ἑλόντα δέρος χρύσειον ὀίω<br>νοστήσειν ἐς Ἰωλκόν, ἐπεὶ δολόεσσα τέτυκται.”", "st": "3.83"}, {"sp": "N", "t": "ὧς ἄρ’ ἔφη· Κύπρις δὲ μετ’ ἀμφοτέρῃσιν ἔειπεν·<br>“Ἥρη, Ἀθηναίη τε, πίθοιτό κεν ὔμμι μάλιστα,<br>ἢ ἐμοί. ὑμείων γὰρ ἀναιδήτῳ περ ἐόντι<br>τυτθή γ’ αἰδὼς ἔσσετ’ ἐν ὄμμασιν· αὐτὰρ ἐμεῖο<br>οὐκ ὄθεται, μάλα δ’ αἰὲν ἐριδμαίνων ἀθερίζει.<br>καὶ δή οἱ μενέηνα, περισχομένη κακότητι,<br>αὐτοῖσιν τόξοισι δυσηχέας ἆξαι ὀιστοὺς<br>ἀμφαδίην. τοῖον γὰρ ἐπηπείλησε χαλεφθείς,<br>εἰ μὴ τηλόθι χεῖρας, ἕως ἔτι θυμὸν ἐρύκει,<br>ἕξω ἐμάς, μετέπειτά γ’ ἀτεμβοίμην ἑοῖ αὐτῇ.”", "st": "3.90"}, {"sp": "N", "t": "ὧς φάτο· μείδησαν δὲ θεαί, καὶ ἐσέδρακον ἄντην<br>ἀλλήλαις. ἡ δ’ αὖτις ἀκηχεμένη προσέειπεν·<br>“ἄλλοις ἄλγεα τἀμὰ γέλως πέλει· οὐδέ τί με χρὴ<br>μυθεῖσθαι πάντεσσιν· ἅλις εἰδυῖα καὶ αὐτή.<br>νῦν δ’ ἐπεὶ ὔμμι φίλον τόδε δὴ πέλει ἀμφοτέρῃσιν,<br>πειρήσω, καί μιν μειλίξομαι, οὐδ’ ἀπιθήσει.”", "st": "3.100"}, {"sp": "N", "t": "ὧς φάτο· τὴν δ’ Ἥρη ῥαδινῆς ἐπεμάσσατο χειρός,<br>ἦκα δὲ μειδιόωσα παραβλήδην προσέειπεν·<br>“οὕτω νῦν, Κυθέρεια, τόδε χρέος, ὡς ἀγορεύεις,<br>ἔρξον ἄφαρ· καὶ μή τι χαλέπτεο, μηδ’ ἐρίδαινε<br>χωομένη σῷ παιδί· μεταλλήξει γὰρ ὀπίσσω.”", "st": "3.106"}, {"sp": "N", "t": "ἦ ῥα, καὶ ἔλλιπε θῶκον· ἐφωμάρτησε δ’ Ἀθήνη·<br>ἐκ δ’ ἴσαν ἄμφω ταίγε παλίσσυτοι. ἡ δὲ καὶ αὐτὴ<br>βῆ ῥ’ ἴμεν Οὐλύμποιο κατὰ πτύχας, εἴ μιν ἐφεύροι.<br>εὗρε δὲ τόνγ’ ἀπάνευθε Διὸς θαλερῇ ἐν ἀλωῇ,<br>οὐκ οἶον, μετὰ καὶ Γανυμήδεα, τόν ῥά ποτε Ζεὺς<br>οὐρανῷ ἐγκατένασσεν ἐφέστιον ἀθανάτοισιν,<br>κάλλεος ἱμερθείς. ἀμφ’ ἀστραγάλοισι δὲ τώγε<br>χρυσείοις, ἅ τε κοῦροι ὁμήθεες, ἑψιόωντο.<br>καί ῥ’ ὁ μὲν ἤδη πάμπαν ἐνίπλεον ᾧ ὑπὸ μαζῷ<br>μάργος Ἔρως λαιῆς ὑποΐσχανε χειρὸς ἀγοστόν,<br>ὀρθὸς ἐφεστηώς· γλυκερὸν δέ οἱ ἀμφὶ παρειὰς<br>χροιῇ θάλλεν ἔρευθος. ὁ δ’ ἐγγύθεν ὀκλαδὸν ἧστο<br>σῖγα κατηφιόων· δοιὼ δ’ ἔχεν, ἄλλον ἔτ’ αὔτως<br>ἄλλῳ ἐπιπροϊείς, κεχόλωτο δὲ καγχαλόωντι.<br>καὶ μὴν τούσγε παρᾶσσον ἐπὶ προτέροισιν ὀλέσσας<br>βῆ κενεαῖς σὺν χερσὶν ἀμήχανος, οὐδ’ ἐνόησεν<br>Κύπριν ἐπιπλομένην. ἡ δ’ ἀντίη ἵστατο παιδός,<br>καί μιν ἄφαρ γναθμοῖο κατασχομένη προσέειπεν·", "st": "3.111"}, {"sp": "N", "t": "“τίπτ’ ἐπιμειδιάᾳς, ἄφατον κακόν; ἦέ μιν αὔτως<br>ἤπαφες, οὐδὲ δίκῃ περιέπλεο νῆιν ἐόντα;<br>εἰ δ’ ἄγε μοι πρόφρων τέλεσον χρέος, ὅττι κεν εἴπω·<br>καί κέν τοι ὀπάσαιμι Διὸς περικαλλὲς ἄθυρμα<br>κεῖνο, τό οἱ ποίησε φίλη τροφὸς Ἀδρήστεια<br>ἄντρῳ ἐν Ἰδαίῳ ἔτι νήπια κουρίζοντι,<br>σφαῖραν ἐυτρόχαλον, τῆς οὐ σύγε μείλιον ἄλλο<br>χειρῶν Ἡφαίστοιο κατακτεατίσσῃ ἄρειον.<br>χρύσεα μέν οἱ κύκλα τετεύχαται· ἀμφὶ δ’ ἑκάστῳ<br>διπλόαι ἁψῖδες περιηγέες εἱλίσσονται·<br>κρυπταὶ δὲ ῥαφαί εἰσιν· ἕλιξ δ’ ἐπιδέδρομε πάσαις<br>κυανέη. ἀτὰρ εἴ μιν ἑαῖς ἐνὶ χερσὶ βάλοιο,<br>ἀστὴρ ὥς, φλεγέθοντα δι’ ἠέρος ὁλκὸν ἵησιν.<br>τήν τοι ἐγὼν ὀπάσω· σὺ δὲ παρθένον Αἰήταο<br>θέλξον ὀιστεύσας ἐπ’ Ἰήσονι· μηδέ τις ἔστω<br>ἀμβολίη. δὴ γάρ κεν ἀφαυροτέρη χάρις εἴη.”", "st": "3.129"}, {"sp": "N", "t": "ὧς φάτο· τῷ δ’ ἀσπαστὸν ἔπος γένετ’ εἰσαΐοντι.<br>μείλια δ’ ἔκβαλε πάντα, καὶ ἀμφοτέρῃσι χιτῶνος<br>νωλεμὲς ἔνθα καὶ ἔνθα θεᾶς ἔχεν ἀμφιμεμαρπώς.<br>λίσσετο δ’ αἶψα πορεῖν αὐτοσχεδόν· ἡ δ’ ἀγανοῖσιν<br>ἀντομένη μύθοισιν, ἐπειρύσσασα παρειάς,<br>κύσσε ποτισχομένη, καὶ ἀμείβετο μειδιόωσα·", "st": "3.145"}, {"sp": "N", "t": "“ἴστω νῦν τόδε σεῖο φίλον κάρη ἠδ’ ἐμὸν αὐτῆς,<br>ἦ μέν τοι δῶρόν γε παρέξομαι, οὐδ’ ἀπατήσω,<br>εἴ κεν ἐνισκίμψῃς κούρῃ βέλος Αἰήταο.”", "st": "3.151"}, {"sp": "N", "t": "φῆ· ὁ δ’ ἄρ’ ἀστραγάλους συναμήσατο, κὰδ δὲ φαεινῷ<br>μητρὸς ἑῆς εὖ πάντας ἀριθμήσας βάλε κόλπῳ.<br>αὐτίκα δ’ ἰοδόκην χρυσέῃ περικάτθετο μίτρῃ<br>πρέμνῳ κεκλιμένην· ἀνὰ δ’ ἀγκύλον εἵλετο τόξον.<br>βῆ δὲ διὲκ μεγάροιο Διὸς πάγκαρπον ἀλωήν.<br>αὐτὰρ ἔπειτα πύλας ἐξήλυθεν Οὐλύμποιο<br>αἰθερίας· ἔνθεν δὲ καταιβάτις ἐστὶ κέλευθος<br>οὐρανίη· δοιὼ δὲ πόλοι ἀνέχουσι κάρηνα<br>οὐρέων ἠλιβάτων, κορυφαὶ χθονός, ᾗχί τ’ ἀερθεὶς<br>ἠέλιος πρώτῃσιν ἐρεύθεται ἀκτίνεσσιν.<br>νειόθι δ’ ἄλλοτε γαῖα φερέσβιος ἄστεά τ’ ἀνδρῶν<br>φαίνετο καὶ ποταμῶν ἱεροὶ ῥόοι, ἄλλοτε δ’ αὖτε<br>ἄκριες, ἀμφὶ δὲ πόντος ἀν’ αἰθέρα πολλὸν ἰόντι.", "st": "3.154"}, {"sp": "N", "t": "ἥρωες δ’ ἀπάνευθεν ἑῆς ἐπὶ σέλμασι νηὸς<br>ἐν ποταμῷ καθ’ ἕλος λελοχημένοι ἠγορόωντο.<br>αὐτὸς δ’ Αἰσονίδης μετεφώνεεν· οἱ δ’ ὑπάκουον<br>ἠρέμας ᾗ ἐνὶ χώρῃ ἐπισχερὼ ἑδριόωντες·<br>“ὦ φίλοι, ἤτοι ἐγὼ μὲν ὅ μοι ἐπιανδάνει αὐτῷ<br>ἐξερέω· τοῦ δ’ ὔμμι τέλος κρηῆναι ἔοικεν.<br>ξυνὴ γὰρ χρειώ, ξυνοὶ δέ τε μῦθοι ἔασιν<br>πᾶσιν ὁμῶς· ὁ δὲ σῖγα νόον βουλήν τ’ ἀπερύκων<br>ἴστω καὶ νόστου τόνδε στόλον οἶος ἀπούρας.<br>ὧλλοι μὲν κατὰ νῆα σὺν ἔντεσι μίμνεθ’ ἕκηλοι·<br>αὐτὰρ ἐγὼν ἐς δώματ’ ἐλεύσομαι Αἰήταο,<br>υἷας ἑλὼν Φρίξοιο δύω δ’ ἐπὶ τοῖσιν ἑταίρους.<br>πειρήσω δ’ ἐπέεσσι παροίτερον ἀντιβολήσας,<br>εἴ κ’ ἐθέλοι φιλότητι δέρος χρύσειον ὀπάσσαι,<br>ἦε καὶ οὔ, πίσυνος δὲ βίῃ μετιόντας ἀτίσσει.<br>ὧδε γὰρ ἐξ αὐτοῖο πάρος κακότητα δαέντες<br>φρασσόμεθ’, εἴτ’ ἄρηι συνοισόμεθ’ εἴτε τις ἄλλη<br>μῆτις ἐπίρροθος ἔσται ἐεργομένοισιν ἀυτῆς.<br>μηδ’ αὔτως ἀλκῇ, πρὶν ἔπεσσί γε πειρηθῆναι,<br>τόνδ’ ἀπαμείρωμεν σφέτερον κτέρας. ἀλλὰ πάροιθεν<br>λωίτερον μύθῳ μιν ἀρέσσασθαι μετιόντας.<br>πολλάκι τοι ῥέα μῦθος, ὅ κεν μόλις ἐξανύσειεν<br>ἠνορέη, τόδ’ ἔρεξε κατὰ χρέος, ᾗπερ ἐῴκει<br>πρηΰνας. ὁ δὲ καί ποτ’ ἀμύμονα Φρίξον ἔδεκτο<br>μητρυιῆς φεύγοντα δόλον πατρός τε θυηλάς.<br>πάντες ἐπεὶ πάντῃ καὶ ὅτις μάλα κύντατος ἀνδρῶν,<br>Ξεινίου αἰδεῖται Ζηνὸς θέμιν ἠδ’ ἀλεγίζει.”", "st": "3.167"}, {"sp": "N", "t": "ὧς φάτ’· ἐπῄνησαν δὲ νέοι ἔπος Αἰσονίδαο<br>πασσυδίῃ, οὐδ’ ἔσκε παρὲξ ὅτις ἄλλο κελεύοι.<br>καὶ τότ’ ἄρ’ υἱῆας Φρίξου Τελαμῶνά θ’ ἕπεσθαι<br>ὦρσε καὶ Αὐγείην· αὐτὸς δ’ ἕλεν Ἑρμείαο<br>σκῆπτρον· ἄφαρ δ’ ἄρα νηὸς ὑπὲρ δόνακάς τε καὶ ὕδωρ<br>χέρσονδ’ ἐξαπέβησαν ἐπὶ θρῳσμοῦ πεδίοιο.<br>Κιρκαῖον τόδε που κικλήσκεται· ἔνθα δὲ πολλαὶ<br>ἑξείης πρόμαλοί τε καὶ ἰτέαι ἐκπεφύασιν,<br>τῶν καὶ ἐπ’ ἀκροτάτων νέκυες σειρῇσι κρέμανται<br>δέσμιοι. εἰσέτι νῦν γὰρ ἄγος Κόλχοισιν ὄρωρεν<br>ἀνέρας οἰχομένους πυρὶ καιέμεν· οὐδ’ ἐνὶ γαίῃ<br>ἔστι θέμις στείλαντας ὕπερθ’ ἐπὶ σῆμα χέεσθαι,<br>ἀλλ’ ἐν ἀδεψήτοισι κατειλύσαντε βοείαις<br>δενδρέων ἐξάπτειν ἑκὰς ἄστεος. ἠέρι δ’ ἴσην<br>καὶ χθὼν ἔμμορεν αἶσαν, ἐπεὶ χθονὶ ταρχύουσιν<br>θηλυτέρας· ἡ γάρ τε δίκη θεσμοῖο τέτυκται.", "st": "3.194"}, {"sp": "N", "t": "τοῖσι δὲ νισσομένοις Ἥρη φίλα μητιόωσα<br>ἠέρα πουλὺν ἐφῆκε δι’ ἄστεος, ὄφρα λάθοιεν<br>Κόλχων μυρίον ἔθνος ἐς Αἰήταο κιόντες.<br>ὦκα δ’ ὅτ’ ἐκ πεδίοιο πόλιν καὶ δώμαθ’ ἵκοντο<br>Αἰήτεω, τότε δ’ αὖτις ἀπεσκέδασεν νέφος Ἥρη.<br>ἔσταν δ’ ἐν προμολῇσι τεθηπότες ἕρκε’ ἄνακτος<br>εὐρείας τε πύλας καὶ κίονας, οἳ περὶ τοίχους<br>ἑξείης ἄνεχον· θριγκὸς δ’ ἐφύπερθε δόμοιο<br>λαΐνεος χαλκέῃσιν ἐπὶ γλυφίδεσσιν ἀρήρει.<br>εὔκηλοι δ’ ὑπὲρ οὐδὸν ἔπειτ’ ἔβαν. ἄγχι δὲ τοῖο<br>ἡμερίδες χλοεροῖσι καταστεφέες πετάλοισιν<br>ὑψοῦ ἀειρόμεναι μέγ’ ἐθήλεον. αἱ δ’ ὑπὸ τῇσιν<br>ἀέναοι κρῆναι πίσυρες ῥέον, ἃς ἐλάχηνεν<br>Ἥφαιστος. καί ῥ’ ἡ μὲν ἀναβλύεσκε γάλακτι,<br>ἡ δ’ οἴνῳ, τριτάτη δὲ θυώδεϊ νᾶεν ἀλοιφῇ·<br>ἡ δ’ ἄρ’ ὕδωρ προρέεσκε, τὸ μέν ποθι δυομένῃσιν<br>θέρμετο Πληιάδεσσιν, ἀμοιβηδὶς δ’ ἀνιούσαις<br>κρυστάλλῳ ἴκελον κοίλης ἀνεκήκιε πέτρης.<br>τοῖ’ ἄρ’ ἐνὶ μεγάροισι Κυταιέος Αἰήταο<br>τεχνήεις Ἥφαιστος ἐμήσατο θέσκελα ἔργα.<br>καί οἱ χαλκόποδας ταύρους κάμε, χάλκεα δέ σφεων<br>ἦν στόματ’, ἐκ δὲ πυρὸς δεινὸν σέλας ἀμπνείεσκον·<br>πρὸς δὲ καὶ αὐτόγυον στιβαροῦ ἀδάμαντος ἄροτρον<br>ἤλασεν, Ἠελίῳ τίνων χάριν, ὅς ῥά μιν ἵπποις<br>δέξατο, Φλεγραίῃ κεκμηότα δηιοτῆτι.<br>ἔνθα δὲ καὶ μέσσαυλος ἐλήλατο· τῇ δ’ ἐπὶ πολλαὶ<br>δικλίδες εὐπηγεῖς θάλαμοί τ’ ἔσαν ἔνθα καὶ ἔνθα·<br>δαιδαλέη δ’ αἴθουσα παρὲξ ἑκάτερθε τέτυκτο.<br>λέχρις δ’ αἰπύτεροι δόμοι ἕστασαν ἀμφοτέρωθεν.<br>τῶν ἤτοι ἄλλῳ μέν, ὅτις καὶ ὑπείροχος ἦεν,<br>κρείων Αἰήτης σὺν ἑῇ ναίεσκε δάμαρτι·<br>ἄλλῳ δ’ Ἄψυρτος ναῖεν πάις Αἰήταο.<br>τὸν μὲν Καυκασίη νύμφη τέκεν Ἀστερόδεια<br>πρίν περ κουριδίην θέσθαι Εἰδυῖαν ἄκοιτιν,<br>Τηθύος Ὠκεανοῦ τε πανοπλοτάτην γεγαυῖαν.<br>καί μιν Κόλχων υἷες ἐπωνυμίην Φαέθοντα<br>ἔκλεον, οὕνεκα πᾶσι μετέπρεπεν ἠιθέοισιν.<br>τοὺς δ’ ἔχον ἀμφίπολοί τε καὶ Αἰήταο θύγατρες<br>ἄμφω, Χαλκιόπη Μήδειά τε. τὴν μὲν ἄρ’ οἵγε<br>ἐκ θαλάμου θάλαμόνδε κασιγνήτην μετιοῦσαν—<br>Ἥρη γάρ μιν ἔρυκε δόμῳ· πρὶν δ’ οὔτι θάμιζεν<br>ἐν μεγάροις, Ἑκάτης δὲ πανήμερος ἀμφεπονεῖτο<br>νηόν, ἐπεί ῥα θεᾶς αὐτὴ πέλεν ἀρήτειρα—<br>καί σφεας ὡς ἴδεν ἆσσον, ἀνίαχεν· ὀξὺ δ’ ἄκουσεν<br>Χαλκιόπη· δμωαὶ δὲ ποδῶν προπάροιθε βαλοῦσαι<br>νήματα καὶ κλωστῆρας ἀολλέες ἔκτοθι πᾶσαι<br>ἔδραμον. ἡ δ’ ἅμα τοῖσιν ἑοὺς υἱῆας ἰδοῦσα<br>ὑψοῦ χάρματι χεῖρας ἀνέσχεθεν· ὧς δὲ καὶ αὐτοὶ<br>μητέρα δεξιόωντο, καὶ ἀμφαγάπαζον ἰδόντες<br>γηθόσυνοι· τοῖον δὲ κινυρομένη φάτο μῦθον·", "st": "3.210"}, {"sp": "N", "t": "“ἔμπης οὐκ ἄρ’ ἐμέλλετ’ ἀκηδείῃ με λιπόντες<br>τηλόθι πλάγξασθαι· μετὰ δ’ ὑμέας ἔτραπεν αἶσα.<br>δειλὴ ἐγώ, οἷον πόθον Ἑλλάδος ἔκποθεν ἄτης<br>λευγαλέης Φρίξοιο ἐφημοσύνῃσιν ἕλεσθε<br>πατρός. ὁ μὲν θνῄσκων στυγερὰς ἐπετείλατ’ ἀνίας<br>ἡμετέρῃ κραδίῃ. τί δέ κεν πόλιν Ὀρχομενοῖο,<br>ὅστις ὅδ’ Ὀρχομενός, κτεάνων Ἀθάμαντος ἕκητι<br>μητέρ’ ἑὴν ἀχέουσαν ἀποπρολιπόντες, ἵκοισθε;”", "st": "3.260"}, {"sp": "N", "t": "ὧς ἔφατ’· Αἰήτης δὲ πανύστατος ὦρτο θύραζε,<br>ἐκ δ’ αὐτὴ Εἰδυῖα δάμαρ κίεν Αἰήταο,<br>Χαλκιόπης ἀίουσα· τὸ δ’ αὐτίκα πᾶν ὁμάδοιο<br>ἕρκος ἐπεπλήθει. τοὶ μὲν μέγαν ἀμφιπένοντο<br>ταῦρον ἅλις δμῶες· τοὶ δὲ ξύλα κάγκανα χαλκῷ<br>κόπτον· τοὶ δὲ λοετρὰ πυρὶ ζέον· οὐδέ τις ἦεν,<br>ὃς καμάτου μεθίεσκεν, ὑποδρήσσων βασιλῆι.", "st": "3.268"}, {"sp": "N", "t": "τόφρα δ’ Ἔρως πολιοῖο δι’ ἠέρος ἷξεν ἄφαντος,<br>τετρηχώς, οἷόν τε νέαις ἐπὶ φορβάσιν οἶστρος<br>τέλλεται, ὅν τε μύωπα βοῶν κλείουσι νομῆες.<br>ὦκα δ’ ὑπὸ φλιὴν προδόμῳ ἔνι τόξα τανύσσας<br>ἰοδόκης ἀβλῆτα πολύστονον ἐξέλετ’ ἰόν.<br>ἐκ δ’ ὅγε καρπαλίμοισι λαθὼν ποσὶν οὐδὸν ἄμειψεν<br>ὀξέα δενδίλλων· αὐτῷ δ’ ὑπὸ βαιὸς ἐλυσθεὶς<br>Αἰσονίδῃ γλυφίδας μέσσῃ ἐνικάτθετο νευρῇ,<br>ἰθὺς δ’ ἀμφοτέρῃσι διασχόμενος παλάμῃσιν<br>ἧκ’ ἐπὶ Μηδείῃ· τὴν δ’ ἀμφασίη λάβε θυμόν.<br>αὐτὸς δ’ ὑψορόφοιο παλιμπετὲς ἐκ μεγάροιο<br>καγχαλόων ἤιξε· βέλος δ’ ἐνεδαίετο κούρῃ<br>νέρθεν ὑπὸ κραδίῃ, φλογὶ εἴκελον· ἀντία δ’ αἰεὶ<br>βάλλεν ὑπ’ Αἰσονίδην ἀμαρύγματα, καί οἱ ἄηντο<br>στηθέων ἐκ πυκιναὶ καμάτῳ φρένες, οὐδέ τιν’ ἄλλην<br>μνῆστιν ἔχεν, γλυκερῇ δὲ κατείβετο θυμὸν ἀνίῃ.<br>ὡς δὲ γυνὴ μαλερῷ περὶ κάρφεα χεύατο δαλῷ<br>χερνῆτις, τῇπερ ταλασήια ἔργα μέμηλεν,<br>ὥς κεν ὑπωρόφιον νύκτωρ σέλας ἐντύναιτο,<br>ἄγχι μάλ’ ἐγρομένη· τὸ δ’ ἀθέσφατον ἐξ ὀλίγοιο<br>δαλοῦ ἀνεγρόμενον σὺν κάρφεα πάντ’ ἀμαθύνει·<br>τοῖος ὑπὸ κραδίῃ εἰλυμένος αἴθετο λάθρῃ<br>οὖλος Ἔρως· ἁπαλὰς δὲ μετετρωπᾶτο παρειὰς<br>ἐς χλόον, ἄλλοτ’ ἔρευθος, ἀκηδείῃσι νόοιο.", "st": "3.275"}, {"sp": "N", "t": "δμῶες δ’ ὁππότε δή σφιν ἐπαρτέα θῆκαν ἐδωδήν,<br>αὐτοί τε λιαροῖσιν ἐφαιδρύναντο λοετροῖς,<br>ἀσπασίως δόρπῳ τε ποτῆτί τε θυμὸν ἄρεσσαν.<br>ἐκ δὲ τοῦ Αἰήτης σφετέρης ἐρέεινε θυγατρὸς<br>υἱῆας τοίοισι παρηγορέων ἐπέεσσιν·", "st": "3.299"}, {"sp": "N", "t": "“παιδὸς ἐμῆς κοῦροι Φρίξοιό τε, τὸν περὶ πάντων<br>ξείνων ἡμετέροισιν ἐνὶ μεγάροισιν ἔτισα,<br>πῶς Αἶάνδε νέεσθε παλίσσυτοι; ἦέ τις ἄτη<br>σωομένοις μεσσηγὺς ἐνέκλασεν; οὐ μὲν ἐμεῖο<br>πείθεσθε προφέροντος ἀπείρονα μέτρα κελεύθου.<br>ᾔδειν γάρ ποτε πατρὸς ἐν ἅρμασιν Ἠελίοιο<br>δινεύσας, ὅτ’ ἐμεῖο κασιγνήτην ἐκόμιζεν<br>Κίρκην ἑσπερίης εἴσω χθονός, ἐκ δ’ ἱκόμεσθα<br>ἀκτὴν ἠπείρου Τυρσηνίδος, ἔνθ’ ἔτι νῦν περ<br>ναιετάει, μάλα πολλὸν ἀπόπροθι Κολχίδος αἴης.<br>ἀλλὰ τί μύθων ἦδος; ἃ δ’ ἐν ποσὶν ὗμιν ὄρωρεν,<br>εἴπατ’ ἀριφραδέως, ἠδ’ οἵτινες οἵδ’ ἐφέπονται<br>ἀνέρες, ὅππῃ τε γλαφυρῆς ἐκ νηὸς ἔβητε.”", "st": "3.304"}, {"sp": "N", "t": "τοῖά μιν ἐξερέοντα κασιγνήτων προπάροιθεν<br>Ἄργος ὑποδδείσας ἀμφὶ στόλῳ Αἰσονίδαο<br>μειλιχίως προσέειπεν, ἐπεὶ προγενέστερος ἦεν·", "st": "3.317"}, {"sp": "N", "t": "“Αἰήτη, κείνην μὲν ἄφαρ διέχευαν ἄελλαι<br>ζαχρηεῖς· αὐτοὺς δ’ ἐπὶ δούρασι πεπτηῶτας<br>νήσου Ἐνυαλίοιο ποτὶ ξερὸν ἔκβαλε κῦμα<br>λυγαίῃ ὑπὸ νυκτί· θεὸς δέ τις ἄμμ’ ἐσάωσεν.<br>οὐδὲ γὰρ αἳ τὸ πάροιθεν ἐρημαίην κατὰ νῆσον<br>ηὐλίζοντ’ ὄρνιθες Ἀρήιαι, οὐδ’ ἔτι κείνας<br>εὕρομεν. ἀλλ’ οἵγ’ ἄνδρες ἀπήλασαν, ἐξαποβάντες<br>νηὸς ἑῆς προτέρῳ ἐνὶ ἤματι· καί σφ’ ἀπέρυκεν<br>ἡμέας οἰκτείρων Ζηνὸς νόος, ἠέ τις αἶσα,<br>αὐτίκ’ ἐπεὶ καὶ βρῶσιν ἅλις καὶ εἵματ’ ἔδωκαν,<br>οὔνομά τε Φρίξοιο περικλεὲς εἰσαΐοντες<br>ἠδ’ αὐτοῖο σέθεν· μετὰ γὰρ τεὸν ἄστυ νέονται.<br>χρειὼ δ’ ἢν ἐθέλῃς ἐξίδμεναι, οὔ σ’ ἐπικεύσω.<br>τόνδε τις ἱέμενος πάτρης ἀπάνευθεν ἐλάσσαι<br>καὶ κτεάνων βασιλεὺς περιώσιον, οὕνεκεν ἀλκῇ<br>σφωιτέρῃ πάντεσσι μετέπρεπεν Αἰολίδῃσιν,<br>πέμπει δεῦρο νέεσθαι ἀμήχανον· οὐδ’ ὑπαλύξειν<br>στεῦται ἀμειλίκτοιο Διὸς θυμαλγέα μῆνιν<br>καὶ χόλον, οὐδ’ ἄτλητον ἄγος Φρίξοιό τε ποινὰς<br>Αἰολιδέων γενεήν, πρὶν ἐς Ἑλλάδα κῶας ἱκέσθαι.<br>νῆα δ’ Ἀθηναίη Παλλὰς κάμεν, οὐ μάλα τοίην,<br>οἷαί περ Κόλχοισι μετ’ ἀνδράσι νῆες ἔασιν,<br>τάων αἰνοτάτης ἐπεκύρσαμεν. ἤλιθα γάρ μιν<br>λάβρον ὕδωρ πνοιή τε διέτμαγεν· ἡ δ’ ἐνὶ γόμφοις<br>ἴσχεται, ἢν καὶ πᾶσαι ἐπιβρίσωσιν ἄελλαι.<br>ἶσον δ’ ἐξ ἀνέμοιο θέει καὶ ὅτ’ ἀνέρες αὐτοὶ<br>νωλεμέως χείρεσσιν ἐπισπέρχωσιν ἐρετμοῖς.<br>τῇ δ’ ἐναγειράμενος Παναχαιίδος εἴ τι φέριστον<br>ἡρώων, τεὸν ἄστυ μετήλυθε, πόλλ’ ἐπαληθεὶς<br>ἄστεα καὶ πελάγη στυγερῆς ἁλός, εἴ οἱ ὀπάσσαις.<br>αὐτῷ δ’ ὥς κεν ἅδῃ, τὼς ἔσσεται· οὐ γὰρ ἱκάνει<br>χερσὶ βιησόμενος· μέμονεν δέ τοι ἄξια τίσειν<br>δωτίνης, ἀίων ἐμέθεν μέγα δυσμενέοντας<br>Σαυρομάτας, τοὺς σοῖσιν ὑπὸ σκήπτροισι δαμάσσει.<br>εἰ δὲ καὶ οὔνομα δῆθεν ἐπιθύεις γενεήν τε<br>ἴδμεναι, οἵτινές εἰσιν, ἕκαστά γε μυθησαίμην.<br>τόνδε μέν, οἷό περ οὕνεκ’ ἀφ’ Ἑλλάδος ὧλλοι ἄγερθεν,<br>κλείουσ’ Αἴσονος υἱὸν Ἰήσονα Κρηθεΐδαο.<br>εἰ δ’ αὐτοῦ Κρηθῆος ἐτήτυμόν ἐστι γενέθλης,<br>οὕτω κεν γνωτὸς πατρώιος ἄμμι πέλοιτο.<br>ἄμφω γὰρ Κρηθεὺς Ἀθάμας τ’ ἔσαν Αἰόλου υἷες·<br>Φρίξος δ’ αὖτ’ Ἀθάμαντος ἔην πάις Αἰολίδαο.<br>τόνδε δ’ ἄρ’, Ἠελίου γόνον ἔμμεναι εἴ τιν’ ἀκούεις,<br>δέρκεαι Αὐγείην· Τελαμὼν δ’ ὅγε, κυδίστοιο<br>Αἰακοῦ ἐκγεγαώς· Ζεὺς δ’ Αἰακὸν αὐτὸς ἔτικτεν.<br>ὧς δὲ καὶ ὧλλοι πάντες, ὅσοι συνέπονται ἑταῖροι,<br>ἀθανάτων υἷές τε καὶ υἱωνοὶ γεγάασιν.”", "st": "3.320"}, {"sp": "N", "t": "τοῖα παρέννεπεν Ἄργος· ἄναξ δ’ ἐπεχώσατο μύθοις<br>εἰσαΐων· ὑψοῦ δὲ χόλῳ φρένες ἠερέθοντο.<br>φῆ δ’ ἐπαλαστήσας· μενέαινε δὲ παισὶ μάλιστα<br>Χαλκιόπης· τῶν γάρ σφε μετελθέμεν οὕνεκ’ ἐώλπει·<br>ἐκ δέ οἱ ὄμματ’ ἔλαμψεν ὑπ’ ὀφρύσιν ἱεμένοιο·", "st": "3.367"}, {"sp": "N", "t": "“οὐκ ἄφαρ ὀφθαλμῶν μοι ἀπόπροθι, λωβητῆρες,<br>νεῖσθ’ αὐτοῖσι δόλοισι παλίσσυτοι ἔκτοθι γαίης,<br>πρίν τινα λευγαλέον τε δέρος καὶ Φρίξον ἰδέσθαι;<br>αὐτίχ’ ὁμαρτήσαντες ἀφ’ Ἑλλάδος, οὐκ ἐπὶ κῶας,<br>σκῆπτρα δὲ καὶ τιμὴν βασιληίδα δεῦρο νέεσθε.<br>εἰ δέ κε μὴ προπάροιθεν ἐμῆς ἥψασθε τραπέζης,<br>ἦ τ’ ἂν ἀπὸ γλώσσας τε ταμὼν καὶ χεῖρε κεάσσας<br>ἀμφοτέρας, οἴοισιν ἐπιπροέηκα πόδεσσιν,<br>ὥς κεν ἐρητύοισθε καὶ ὕστερον ὁρμηθῆναι,<br>οἷα δὲ καὶ μακάρεσσιν ἐπεψεύσασθε θεοῖσιν.”", "st": "3.372"}, {"sp": "N", "t": "φῆ ῥα χαλεψάμενος· μέγα δὲ φρένες Αἰακίδαο<br>νειόθεν οἰδαίνεσκον· ἐέλδετο δ’ ἔνδοθι θυμὸς<br>ἀντιβίην ὀλοὸν φάσθαι ἔπος· ἀλλ’ ἀπέρυκεν<br>Αἰσονίδης· πρὸ γὰρ αὐτὸς ἀμείψατο μειλιχίοισιν·", "st": "3.382"}, {"sp": "N", "t": "“Αἰήτη, σχέο μοι τῷδε στόλῳ. οὔτι γὰρ αὔτως<br>ἄστυ τεὸν καὶ δώμαθ’ ἱκάνομεν, ὥς που ἔολπας,<br>οὐδὲ μὲν ἱέμενοι. τίς δ’ ἂν τόσον οἶδμα περῆσαι<br>τλαίη ἑκὼν ὀθνεῖον ἐπὶ κτέρας; ἀλλά με δαίμων<br>καὶ κρυερὴ βασιλῆος ἀτασθάλου ὦρσεν ἐφετμή.<br>δὸς χάριν ἀντομένοισι· σέθεν δ’ ἐγὼ Ἑλλάδι πάσῃ<br>θεσπεσίην οἴσω κληηδόνα· καὶ δέ τοι ἤδη<br>πρόφρονές εἰμεν ἄρηι θοὴν ἀποτῖσαι ἀμοιβήν,<br>εἴτ’ οὖν Σαυρομάτας γε λιλαίεαι, εἴτε τιν’ ἄλλον<br>δῆμον σφωιτέροισιν ὑπὸ σκήπτροισι δαμάσσαι.”", "st": "3.386"}, {"sp": "N", "t": "Ἴσκεν ὑποσσαίνων ἀγανῇ ὀπί· τοῖο δὲ θυμὸς<br>διχθαδίην πόρφυρεν ἐνὶ στήθεσσι μενοινήν,<br>ἤ σφεας ὁρμηθεὶς αὐτοσχεδὸν ἐξεναρίζοι,<br>ἦ ὅγε πειρήσαιτο βίης. τό οἱ εἴσατ’ ἄρειον<br>φραζομένῳ· καὶ δή μιν ὑποβλήδην προσέειπεν·", "st": "3.396"}, {"sp": "N", "t": "“ξεῖνε, τί κεν τὰ ἕκαστα διηνεκέως ἀγορεύοις;<br>εἰ γὰρ ἐτήτυμόν ἐστε θεῶν γένος, ἠὲ καὶ ἄλλως<br>οὐδὲν ἐμεῖο χέρηες ἐπ’ ὀθνείοισιν ἔβητε,<br>δώσω τοι χρύσειον ἄγειν δέρος, αἴ κ’ ἐθέλῃσθα,<br>πειρηθείς. ἐσθλοῖς γὰρ ἐπ’ ἀνδράσιν οὔτι μεγαίρω,<br>ὡς αὐτοὶ μυθεῖσθε τὸν Ἑλλάδι κοιρανέοντα.<br>πεῖρα δέ τοι μένεός τε καὶ ἀλκῆς ἔσσετ’ ἄεθλος,<br>τόν ῥ’ αὐτὸς περίειμι χεροῖν ὀλοόν περ ἐόντα.<br>δοιώ μοι πεδίον τὸ Ἀρήιον ἀμφινέμονται<br>ταύρω χαλκόποδε, στόματι φλόγα φυσιόωντες·<br>τοὺς ἐλάω ζεύξας στυφελὴν κατὰ νειὸν Ἄρηος<br>τετράγυον, τὴν αἶψα ταμὼν ἐπὶ τέλσον ἀρότρῳ<br>οὐ σπόρον ὁλκοῖσιν Δηοῦς ἐνιβάλλομαι ἀκτήν,<br>ἀλλ’ ὄφιος δεινοῖο μεταλδήσκοντας ὀδόντας<br>ἀνδράσι τευχηστῇσι δέμας. τοὺς δ’ αὖθι δαΐζων<br>κείρω ἐμῷ ὑπὸ δουρὶ περισταδὸν ἀντιόωντας.<br>ἠέριος ζεύγνυμι βόας, καὶ δείελον ὥρην<br>παύομαι ἀμήτοιο. σὺ δ’, εἰ τάδε τοῖα τελέσσεις,<br>αὐτῆμαρ τόδε κῶας ἀποίσεαι εἰς βασιλῆος·<br>πρὶν δέ κεν οὐ δοίην, μηδ’ ἔλπεο. δὴ γὰρ ἀεικὲς<br>ἄνδρ’ ἀγαθὸν γεγαῶτα κακωτέρῳ ἀνέρι εἶξαι.”", "st": "3.401"}, {"sp": "N", "t": "ὧς ἄρ’ ἔφη· ὁ δὲ σῖγα ποδῶν πάρος ὄμματα πήξας<br>ἧστ’ αὔτως ἄφθογγος, ἀμηχανέων κακότητι.<br>βουλὴν δ’ ἀμφὶ πολὺν στρώφα χρόνον, οὐδέ πῃ εἶχεν<br>θαρσαλέως ὑποδέχθαι, ἐπεὶ μέγα φαίνετο ἔργον·<br>ὀψὲ δ’ ἀμειβόμενος προσελέξατο κερδαλέοισιν·", "st": "3.422"}, {"sp": "N", "t": "“Αἰήτη, μάλα τοί με δίκῃ περιπολλὸν ἐέργεις.<br>τῶ καὶ ἐγὼ τὸν ἄεθλον ὑπερφίαλόν περ ἐόντα<br>τλήσομαι, εἰ καί μοι θανέειν μόρος. οὐ γὰρ ἔτ’ ἄλλο<br>ῥίγιον ἀνθρώποισι κακῆς ἐπικείσετ’ ἀνάγκης,<br>ἥ με καὶ ἐνθάδε νεῖσθαι ἐπέχραεν ἐκ βασιλῆος.”", "st": "3.427"}, {"sp": "N", "t": "ὧς φάτ’ ἀμηχανίῃ βεβολημένος· αὐτὰρ ὁ τόνγε<br>σμερδαλέοις ἐπέεσσι προσέννεπεν ἀσχαλόωντα·<br>“ἔρχεο νῦν μεθ’ ὅμιλον, ἐπεὶ μέμονάς γε πόνοιο·<br>εἰ δὲ σύγε ζυγὰ βουσὶν ὑποδδείσαις ἐπαεῖραι,<br>ἠὲ καὶ οὐλομένου μεταχάσσεαι ἀμήτοιο,<br>αὐτῷ κεν τὰ ἕκαστα μέλοιτό μοι, ὄφρα καὶ ἄλλος<br>ἀνὴρ ἐρρίγῃσιν ἀρείονα φῶτα μετελθεῖν.”", "st": "3.432"}, {"sp": "N", "t": "Ἴσκεν ἀπηλεγέως· ὁ δ’ ἀπὸ θρόνου ὤρνυτ’ Ἰήσων,<br>Αὐγείης Τελαμών τε παρασχεδόν· εἵπετο δ’ Ἄργος<br>οἶος, ἐπεὶ μεσσηγὺς ἔτ’ αὐτόθι νεῦσε λιπέσθαι<br>αὐτοκασιγνήτοις· οἱ δ’ ἤισαν ἐκ μεγάροιο.<br>θεσπέσιον δ’ ἐν πᾶσι μετέπρεπεν Αἴσονος υἱὸς<br>κάλλεϊ καὶ χαρίτεσσιν· ἐπ’ αὐτῷ δ’ ὄμματα κούρη<br>λοξὰ παρὰ λιπαρὴν σχομένη θηεῖτο καλύπτρην,<br>κῆρ ἄχεϊ σμύχουσα· νόος δέ οἱ ἠύτ’ ὄνειρος<br>ἑρπύζων πεπότητο μετ’ ἴχνια νισσομένοιο.<br>καί ῥ’ οἱ μέν ῥα δόμων ἐξήλυθον ἀσχαλόωντες.<br>Χαλκιόπη δὲ χόλον πεφυλαγμένη Αἰήταο<br>καρπαλίμως θάλαμόνδε σὺν υἱάσιν οἷσι βεβήκει.<br>αὔτως δ’ αὖ Μήδεια μετέστιχε· πολλὰ δὲ θυμῷ<br>ὥρμαιν’, ὅσσα τ’ Ἔρωτες ἐποτρύνουσι μέλεσθαι.<br>προπρὸ δ’ ἄρ’ ὀφθαλμῶν ἔτι οἱ ἰνδάλλετο πάντα,<br>αὐτός θ’ οἷος ἔην, οἵοισί τε φάρεσιν ἕστο,<br>οἷά τ’ ἔειφ’, ὥς θ’ ἕζετ’ ἐπὶ θρόνου, ὥς τε θύραζε<br>ἤιεν· οὐδέ τιν’ ἄλλον ὀίσσατο πορφύρουσα<br>ἔμμεναι ἀνέρα τοῖον· ἐν οὔασι δ’ αἰὲν ὀρώρει<br>αὐδή τε μῦθοί τε μελίφρονες, οὓς ἀγόρευσεν.<br>τάρβει δ’ ἀμφ’ αὐτῷ, μή μιν βόες ἠὲ καὶ αὐτὸς<br>Αἰήτης φθίσειεν· ὀδύρετο δ’ ἠύτε πάμπαν<br>ἤδη τεθνειῶτα, τέρεν δέ οἱ ἀμφὶ παρειὰς<br>δάκρυον αἰνοτάτῳ ἐλέῳ ῥέε κηδοσύνῃσιν·<br>ἦκα δὲ μυρομένη λιγέως ἀνενείκατο μῦθον·", "st": "3.439"}, {"sp": "N", "t": "“τίπτε με δειλαίην τόδ’ ἔχει ἄχος; εἴθ’ ὅγε πάντων<br>φθίσεται ἡρώων προφερέστατος, εἴτε χερείων,<br>ἐρρέτω. ἦ μὲν ὄφελλεν ἀκήριος ἐξαλέασθαι.<br>ναὶ δὴ τοῦτό γε, πότνα θεὰ Περσηί, πέλοιτο,<br>οἴκαδε νοστήσειε φυγὼν μόρον· εἰ δέ μιν αἶσα<br>δμηθῆναι ὑπὸ βουσί, τόδε προπάροιθε δαείη,<br>οὕνεκεν οὔ οἱ ἔγωγε κακῇ ἐπαγαίομαι ἄτῃ.”", "st": "3.464"}, {"sp": "N", "t": "ἡ μὲν ἄρ’ ὧς ἐόλητο νόον μελεδήμασι κούρη.<br>οἱ δ’ ἐπεὶ οὖν δήμου τε καὶ ἄστεος ἐκτὸς ἔβησαν<br>τὴν ὁδόν, ἣν τὸ πάροιθεν ἀνήλυθον ἐκ πεδίοιο,<br>δὴ τότ’ Ἰήσονα τοῖσδε προσέννεπεν Ἄργος ἔπεσσιν·", "st": "3.471"}, {"sp": "N", "t": "“Αἰσονίδη, μῆτιν μὲν ὀνόσσεαι, ἥντιν’ ἐνίψω·<br>πείρης δ’ οὐ μάλ’ ἔοικε μεθιέμεν ἐν κακότητι.<br>κούρην δή τινα πρόσθεν ὑπέκλυες αὐτὸς ἐμεῖο<br>φαρμάσσειν Ἑκάτης Περσηίδος ἐννεσίῃσιν.<br>τὴν εἴ κεν πεπίθοιμεν, ὀίομαι, οὐκέτι τάρβος<br>ἔσσετ’ ἀεθλεύοντι δαμήμεναι· ἀλλὰ μάλ’ αἰνῶς<br>δείδω, μή πως οὔ μοι ὑποσταίη τόγε μήτηρ.<br>ἔμπης δ’ ἐξαῦτις μετελεύσομαι ἀντιβολήσων,<br>ξυνὸς ἐπεὶ πάντεσσιν ἐπικρέμαθ’ ἧμιν ὄλεθρος.”", "st": "3.475"}, {"sp": "N", "t": "Ἴσκεν ἐυφρονέων· ὁ δ’ ἀμείβετο τοῖσδ’ ἐπέεσσιν·<br>“ὦ πέπον, εἴ νύ τοι αὐτῷ ἐφανδάνει, οὔτι μεγαίρω.<br>βάσκ’ ἴθι καὶ πυκινοῖσι τεὴν παρὰ μητέρα μύθοις<br>ὄρνυθι λισσόμενος· μελέη γε μὲν ἧμιν ὄρωρεν<br>ἐλπωρή, ὅτε νόστον ἐπετραπόμεσθα γυναιξίν.”<br>ὧς ἔφατ’· ὦκα δ’ ἕλος μετεκίαθον. αὐτὰρ ἑταῖροι<br>γηθόσυνοι ἐρέεινον, ὅπως παρεόντας ἴδοντο·<br>τοῖσιν δ’ Αἰσονίδης τετιημένος ἔκφατο μῦθον·", "st": "3.484"}, {"sp": "N", "t": "“ὦ φίλοι, Αἰήταο ἀπηνέος ἄμμι φίλον κῆρ<br>ἀντικρὺ κεχόλωται, ἕκαστα γὰρ οὔ νύ τι τέκμωρ<br>οὔτ’ ἐμοί, οὔτε κεν ὔμμι διειρομένοισι πέλοιτο.<br>φῆ δὲ δύω πεδίον τὸ Ἀρήιον ἀμφινέμεσθαι<br>ταύρω χαλκόποδε, στόματι φλόγα φυσιόωντας.<br>τετράγυον δ’ ἐπὶ τοῖσιν ἐφίετο νειὸν ἀρόσσαι·<br>δώσειν δ’ ἐξ ὄφιος γενύων σπόρον, ὅς ῥ’ ἀνίῃσιν<br>γηγενέας χαλκέοις σὺν τεύχεσιν· ἤματι δ’ αὐτῷ<br>χρειὼ τούσγε δαΐξαι. ὃ δή νύ οἱ—οὔτι γὰρ ἄλλο<br>βέλτερον ἦν φράσσασθαι—ἀπηλεγέως ὑποέστην.”", "st": "3.492"}, {"sp": "N", "t": "ὧς ἄρ’ ἔφη· πάντεσσι δ’ ἀνήνυτος εἴσατ’ ἄεθλος,<br>δὴν δ’ ἄνεῳ καὶ ἄναυδοι ἐς ἀλλήλους ὁρόωντο,<br>ἄτῃ ἀμηχανίῃ τε κατηφέες· ὀψὲ δὲ Πηλεὺς<br>θαρσαλέως μετὰ πᾶσιν ἀριστήεσσιν ἔειπεν·<br>“ὥρη μητιάασθαι ὅ κ’ ἔρξομεν. οὐ μὲν ἔολπα<br>βουλῆς εἶναι ὄνειαρ, ὅσον τ’ ἐπὶ κάρτεϊ χειρῶν.<br>εἰ μέν νυν τύνη ζεῦξαι βόας Αἰήταο,<br>ἥρως Αἰσονίδη, φρονέεις, μέμονάς τε πόνοιο,<br>ἦ τ’ ἂν ὑποσχεσίην πεφυλαγμένος ἐντύναιο·<br>εἰ δ’ οὔ τοι μάλα θυμὸς ἑῇ ἐπὶ πάγχυ πέποιθεν<br>ἠνορέῃ, μήτ’ αὐτὸς ἐπείγεο, μήτε τιν’ ἄλλον<br>τῶνδ’ ἀνδρῶν πάπταινε παρήμενος. οὐ γὰρ ἔγωγε<br>σχήσομ’, ἐπεὶ θάνατός γε τὸ κύντατον ἔσσεται ἄλγος.”", "st": "3.502"}, {"sp": "N", "t": "ὧς ἔφατ’ Αἰακίδης· Τελαμῶνι δὲ θυμὸς ὀρίνθη·<br>σπερχόμενος δ’ ἀνόρουσε θοῶς· ἐπὶ δὲ τρίτος Ἴδας<br>ὦρτο μέγα φρονέων, ἐπὶ δ’ υἱέε Τυνδαρέοιο·<br>σὺν δὲ καὶ Οἰνεΐδης ἐναρίθμιος αἰζηοῖσιν<br>ἀνδράσιν, οὐδέ περ ὅσσον ἐπανθιόωντας ἰούλους<br>ἀντέλλων· τοίῳ οἱ ἀείρετο κάρτεϊ θυμός.<br>οἱ δ’ ἄλλοι εἴξαντες ἀκὴν ἔχον. αὐτίκα δ’ Ἄργος<br>τοῖον ἔπος μετέειπεν ἐελδομένοισιν ἀέθλου·", "st": "3.515"}, {"sp": "N", "t": "“ὦ φίλοι, ἤτοι μὲν τόδε λοίσθιον. ἀλλά τιν’ οἴω<br>μητρὸς ἐμῆς ἔσσεσθαι ἐναίσιμον ὔμμιν ἀρωγήν.<br>τῶ καί περ μεμαῶτες, ἐρητύοισθ’ ἐνὶ νηὶ<br>τυτθὸν ἔθ’, ὡς τὸ πάροιθεν, ἐπεὶ καὶ ἐπισχέμεν ἔμπης<br>λώιον, ἢ κακὸν οἶτον ἀφειδήσαντας ἑλέσθαι.<br>κούρη τις μεγάροισιν ἐνιτρέφετ’ Αἰήταο,<br>τὴν Ἑκάτη περίαλλα θεὰ δάε τεχνήσασθαι<br>φάρμαχ’, ὅσ’ ἤπειρός τε φύει καὶ νήχυτον ὕδωρ,<br>τοῖσι καὶ ἀκαμάτοιο πυρὸς μειλίσσετ’ ἀυτμή,<br>καὶ ποταμοὺς ἵστησιν ἄφαρ κελαδεινὰ ῥέοντας,<br>ἄστρα τε καὶ μήνης ἱερῆς ἐπέδησε κελεύθους.<br>τῆς μὲν ἀπὸ μεγάροιο κατὰ στίβον ἐνθάδ’ ἰόντες<br>μνησάμεθ’, εἴ κε δύναιτο, κασιγνήτη γεγαυῖα,<br>μήτηρ ἡμετέρη πεπιθεῖν ἐπαρῆξαι ἀέθλῳ.<br>εἰ δὲ καὶ αὐτοῖσιν τόδ’ ἐφανδάνει, ἦ τ’ ἂν ἱκοίμην<br>ἤματι τῷδ’ αὐτῷ πάλιν εἰς δόμον Αἰήταο<br>πειρήσων· τάχα δ’ ἂν σὺν δαίμονι πειρηθείην.”", "st": "3.523"}, {"sp": "N", "t": "ὧς φάτο· τοῖσι δὲ σῆμα θεοὶ δόσαν εὐμενέοντες.<br>τρηρὼν μὲν φεύγουσα βίην κίρκοιο πελειὰς<br>ὑψόθεν Αἰσονίδεω πεφοβημένη ἔμπεσε κόλποις·<br>κίρκος δ’ ἀφλάστῳ περικάππεσεν. ὦκα δὲ Μόψος<br>τοῖον ἔπος μετὰ πᾶσι θεοπροπέων ἀγόρευσεν·", "st": "3.540"}, {"sp": "N", "t": "“ὔμμι, φίλοι, τόδε σῆμα θεῶν ἰότητι τέτυκται·<br>οὐδέ πῃ ἄλλως ἐστὶν ὑποκρίνασθαι ἄρειον,<br>παρθενικὴν δ’ ἐπέεσσι μετελθέμεν ἀμφιέποντας<br>μήτι παντοίῃ. δοκέω δέ μιν οὐκ ἀθερίζειν,<br>εἰ ἐτεὸν Φινεύς γε θεᾷ ἐνὶ Κύπριδι νόστον<br>πέφραδεν ἔσσεσθαι. κείνης δ’ ὅγε μείλιχος ὄρνις<br>πότμον ὑπεξήλυξε· κέαρ δέ μοι ὡς ἐνὶ θυμῷ<br>τόνδε κατ’ οἰωνὸν προτιόσσεται, ὧς δὲ πέλοιτο.<br>ἀλλά, φίλοι, Κυθέρειαν ἐπικλείοντες ἀμύνειν,<br>ἤδη νῦν Ἄργοιο παραιφασίῃσι πίθεσθε.”", "st": "3.545"}, {"sp": "N", "t": "Ἴσκεν· ἐπῄνησαν δὲ νέοι, Φινῆος ἐφετμὰς<br>μνησάμενοι· μοῦνος δ’ Ἀφαρήιος ἄνθορεν Ἴδας,<br>δείν’ ἐπαλαστήσας μεγάλῃ ὀπί, φώνησέν τε·<br>“ὦ πόποι, ἦ ῥα γυναιξὶν ὁμόστολοι ἐνθάδ’ ἔβημεν,<br>οἳ Κύπριν καλέουσιν ἐπίρροθον ἄμμι πέλεσθαι,<br>οὐκέτ’ Ἐνυαλίοιο μέγα σθένος; ἐς δὲ πελείας<br>καὶ κίρκους λεύσσοντες ἐρητύεσθε ἀέθλων;<br>ἔρρετε, μηδ’ ὔμμιν πολεμήια ἔργα μέλοιτο,<br>παρθενικὰς δὲ λιτῇσιν ἀνάλκιδας ἠπεροπεύειν.”", "st": "3.555"}, {"sp": "N", "t": "ὧς ηὔδα μεμαώς· πολέες δ’ ὁμάδησαν ἑταῖροι<br>ἦκα μάλ’, οὐδ’ ἄρα τίς οἱ ἐναντίον ἔκφατο μῦθον.<br>χωόμενος δ’ ὅγ’ ἔπειτα καθέζετο· τοῖσι δ’ Ἰήσων<br>αὐτίκ’ ἐποτρύνων τὸν ἑὸν νόον ὧδ’ ἀγόρευεν·<br>“Ἄργος μὲν παρὰ νηός, ἐπεὶ τόδε πᾶσιν ἕαδεν,<br>στελλέσθω· ἀτὰρ αὐτοὶ ἐπὶ χθονὸς ἐκ ποταμοῖο<br>ἀμφαδὸν ἤδη πείσματ’ ἀνάψομεν. ἦ γὰρ ἔοικεν<br>μηκέτι δὴν κρύπτεσθαι ὑποπτήσσοντας ἀυτήν.”", "st": "3.564"}, {"sp": "N", "t": "ὧς ἄρ’ ἔφη· καὶ τὸν μὲν ἄφαρ προΐαλλε νέεσθαι<br>καρπαλίμως ἐξαῦτις ἀνὰ πτόλιν· οἱ δ’ ἐπὶ νηὸς<br>εὐναίας ἐρύσαντες ἐφετμαῖς Αἰσονίδαο<br>τυτθὸν ὑπὲξ ἕλεος χέρσῳ ἐπέκελσαν ἐρετμοῖς.", "st": "3.572"}, {"sp": "N", "t": "αὐτίκα δ’ Αἰήτης ἀγορὴν ποιήσατο Κόλχων<br>νόσφιν ἑοῖο δόμου, τόθι περ καὶ πρόσθε κάθιζον,<br>ἀτλήτους Μινύῃσι δόλους καὶ κήδεα τεύχων.<br>στεῦτο δ’, ἐπεί κεν πρῶτα βόες διαδηλήσωνται<br>ἄνδρα τόν, ὅς ῥ’ ὑπέδεκτο βαρὺν καμέεσθαι ἄεθλον,<br>δρυμὸν ἀναρρήξας λασίης καθύπερθε· κολώνης<br>αὔτανδρον φλέξειν δόρυ νήιον, ὄφρ’ ἀλεγεινὴν<br>ὕβριν ἀποφλύξωσιν ὑπέρβια μηχανόωντες.<br>οὐδὲ γὰρ Αἰολίδην Φρίξον μάλα περ χατέοντα<br>δέχθαι ἐνὶ μεγάροισιν ἐφέστιον, ὃς περὶ πάντων<br>ξείνων μειλιχίῃ τε θεουδείῃ τ’ ἐκέκαστο,<br>εἰ μή οἱ Ζεὺς αὐτὸς ἀπ’ οὐρανοῦ ἄγγελον ἧκεν<br>Ἑρμείαν, ὥς κεν προσκηδέος ἀντιάσειεν·<br>μὴ καὶ ληιστῆρας ἑὴν ἐς γαῖαν ἰόντας<br>ἔσσεσθαι δηναιὸν ἀπήμονας, οἷσι μέμηλεν<br>ὀθνείοις ἐπὶ χεῖρα ἑὴν κτεάτεσσιν ἀείρειν,<br>κρυπταδίους τε δόλους τεκταινέμεν, ἠδὲ βοτήρων<br>αὔλια δυσκελάδοισιν ἐπιδρομίῃσι δαΐξαι.<br>νόσφι δὲ οἷ αὐτῷ φάτ’ ἐοικότα μείλια τίσειν<br>υἱῆας Φρίξοιο, κακορρέκτῃσιν ὀπηδοὺς<br>ἀνδράσι νοστήσαντας ὁμιλαδόν, ὄφρα ἑ τιμῆς<br>καὶ σκήπτρων ἐλάσειαν ἀκηδέες· ὥς ποτε βάξιν<br>λευγαλέην οὗ πατρὸς ἐπέκλυεν Ἠελίοιο,<br>χρειώ μιν πυκινόν τε δόλον βουλάς τε γενέθλης<br>σφωιτέρης ἄτην τε πολύτροπον ἐξαλέασθαι·<br>τῶ καὶ ἐελδομένους πέμπειν ἐς Ἀχαιίδα γαῖαν<br>πατρὸς ἐφημοσύνῃ, δολιχὴν ὁδόν. οὐδὲ θυγατρῶν<br>εἶναί οἱ τυτθόν γε δέος, μή πού τινα μῆτιν<br>φράσσωνται στυγερήν, οὐδ’ υἱέος Ἀψύρτοιο·<br>ἀλλ’ ἐνὶ Χαλκιόπης γενεῇ τάδε λυγρὰ τετύχθαι.<br>καί ῥ’ ὁ μὲν ἄσχετα ἔργα πιφαύσκετο δημοτέροισιν<br>χωόμενος· μέγα δέ σφιν ἀπείλεε νῆά τ’ ἔρυσθαι<br>ἠδ’ αὐτούς, ἵνα μήτις ὑπὲκ κακότητος ἀλύξῃ.", "st": "3.576"}, {"sp": "N", "t": "τόφρα δὲ μητέρ’ ἑήν, μετιὼν δόμον Αἰήταο,<br>Ἄργος παντοίοισι παρηγορέεσκ’ ἐπέεσσιν,<br>Μήδειαν λίσσεσθαι ἀμυνέμεν· ἡ δὲ καὶ αὐτὴ<br>πρόσθεν μητιάασκε· δέος δέ μιν ἴσχανε θυμόν,<br>μή πως ἠὲ παρ’ αἶσαν ἐτώσια μειλίξαιτο<br>πατρὸς ἀτυζομένην ὀλοὸν χόλον, ἠὲ λιτῇσιν<br>ἑσπομένης ἀρίδηλα καὶ ἀμφαδὰ ἔργα πέλοιτο.", "st": "3.609"}, {"sp": "N", "t": "κούρην δ’ ἐξ ἀχέων ἀδινὸς κατελώφεεν ὕπνος<br>λέκτρῳ ἀνακλινθεῖσαν. ἄφαρ δέ μιν ἠπεροπῆες,<br>οἷά τ’ ἀκηχεμένην, ὀλοοὶ ἐρέθεσκον ὄνειροι.<br>τὸν ξεῖνον δ’ ἐδόκησεν ὑφεστάμεναι τὸν ἄεθλον,<br>οὔτι μάλ’ ὁρμαίνοντα δέρος κριοῖο κομίσσαι,<br>οὐδέ τι τοῖο ἕκητι μετὰ πτόλιν Αἰήταο<br>ἐλθέμεν, ὄφρα δέ μιν σφέτερον δόμον εἰσαγάγοιτο<br>κουριδίην παράκοιτιν· ὀίετο δ’ ἀμφὶ βόεσσιν<br>αὐτὴ ἀεθλεύουσα μάλ’ εὐμαρέως πονέεσθαι·<br>σφωιτέρους δὲ τοκῆας ὑποσχεσίης ἀθερίζειν,<br>οὕνεκεν οὐ κούρῃ ζεῦξαι βόας, ἀλλά οἱ αὐτῷ<br>προύθεσαν· ἐκ δ’ ἄρα τοῦ νεῖκος πέλεν ἀμφήριστον<br>πατρί τε καὶ ξείνοις· αὐτῇ δ’ ἐπιέτρεπον ἄμφω<br>τὼς ἔμεν, ὥς κεν ἑῇσι μετὰ φρεσὶν ἰθύσειεν.<br>ἡ δ’ ἄφνω τὸν ξεῖνον, ἀφειδήσασα τοκήων,<br>εἵλετο· τοὺς δ’ ἀμέγαρτον ἄχος λάβεν, ἐκ δ’ ἐβόησαν<br>χωόμενοι· τὴν δ’ ὕπνος ἅμα κλαγγῇ μεθέηκεν.<br>παλλομένη δ’ ἀνόρουσε φόβῳ, περί τ’ ἀμφί τε τοίχους<br>πάπτηνεν θαλάμοιο· μόλις δ’ ἐσαγείρατο θυμὸν<br>ὡς πάρος ἐν στέρνοις, ἀδινὴν δ’ ἀνενείκατο φωνήν·", "st": "3.616"}, {"sp": "N", "t": "“δειλὴ ἐγών, οἷόν με βαρεῖς ἐφόβησαν ὄνειροι.<br>δείδια, μὴ μέγα δή τι φέρῃ κακὸν ἥδε κέλευθος<br>ἡρώων. περί μοι ξείνῳ φρένες ἠερέθονται.<br>μνάσθω ἑὸν κατὰ δῆμον Ἀχαιίδα τηλόθι κούρην<br>ἄμμι δὲ παρθενίη τε μέλοι καὶ δῶμα τοκήων.<br>ἔμπα γε μὴν θεμένη κύνεον κέαρ, οὐκέτ’ ἄνευθεν<br>αὐτοκασιγνήτης πειρήσομαι, εἴ κέ μ’ ἀέθλῳ<br>χραισμεῖν ἀντιάσῃσιν, ἐπὶ σφετέροις ἀχέουσα<br>παισί· τό κέν μοι λυγρὸν ἐνὶ κραδίῃ σβέσαι ἄλγος.”", "st": "3.636"}, {"sp": "N", "t": "ἦ ῥα, καὶ ὀρθωθεῖσα θύρας ὤιξε δόμοιο,<br>νήλιπος, οἰέανος· καὶ δὴ λελίητο νέεσθαι<br>αὐτοκασιγνήτηνδε, καὶ ἕρκεος οὐδὸν ἄμειψεν.<br>δὴν δὲ καταυτόθι μίμνεν ἐνὶ προδόμῳ θαλάμοιο,<br>αἰδοῖ ἐεργομένη· μετὰ δ’ ἐτράπετ’ αὖτις ὀπίσσω<br>στρεφθεῖσ’· ἐκ δὲ πάλιν κίεν ἔνδοθεν, ἄψ τ’ ἀλέεινεν<br>εἴσω· τηΰσιοι δὲ πόδες φέρον ἔνθα καὶ ἔνθα·<br>ἤτοι ὅτ’ ἰθύσειεν, ἔρυκέ μιν ἔνδοθεν αἰδώς·<br>αἰδοῖ δ’ ἐργομένην θρασὺς ἵμερος ὀτρύνεσκεν.<br>τρὶς μὲν ἐπειρήθη, τρὶς δ’ ἔσχετο, τέτρατον αὖτις<br>λέκτροισιν πρηνὴς ἐνικάππεσεν εἱλιχθεῖσα.<br>ὡς δ’ ὅτε τις νύμφη θαλερὸν πόσιν ἐν θαλάμοισιν<br>μύρεται, ᾧ μιν ὄπασσαν ἀδελφεοὶ ἠδὲ τοκῆες,<br>οὐδέ τί πω πάσαις ἐπιμίσγεται ἀμφιπόλοισιν<br>αἰδοῖ ἐπιφροσύνῃ τε· μυχῷ δ’ ἀχέουσα θαάσσει·<br>τὸν δέ τις ὤλεσε μοῖρα, πάρος ταρπήμεναι ἄμφω<br>δήνεσιν ἀλλήλων· ἡ δ’ ἔνδοθι δαιομένη περ<br>σῖγα μάλα κλαίει χῆρον λέχος εἰσορόωσα,<br>μή μιν κερτομέουσαι ἐπιστοβέωσι γυναῖκες·<br>τῇ ἰκέλη Μήδεια κινύρετο. τὴν δέ τις ἄφνω<br>μυρομένην μεσσηγὺς ἐπιπρομολοῦσ’ ἐνόησεν<br>δμωάων, ἥ οἱ ἑπέτις πέλε κουρίζουσα·<br>Χαλκιόπῃ δ’ ἤγγειλε παρασχεδόν· ἡ δ’ ἐνὶ παισὶν<br>ἧστ’ ἐπιμητιόωσα κασιγνήτην ἀρέσασθαι.<br>ἀλλ’ οὐδ’ ὧς ἀπίθησεν, ὅτ’ ἔκλυεν ἀμφιπόλοιο<br>μῦθον ἀνώιστον· διὰ δ’ ἔσσυτο θαμβήσασα<br>ἐκ θαλάμου θάλαμόνδε διαμπερές, ᾧ ἔνι κούρη<br>κέκλιτ’ ἀκηχεμένη, δρύψεν δ’ ἑκάτερθε παρειάς·<br>ὡς δ’ ἴδε δάκρυσιν ὄσσε πεφυρμένα, φώνησέν μιν·", "st": "3.645"}, {"sp": "N", "t": "“Ὤι μοι ἐγώ, Μήδεια, τί δὴ τάδε δάκρυα λείβεις;<br>τίπτ’ ἔπαθες; τί τοι αἰνὸν ὑπὸ φρένας ἵκετο πένθος;<br>ἤ νύ σε θευμορίη περιδέδρομεν ἅψεα νοῦσος,<br>ἦέ τιν’ οὐλομένην ἐδάης ἐκ πατρὸς ἐνιπὴν<br>ἀμφί τ’ ἐμοὶ καὶ παισίν; ὄφελλέ με μήτε τοκήων<br>δῶμα τόδ’ εἰσοράαν, μηδὲ πτόλιν, ἀλλ’ ἐπὶ γαίης<br>πείρασι ναιετάειν, ἵνα μηδέ περ οὔνομα Κόλχων.”", "st": "3.674"}, {"sp": "N", "t": "ὧς φάτο· τῆς δ’ ἐρύθηνε παρήια· δὴν δέ μιν αἰδὼς<br>παρθενίη κατέρυκεν ἀμείψασθαι μεμαυῖαν.<br>μῦθος δ’ ἄλλοτε μέν οἱ ἐπ’ ἀκροτάτης ἀνέτελλεν<br>γλώσσης, ἄλλοτ’ ἔνερθε κατὰ στῆθος πεπότητο.<br>πολλάκι δ’ ἱμερόεν μὲν ἀνὰ στόμα θυῖεν ἐνισπεῖν·<br>φθογγῇ δ’ οὐ προύβαινε παροιτέρω· ὀψὲ δ’ ἔειπεν<br>τοῖα δόλῳ· θρασέες γὰρ ἐπεκλονέεσκον Ἔρωτες·", "st": "3.681"}, {"sp": "N", "t": "“Χαλκιόπη, περί μοι παίδων σέο θυμὸς ἄηται,<br>μή σφε πατὴρ ξείνοισι σὺν ἀνδράσιν αὐτίκ’ ὀλέσσῃ.<br>τοῖα κατακνώσσουσα μινυνθαδίῳ νέον ὕπνῳ<br>λεύσσω ὀνείρατα λυγρά, τά τις θεὸς ἀκράαντα<br>θείη, μηδ’ ἀλεγεινὸν ἐφ’ υἱάσι κῆδος ἕλοιο.”", "st": "3.688"}, {"sp": "N", "t": "φῆ ῥα, κασιγνήτης πειρωμένη, εἴ κέ μιν αὐτὴ<br>ἀντιάσειε πάροιθεν ἑοῖς τεκέεσσιν ἀμύνειν.<br>τὴν δ’ αἰνῶς ἄτλητος ἐπέκλυσε θυμὸν ἀνίη<br>δείματι, τοῖ’ ἐσάκουσεν· ἀμείβετο δ’ ὧδ’ ἐπέεσσιν·<br>“καὶ δ’ αὐτὴ τάδε πάντα μετήλυθον ὁρμαίνουσα,<br>εἴ τινα συμφράσσαιο καὶ ἀρτύνειας ἀρωγήν.<br>ἀλλ’ ὄμοσον Γαῖάν τε καὶ Οὐρανόν, ὅττι τοι εἴπω<br>σχήσειν ἐν θυμῷ, σύν τε δρήστειρα πέλεσθαι.<br>λίσσομ’ ὑπὲρ μακάρων σέο τ’ αὐτῆς ἠδὲ τοκήων,<br>μή σφε κακῇ ὑπὸ κηρὶ διαρραισθέντας ἰδέσθαι<br>λευγαλέως· ἢ σοίγε φίλοις σὺν παισὶ θανοῦσα<br>εἴην ἐξ Ἀίδεω στυγερὴ μετόπισθεν Ἐρινύς.”", "st": "3.693"}, {"sp": "N", "t": "ὧς ἄρ’ ἔφη, τὸ δὲ πολλὸν ὑπεξέχυτ’ αὐτίκα δάκρυ·<br>νειόθι θ’ ἀμφοτέρῃσι περίσχετο γούνατα χερσίν,<br>σὺν δὲ κάρη κόλποις περικάββαλεν. ἔνθ’ ἐλεεινὸν<br>ἄμφω ἐπ’ ἀλλήλῃσι θέσαν γόον· ὦρτο δ’ ἰωὴ<br>λεπταλέη διὰ δώματ’ ὀδυρομένων ἀχέεσσιν.<br>τὴν δὲ πάρος Μήδεια προσέννεπεν ἀσχαλόωσα·", "st": "3.705"}, {"sp": "N", "t": "“δαιμονίη, τί νύ τοι ῥέξω ἄκος, οἷ’ ἀγορεύεις,<br>ἀράς τε στυγερὰς καὶ Ἐρινύας; αἲ γὰρ ὄφελλεν<br>ἔμπεδον εἶναι ἐπ’ ἄμμι τεοὺς υἱῆας ἔρυσθαι.<br>ἴστω Κόλχων ὅρκος ὑπέρβιος ὅντιν’ ὀμόσσαι<br>αὐτὴ ἐποτρύνεις, μέγας Οὐρανός, ἥ θ’ ὑπένερθεν<br>Γαῖα, θεῶν μήτηρ, ὅσσον σθένος ἐστὶν ἐμεῖο,<br>μή σ’ ἐπιδευήσεσθαι, ἀνυστά περ ἀντιόωσαν.”", "st": "3.711"}, {"sp": "N", "t": "φῆ ἄρα· Χαλκιόπη δ’ ἠμείβετο τοῖσδ’ ἐπέεσσιν·<br>“οὐκ ἂν δὴ ξείνῳ τλαίης χατέοντι καὶ αὐτῷ<br>ἢ δόλον, ἤ τινα μῆτιν ἐπιφράσσασθαι ἀέθλου,<br>παίδων εἵνεκ’ ἐμεῖο; καὶ ἐκ κείνοιο δ’ ἱκάνει<br>Ἄργος, ἐποτρύνων με τεῆς πειρῆσαι ἀρωγῆς·<br>μεσσηγὺς μὲν τόνγε δόμῳ λίπον ἐνθάδ’ ἰοῦσα.”", "st": "3.718"}, {"sp": "N", "t": "ὧς φάτο· τῇ δ’ ἔντοσθεν ἀνέπτατο χάρματι θυμός,<br>φοινίχθη δ’ ἄμυδις καλὸν χρόα, κὰδ δέ μιν ἀχλὺς<br>εἷλεν ἰαινομένην, τοῖον δ’ ἐπὶ μῦθον ἔειπεν·<br>“Χαλκιόπη, ὡς ὔμμι φίλον τερπνόν τε τέτυκται,<br>ὧς ἔρξω. μὴ γάρ μοι ἐν ὀφθαλμοῖσι φαείνοι<br>ἠώς, μηδέ με δηρὸν ἔτι ζώουσαν ἴδοιο,<br>εἴ γέ τι σῆς ψυχῆς προφερέστερον, ἠέ τι παίδων<br>σῶν θείην, οἳ δή μοι ἀδελφειοὶ γεγάασιν,<br>κηδεμόνες τε φίλοι καὶ ὁμήλικες. ὧς δὲ καὶ αὐτὴ<br>φημὶ κασιγνήτη τε σέθεν κούρη τε πέλεσθαι,<br>ἶσον ἐπεὶ κείνοις με τεῷ ἐπαείραο μαζῷ<br>νηπυτίην, ὡς αἰὲν ἐγώ ποτε μητρὸς ἄκουον.<br>ἀλλ’ ἴθι, κεῦθε δ’ ἐμὴν σιγῇ χάριν, ὄφρα τοκῆας<br>λήσομαι ἐντύνουσα ὑπόσχεσιν· ἦρι δὲ νηὸν<br>οἴσομαι εἰς Ἑκάτης θελκτήρια φάρμακα ταύρων.”", "st": "3.724"}, {"sp": "N", "t": "ὧς ἥγ’ ἐκ θαλάμοιο πάλιν κίε, παισί τ’ ἀρωγὴν<br>αὐτοκασιγνήτης διεπέφραδε. τὴν δέ μιν αὖτις<br>αἰδώς τε στυγερόν τε δέος λάβε μουνωθεῖσαν,<br>τοῖα παρὲξ οὗ πατρὸς ἐπ’ ἀνέρι μητιάασθαι.", "st": "3.740"}, {"sp": "N", "t": "νὺξ μὲν ἔπειτ’ ἐπὶ γαῖαν ἄγεν κνέφας· οἱ δ’ ἐνὶ πόντῳ<br>ναῦται εἰς Ἑλίκην τε καὶ ἀστέρας Ὠρίωνος<br>ἔδρακον ἐκ νηῶν· ὕπνοιο δὲ καί τις ὁδίτης<br>ἤδη καὶ πυλαωρὸς ἐέλδετο· καί τινα παίδων<br>μητέρα τεθνεώτων ἀδινὸν περὶ κῶμ’ ἐκάλυπτεν·<br>οὐδὲ κυνῶν ὑλακὴ ἔτ’ ἀνὰ πτόλιν, οὐ θρόος ἦεν<br>ἠχήεις· σιγὴ δὲ μελαινομένην ἔχεν ὄρφνην.<br>ἀλλὰ μάλ’ οὐ Μήδειαν ἐπὶ γλυκερὸς λάβεν ὕπνος.<br>πολλὰ γὰρ Αἰσονίδαο πόθῳ μελεδήματ’ ἔγειρεν<br>δειδυῖαν ταύρων κρατερὸν μένος, οἷσιν ἔμελλεν<br>φθίσθαι ἀεικελίῃ μοίρῃ κατὰ νειὸν Ἄρηος.<br>πυκνὰ δέ οἱ κραδίη στηθέων ἔντοσθεν ἔθυιεν,<br>ἠελίου ὥς τίς τε δόμοις ἐνιπάλλεται αἴγλη<br>ὕδατος ἐξανιοῦσα, τὸ δὴ νέον ἠὲ λέβητι<br>ἠέ που ἐν γαυλῷ κέχυται· ἡ δ’ ἔνθα καὶ ἔνθα<br>ὠκείῃ στροφάλιγγι τινάσσεται ἀίσσουσα·<br>ὧς δὲ καὶ ἐν στήθεσσι κέαρ ἐλελίζετο κούρης.<br>δάκρυ δ’ ἀπ’ ὀφθαλμῶν ἐλέῳ ῥέεν· ἔνδοθι δ’ αἰεὶ<br>τεῖρ’ ὀδύνη σμύχουσα διὰ χροός, ἀμφί τ’ ἀραιὰς<br>ἶνας καὶ κεφαλῆς ὑπὸ νείατον ἰνίον ἄχρις,<br>ἔνθ’ ἀλεγεινότατον δύνει ἄχος, ὁππότ’ ἀνίας<br>ἀκάματοι πραπίδεσσιν ἐνισκίμψωσιν Ἔρωτες.<br>φῆ δέ οἱ ἄλλοτε μὲν θελκτήρια φάρμακα ταύρων<br>δωσέμεν, ἄλλοτε δ’ οὔτι· καταφθίσθαι δὲ καὶ αὐτή·<br>αὐτίκα δ’ οὔτ’ αὐτὴ θανέειν, οὐ φάρμακα δώσειν,<br>ἀλλ’ αὔτως εὔκηλος ἑὴν ὀτλησέμεν ἄτην.<br>ἑζομένη δἤπειτα δοάσσατο, φώνησέν τε·", "st": "3.744"}, {"sp": "N", "t": "“δειλὴ ἐγώ, νῦν ἔνθα κακῶν ἢ ἔνθα γένωμαι;<br>πάντῃ μοι φρένες εἰσὶν ἀμήχανοι· οὐδέ τις ἀλκὴ<br>πήματος· ἀλλ’ αὔτως φλέγει ἔμπεδον. ὡς ὄφελόν γε<br>Ἀρτέμιδος κραιπνοῖσι πάρος βελέεσσι δαμῆναι,<br>πρὶν τόνγ’ εἰσιδέειν, πρὶν Ἀχαιίδα γαῖαν ἱκέσθαι<br>Χαλκιόπης υἷας. τοὺς μὲν θεὸς ἤ τις Ἐρινὺς<br>ἄμμι πολυκλαύτους δεῦρ’ ἤγαγε κεῖθεν ἀνίας.<br>φθίσθω ἀεθλεύων, εἴ οἱ κατὰ νειὸν ὀλέσθαι<br>μοῖρα πέλει. πῶς γάρ κεν ἐμοὺς λελάθοιμι τοκῆας<br>φάρμακα μησαμένη; ποῖον δ’ ἐπὶ μῦθον ἐνίψω;<br>τίς δὲ δόλος, τίς μῆτις ἐπίκλοπος ἔσσετ’ ἀρωγῆς;<br>ἦ μιν ἄνευθ’ ἑτάρων προσπτύξομαι οἶον ἰδοῦσα;<br>δύσμορος· οὐ μὲν ἔολπα καταφθιμένοιό περ ἔμπης<br>λωφήσειν ἀχέων· τότε δ’ ἂν κακὸν ἄμμι πέλοιτο,<br>κεῖνος ὅτε ζωῆς ἀπαμείρεται. ἐρρέτω αἰδώς,<br>ἐρρέτω ἀγλαΐη· ὁ δ’ ἐμῇ ἰότητι σαωθεὶς<br>ἀσκηθής, ἵνα οἱ θυμῷ φίλον, ἔνθα νέοιτο.<br>αὐτὰρ ἐγὼν αὐτῆμαρ, ὅτ’ ἐξανύσειεν ἄεθλον,<br>τεθναίην, ἢ λαιμὸν ἀναρτήσασα μελάθρῳ,<br>ἢ καὶ πασσαμένη ῥαιστήρια φάρμακα θυμοῦ.<br>ἀλλὰ καὶ ὧς φθιμένῃ μοι ἐπιλλίξουσιν ὀπίσσω<br>κερτομίας· τηλοῦ δὲ πόλις περὶ πᾶσα βοήσει<br>πότμον ἐμόν· καί κέν με διὰ στόματος φορέουσαι<br>Κολχίδες ἄλλυδις ἄλλαι ἀεικέα μωμήσονται·<br>ἥτις κηδομένη τόσον ἀνέρος ἀλλοδαποῖο<br>κάτθανεν, ἥτις δῶμα καὶ οὓς ᾔσχυνε τοκῆας,<br>μαργοσύνῃ εἴξασα. τί δ’ οὐκ ἐμὸν ἔσσεται αἶσχος;<br>ᾤ μοι ἐμῆς ἄτης. ἦ τ’ ἂν πολὺ κέρδιον εἴη<br>τῇδ’ αὐτῇ ἐν νυκτὶ λιπεῖν βίον ἐν θαλάμοισιν<br>πότμῳ ἀνωίστῳ, κάκ’ ἐλέγχεα πάντα φυγοῦσαν,<br>πρὶν τάδε λωβήεντα καὶ οὐκ ὀνομαστὰ τελέσσαι.”", "st": "3.771"}, {"sp": "N", "t": "ἦ, καὶ φωριαμὸν μετεκίαθεν, ᾗ ἔνι πολλὰ<br>φάρμακά οἱ, τὰ μὲν ἐσθλά, τὰ δὲ ῥαιστήρι’, ἔκειτο.<br>ἐνθεμένη δ’ ἐπὶ γούνατ’ ὀδύρετο. δεῦε δὲ κόλπους<br>ἄλληκτον δακρύοισι, τὰ δ’ ἔρρεεν ἀσταγὲς αὔτως,<br>αἴν’ ὀλοφυρομένης τὸν ἑὸν μόρον. ἵετο δ’ ἥγε<br>φάρμακα λέξασθαι θυμοφθόρα, τόφρα πάσαιτο.<br>ἤδη καὶ δεσμοὺς ἀνελύετο φωριαμοῖο,<br>ἐξελέειν μεμαυῖα, δυσάμμορος. ἀλλά οἱ ἄφνω<br>δεῖμ’ ὀλοὸν στυγεροῖο κατὰ φρένας ἦλθ’ Ἀίδαο.<br>ἔσχετο δ’ ἀμφασίῃ δηρὸν χρόνον, ἀμφὶ δὲ πᾶσαι<br>θυμηδεῖς βιότοιο μεληδόνες ἰνδάλλοντο.<br>μνήσατο μὲν τερπνῶν, ὅσ’ ἐνὶ ζωοῖσι πέλονται,<br>μνήσαθ’ ὁμηλικίης περιγηθέος, οἷά τε κούρη·<br>καί τέ οἱ ἠέλιος γλυκίων γένετ’ εἰσοράασθαι,<br>ἢ πάρος, εἰ ἐτεόν γε νόῳ ἐπεμαίεθ’ ἕκαστα.<br>καὶ τὴν μέν ῥα πάλιν σφετέρων ἀποκάτθετο γούνων,<br>Ἥρης ἐννεσίῃσι μετάτροπος, οὐδ’ ἔτι βουλὰς<br>ἄλλῃ δοιάζεσκεν· ἐέλδετο δ’ αἶψα φανῆναι<br>ἠῶ τελλομένην, ἵνα οἱ θελκτήρια δοίη<br>φάρμακα συνθεσίῃσι, καὶ ἀντήσειεν ἐς ὠπήν.<br>πυκνὰ δ’ ἀνὰ κληῖδας ἑῶν λύεσκε θυράων,<br>αἴγλην σκεπτομένη· τῇ δ’ ἀσπάσιον βάλε φέγγος<br>Ἠριγενής, κίνυντο δ’ ἀνὰ πτολίεθρον ἕκαστοι.", "st": "3.802"}, {"sp": "N", "t": "ἔνθα κασιγνήτους μὲν ἔτ’ αὐτόθι μεῖναι ἀνώγει<br>Ἄργος, ἵνα φράζοιντο νόον καὶ μήδεα κούρης·<br>αὐτὸς δ’ αὖτ’ ἐπὶ νῆα κίεν προπάροιθε λιασθείς.", "st": "3.825"}, {"sp": "N", "t": "ἡ δ’ ἐπεὶ οὖν τὰ πρῶτα φαεινομένην ἴδεν ἠῶ<br>παρθενική, ξανθὰς μὲν ἀνήψατο χερσὶν ἐθείρας,<br>αἵ οἱ ἀτημελίῃ καταειμέναι ἠερέθοντο,<br>αὐσταλέας δ’ ἔψησε παρηίδας· αὐτὰρ ἀλοιφῇ<br>νεκταρέῃ φαιδρύνετ’ ἐπὶ χρόα· δῦνε δὲ πέπλον<br>καλόν, ἐυγνάμπτοισιν ἀρηρέμενον περόνῃσιν·<br>ἀμβροσίῳ δ’ ἐφύπερθε καρήατι βάλλε καλύπτρην<br>ἀργυφέην. αὐτοῦ δὲ δόμοις ἔνι δινεύουσα<br>στεῖβε πέδον λήθῃ ἀχέων, τά οἱ ἐν ποσὶν ἦεν<br>θεσπέσι’, ἄλλα τ’ ἔμελλεν ἀεξήσεσθαι ὀπίσσω.<br>κέκλετο δ’ ἀμφιπόλοις, αἵ οἱ δυοκαίδεκα πᾶσαι<br>ἐν προδόμῳ θαλάμοιο θυώδεος ηὐλίζοντο<br>ἥλικες, οὔπω λέκτρα σὺν ἀνδράσι πορσύνουσαι,<br>ἐσσυμένως οὐρῆας ὑποζεύξασθαι ἀπήνῃ,<br>οἵ κέ μιν εἰς Ἑκάτης περικαλλέα νηὸν ἄγοιεν.<br>ἔνθ’ αὖτ’ ἀμφίπολοι μὲν ἐφοπλίζεσκον ἀπήνην·<br>ἡ δὲ τέως γλαφυρῆς ἐξείλετο φωριαμοῖο<br>φάρμακον, ὅ ῥά τέ φασι Προμήθειον καλέεσθαι.<br>τῷ εἴ κ’ ἐννυχίοισιν ἀρεσσάμενος θυέεσσιν<br>κούρην μουνογένειαν ἑὸν δέμας ἰκμαίνοιτο,<br>ἦ τ’ ἂν ὅγ’ οὔτε ῥηκτὸς ἔοι χαλκοῖο τυπῇσιν,<br>οὔτε κεν αἰθομένῳ πυρὶ εἰκάθοι· ἀλλὰ καὶ ἀλκῇ<br>λωίτερος κεῖν’ ἦμαρ ὁμῶς κάρτει τε πέλοιτο.<br>πρωτοφυὲς τόγ’ ἀνέσχε καταστάξαντος ἔραζε<br>αἰετοῦ ὠμηστέω κνημοῖς ἔνι Καυκασίοισιν<br>αἱματόεντ’ ἰχῶρα Προμηθῆος μογεροῖο.<br>τοῦ δ’ ἤτοι ἄνθος μὲν ὅσον πήχυιον ὕπερθεν<br>χροιῇ Κωρυκίῳ ἴκελον κρόκῳ ἐξεφαάνθη,<br>καυλοῖσιν διδύμοισιν ἐπήορον· ἡ δ’ ἐνὶ γαίῃ<br>σαρκὶ νεοτμήτῳ ἐναλιγκίη ἔπλετο ῥίζα.<br>τῆς οἵην τ’ ἐν ὄρεσσι κελαινὴν ἰκμάδα φηγοῦ<br>Κασπίῃ ἐν κόχλῳ ἀμήσατο φαρμάσσεσθαι,<br>ἑπτὰ μὲν ἀενάοισι λοεσσαμένη ὑδάτεσσιν,<br>ἑπτάκι δὲ Βριμὼ κουροτρόφον ἀγκαλέσασα,<br>Βριμὼ νυκτιπόλον, χθονίην, ἐνέροισιν ἄνασσαν,<br>λυγαίῃ ἐνὶ νυκτί, σὺν ὀρφναίοις φαρέεσσιν.<br>μυκηθμῷ δ’ ὑπένερθεν ἐρεμνὴ σείετο γαῖα,<br>ῥίζης τεμνομένης Τιτηνίδος· ἔστενε δ’ αὐτὸς<br>Ἰαπετοῖο πάις ὀδύνῃ πέρι θυμὸν ἀλύων.<br>τό ῥ’ ἥγ’ ἐξανελοῦσα θυώδεϊ κάτθετο μίτρῃ,<br>ἥ τέ οἱ ἀμβροσίοισι περὶ στήθεσσιν ἔερτο.<br>ἐκ δὲ θύραζε κιοῦσα θοῆς ἐπεβήσατ’ ἀπήνης·<br>σὺν δέ οἱ ἀμφίπολοι δοιαὶ ἑκάτερθεν ἔβησαν.<br>αὐτὴ δ’ ἡνί’ ἔδεκτο καὶ εὐποίητον ἱμάσθλην<br>δεξιτερῇ, ἔλαεν δὲ δι’ ἄστεος· αἱ δὲ δὴ ἄλλαι<br>ἀμφίπολοι, πείρινθος ἐφαπτόμεναι μετόπισθεν,<br>τρώχων εὐρεῖαν κατ’ ἀμαξιτόν· ἂν δὲ χιτῶνας<br>λεπταλέους λευκῆς ἐπιγουνίδος ἄχρις ἄειρον.<br>οἵη δὲ λιαροῖσιν ἐφ’ ὕδασι Παρθενίοιο,<br>ἠὲ καὶ Ἀμνισοῖο λοεσσαμένη ποταμοῖο<br>χρυσείοις Λητωὶς ἐφ’ ἅρμασιν ἑστηυῖα<br>ὠκείαις κεμάδεσσι διεξελάσῃσι κολώνας,<br>τηλόθεν ἀντιόωσα πολυκνίσου ἑκατόμβης·<br>τῇ δ’ ἅμα νύμφαι ἕπονται ἀμορβάδες, αἱ μὲν ἐπ’ αὐτῆς<br>ἀγρόμεναι πηγῆς Ἀμνισίδος, ἂν δὲ δὴ ἄλλαι<br>ἄλσεα καὶ σκοπιὰς πολυπίδακας· ἀμφὶ δὲ θῆρες<br>κνυζηθμῷ σαίνουσιν ὑποτρομέοντες ἰοῦσαν·<br>ὧς αἵγ’ ἐσσεύοντο δι’ ἄστεος· ἀμφὶ δὲ λαοὶ<br>εἶκον, ἀλευάμενοι βασιληίδος ὄμματα κούρης.<br>αὐτὰρ ἐπεὶ πόλιος μὲν ἐυδμήτους λίπ’ ἀγυιάς,<br>νηὸν δ’ εἰσαφίκανε διὲκ πεδίων ἐλάουσα,<br>δὴ τότ’ ἐυτροχάλοιο κατ’ αὐτόθι βήσατ’ ἀπήνης<br>ἱεμένη, καὶ τοῖα μετὰ δμωῇσιν ἔειπεν·", "st": "3.828"}, {"sp": "N", "t": "“ὦ φίλαι, ἦ μέγα δή τι παρήλιτον, οὐδ’ ἐνόησα<br>μὴ ἴμεν ἀλλοδαποῖσι μετ’ ἀνδράσιν, οἵ τ’ ἐπὶ γαῖαν<br>ἡμετέρην στρωφῶσιν. ἀμηχανίῃ βεβόληται<br>πᾶσα πόλις· τὸ καὶ οὔτις ἀνήλυθε δεῦρο γυναικῶν<br>τάων, αἳ τὸ πάροιθεν ἐπημάτιαι ἀγέρονται.<br>ἀλλ’ ἐπεὶ οὖν ἱκόμεσθα, καὶ οὔ νύ τις ἄλλος ἔπεισιν,<br>εἰ δ’ ἄγε μολπῇ θυμὸν ἀφειδείως κορέσωμεν<br>μειλιχίῃ, τὰ δὲ καλὰ τερείνης ἄνθεα ποίης<br>λεξάμεναι τότ’ ἔπειτ’ αὐτὴν ἀπονισσόμεθ’ ὥρην.<br>καὶ δέ κε σὺν πολέεσσιν ὀνείασιν οἴκαδ’ ἵκοισθε<br>ἤματι τῷ, εἴ μοι συναρέσσετε τήνδε μενοινήν.<br>Ἄργος γάρ μ’ ἐπέεσσι παρατρέπει, ὧς δὲ καὶ αὐτὴ<br>Χαλκιόπη· τὰ δὲ σῖγα νόῳ ἔχετ’ εἰσαΐουσαι<br>ἐξ ἐμέθεν, μὴ πατρὸς ἐς οὔατα μῦθος ἵκηται.<br>τὸν ξεῖνόν με κέλονται, ὅτις περὶ βουσὶν ὑπέστη,<br>δῶρ’ ἀποδεξαμένην ὀλοῶν ῥύσασθαι ἀέθλων.<br>αὐτὰρ ἐγὼ τὸν μῦθον ἐπῄνεον, ἠδὲ καὶ αὐτὸν<br>κέκλομαι εἰς ὠπὴν ἑτάρων ἄπο μοῦνον ἱκέσθαι,<br>ὄφρα τὰ μὲν δασόμεσθα μετὰ σφίσιν, εἴ κεν ὀπάσσῃ<br>δῶρα φέρων, τῷ δ’ αὖτε κακώτερον ἄλλο πόρωμεν<br>φάρμακον. ἀλλ’ ἀπονόσφι πέλεσθέ μοι, εὖτ’ ἂν ἵκηται.”", "st": "3.891"}, {"sp": "N", "t": "ὧς ηὔδα· πάσῃσι δ’ ἐπίκλοπος ἥνδανε μῆτις.<br>αὐτίκα δ’ Αἰσονίδην ἑτάρων ἄπο μοῦνον ἐρύσσας<br>Ἄργος, ὅτ’ ἤδη τήνδε κασιγνήτων ἐσάκουσεν<br>ἠερίην Ἑκάτης ἱερὸν μετὰ νηὸν ἰοῦσαν,<br>ἦγε διὲκ πεδίου· ἅμα δέ σφισιν εἵπετο Μόψος<br>Ἀμπυκίδης, ἐσθλὸς μὲν ἐπιπροφανέντας ἐνισπεῖν<br>οἰωνούς, ἐσθλὸς δὲ σὺν εὖ φράσσασθαι ἰοῦσιν.", "st": "3.912"}, {"sp": "N", "t": "ἔνθ’ οὔπω τις τοῖος ἐπὶ προτέρων γένετ’ ἀνδρῶν,<br>οὔθ’ ὅσοι ἐξ αὐτοῖο Διὸς γένος, οὔθ’ ὅσοι ἄλλων<br>ἀθανάτων ἥρωες ἀφ’ αἵματος ἐβλάστησαν,<br>οἷον Ἰήσονα θῆκε Διὸς δάμαρ ἤματι κείνῳ<br>ἠμὲν ἐσάντα ἰδεῖν, ἠδὲ προτιμυθήσασθαι.<br>τὸν καὶ παπταίνοντες ἐθάμβεον αὐτοὶ ἑταῖροι<br>λαμπόμενον χαρίτεσσιν· ἐγήθησεν δὲ κελεύθῳ<br>Ἀμπυκίδης, ἤδη που ὀισσάμενος τὰ ἕκαστα.", "st": "3.919"}, {"sp": "N", "t": "ἔστι δέ τις πεδίοιο κατὰ στίβον ἐγγύθι νηοῦ<br>αἴγειρος φύλλοισιν ἀπειρεσίοις κομόωσα,<br>τῇ θαμὰ δὴ λακέρυζαι ἐπηυλίζοντο κορῶναι.<br>τάων τις μεσσηγὺς ἀνὰ πτερὰ κινήσασα<br>ὑψοῦ ἐπ’ ἀκρεμόνων Ἥρης ἠνίπαπε βουλάς·", "st": "3.927"}, {"sp": "N", "t": "“Ἀκλειὴς ὅδε μάντις, ὃς οὐδ’ ὅσα παῖδες ἴσασιν<br>οἶδε νόῳ φράσσασθαι, ὁθούνεκεν οὔτε τι λαρὸν<br>οὔτ’ ἐρατὸν κούρη κεν ἔπος προτιμυθήσαιτο<br>ἠιθέῳ, εὖτ’ ἄν σφιν ἐπήλυδες ἄλλοι ἕπωνται.<br>ἔρροις, ὦ κακόμαντι, κακοφραδές· οὔτε σε Κύπρις,<br>οὔτ’ ἀγανοὶ φιλέοντες ἐπιπνείουσιν Ἔρωτες.”", "st": "3.932"}, {"sp": "N", "t": "Ἴσκεν ἀτεμβομένη· μείδησε δὲ Μόψος ἀκούσας<br>ὀμφὴν οἰωνοῖο θεήλατον, ὧδέ τ’ ἔειπεν·<br>“τύνη μὲν νηόνδε θεᾶς ἴθι, τῷ ἔνι κούρην<br>δήεις, Αἰσονίδη· μάλα δ’ ἠπίῃ ἀντιβολήσεις<br>Κύπριδος ἐννεσίῃς, ἥ τοι συνέριθος ἀέθλων<br>ἔσσεται, ὡς δὴ καὶ πρὶν Ἀγηνορίδης φάτο Φινεύς.<br>νῶι δ’, ἐγὼν Ἄργος τε, δεδεγμένοι, εὖτ’ ἂν ἵκηαι,<br>τῷδ’ αὐτῷ ἐνὶ χώρῳ ἀπεσσόμεθ’· οἰόθι δ’ αὐτὸς<br>λίσσεό μιν πυκινοῖσι παρατροπέων ἐπέεσσιν.”", "st": "3.938"}, {"sp": "N", "t": "ἦ ῥα περιφραδέως, ἐπὶ δὲ σχεδὸν ᾔνεον ἄμφω.<br>οὐδ’ ἄρα Μηδείης θυμὸς τράπετ’ ἄλλα νοῆσαι,<br>μελπομένης περ ὅμως· πᾶσαι δέ οἱ, ἥντιν’ ἀθύροι<br>μολπήν, οὐκ ἐπὶ δηρὸν ἐφήνδανεν ἑψιάασθαι.<br>ἀλλὰ μεταλλήγεσκεν ἀμήχανος, οὐδέ ποτ’ ὄσσε<br>ἀμφιπόλων μεθ’ ὅμιλον ἔχ’ ἀτρέμας· ἐς δὲ κελεύθους<br>τηλόσε παπταίνεσκε, παρακλίνουσα παρειάς.<br>ἦ θαμὰ δὴ στηθέων ἐάγη κέαρ, ὁππότε δοῦπον<br>ἢ ποδὸς ἢ ἀνέμοιο παραθρέξαντα δοάσσαι.<br>αὐτὰρ ὅγ’ οὐ μετὰ δηρὸν ἐελδομένῃ ἐφαάνθη<br>ὑψόσ’ ἀναθρώσκων ἅ τε Σείριος Ὠκεανοῖο,<br>ὃς δή τοι καλὸς μὲν ἀρίζηλός τ’ ἐσιδέσθαι<br>ἀντέλλει, μήλοισι δ’ ἐν ἄσπετον ἧκεν ὀιζύν·<br>ὧς ἄρα τῇ καλὸς μὲν ἐπήλυθεν εἰσοράασθαι<br>Αἰσονίδης, κάματον δὲ δυσίμερον ὦρσε φαανθείς.<br>ἐκ δ’ ἄρα οἱ κραδίη στηθέων πέσεν, ὄμματα δ’ αὔτως<br>ἤχλυσαν· θερμὸν δὲ παρηίδας εἷλεν ἔρευθος.<br>γούνατα δ’ οὔτ’ ὀπίσω οὔτε προπάροιθεν ἀεῖραι<br>ἔσθενεν, ἀλλ’ ὑπένερθε πάγη πόδας. αἱ δ’ ἄρα τείως<br>ἀμφίπολοι μάλα πᾶσαι ἀπὸ σφείων ἐλίασθεν.<br>τὼ δ’ ἄνεῳ καὶ ἄναυδοι ἐφέστασαν ἀλλήλοισιν,<br>ἢ δρυσίν, ἢ μακρῇσιν ἐειδόμενοι ἐλάτῃσιν,<br>αἵ τε παρᾶσσον ἕκηλοι ἐν οὔρεσιν ἐρρίζωνται,<br>νηνεμίῃ· μετὰ δ’ αὖτις ὑπὸ ῥιπῆς ἀνέμοιο<br>κινύμεναι ὁμάδησαν ἀπείριτον· ὧς ἄρα τώγε<br>μέλλον ἅλις φθέγξασθαι ὑπὸ πνοιῇσιν Ἔρωτος.<br>γνῶ δέ μιν Αἰσονίδης ἄτῃ ἐνιπεπτηυῖαν<br>θευμορίῃ, καὶ τοῖον ὑποσσαίνων φάτο μῦθον·", "st": "3.947"}, {"sp": "N", "t": "“τίπτε με, παρθενική, τόσον ἅζεαι, οἶον ἐόντα;<br>οὔ τοι ἐγών, οἷοί τε δυσαυχέες ἄλλοι ἔασιν<br>ἀνέρες, οὐδ’ ὅτε περ πάτρῃ ἔνι ναιετάασκον,<br>ἦα πάρος. τῶ μή με λίην ὑπεραίδεο, κούρη,<br>ἤ τι παρεξερέεσθαι, ὅ τοι φίλον, ἠέ τι φάσθαι.<br>ἀλλ’ ἐπεὶ ἀλλήλοισιν ἱκάνομεν εὐμενέοντες,<br>χώρῳ ἐν ἠγαθέῳ, ἵνα τ’ οὐ θέμις ἔστ’ ἀλιτέσθαι,<br>ἀμφαδίην ἀγόρευε καὶ εἴρεο· μηδέ με τερπνοῖς<br>φηλώσῃς ἐπέεσσιν, ἐπεὶ τὸ πρῶτον ὑπέστης<br>αὐτοκασιγνήτῃ μενοεικέα φάρμακα δώσειν.<br>πρός σ’ αὐτῆς Ἑκάτης μειλίσσομαι ἠδὲ τοκήων<br>καὶ Διός, ὃς ξείνοις ἱκέτῃσί τε χεῖρ’ ὑπερίσχει·<br>ἀμφότερον δ’, ἱκέτης ξεῖνός τέ τοι ἐνθάδ’ ἱκάνω,<br>χρειοῖ ἀναγκαίῃ γουνούμενος. οὐ γὰρ ἄνευθεν<br>ὑμείων στονόεντος ὑπέρτερος ἔσσομ’ ἀέθλου.<br>σοὶ δ’ ἂν ἐγὼ τίσαιμι χάριν μετόπισθεν ἀρωγῆς,<br>ἣ θέμις, ὡς ἐπέοικε διάνδιχα ναιετάοντας,<br>οὔνομα καὶ καλὸν τεύχων κλέος· ὧς δὲ καὶ ὧλλοι<br>ἥρωες κλῄσουσιν ἐς Ἑλλάδα νοστήσαντες<br>ἡρώων τ’ ἄλοχοι καὶ μητέρες, αἵ νύ που ἤδη<br>ἡμέας ἠιόνεσσιν ἐφεζόμεναι γοάουσιν·<br>τάων ἀργαλέας κεν ἀποσκεδάσειας ἀνίας.<br>δή ποτε καὶ Θησῆα κακῶν ὑπελύσατ’ ἀέθλων<br>παρθενικὴ Μινωὶς ἐυφρονέουσ’ Ἀριάδνη,<br>ἥν ῥά τε Πασιφάη κούρη τέκεν Ἠελίοιο.<br>ἀλλ’ ἡ μὲν καὶ νηός, ἐπεὶ χόλον εὔνασε Μίνως,<br>σὺν τῷ ἐφεζομένη πάτρην λίπε· τὴν δὲ καὶ αὐτοὶ<br>ἀθάνατοι φίλαντο, μέσῳ δέ οἱ αἰθέρι τέκμαρ<br>ἀστερόεις στέφανος, τόν τε κλείουσ’ Ἀριάδνης,<br>πάννυχος οὐρανίοισιν ἑλίσσεται εἰδώλοισιν.<br>ὧς καὶ σοὶ θεόθεν χάρις ἔσσεται, εἴ κε σαώσῃς<br>τόσσον ἀριστήων ἀνδρῶν στόλον. ἦ γὰρ ἔοικας<br>ἐκ μορφῆς ἀγανῇσιν ἐπητείῃσι κεκάσθαι.”", "st": "3.975"}, {"sp": "N", "t": "ὧς φάτο κυδαίνων· ἡ δ’ ἐγκλιδὸν ὄσσε βαλοῦσα<br>νεκτάρεον μείδησ’ ἐχύθη δέ οἱ ἔνδοθι θυμὸς<br>αἴνῳ ἀειρομένης, καὶ ἀνέδρακεν ὄμμασιν ἄντην·<br>οὐδ’ ἔχεν ὅττι πάροιθεν ἔπος προτιμυθήσαιτο,<br>ἀλλ’ ἄμυδις μενέαινεν ἀολλέα πάντ’ ἀγορεῦσαι.<br>προπρὸ δ’ ἀφειδήσασα θυώδεος ἔξελε μίτρης<br>φάρμακον· αὐτὰρ ὅγ’ αἶψα χεροῖν ὑπέδεκτο γεγηθώς.<br>καί νύ κέ οἱ καὶ πᾶσαν ἀπὸ στηθέων ἀρύσασα<br>ψυχὴν ἐγγυάλιξεν ἀγαιομένη χατέοντι·<br>τοῖος ἀπὸ ξανθοῖο καρήατος Αἰσονίδαο<br>στράπτεν Ἔρως ἡδεῖαν ἀπὸ φλόγα· τῆς δ’ ἀμαρυγὰς<br>ὀφθαλμῶν ἥρπαζεν· ἰαίνετο δὲ φρένας εἴσω<br>τηκομένη, οἷόν τε περὶ ῥοδέῃσιν ἐέρση<br>τήκεται ἠῴοισιν ἰαινομένη φαέεσσιν.<br>ἄμφω δ’ ἄλλοτε μέν τε κατ’ οὔδεος ὄμματ’ ἔρειδον<br>αἰδόμενοι, ὁτὲ δ’ αὖτις ἐπὶ σφίσι βάλλον ὀπωπάς,<br>ἱμερόεν φαιδρῇσιν ὑπ’ ὀφρύσι μειδιόωντες.<br>ὀψὲ δὲ δὴ τοίοισι μόλις προσπτύξατο κούρη·", "st": "3.1008"}, {"sp": "N", "t": "“φράζεο νῦν, ὥς κέν τοι ἐγὼ μητίσομ’ ἀρωγήν.<br>εὖτ’ ἂν δὴ μετιόντι πατὴρ ἐμὸς ἐγγυαλίξῃ<br>ἐξ ὄφιος γενύων ὀλοοὺς σπείρασθαι ὀδόντας,<br>δὴ τότε μέσσην νύκτα διαμμοιρηδὰ φυλάξας,<br>ἀκαμάτοιο ῥοῇσι λοεσσάμενος ποταμοῖο,<br>οἶος ἄνευθ’ ἄλλων ἐνὶ φάρεσι κυανέοισιν<br>βόθρον ὀρύξασθαι περιηγέα· τῷ δ’ ἔνι θῆλυν<br>ἀρνειὸν σφάζειν, καὶ ἀδαίετον ὠμοθετῆσαι,<br>αὐτῷ πυρκαϊὴν εὖ νηήσας ἐπὶ βόθρῳ.<br>μουνογενῆ δ’ Ἑκάτην Περσηίδα μειλίσσοιο,<br>λείβων ἐκ δέπαος σιμβλήια ἔργα μελισσέων.<br>ἔνθα δ’ ἐπεί κε θεὰν μεμνημένος ἱλάσσηαι,<br>ἂψ ἀπὸ πυρκαϊῆς ἀναχάζεο· μηδέ σε δοῦπος<br>ἠὲ ποδῶν ὄρσῃσι μεταστρεφθῆναι ὀπίσσω,<br>ἠὲ κυνῶν ὑλακή, μή πως τὰ ἕκαστα κολούσας<br>οὐδ’ αὐτὸς κατὰ κόσμον ἑοῖς ἑτάροισι πελάσσῃς.<br>ἦρι δὲ μυδήνας τόδε φάρμακον, ἠύτ’ ἀλοιφῇ<br>γυμνωθεὶς φαίδρυνε τεὸν δέμας· ἐν δέ οἱ ἀλκὴ<br>ἔσσετ’ ἀπειρεσίη μέγα τε σθένος, οὐδέ κε φαίης<br>ἀνδράσιν, ἀλλὰ θεοῖσιν ἰσαζέμεν ἀθανάτοισιν.<br>πρὸς δὲ καὶ αὐτῷ δουρὶ σάκος πεπαλαγμένον ἔστω<br>καὶ ξίφος. ἔνθ’ οὐκ ἄν σε διατμήξειαν ἀκωκαὶ<br>γηγενέων ἀνδρῶν, οὐδ’ ἄσχετος ἀίσσουσα<br>φλὸξ ὀλοῶν ταύρων. τοῖός γε μὲν οὐκ ἐπὶ δηρὸν<br>ἔσσεαι, ἀλλ’ αὐτῆμαρ· ὅμως σύγε μή ποτ’ ἀέθλου<br>χάζεο. καὶ δέ τοι ἄλλο παρὲξ ὑποθήσομ’ ὄνειαρ.<br>αὐτίκ’ ἐπὴν κρατεροὺς ζεύξῃς βόας, ὦκα δὲ πᾶσαν<br>χερσὶ καὶ ἠνορέῃ στυφελὴν διὰ νειὸν ἀρόσσῃς,<br>οἱ δ’ ἤδη κατὰ ὦλκας ἀνασταχύωσι Γίγαντες<br>σπειρομένων ὄφιος δνοφερὴν ἐπὶ βῶλον ὀδόντων,<br>αἴ κεν ὀρινομένους πολέας νειοῖο δοκεύσῃς,<br>λάθρῃ λᾶαν ἄφες στιβαρώτερον· οἱ δ’ ἂν ἐπ’ αὐτῷ,<br>καρχαλέοι κύνες ὥστε περὶ βρώμης, ὀλέκοιεν<br>ἀλλήλους· καὶ δ’ αὐτὸς ἐπείγεο δηιοτῆτος<br>ἰθῦσαι. τὸ δὲ κῶας ἐς Ἑλλάδα τοῖό γ’ ἕκητι<br>οἴσεαι ἐξ Αἴης τηλοῦ ποθί· νίσσεο δ’ ἔμπης,<br>ᾗ φίλον, ἤ τοι ἕαδεν ἀφορμηθέντι νέεσθαι.”", "st": "3.1026"}, {"sp": "N", "t": "ὧς ἄρ’ ἔφη, καὶ σῖγα ποδῶν πάρος ὄσσε βαλοῦσα<br>θεσπέσιον λιαροῖσι παρηίδα δάκρυσι δεῦεν<br>μυρομένη, ὅ τ’ ἔμελλεν ἀπόπροθι πολλὸν ἑοῖο<br>πόντον ἐπιπλάγξεσθαι· ἀνιηρῷ δέ μιν ἄντην<br>ἐξαῦτις μύθῳ προσεφώνεεν, εἷλέ τε χειρὸς<br>δεξιτερῆς· δὴ γάρ οἱ ἀπ’ ὀφθαλμοὺς λίπεν αἰδώς·", "st": "3.1063"}, {"sp": "N", "t": "“μνώεο δ’, ἢν ἄρα δή ποθ’ ὑπότροπος οἴκαδ’ ἵκηαι,<br>οὔνομα Μηδείης· ὧς δ’ αὖτ’ ἐγὼ ἀμφὶς ἐόντος<br>μνήσομαι. εἰπὲ δέ μοι πρόφρων τόδε, πῇ τοι ἔασιν<br>δώματα, πῇ νῦν ἔνθεν ὑπεὶρ ἅλα νηὶ περήσεις·<br>ἤ νύ που ἀφνειοῦ σχεδὸν ἵξεαι Ὀρχομενοῖο,<br>ἦε καὶ Αἰαίης νήσου πέλας; εἰπὲ δὲ κούρην,<br>ἥντινα τήνδ’ ὀνόμηνας ἀριγνώτην γεγαυῖαν<br>Πασιφάης, ἣ πατρὸς ὁμόγνιός ἐστιν ἐμεῖο.”", "st": "3.1069"}, {"sp": "N", "t": "ὧς φάτο· τὸν δὲ καὶ αὐτὸν ὑπήιε δάκρυσι κούρης<br>οὖλος Ἔρως, τοῖον δὲ παραβλήδην ἔπος ηὔδα·", "st": "3.1077"}, {"sp": "N", "t": "“καὶ λίην οὐ νύκτας ὀίομαι, οὐδέ ποτ’ ἦμαρ<br>σεῦ ἐπιλήσεσθαι, προφυγὼν μόρον, εἰ ἐτεόν γε<br>φεύξομαι ἀσκηθὴς ἐς Ἀχαιίδα, μηδέ τιν’ ἄλλον<br>Αἰήτης προβάλῃσι κακώτερον ἄμμιν ἄεθλον.<br>εἰ δέ τοι ἡμετέρην ἐξίδμεναι εὔαδε πάτρην,<br>ἐξερέω· μάλα γάρ με καὶ αὐτὸν θυμὸς ἀνώγει.<br>ἔστι τις αἰπεινοῖσι περίδρομος οὔρεσι γαῖα,<br>πάμπαν ἐύρρηνός τε καὶ εὔβοτος, ἔνθα Προμηθεὺς<br>Ἰαπετιονίδης ἀγαθὸν τέκε Δευκαλίωνα,<br>ὃς πρῶτος ποίησε πόλεις καὶ ἐδείματο νηοὺς<br>ἀθανάτοις, πρῶτος δὲ καὶ ἀνθρώπων βασίλευσεν.<br>Αἱμονίην δὴ τήνγε περικτίονες καλέουσιν.<br>ἐν δ’ αὐτῇ Ἰαωλκός, ἐμὴ πόλις, ἐν δὲ καὶ ἄλλαι<br>πολλαὶ ναιετάουσιν, ἵν’ οὐδέ περ οὔνομ’ ἀκοῦσαι<br>Αἰαίης νήσου· Μινύην γε μὲν ὁρμηθέντα,<br>Αἰολίδην Μινύην ἔνθεν φάτις Ὀρχομενοῖο<br>δή ποτε Καδμείοισιν ὁμούριον ἄστυ πολίσσαι.<br>ἀλλὰ τίη τάδε τοι μεταμώνια πάντ’ ἀγορεύω,<br>ἡμετέρους τε δόμους τηλεκλείτην τ’ Ἀριάδνην,<br>κούρην Μίνωος, τόπερ ἀγλαὸν οὔνομα κείνην<br>παρθενικὴν καλέεσκον ἐπήρατον, ἥν μ’ ἐρεείνεις;<br>αἴθε γάρ, ὡς Θησῆι τότε ξυναρέσσατο Μίνως<br>ἀμφ’ αὐτῆς, ὧς ἄμμι πατὴρ τεὸς ἄρθμιος εἴη.”", "st": "3.1079"}, {"sp": "N", "t": "ὧς φάτο, μειλιχίοισι καταψήχων ὀάροισιν.<br>τῆς δ’ ἀλεγεινόταται κραδίην ἐρέθεσκον ἀνῖαι,<br>καί μιν ἀκηχεμένη ἀδινῷ προσπτύξατο μύθῳ·", "st": "3.1102"}, {"sp": "N", "t": "“Ἑλλάδι που τάδε καλά, συνημοσύνας ἀλεγύνειν.<br>Αἰήτης δ’ οὐ τοῖος ἐν ἀνδράσιν, οἷον ἔειπας<br>Μίνω Πασιφάης πόσιν ἔμμεναι· οὐδ’ Ἀριάδνῃ<br>ἰσοῦμαι· τῶ μήτι φιλοξενίην ἀγόρευε.<br>ἀλλ’ οἶον τύνη μὲν ἐμεῦ, ὅτ’ Ἰωλκὸν ἵκηαι,<br>μνώεο· σεῖο δ’ ἐγὼ καὶ ἐμῶν ἀέκητι τοκήων<br>μνήσομαι. ἔλθοι δ’ ἧμιν ἀπόπροθεν ἠέ τις ὄσσα,<br>ἠέ τις ἄγγελος ὄρνις, ὅτ’ ἐκλελάθοιο ἐμεῖο·<br>ἢ αὐτήν με ταχεῖαι ὑπὲρ πόντοιο φέροιεν<br>ἐνθένδ’ εἰς Ἰαωλκὸν ἀναρπάξασαι ἄελλαι,<br>ὄφρα σ’, ἐν ὀφθαλμοῖσιν ἐλεγχείας προφέρουσα,<br>μνήσω ἐμῇ ἰότητι πεφυγμένον. αἴθε γὰρ εἴην<br>ἀπροφάτως τότε σοῖσιν ἐφέστιος ἐν μεγάροισιν.”", "st": "3.1105"}, {"sp": "N", "t": "ὧς ἄρ’ ἔφη, ἐλεεινὰ καταπροχέουσα παρειῶν<br>δάκρυα· τὴν δ’ ὅγε δῆθεν ὑποβλήδην προσέειπεν·<br>“δαιμονίη, κενεὰς μὲν ἔα πλάζεσθαι ἀέλλας,<br>ὧς δὲ καὶ ἄγγελον ὄρνιν, ἐπεὶ μεταμώνια βάζεις.<br>εἰ δέ κεν ἤθεα κεῖνα καὶ Ἑλλάδα γαῖαν ἵκηαι,<br>τιμήεσσα γυναιξὶ καὶ ἀνδράσιν αἰδοίη τε<br>ἔσσεαι· οἱ δέ σε πάγχυ θεὸν ὣς πορσανέουσιν,<br>οὕνεκα τῶν μὲν παῖδες ὑπότροποι οἴκαδ’ ἵκοντο<br>σῇ βουλῇ, τῶν δ’ αὖτε κασίγνητοί τε ἔται τε<br>καὶ θαλεροὶ κακότητος ἄδην ἐσάωθεν ἀκοῖται.<br>ἡμέτερον δὲ λέχος θαλάμοις ἔνι κουριδίοισιν<br>πορσυνέεις· οὐδ’ ἄμμε διακρινέει φιλότητος<br>ἄλλο, πάρος θάνατόν γε μεμορμένον ἀμφικαλύψαι.”", "st": "3.1118"}, {"sp": "N", "t": "ὧς φάτο· τῇ δ’ ἔντοσθε κατείβετο θυμὸς ἀκουῇ,<br>ἔμπης δ’ ἔργ’ ἀίδηλα κατερρίγησεν ἰδέσθαι.<br>σχετλίη· οὐ μὲν δηρὸν ἀπαρνήσεσθαι ἔμελλεν<br>Ἑλλάδα ναιετάειν. ὧς γὰρ τόδε μήδετο Ἥρη,<br>ὄφρα κακὸν Πελίῃ ἱερὴν ἐς Ἰωλκὸν ἵκοιτο<br>Αἰαίη Μήδεια, λιποῦσ’ ἄπο πατρίδα γαῖαν.", "st": "3.1131"}, {"sp": "N", "t": "ἤδη δ’ ἀμφίπολοι μὲν ὀπιπεύουσαι ἄπωθεν<br>σιγῇ ἀνιάζεσκον· ἐδεύετο δ’ ἤματος ὥρη<br>ἂψ οἶκόνδε νέεσθαι ἑὴν μετὰ μητέρα κούρην.<br>ἡ δ’ οὔπω κομιδῆς μιμνήσκετο, τέρπετο γάρ οἱ<br>θυμὸς ὁμῶς μορφῇ τε καὶ αἱμυλίοισι λόγοισιν,<br>εἰ μὴ ἄρ’ Αἰσονίδης πεφυλαγμένος ὀψέ περ ηὔδα·<br>“ὥρη ἀποβλώσκειν, μὴ πρὶν φάος ἠελίοιο<br>δύῃ ὑποφθάμενον, καί τις τὰ ἕκαστα νοήσῃ<br>ὀθνείων· αὖτις δ’ ἀβολήσομεν ἐνθάδ’ ἰόντες.”", "st": "3.1137"}, {"sp": "N", "t": "ὧς τώγ’ ἀλλήλων ἀγανοῖς ἐπὶ τόσσον ἔπεσσιν<br>πείρηθεν· μετὰ δ’ αὖτε διέτμαγεν. ἤτοι Ἰήσων<br>εἰς ἑτάρους καὶ νῆα κεχαρμένος ὦρτο νέεσθαι·<br>ἡ δὲ μετ’ ἀμφιπόλους· αἱ δὲ σχεδὸν ἀντεβόλησαν<br>πᾶσαι ὁμοῦ· τὰς δ’ οὔτι περιπλομένας ἐνόησεν.<br>ψυχὴ γὰρ νεφέεσσι μεταχρονίη πεπότητο.<br>αὐτομάτοις δὲ πόδεσσι θοῆς ἐπεβήσατ’ ἀπήνης,<br>καί ῥ’ ἑτέρῃ μὲν χειρὶ λάβ’ ἡνία, τῇ δ’ ἄρ’ ἱμάσθλην<br>δαιδαλέην, οὐρῆας ἐλαυνέμεν· οἱ δὲ πόλινδε<br>θῦνον ἐπειγόμενοι ποτὶ δώματα. τὴν δ’ ἄρ’ ἰοῦσαν<br>Χαλκιόπη περὶ παισὶν ἀκηχεμένη ἐρέεινεν·<br>ἡ δὲ παλιντροπίῃσιν ἀμήχανος οὔτε τι μύθων<br>ἔκλυεν, οὔτ’ αὐδῆσαι ἀνειρομένῃ λελίητο.<br>ἷζε δ’ ἐπὶ χθαμαλῷ σφέλαϊ κλιντῆρος ἔνερθεν<br>λέχρις ἐρεισαμένη λαιῇ ἐπὶ χειρὶ παρειήν·<br>ὑγρὰ δ’ ἐνὶ βλεφάροις ἔχεν ὄμματα, πορφύρουσα<br>οἷον ἑῇ κακὸν ἔργον ἐπιξυνώσατο βουλῇ.", "st": "3.1146"}, {"sp": "N", "t": "Αἰσονίδης δ’ ὅτε δὴ ἑτάροις ἐξαῦτις ἔμικτο<br>ἐν χώρῃ, ὅθι τούσγε καταπρολιπὼν ἐλιάσθη,<br>ὦρτ’ ἰέναι σὺν τοῖσι, πιφαυσκόμενος τὰ ἕκαστα,<br>ἡρώων ἐς ὅμιλον· ὁμοῦ δ’ ἐπὶ νῆα πέλασσαν.<br>οἱ δέ μιν ἀμφαγάπαζον, ὅπως ἴδον, ἔκ τ’ ἐρέοντο.<br>αὐτὰρ ὁ τοῖς πάντεσσι μετέννεπε δήνεα κούρης,<br>δεῖξέ τε φάρμακον αἰνόν· ὁ δ’ οἰόθεν οἶος ἑταίρων<br>Ἴδας ἧστ’ ἀπάνευθε δακὼν χόλον· οἱ δὲ δὴ ἄλλοι<br>γηθόσυνοι τῆμος μέν, ἐπεὶ κνέφας ἔργαθε νυκτός,<br>εὔκηλοι ἐμέλοντο περὶ σφίσιν. αὐτὰρ ἅμ’ ἠοῖ<br>πέμπον ἐς Αἰήτην ἰέναι σπόρον αἰτήσοντας<br>ἄνδρε δύω, πρὸ μὲν αὐτὸν ἀρηίφιλον Τελαμῶνα,<br>σὺν δὲ καὶ Αἰθαλίδην, υἷα κλυτὸν Ἑρμείαο.<br>βὰν δ’ ἴμεν, οὐδ’ ἁλίωσαν ὁδόν· πόρε δέ σφιν ἰοῦσιν<br>κρείων Αἰήτης χαλεποὺς ἐς ἄεθλον ὀδόντας<br>Ἀονίοιο δράκοντος, ὃν Ὠγυγίῃ ἐνὶ Θήβῃ<br>Κάδμος, ὅτ’ Εὐρώπην διζήμενος εἰσαφίκανεν,<br>πέφνεν Ἀρητιάδι κρήνῃ ἐπίουρον ἐόντα·<br>ἔνθα καὶ ἐννάσθη πομπῇ βοός, ἥν οἱ Ἀπόλλων<br>ὤπασε μαντοσύνῃσι προηγήτειραν ὁδοῖο.<br>τοὺς δὲ θεὰ Τριτωνὶς ὑπὲκ γενύων ἐλάσασα<br>Αἰήτῃ πόρε δῶρον ὁμῶς αὐτῷ τε φονῆι.<br>καί ῥ’ ὁ μὲν Ἀονίοισιν ἐνισπείρας πεδίοισιν<br>Κάδμος Ἀγηνορίδης γαιηγενῆ εἵσατο λαόν,<br>Ἄρεος ἀμώοντος ὅσοι ὑπὸ δουρὶ λίποντο·<br>τοὺς δὲ τότ’ Αἰήτης ἔπορεν μετὰ νῆα φέρεσθαι<br>προφρονέως, ἐπεὶ οὔ μιν ὀίσσατο πείρατ’ ἀέθλου<br>ἐξανύσειν, εἰ καί περ ἐπὶ ζυγὰ βουσὶ βάλοιτο.", "st": "3.1163"}, {"sp": "N", "t": "Ἠέλιος μὲν ἄπωθεν ἐρεμνὴν δύετο γαῖαν<br>ἑσπέριος, νεάτας ὑπὲρ ἄκριας Αἰθιοπήων·<br>Νὺξ δ’ ἵπποισιν ἔβαλλεν ἔπι ζυγά· τοὶ δὲ χαμεύνας<br>ἔντυον ἥρωες παρὰ πείσμασιν. αὐτὰρ Ἰήσων<br>αὐτίκ’ ἐπεί ῥ’ Ἑλίκης εὐφεγγέος ἀστέρες Ἄρκτου<br>ἔκλιθεν, οὐρανόθεν δὲ πανεύκηλος γένετ’ αἰθήρ,<br>βῆ ῥ’ ἐς ἐρημαίην, κλωπήιος ἠύτε τις φώρ,<br>σὺν πᾶσιν χρήεσσι· πρὸ γάρ τ’ ἀλέγυνεν ἕκαστα<br>ἠμάτιος· θῆλυν μὲν ὄιν, γάλα τ’ ἔκτοθι ποίμνης<br>Ἄργος ἰὼν ἤνεικε· τὰ δ’ ἐξ αὐτῆς ἕλε νηός.<br>ἀλλ’ ὅτε δὴ ἴδε χῶρον, ὅτις πάτου ἔκτοθεν ἦεν<br>ἀνθρώπων, καθαρῇσιν ὑπεύδιος εἱαμενῇσιν,<br>ἔνθ’ ἤτοι πάμπρωτα λοέσσατο μὲν ποταμοῖο<br>εὐαγέως θείοιο τέρεν δέμας· ἀμφὶ δὲ φᾶρος<br>ἕσσατο κυάνεον, τό ῥά οἱ πάρος ἐγγυάλιξεν<br>Λημνιὰς Ὑψιπύλη, ἀδινῆς μνημήιον εὐνῆς.<br>πήχυιον δ’ ἄρ’ ἔπειτα πέδῳ ἔνι βόθρον ὀρύξας<br>νήησε σχίζας, ἐπὶ δ’ ἀρνειοῦ τάμε λαιμόν,<br>αὐτόν τ’ εὖ καθύπερθε τανύσσατο· δαῖε δὲ φιτροὺς<br>πῦρ ὑπένερθεν ἱείς, ἐπὶ δὲ μιγάδας χέε λοιβάς,<br>Βριμὼ κικλήσκων Ἑκάτην ἐπαρωγὸν ἀέθλων.<br>καί ῥ’ ὁ μὲν ἀγκαλέσας πάλιν ἔστιχεν· ἡ δ’ ἀίουσα<br>κευθμῶν ἐξ ὑπάτων δεινὴ θεὸς ἀντεβόλησεν<br>ἱροῖς Αἰσονίδαο· πέριξ δέ μιν ἐστεφάνωντο<br>σμερδαλέοι δρυΐνοισι μετὰ πτόρθοισι δράκοντες.<br>στράπτε δ’ ἀπειρέσιον δαΐδων σέλας· ἀμφὶ δὲ τήνγε<br>ὀξείῃ ὑλακῇ χθόνιοι κύνες ἐφθέγγοντο.<br>πίσεα δ’ ἔτρεμε πάντα κατὰ στίβον· αἱ δ’ ὀλόλυξαν<br>νύμφαι ἑλειονόμοι ποταμηίδες, αἳ περὶ κείνην<br>Φάσιδος εἱαμενὴν Ἀμαραντίου εἱλίσσονται.<br>Αἰσονίδην δ’ ἤτοι μὲν ἕλεν δέος, ἀλλά μιν οὐδ’ ὧς<br>ἐντροπαλιζόμενον πόδες ἔκφερον, ὄφρ’ ἑτάροισιν<br>μίκτο κιών· ἤδη δὲ φόως νιφόεντος ὕπερθεν<br>Καυκάσου ἠριγενὴς Ἠὼς βάλεν ἀντέλλουσα.", "st": "3.1191"}, {"sp": "N", "t": "καὶ τότ’ ἄρ’ Αἰήτης περὶ μὲν στήθεσσιν ἕεστο<br>θώρηκα στάδιον, τόν οἱ πόρεν ἐξεναρίξας<br>σφωιτέραις Φλεγραῖον Ἄρης ὑπὸ χερσὶ Μίμαντα·<br>χρυσείην δ’ ἐπὶ κρατὶ κόρυν θέτο τετραφάληρον,<br>λαμπομένην οἷόν τε περίτροχον ἔπλετο φέγγος<br>ἠελίου, ὅτε πρῶτον ἀνέρχεται Ὠκεανοῖο.<br>ἂν δὲ πολύρρινον νώμα σάκος, ἂν δὲ καὶ ἔγχος<br>δεινόν, ἀμαιμάκετον· τὸ μὲν οὔ κέ τις ἄλλος ὑπέστη<br>ἀνδρῶν ἡρώων, ὅτε κάλλιπον Ἡρακλῆα<br>τῆλε παρέξ, ὅ κεν οἶος ἐναντίβιον πολέμιξεν.<br>τῷ δὲ καὶ ὠκυπόδων ἵππων εὐπηγέα δίφρον<br>ἔσχε πέλας Φαέθων ἐπιβήμεναι· ἂν δὲ καὶ αὐτὸς<br>βήσατο, ῥυτῆρας δὲ χεροῖν ἔχεν. ἐκ δὲ πόληος<br>ἤλασεν εὐρεῖαν κατ’ ἀμαξιτόν, ὥς κεν ἀέθλῳ<br>παρσταίη· σὺν δέ σφιν ἀπείριτος ἔσσυτο λαός.<br>οἷος δ’ Ἴσθμιον εἶσι Ποσειδάων ἐς ἀγῶνα<br>ἅρμασιν ἐμβεβαώς, ἢ Ταίναρον, ἢ ὅγε Λέρνης<br>ὕδωρ, ἠὲ κατ’ ἄλσος Ὑαντίου Ὀγχηστοῖο,<br>καί τε Καλαύρειαν μετὰ δῆθ’ ἅμα νίσσεται ἵπποις,<br>Πέτρην θ’ Αἱμονίην, ἢ δενδρήεντα Γεραιστόν·<br>τοῖος ἄρ’ Αἰήτης Κόλχων ἀγὸς ἦεν ἰδέσθαι.", "st": "3.1225"}, {"sp": "N", "t": "τόφρα δὲ Μηδείης ὑποθημοσύνῃσιν Ἰήσων<br>φάρμακα μυδήνας ἠμὲν σάκος ἀμφεπάλυνεν<br>ἠδὲ δόρυ βριαρόν, περὶ δὲ ξίφος· ἀμφὶ δ’ ἑταῖροι<br>πείρησαν τευχέων βεβιημένοι, οὐδ’ ἐδύναντο<br>κεῖνο δόρυ γνάμψαι τυτθόν γέ περ, ἀλλὰ μάλ’ αὔτως<br>ἀαγὲς κρατερῇσιν ἐνεσκλήκει παλάμῃσιν.<br>αὐτὰρ ὁ τοῖς ἄμοτον κοτέων Ἀφαρήιος Ἴδας<br>κόψε παρ’ οὐρίαχον μεγάλῳ ξίφει· ἆλτο δ’ ἀκωκὴ<br>ῥαιστὴρ ἄκμονος ὥστε, παλιντυπές· οἱ δ’ ὁμάδησαν<br>γηθόσυνοι ἥρωες ἐπ’ ἐλπωρῇσιν ἀέθλου.<br>καὶ δ’ αὐτὸς μετέπειτα παλύνετο· δῦ δέ μιν ἀλκὴ<br>σμερδαλέη ἄφατός τε καὶ ἄτρομος· αἱ δ’ ἑκάτερθεν<br>χεῖρες ἐπερρώσαντο περὶ σθένεϊ σφριγόωσαι.<br>ὡς δ’ ὅτ’ ἀρήιος ἵππος ἐελδόμενος πολέμοιο<br>σκαρθμῷ ἐπιχρεμέθων κρούει πέδον, αὐτὰρ ὕπερθεν<br>κυδιόων ὀρθοῖσιν ἐπ’ οὔασιν αὐχέν’ ἀείρει·<br>τοῖος ἄρ’ Αἰσονίδης ἐπαγαίετο κάρτεϊ γυίων.<br>πολλὰ δ’ ἄρ’ ἔνθα καὶ ἔνθα μετάρσιον ἴχνος ἔπαλλεν,<br>ἀσπίδα χαλκείην μελίην τ’ ἐν χερσὶ τινάσσων.<br>φαίης κε ζοφεροῖο κατ’ αἰθέρος ἀίσσουσαν<br>χειμερίην στεροπὴν θαμινὸν μεταπαιφάσσεσθαι<br>ἐκ νεφέων, ὅτ’ ἔπειτα μελάντατον ὄμβρον ἄγωνται.<br>καὶ τότ’ ἔπειτ’ οὐ δηρὸν ἔτι σχήσεσθαι ἀέθλων<br>μέλλον· ἀτὰρ κληῖσιν ἐπισχερὼ ἱδρυνθέντες<br>ῥίμφα μάλ’ ἐς πεδίον τὸ Ἀρήιον ἠπείγοντο.<br>τόσσον δὲ προτέρω πέλεν ἄστεος ἀντιπέρηθεν,<br>ὅσσον τ’ ἐκ βαλβῖδος ἐπήβολος ἅρματι νύσσα<br>γίγνεται, ὁππότ’ ἄεθλα καταφθιμένοιο ἄνακτος<br>κηδεμόνες πεζοῖσι καὶ ἱππήεσσι τίθενται.<br>τέτμον δ’ Αἰήτην τε καὶ ἄλλων ἔθνεα Κόλχων,<br>τοὺς μὲν Καυκασίοισιν ἐφεσταότας σκοπέλοισιν,<br>τὸν δ’ αὐτοῦ παρὰ χεῖλος ἑλισσόμενον ποταμοῖο.", "st": "3.1246"}, {"sp": "N", "t": "Αἰσονίδης δ’, ὅτε δὴ πρυμνήσια δῆσαν ἑταῖροι,<br>δή ῥα τότε ξὺν δουρὶ καὶ ἀσπίδι βαῖν’ ἐς ἄεθλον,<br>νηὸς ἀποπροθορών· ἄμυδις δ’ ἕλε παμφανόωσαν<br>χαλκείην πήληκα θοῶν ἔμπλειον ὀδόντων<br>καὶ ξίφος ἀμφ’ ὤμοις, γυμνὸς δέμας, ἄλλα μὲν Ἄρει<br>εἴκελος, ἄλλα δέ που χρυσαόρῳ Ἀπόλλωνι.<br>παπτήνας δ’ ἀνὰ νειὸν ἴδε ζυγὰ χάλκεα ταύρων<br>αὐτόγυόν τ’ ἐπὶ τοῖς στιβαροῦ ἀδάμαντος ἄροτρον.<br>χρίμψε δ’ ἔπειτα κιών, παρὰ δ’ ὄβριμον ἔγχος ἔπηξεν<br>ὀρθὸν ἐπ’ οὐριάχῳ, κυνέην δ’ ἀποκάτθετ’ ἐρείσας.<br>βῆ δ’ αὐτῇ προτέρωσε σὺν ἀσπίδι νήριτα ταύρων<br>ἴχνια μαστεύων· οἱ δ’ ἔκποθεν ἀφράστοιο<br>κευθμῶνος χθονίου, ἵνα τέ σφισιν ἔσκε βόαυλα<br>καρτερὰ λιγνυόεντι πέριξ εἰλυμένα καπνῷ,<br>ἄμφω ὁμοῦ προγένοντο πυρὸς σέλας ἀμπνείοντες.<br>ἔδδεισαν δ’ ἥρωες, ὅπως ἴδον. αὐτὰρ ὁ τούσγε,<br>εὖ διαβάς, ἐπιόντας, ἅ τε σπιλὰς εἰν ἁλὶ πέτρη<br>μίμνει ἀπειρεσίῃσι δονεύμενα κύματ’ ἀέλλαις.<br>πρόσθε δέ οἱ σάκος ἔσχεν ἐναντίον· οἱ δέ μιν ἄμφω<br>μυκηθμῷ κρατεροῖσιν ἐνέπληξαν κεράεσσιν·<br>οὐδ’ ἄρα μιν τυτθόν περ ἀνώχλισαν ἀντιόωντες.<br>ὡς δ’ ὅτ’ ἐνὶ τρητοῖσιν ἐύρρινοι χοάνοισιν<br>φῦσαι χαλκήων ὁτὲ μέν τ’ ἀναμαρμαίρουσιν,<br>πῦρ ὀλοὸν πιμπρᾶσαι, ὅτ’ αὖ λήγουσιν ἀυτμῆς,<br>δεινὸς δ’ ἐξ αὐτοῦ πέλεται βρόμος, ὁππότ’ ἀίξῃ<br>νειόθεν· ὧς ἄρα τώγε θοὴν φλόγα φυσιόωντες<br>ἐκ στομάτων ὁμάδευν, τὸν δ’ ἄμφεπε δήιον αἶθος<br>βάλλον ἅ τε στεροπή· κούρης δέ ἑ φάρμακ’ ἔρυτο.<br>καί ῥ’ ὅγε δεξιτεροῖο βοὸς κέρας ἄκρον ἐρύσσας<br>εἷλκεν ἐπικρατέως παντὶ σθένει, ὄφρα πελάσσῃ<br>ζεύγλῃ χαλκείῃ, τὸν δ’ ἐν χθονὶ κάββαλεν ὀκλάξ,<br>ῥίμφα ποδὶ κρούσας πόδα χάλκεον. ὧς δὲ καὶ ἄλλον<br>σφῆλεν γνὺξ ἐπιόντα, μιῇ βεβολημένον ὁρμῇ.<br>εὐρὺ δ’ ἀποπροβαλὼν χαμάδις σάκος, ἔνθα καὶ ἔνθα<br>τῇ καὶ τῇ βεβαὼς ἄμφω ἔχε πεπτηῶτας<br>γούνασιν ἐν προτέροισι, διὰ φλογὸς εἶθαρ ἐλυσθείς.<br>θαύμασε δ’ Αἰήτης σθένος ἀνέρος. οἱ δ’ ἄρα τείως<br>Τυνδαρίδαι—δὴ γάρ σφι πάλαι προπεφραδμένον ἦεν—<br>ἀγχίμολον ζυγά οἱ πεδόθεν δόσαν ἀμφιβαλέσθαι.<br>αὐτὰρ ὁ εὖ ἐνέδησε λόφους· μεσσηγὺ δ’ ἀείρας<br>χάλκεον ἱστοβοῆα, θοῇ συνάρασσε κορώνῃ<br>ζεύγληθεν. καὶ τὼ μὲν ὑπὲκ πυρὸς ἂψ ἐπὶ νῆα<br>χαζέσθην. ὁ δ’ ἄρ’ αὖτις ἑλὼν σάκος ἔνθετο νώτῳ<br>ἐξόπιθεν, καὶ γέντο θοῶν ἔμπλειον ὀδόντων<br>πήληκα βριαρὴν δόρυ τ’ ἄσχετον, ᾧ ῥ’ ὑπὸ μέσσας<br>ἐργατίνης ὥς τίς τε Πελασγίδι νύσσεν ἀκαίνῃ<br>οὐτάζων λαγόνας· μάλα δ’ ἔμπεδον εὖ ἀραρυῖαν<br>τυκτὴν ἐξ ἀδάμαντος ἐπιθύνεσκεν ἐχέτλην.", "st": "3.1278"}, {"sp": "N", "t": "οἱ δ’ εἵως μὲν δὴ περιώσια θυμαίνεσκον,<br>λάβρον ἐπιπνείοντε πυρὸς σέλας· ὦρτο δ’ ἀυτμὴ<br>ἠύτε βυκτάων ἀνέμων βρόμος, οὕς τε μάλιστα<br>δειδιότες μέγα λαῖφος ἁλίπλοοι ἐστείλαντο.<br>δηρὸν δ’ οὐ μετέπειτα κελευόμενοι ὑπὸ δουρὶ<br>ἤισαν· ὀκριόεσσα δ’ ἐρείκετο νειὸς ὀπίσσω,<br>σχιζομένη ταύρων τε βίῃ κρατερῷ τ’ ἀροτῆρι.<br>δεινὸν δ’ ἐσμαράγευν ἄμυδις κατὰ ὦλκας ἀρότρου<br>βώλακες ἀγνύμεναι ἀνδραχθέες· εἵπετο δ’ αὐτὸς<br>λαῖον ἐπὶ στιβαρῷ πιέσας ποδί· τῆλε δ’ ἑοῖο<br>βάλλεν ἀρηρομένην αἰεὶ κατὰ βῶλον ὀδόντας<br>ἐντροπαλιζόμενος, μή οἱ πάρος ἀντιάσειεν<br>γηγενέων ἀνδρῶν ὀλοὸς στάχυς· οἱ δ’ ἄρ’ ἐπιπρὸ<br>χαλκείῃς χηλῇσιν ἐρειδόμενοι πονέοντο.", "st": "3.1326"}, {"sp": "N", "t": "ἦμος δὲ τρίτατον λάχος ἤματος ἀνομένοιο<br>λείπεται ἐξ ἠοῦς, καλέουσι δὲ κεκμηῶτες<br>ἐργατίναι γλυκερόν σφιν ἄφαρ βουλυτὸν ἱκέσθαι,<br>τῆμος ἀρήροτο νειὸς ὑπ’ ἀκαμάτῳ ἀροτῆρι,<br>τετράγυός περ ἐοῦσα· βοῶν τ’ ἀπελύετ’ ἄροτρα.<br>καὶ τοὺς μὲν πεδίονδε διεπτοίησε φέβεσθαι·<br>αὐτὰρ ὁ ἂψ ἐπὶ νῆα πάλιν κίεν, ὄφρ’ ἔτι κεινὰς<br>γηγενέων ἀνδρῶν ἴδεν αὔλακας. ἀμφὶ δ’ ἑταῖροι<br>θάρσυνον μύθοισιν. ὁ δ’ ἐκ ποταμοῖο ῥοάων<br>αὐτῇ ἀφυσσάμενος κυνέῃ σβέσεν ὕδατι δίψαν·<br>γνάμψε δὲ γούνατ’ ἐλαφρά, μέγαν δ’ ἐμπλήσατο θυμὸν<br>ἀλκῆς, μαιμώων συῒ εἴκελος, ὅς ῥά τ’ ὀδόντας<br>θήγει θηρευτῇσιν ἐπ’ ἀνδράσιν, ἀμφὶ δὲ πολλὸς<br>ἀφρὸς ἀπὸ στόματος χαμάδις ῥεῖ χωομένοιο.<br>οἱ δ’ ἤδη κατὰ πᾶσαν ἀνασταχύεσκον ἄρουραν<br>γηγενέες· φρίξεν δὲ περὶ στιβαροῖς σακέεσσιν<br>δούρασί τ’ ἀμφιγύοις κορύθεσσί τε λαμπομένῃσιν<br>Ἄρηος τέμενος φθισιμβρότου· ἵκετο δ’ αἴγλη<br>νειόθεν Οὔλυμπόνδε δι’ ἠέρος ἀστράπτουσα.<br>ὡς δ’ ὁπότ’ ἐς γαῖαν πολέος νιφετοῖο πεσόντος<br>ἂψ ἀπὸ χειμερίας νεφέλας ἐκέδασσαν ἄελλαι<br>λυγαίῃ ὑπὸ νυκτί, τὰ δ’ ἀθρόα πάντ’ ἐφαάνθη<br>τείρεα λαμπετόωντα διὰ κνέφας· ὧς ἄρα τοίγε<br>λάμπον ἀναλδήσκοντες ὑπὲρ χθονός. αὐτὰρ Ἰήσων<br>μνήσατο Μηδείης πολυκερδέος ἐννεσιάων,<br>λάζετο δ’ ἐκ πεδίοιο μέγαν περιηγέα πέτρον,<br>δεινὸν Ἐνυαλίου σόλον Ἄρεος· οὔ κέ μιν ἄνδρες<br>αἰζηοὶ πίσυρες γαίης ἄπο τυτθὸν ἄειραν.<br>τόν ῥ’ ἀνὰ χεῖρα λαβὼν μάλα τηλόθεν ἔμβαλε μέσσοις<br>ἀίξας· αὐτὸς δ’ ὑφ’ ἑὸν σάκος ἕζετο λάθρῃ<br>θαρσαλέως. Κόλχοι δὲ μέγ’ ἴαχον, ὡς ὅτε πόντος<br>ἴαχεν ὀξείῃσιν ἐπιβρομέων σπιλάδεσσιν·<br>τὸν δ’ ἕλεν ἀμφασίη ῥιπῇ στιβαροῖο σόλοιο<br>Αἰήτην. οἱ δ’ ὥστε θοοὶ κύνες ἀμφιθορόντες<br>ἀλλήλους βρυχηδὸν ἐδήιον· οἱ δ’ ἐπὶ γαῖαν<br>μητέρα πῖπτον ἑοῖς ὑπὸ δούρασιν, ἠύτε πεῦκαι<br>ἢ δρύες, ἅς τ’ ἀνέμοιο κατάικες δονέουσιν.<br>οἷος δ’ οὐρανόθεν πυρόεις ἀναπάλλεται ἀστὴρ<br>ὁλκὸν ὑπαυγάζων, τέρας ἀνδράσιν, οἵ μιν ἴδωντοι<br>μαρμαρυγῇ σκοτίοιο δι’ ἠέρος ἀίξαντα·<br>τοῖος ἄρ’ Αἴσονος υἱὸς ἐπέσσυτο γηγενέεσσιν,<br>γυμνὸν δ’ ἐκ κολεοῖο φέρε ξίφος, οὖτα δὲ μίγδην<br>ἀμώων, πολέας μὲν ἔτ’ ἐς νηδὺν λαγόνας τε<br>ἡμίσεας ἀνέχοντας ἐς ἠέρα· τοὺς δὲ καὶ ἄχρις<br>ὤμων τελλομένους· τοὺς δὲ νέον ἑστηῶτας,<br>τοὺς δ’ ἤδη καὶ ποσσὶν ἐπειγομένους ἐς ἄρηα.<br>ὡς δ’ ὁπότ’ ἀμφ’ οὔροισιν ἐγειρομένου πολέμοιο,<br>δείσας γειομόρος, μή οἱ προτάμωνται ἀρούρας,<br>ἅρπην εὐκαμπῆ νεοθηγέα χερσὶ μεμαρπὼς<br>ὠμὸν ἐπισπεύδων κείρει στάχυν, οὐδὲ βολῇσιν<br>μίμνει ἐς ὡραίην τερσήμεναι ἠελίοιο·<br>ὧς τότε γηγενέων κεῖρε στάχυν· αἵματι δ’ ὁλκοὶ<br>ἠύτε κρηναῖαι ἀμάραι πλήθοντο ῥοῇσιν.<br>πῖπτον δ’, οἱ μὲν ὀδὰξ τετρηχότα βῶλον ὀδοῦσιν<br>λαζόμενοι πρηνεῖς, οἱ δ’ ἔμπαλιν, οἱ δ’ ἐπ’ ἀγοστῷ<br>καὶ πλευροῖς, κήτεσσι δομὴν ἀτάλαντοι ἰδέσθαι.<br>πολλοὶ δ’ οὐτάμενοι, πρὶν ὑπὸ χθονὸς ἴχνος ἀεῖραι,<br>ὅσσον ἄνω προύτυψαν ἐς ἠέρα, τόσσον ἔραζε<br>βριθόμενοι πλαδαροῖσι καρήασιν ἠρήρειντο.<br>ἔρνεά που τοίως, Διὸς ἄσπετον ὀμβρήσαντος,<br>φυταλιῇ νεόθρεπτα κατημύουσιν ἔραζε<br>κλασθέντα ῥίζηθεν, ἀλωήων πόνος ἀνδρῶν·<br>τὸν δὲ κατηφείη τε καὶ οὐλοὸν ἄλγος ἱκάνει<br>κλήρου σημαντῆρα φυτοτρόφον· ὧς τότ’ ἄνακτος<br>Αἰήταο βαρεῖαι ὑπὸ φρένας ἦλθον ἀνῖαι.<br>ἤιε δ’ ἐς πτολίεθρον ὑπότροπος ἄμμιγα Κόλχοις,<br>πορφύρων, ᾗ κέ σφι θοώτερον ἀντιόῳτο.<br>ἦμαρ ἔδυ, καὶ τῷ τετελεσμένος ἦεν ἄεθλος.", "st": "3.1340"}, {"sp": "HDR", "t": "Βιβλίον Δʹ", "st": "4"}, {"sp": "N", "t": "αὐτὴ νῦν κάματόν γε, θεά, καὶ δήνεα κούρης<br>Κολχίδος ἔννεπε, Μοῦσα, Διὸς τέκος. ἦ γὰρ ἔμοιγε<br>ἀμφασίῃ νόος ἔνδον ἑλίσσεται ὁρμαίνοντι,<br>ἢ ἔμεν ἄτης πῆμα δυσίμερον, ἦ τόγ’ ἐνίσπω<br>φύζαν ἀεικελίην, ᾗ κάλλιπεν ἔθνεα Κόλχων.", "st": "4.1"}, {"sp": "N", "t": "ἤτοι ὁ μὲν δήμοιο μετ’ ἀνδράσιν, ὅσσοι ἄριστοι,<br>παννύχιος δόλον αἰπὺν ἐπὶ σφίσι μητιάασκεν<br>οἷσιν ἐνὶ μεγάροις, στυγερῷ ἐπὶ θυμὸν ἀέθλῳ<br>Αἰήτης ἄμοτον κεχολωμένος· οὐδ’ ὅγε πάμπαν<br>θυγατέρων τάδε νόσφιν ἑῶν τελέεσθαι ἐώλπει.", "st": "4.6"}, {"sp": "N", "t": "τῇ δ’ ἀλεγεινότατον κραδίῃ φόβον ἔμβαλεν Ἥρη·<br>τρέσσεν δ’, ἠύτε τις κούφη κεμάς, ἥν τε βαθείης<br>τάρφεσιν ἐν ξυλόχοιο κυνῶν ἐφόβησεν ὁμοκλή.<br>αὐτίκα γὰρ νημερτὲς ὀίσσατο, μή μιν ἀρωγὴν<br>ληθέμεν, αἶψα δὲ πᾶσαν ἀναπλήσειν κακότητα.<br>τάρβει δ’ ἀμφιπόλους ἐπιίστορας· ἐν δέ οἱ ὄσσε<br>πλῆτο πυρός, δεινὸν δὲ περιβρομέεσκον ἀκουαί.<br>πυκνὰ δὲ λευκανίης ἐπεμάσσατο, πυκνὰ δὲ κουρὶξ<br>ἑλκομένη πλοκάμους γοερῇ βρυχήσατ’ ἀνίῃ.<br>καί νύ κεν αὐτοῦ τῆμος ὑπὲρ μόρον ὤλετο κούρη,<br>φάρμακα πασσαμένη, Ἥρης δ’ ἁλίωσε μενοινάς,<br>εἰ μή μιν Φρίξοιο θεὰ σὺν παισὶ φέβεσθαι<br>ὦρσεν ἀτυζομένην· πτερόεις δέ οἱ ἐν φρεσὶ θυμὸς<br>ἰάνθη· μετὰ δ’ ἥγε παλίσσυτος ἀθρόα κόλπων<br>φάρμακα πάντ’ ἄμυδις κατεχεύατο φωριαμοῖο.<br>κύσσε δ’ ἑόν τε λέχος καὶ δικλίδας ἀμφοτέρωθεν<br>σταθμούς, καὶ τοίχων ἐπαφήσατο, χερσί τε μακρὸν<br>ῥηξαμένη πλόκαμον, θαλάμῳ μνημήια μητρὶ<br>κάλλιπε παρθενίης, ἀδινῇ δ’ ὀλοφύρατο φωνῇ·", "st": "4.11"}, {"sp": "N", "t": "“τόνδε τοι ἀντ’ ἐμέθεν ταναὸν πλόκον εἶμι λιποῦσα,<br>μῆτερ ἐμή· χαίροις δὲ καὶ ἄνδιχα πολλὸν ἰούσῃ·<br>χαίροις Χαλκιόπη, καὶ πᾶς δόμος. αἴθε σε πόντος,<br>ξεῖνε, διέρραισεν, πρὶν Κολχίδα γαῖαν ἱκέσθαι.”", "st": "4.30"}, {"sp": "N", "t": "ὧς ἄρ’ ἔφη· βλεφάρων δὲ κατ’ ἀθρόα δάκρυα χεῦεν.<br>οἵη δ’ ἀφνειοῖο διειλυσθεῖσα δόμοιο<br>ληιάς, ἥν τε νέον πάτρης ἀπενόσφισεν αἶσα,<br>οὐδέ νύ πω μογεροῖο πεπείρηται καμάτοιο,<br>ἀλλ’ ἔτ’ ἀηθέσσουσα δύης καὶ δούλια ἔργα<br>εἶσιν ἀτυζομένη χαλεπὰς ὑπὸ χεῖρας ἀνάσσης·<br>τοίη ἄρ’ ἱμερόεσσα δόμων ἐξέσσυτο κούρη.<br>τῇ δὲ καὶ αὐτόματοι θυρέων ὑπόειξαν ὀχῆες,<br>ὠκείαις ἄψορροι ἀναθρώσκοντες ἀοιδαῖς.<br>γυμνοῖσιν δὲ πόδεσσιν ἀνὰ στεινὰς θέεν οἴμους,<br>λαιῇ μὲν χερὶ πέπλον ἐπ’ ὀφρύσιν ἀμφὶ μέτωπα<br>στειλαμένη καὶ καλὰ παρήια, δεξιτερῇ δὲ<br>ἄκρην ὑψόθι πέζαν ἀερτάζουσα χιτῶνος.<br>καρπαλίμως δ’ ἀίδηλον ἀνὰ στίβον ἔκτοθι πύργων<br>ἄστεος εὐρυχόροιο φόβῳ ἵκετ’· οὐδέ τις ἔγνω<br>τήνγε φυλακτήρων, λάθε δέ σφεας ὁρμηθεῖσα.<br>ἔνθεν ἴμεν νηόνδε μάλ’ ἐφράσατ’· οὐ γὰρ ἄιδρις<br>ἦεν ὁδῶν, θαμὰ καὶ πρὶν ἀλωμένη ἀμφί τε νεκρούς,<br>ἀμφί τε δυσπαλέας ῥίζας χθονός, οἷα γυναῖκες<br>φαρμακίδες· τρομερῷ δ’ ὑπὸ δείματι πάλλετο θυμός.<br>τὴν δὲ νέον Τιτηνὶς ἀνερχομένη περάτηθεν<br>φοιταλέην ἐσιδοῦσα θεὰ ἐπεχήρατο Μήνη<br>ἁρπαλέως, καὶ τοῖα μετὰ φρεσὶν ᾗσιν ἔειπεν·", "st": "4.34"}, {"sp": "N", "t": "“οὐκ ἄρ’ ἐγὼ μούνη μετὰ Λάτμιον ἄντρον ἀλύσκω,<br>οὐδ’ οἴη καλῷ περιδαίομαι Ἐνδυμίωνι·<br>ἦ θαμὰ δὴ καὶ σεῖο κίον δολίῃσιν ἀοιδαῖς,<br>μνησαμένη φιλότητος, ἵνα σκοτίῃ ἐνὶ νυκτὶ<br>φαρμάσσῃς εὔκηλος, ἅ τοι φίλα ἔργα τέτυκται.<br>νῦν δὲ καὶ αὐτὴ δῆθεν ὁμοίης ἔμμορες ἄτης·<br>δῶκε δ’ ἀνιηρόν τοι Ἰήσονα πῆμα γενέσθαι<br>δαίμων ἀλγινόεις. ἀλλ’ ἔρχεο, τέτλαθι δ’ ἔμπης,<br>καὶ πινυτή περ ἐοῦσα, πολύστονον ἄλγος ἀείρειν.”", "st": "4.57"}, {"sp": "N", "t": "ὦς ἄρ’ ἔφη· τὴν δ’ αἶψα πόδες φέρον ἐγκονέουσαν.<br>ἀσπασίως δ’ ὄχθῃσιν ἐπηέρθη ποταμοῖο,<br>ἀντιπέρην λεύσσουσα πυρὸς σέλας, ὅ ῥά τ’ ἀέθλου<br>παννύχιοι ἥρωες ἐυφροσύνῃσιν ἔδαιον.<br>ὀξείῃ δἤπειτα διὰ κνέφας ὄρθια φωνῇ<br>ὁπλότατον Φρίξοιο περαιόθεν ἤπυε παίδων,<br>Φρόντιν· ὁ δὲ ξὺν ἑοῖσι κασιγνήτοις ὄπα κούρης<br>αὐτῷ τ’ Αἰσονίδῃ τεκμήρατο· σῖγα δ’ ἑταῖροι<br>θάμβεον, εὖτ’ ἐνόησαν ὃ δὴ καὶ ἐτήτυμον ἦεν.<br>τρὶς μὲν ἀνήυσεν, τρὶς δ’ ὀτρύνοντος ὁμίλου<br>Φρόντις ἀμοιβήδην ἀντίαχεν· οἱ δ’ ἄρα τείως<br>ἥρωες μετὰ τήνγε θοοῖς ἐλάασκον ἐρετμοῖς.<br>οὔπω πείσματα νηὸς ἐπ’ ἠπείροιο περαίης<br>βάλλον, ὁ δὲ κραιπνοὺς χέρσῳ πόδας ἧκεν Ἰήσων<br>ὑψοῦ ἀπ’ ἰκριόφιν· μετὰ δὲ Φρόντις τε καὶ Ἄργος,<br>υἷε δύω Φρίξου, χαμάδις θόρον· ἡ δ’ ἄρα τούσγε<br>γούνων ἀμφοτέρῃσι περισχομένη προσέειπεν·", "st": "4.66"}, {"sp": "N", "t": "“ἔκ με, φίλοι, ῥύσασθε δυσάμμορον, ὧς δὲ καὶ αὐτοὺς<br>ὑμέας Αἰήταο, πρὸ γάρ τ’ ἀναφανδὰ τέτυκται<br>πάντα μάλ’, οὐδέ τι μῆχος ἱκάνεται. ἀλλ’ ἐπὶ νηὶ<br>φεύγωμεν, πρὶν τόνδε θοῶν ἐπιβήμεναι ἵππων.<br>δώσω δὲ χρύσειον ἐγὼ δέρος, εὐνήσασα<br>φρουρὸν ὄφιν· τύνη δὲ θεοὺς ἐνὶ σοῖσιν ἑταίροις,<br>ξεῖνε, τεῶν μύθων ἐπιίστορας, οὕς μοι ὑπέστης,<br>ποίησαι· μηδ’ ἔνθεν ἑκαστέρω ὁρμηθεῖσαν<br>χήτει κηδεμόνων ὀνοτὴν καὶ ἀεικέα θείης.”", "st": "4.83"}, {"sp": "N", "t": "Ἴσκεν ἀκηχεμένη· μέγα δὲ φρένες Αἰσονίδαο<br>γήθεον· αἶψα δέ μιν περὶ γούνασι πεπτηυῖαν<br>ἦκ’ ἀναειρόμενος προσπτύξατο, θάρσυνέν τε·<br>“δαιμονίη, Ζεὺς αὐτὸς Ὀλύμπιος ὅρκιος ἔστω,<br>Ἥρη τε Ζυγίη, Διὸς εὐνέτις, ἦ μὲν ἐμοῖσιν<br>κουριδίην σε δόμοισιν ἐνιστήσεσθαι ἄκοιτιν,<br>εὖτ’ ἂν ἐς Ἑλλάδα γαῖαν ἱκώμεθα νοστήσαντες.”", "st": "4.92"}, {"sp": "N", "t": "ὧς ηὔδα, καὶ χεῖρα παρασχεδὸν ἤραρε χειρὶ<br>δεξιτερήν· ἡ δέ σφιν ἐς ἱερὸν ἄλσος ἀνώγει<br>νῆα θοὴν ἐλάαν αὐτοσχεδόν, ὄφρ’ ἔτι νύκτωρ<br>κῶας ἑλόντες ἄγοιντο παρὲκ νόον Αἰήταο.<br>ἔνθ’ ἔπος ἠδὲ καὶ ἔργον ὁμοῦ πέλεν ἐσσυμένοισιν.<br>εἰς γάρ μιν βήσαντες, ἀπὸ χθονὸς αὐτίκ’ ἔωσαν<br>νῆα· πολὺς δ’ ὀρυμαγδὸς ἐπειγομένων ἐλάτῃσιν<br>ἦεν ἀριστήων· ἡ δ’ ἔμπαλιν ἀίσσουσα<br>γαίῃ χεῖρας ἔτεινεν ἀμήχανος. αὐτὰρ Ἰήσων<br>θάρσυνέν τ’ ἐπέεσσι, καὶ ἴσχανεν ἀσχαλόωσαν.", "st": "4.99"}, {"sp": "N", "t": "ἦμος δ’ ἀνέρες ὕπνον ἀπ’ ὀφθαλμῶν ἐβάλοντο<br>ἀγρόται, οἵ τε κύνεσσι πεποιθότες οὔποτε νύκτα<br>ἄγχαυρον κνώσσουσιν, ἀλευάμενοι φάος ἠοῦς,<br>μὴ πρὶν ἀμαλδύνῃ θηρῶν στίβον ἠδὲ καὶ ὀδμὴν<br>θηρείην λευκῇσιν ἐνισκίμψασα βολῇσιν·<br>τῆμος ἄρ’ Αἰσονίδης κούρη τ’ ἀπὸ νηὸς ἔβησαν<br>ποιήεντ’ ἀνὰ χῶρον, ἵνα κριοῦ καλέονται<br>εὐναί, ὅθι πρῶτον κεκμηότα γούνατ’ ἔκαμψεν,<br>νώτοισιν φορέων Μινυήιον υἷ’ Ἀθάμαντος.<br>ἐγγύθι δ’ αἰθαλόεντα πέλεν βωμοῖο θέμεθλα,<br>ὅν ῥά ποτ’ Αἰολίδης Διὶ Φυξίῳ εἵσατο Φρίξος,<br>ῥέζων κεῖνο τέρας παγχρύσεον, ὥς οἱ ἔειπεν<br>Ἑρμείας πρόφρων ξυμβλήμενος. ἔνθ’ ἄρα τούσγε<br>Ἄργου φραδμοσύνῃσιν ἀριστῆες μεθέηκαν.", "st": "4.109"}, {"sp": "N", "t": "τὼ δὲ δι’ ἀτραπιτοῖο μεθ’ ἱερὸν ἄλσος ἵκοντο,<br>φηγὸν ἀπειρεσίην διζημένω, ᾗ ἔπι κῶας<br>βέβλητο, νεφέλῃ ἐναλίγκιον, ἥ τ’ ἀνιόντος<br>ἠελίου φλογερῇσιν ἐρεύθεται ἀκτίνεσσιν.<br>αὐτὰρ ὁ ἀντικρὺ περιμήκεα τείνετο δειρὴν<br>ὀξὺς ἀύπνοισιν προϊδὼν ὄφις ὀφθαλμοῖσιν<br>νισσομένους, ῥοίζει δὲ πελώριον· ἀμφὶ δὲ μακραὶ<br>ἠιόνες ποταμοῖο καὶ ἄσπετον ἴαχεν ἄλσος.<br>ἔκλυον οἳ καὶ πολλὸν ἑκὰς Τιτηνίδος Αἴης<br>Κολχίδα γῆν ἐνέμοντο παρὰ προχοῇσι Λύκοιο,<br>ὅς τ’ ἀποκιδνάμενος ποταμοῦ κελάδοντος Ἀράξεω<br>Φάσιδι συμφέρεται ἱερὸν ῥόον· οἱ δὲ συνάμφω<br>Καυκασίην ἅλαδ’ εἰς ἓν ἐλαυνόμενοι προχέουσιν.<br>δείματι δ’ ἐξέγροντο λεχωίδες, ἀμφὶ δὲ παισὶν<br>νηπιάχοις, οἵ τέ σφιν ὑπ’ ἀγκαλίδεσσιν ἴαυον,<br>ῥοίζῳ παλλομένοις χεῖρας βάλον ἀσχαλόωσαι.<br>ὡς δ’ ὅτε τυφομένης ὕλης ὕπερ αἰθαλόεσσαι<br>καπνοῖο στροφάλιγγες ἀπείριτοι εἱλίσσονται,<br>ἄλλη δ’ αἶψ’ ἑτέρῃ ἐπιτέλλεται αἰὲν ἐπιπρὸ<br>νειόθεν εἰλίγγοισιν ἐπήορος ἐξανιοῦσα·<br>ὧς τότε κεῖνο πέλωρον ἀπειρεσίας ἐλέλιξεν<br>ῥυμβόνας ἀζαλέῃσιν ἐπηρεφέας φολίδεσσιν.<br>τοῖο δ’ ἑλισσομένοιο κατ’ ὄμματα νίσσετο κούρη,<br>Ὕπνον ἀοσσητῆρα, θεῶν ὕπατον, καλέουσα<br>ἡδείῃ ἐνοπῇ, θέλξαι τέρας· αὖε δ’ ἄνασσαν<br>νυκτιπόλον, χθονίην, εὐαντέα δοῦναι ἐφορμήν.<br>εἵπετο δ’ Αἰσονίδης πεφοβημένος, αὐτὰρ ὅγ’ ἤδη<br>οἴμῃ θελγόμενος δολιχὴν ἀνελύετ’ ἄκανθαν<br>γηγενέος σπείρης, μήκυνε δὲ μυρία κύκλα,<br>οἷον ὅτε βληχροῖσι κυλινδόμενον πελάγεσσιν<br>κῦμα μέλαν κωφόν τε καὶ ἄβρομον· ἀλλὰ καὶ ἔμπης<br>ὑψοῦ σμερδαλέην κεφαλὴν μενέαινεν ἀείρας<br>ἀμφοτέρους ὀλοῇσι περιπτύξαι γενύεσσιν.<br>ἡ δέ μιν ἀρκεύθοιο νέον τετμηότι θαλλῷ<br>βάπτουσ’ ἐκ κυκεῶνος ἀκήρατα φάρμακ’ ἀοιδαῖς<br>ῥαῖνε κατ’ ὀφθαλμῶν· περί τ’ ἀμφί τε νήριτος ὀδμὴ<br>φαρμάκου ὕπνον ἔβαλλε· γένυν δ’ αὐτῇ ἐνὶ χώρῃ<br>θῆκεν ἐρεισάμενος· τὰ δ’ ἀπείρονα πολλὸν ὀπίσσω<br>κύκλα πολυπρέμνοιο διὲξ ὕλης τετάνυστο.", "st": "4.123"}, {"sp": "N", "t": "ἔνθα δ’ ὁ μὲν χρύσειον ἀπὸ δρυὸς αἴνυτο κῶας,<br>κούρης κεκλομένης· ἡ δ’ ἔμπεδον ἑστηυῖα<br>φαρμάκῳ ἔψηχεν θηρὸς κάρη, εἰσόκε δή μιν<br>αὐτὸς ἑὴν ἐπὶ νῆα παλιντροπάασθαι Ἰήσων<br>ἤνωγεν, λεῖπεν δὲ πολύσκιον ἄλσος Ἄρηος.<br>ὡς δὲ σεληναίην διχομήνιδα παρθένος αἴγλην<br>ὑψόθεν ἐξανέχουσαν ὑπωροφίου θαλάμοιο<br>λεπταλέῳ ἑανῷ ὑποΐσχεται· ἐν δέ οἱ ἦτορ<br>χαίρει δερκομένης καλὸν σέλας· ὧς τότ’ Ἰήσων<br>γηθόσυνος μέγα κῶας ἑαῖς ἐναείρατο χερσίν·<br>καί οἱ ἐπὶ ξανθῇσι παρηίσιν ἠδὲ μετώπῳ<br>μαρμαρυγῇ ληνέων φλογὶ εἴκελον ἷζεν ἔρευθος.<br>ὅσση δὲ ῥινὸς βοὸς ἤνιος ἢ ἐλάφοιο<br>γίγνεται, ἥν τ’ ἀγρῶσται ἀχαιινέην καλέουσιν,<br>τόσσον ἔην πάντῃ χρύσεον ἐφύπερθεν ἄωτον.<br>βεβρίθει λήνεσσιν ἐπηρεφές· ἤλιθα δὲ χθὼν<br>αἰὲν ὑποπρὸ ποδῶν ἀμαρύσσετο νισσομένοιο.<br>ἤιε δ’ ἄλλοτε μὲν λαιῷ ἐπιειμένος ὤμῳ<br>αὐχένος ἐξ ὑπάτοιο ποδηνεκές, ἄλλοτε δ’ αὖτε<br>εἴλει ἀφασσόμενος· περὶ γὰρ δίεν, ὄφρα ἓ μή τις<br>ἀνδρῶν ἠὲ θεῶν νοσφίσσεται ἀντιβολήσας.", "st": "4.162"}, {"sp": "N", "t": "Ἠὼς μέν ῥ’ ἐπὶ γαῖαν ἐκίδνατο, τοὶ δ’ ἐς ὅμιλον<br>ἷξον· θάμβησαν δὲ νέοι μέγα κῶας ἰδόντες<br>λαμπόμενον στεροπῇ ἴκελον Διός. ὦρτο δ’ ἕκαστος<br>ψαῦσαι ἐελδόμενος δέχθαι τ’ ἐνὶ χερσὶν ἑῇσιν.<br>Αἰσονίδης δ’ ἄλλους μὲν ἐρήτυε, τῷ δ’ ἐπὶ φᾶρος<br>κάββαλε νηγάτεον· πρύμνῃ δ’ ἐνεείσατο κούρην<br>ἀνθέμενος, καὶ τοῖον ἔπος μετὰ πᾶσιν ἔειπεν·", "st": "4.183"}, {"sp": "N", "t": "“μηκέτι νῦν χάζεσθε, φίλοι, πάτρηνδε νέεσθαι.<br>ἤδη γὰρ χρειώ, τῆς εἵνεκα τήνδ’ ἀλεγεινὴν<br>ναυτιλίην ἔτλημεν ὀιζύι μοχθίζοντες,<br>εὐπαλέως κούρης ὑπὸ δήνεσι κεκράανται.<br>τὴν μὲν ἐγὼν ἐθέλουσαν ἀνάξομαι οἴκαδ’ ἄκοιτιν<br>κουριδίην· ἀτὰρ ὔμμες Ἀχαιίδος οἷά τε πάσης<br>αὐτῶν θ’ ὑμείων ἐσθλὴν ἐπαρωγὸν ἐοῦσαν<br>σώετε. δὴ γάρ που, μάλ’ ὀίομαι, εἶσιν ἐρύξων<br>Αἰήτης ὁμάδῳ πόντονδ’ ἴμεν ἐκ ποταμοῖο.<br>ἀλλ’ οἱ μὲν διὰ νηός, ἀμοιβαδὶς ἀνέρος ἀνὴρ<br>ἑζόμενος, πηδοῖσιν ἐρέσσετε· τοὶ δὲ βοείας<br>ἀσπίδας ἡμίσεες, δῄων θοὸν ἔχμα βολάων,<br>προσχόμενοι νόστῳ ἐπαμύνετε. νῦν δ’ ἐνὶ χερσὶν<br>παῖδας ἑοὺς πάτρην τε φίλην, γεραρούς τε τοκῆας<br>ἴσχομεν· ἡμετέρῃ δ’ ἐπερείδεται Ἑλλὰς ἐφορμῇ,<br>ἠὲ κατηφείην, ἢ καὶ μέγα κῦδος ἀρέσθαι.”", "st": "4.190"}, {"sp": "N", "t": "ὧς φάτο, δῦνε δὲ τεύχε’ ἀρήια· τοὶ δ’ ἰάχησαν<br>θεσπέσιον μεμαῶτες. ὁ δὲ ξίφος ἐκ κολεοῖο<br>σπασσάμενος πρυμναῖα νεὼς ἀπὸ πείσματ’ ἔκοψεν.<br>ἄγχι δὲ παρθενικῆς κεκορυθμένος ἰθυντῆρι<br>Ἀγκαίῳ παρέβασκεν· ἐπείγετο δ’ εἰρεσίῃ νηῦς<br>σπερχομένων ἄμοτον ποταμοῦ ἄφαρ ἐκτὸς ἐλάσσαι.", "st": "4.206"}, {"sp": "N", "t": "ἤδη δ’ Αἰήτῃ ὑπερήνορι πᾶσί τε Κόλχοις<br>Μηδείης περίπυστος ἔρως καὶ ἔργ’ ἐτέτυκτο.<br>ἐς δ’ ἀγορὴν ἀγέροντ’ ἐνὶ τεύχεσιν· ὅσσα δὲ πόντου<br>κύματα χειμερίοιο κορύσσεται ἐξ ἀνέμοιο,<br>ἢ ὅσα φύλλα χαμᾶζε περικλαδέος πέσεν ὕλης<br>φυλλοχόῳ ἐνὶ μηνί—τίς ἂν τάδε τεκμήραιτο;<br>ὧς οἱ ἀπειρέσιοι ποταμοῦ παρεμέτρεον ὄχθας,<br>κλαγγῇ μαιμώοντες· ὁ δ’ εὐτύκτῳ ἐνὶ δίφρῳ<br>Αἰήτης ἵπποισι μετέπρεπεν, οὕς οἱ ὄπασσεν<br>ἠέλιος πνοιῇσιν ἐειδομένους ἀνέμοιο,<br>σκαιῇ μέν ῥ’ ἐνὶ χειρὶ σάκος δινωτὸν ἀείρων,<br>τῇ δ’ ἑτέρῃ πεύκην περιμήκεα· πὰρ δέ οἱ ἔγχος<br>ἀντικρὺ τετάνυστο πελώριον. ἡνία δ’ ἵππων<br>γέντο χεροῖν Ἄψυρτος. υπεκπρὸ δὲ πόντον ἔταμνεν<br>νηῦς ἤδη κρατεροῖσιν ἐπειγομένη ἐρέτῃσιν,<br>καὶ μεγάλου ποταμοῖο καταβλώσκοντι ῥεέθρῳ.<br>αὐτὰρ ἄναξ ἄτῃ πολυπήμονι χεῖρας ἀείρας<br>ἠέλιον καὶ Ζῆνα κακῶν ἐπιμάρτυρας ἔργων<br>κέκλετο· δεινὰ δὲ παντὶ παρασχεδὸν ἤπυε λαῷ<br>εἰ μή οἱ κούρην αὐτάγρετον, ἢ ἀνὰ γαῖαν,<br>ἢ πλωτῆς εὑρόντες ἔτ’ εἰν ἁλὸς οἴδματι νῆα,<br>ἄξουσιν, καὶ θυμὸν ἐνιπλήσει μενεαίνων<br>τίσασθαι τάδε πάντα, δαήσονται κεφαλῇσιν<br>πάντα χόλον καὶ πᾶσαν ἑὴν ὑποδέγμενοι ἄτην.", "st": "4.212"}, {"sp": "N", "t": "ὧς ἔφατ’ Αἰήτης· αὐτῷ δ’ ἐνὶ ἤματι Κόλχοι<br>νῆάς τ’ εἰρύσσαντο, καὶ ἄρμενα νηυσὶ βάλοντο,<br>αὐτῷ δ’ ἤματι πόντον ἀνήιον· οὐδέ κε φαίης<br>τόσσον νηίτην στόλον ἔμμεναι, ἀλλ’ οἰωνῶν<br>ἰλαδὸν ἄσπετον ἔθνος ἐπιβρομέειν πελάγεσσιν.", "st": "4.236"}, {"sp": "N", "t": "οἱ δ’ ἀνέμου λαιψηρὰ θεᾶς βουλῇσιν ἀέντος<br>Ἥρης, ὄφρ’ ὤκιστα κακὸν Πελίαο δόμοισιν<br>Αἰαίη Μήδεια Πελασγίδα γαῖαν ἵκηται,<br>ἠοῖ ἐνὶ τριτάτῃ πρυμνήσια νηὸς ἔδησαν<br>Παφλαγόνων ἀκτῇσι, πάροιθ’ Ἅλυος ποταμοῖο.<br>ἡ γάρ σφ’ ἐξαποβάντας ἀρέσσασθαι θυέεσσιν<br>ἠνώγει Ἑκάτην. καὶ δὴ τὰ μέν, ὅσσα θυηλὴν<br>κούρη πορσανέουσα τιτύσκετο, μήτε τις ἴστωρ<br>εἴη, μήτ’ ἐμὲ θυμὸς ἐποτρύνειεν ἀείδειν.<br>ἅζομαι αὐδῆσαι· τό γε μὴν ἕδος ἐξέτι κείνου,<br>ὅ ῥα θεᾷ ἥρωες ἐπὶ ῥηγμῖσιν ἔδειμαν,<br>ἀνδράσιν ὀψιγόνοισι μένει καὶ τῆμος ἰδέσθαι.", "st": "4.241"}, {"sp": "N", "t": "αὐτίκα δ’ Αἰσονίδης ἐμνήσατο, σὺν δὲ καὶ ὧλλοι<br>ἥρωες, Φινῆος, ὃ δὴ πλόον ἄλλον ἔειπεν<br>ἐξ Αἴης ἔσσεσθαι· ἀνώιστος δ’ ἐτέτυκτο<br>πᾶσιν ὁμῶς. Ἄργος δὲ λιλαιομένοις ἀγόρευσεν·", "st": "4.253"}, {"sp": "N", "t": "“Νισσόμεθ’ Ὀρχομενὸν τὴν ἔχραεν ὔμμι περῆσαι<br>νημερτὴς ὅδε μάντις, ὅτῳ ξυνέβητε πάροιθεν.<br>ἔστιν γὰρ πλόος ἄλλος, ὃν ἀθανάτων ἱερῆες<br>πέφραδον, οἳ Θήβης Τριτωνίδος ἐκγεγάασιν.<br>οὔπω τείρεα πάντα, τά τ’ οὐρανῷ εἱλίσσονται,<br>οὐδέ τί πω Δαναῶν ἱερὸν γένος ἦεν ἀκοῦσαι<br>πευθομένοις· οἶοι δ’ ἔσαν Ἀρκάδες Ἀπιδανῆες,<br>Ἀρκάδες, οἳ καὶ πρόσθε σεληναίης ὑδέονται<br>ζώειν, φηγὸν ἔδοντες ἐν οὔρεσιν. οὐδὲ Πελασγὶς<br>χθὼν τότε κυδαλίμοισιν ἀνάσσετο Δευκαλίδῃσιν,<br>ἦμος ὅτ’ Ἠερίη πολυλήιος ἐκλήιστο,<br>μήτηρ Αἴγυπτος προτερηγενέων αἰζηῶν,<br>καὶ ποταμὸς Τρίτων ἠύρροος, ᾧ ὕπο πᾶσα<br>ἄρδεται Ἠερίη· Διόθεν δέ μιν οὔποτε δεύει<br>ὄμβρος· ἅλις προχοῇσι δ’ ἀνασταχύουσιν ἄρουραι.<br>ἔνθεν δή τινά φασι πέριξ διὰ πᾶσαν ὁδεῦσαι<br>Εὐρώπην Ἀσίην τε βίῃ καὶ κάρτεϊ λαῶν<br>σφωιτέρων θάρσει τε πεποιθότα· μυρία δ’ ἄστη<br>νάσσατ’ ἐποιχόμενος, τὰ μὲν ἤ ποθι ναιετάουσιν,<br>ἠὲ καὶ οὔ· πουλὺς γὰρ ἄδην ἐπενήνοθεν αἰών.<br>αἶά γε μὴν ἔτι νῦν μένει ἔμπεδον υἱωνοί τε<br>τῶνδ’ ἀνδρῶν, οὓς ὅσγε καθίσσατο ναιέμεν Αἶαν,<br>οἳ δή τοι γραπτῦς πατέρων ἕθεν εἰρύονται,<br>κύρβιας, οἷς ἔνι πᾶσαι ὁδοὶ καὶ πείρατ’ ἔασιν<br>ὑγρῆς τε τραφερῆς τε πέριξ ἐπινισσομένοισιν.<br>ἔστι δέ τις ποταμός, ὕπατον κέρας Ὠκεανοῖο,<br>εὐρύς τε προβαθής τε καὶ ὁλκάδι νηὶ περῆσαι·<br>Ἴστρον μιν καλέοντες ἑκὰς διετεκμήραντο·<br>ὅς δή τοι τείως μὲν ἀπείρονα τέμνετ’ ἄρουραν<br>εἷς οἶος· πηγαὶ γὰρ ὑπὲρ πνοιῆς βορέαο<br>Ῥιπαίοις ἐν ὄρεσσιν ἀπόπροθι μορμύρουσιν.<br>ἀλλ’ ὁπόταν Θρῃκῶν Σκυθέων τ’ ἐπιβήσεται οὔρους,<br>ἔνθα διχῆ τὸ μὲν ἔνθα μετ’ ἠῴην ἅλα βάλλει<br>τῇδ’ ὕδωρ, τὸ δ’ ὄπισθε βαθὺν διὰ κόλπον ἵησιν<br>σχιζόμενος πόντου Τρινακρίου εἰσανέχοντα,<br>γαίῃ ὃς ὑμετέρῃ παρακέκλιται, εἰ ἐτεὸν δὴ<br>ὑμετέρης γαίης Ἀχελώιος ἐξανίησιν.”", "st": "4.257"}, {"sp": "N", "t": "ὧς ἄρ’ ἔφη· τοῖσιν δὲ θεὰ τέρας ἐγγυάλιξεν<br>αἴσιον, ᾧ καὶ πάντες ἐπευφήμησαν ἰδόντες<br>στέλλεσθαι τήνδ’ οἶμον. ἐπιπρὸ γὰρ ὁλκὸς ἐτύχθη<br>οὐρανίης ἀκτῖνος, ὅπῃ καὶ ἀμεύσιμον ἦεν.<br>γηθόσυνοι δὲ Λύκοιο κατ’ αὐτόθι παῖδα λιπόντες<br>λαίφεσι πεπταμένοισιν ὑπεὶρ ἅλα ναυτίλλοντο,<br>οὔρεα Παφλαγόνων θηεύμενοι. οὐδὲ Κάραμβιν<br>γνάμψαν, ἐπεὶ πνοιαί τε καὶ οὐρανίου πυρὸς αἴγλη<br>μεῖνεν, ἕως Ἴστροιο μέγαν ῥόον εἰσαφίκοντο.", "st": "4.294"}, {"sp": "N", "t": "Κόλχοι δ’ αὖτ’ ἄλλοι μέν, ἐτώσια μαστεύοντες,<br>Κυανέας Πόντοιο διὲκ πέτρας ἐπέρησαν·<br>ἄλλοι δ’ αὖ ποταμὸν μετεκίαθον, οἷσιν ἄνασσεν<br>Ἄψυρτος, Καλὸν δὲ διὰ στόμα πεῖρε λιασθείς.<br>τῶ καὶ ὑπέφθη τούσγε βαλὼν ὕπερ αὐχένα γαίης<br>κόλπον ἔσω πόντοιο πανέσχατον Ἰονίοιο.<br>Ἴστρῳ γάρ τις νῆσος ἐέργεται οὔνομα Πεύκη,<br>τριγλώχιν, εὖρος μὲν ἐς αἰγιαλοὺς ἀνέχουσα,<br>στεινὸν δ’ αὖτ’ ἀγκῶνα ποτὶ ῥόον· ἀμφὶ δὲ δοιαὶ<br>σχίζονται προχοαί. τὴν μὲν καλέουσι Νάρηκος·<br>τὴν δ’ ὑπὸ τῇ νεάτῃ, Καλὸν στόμα. τῇ δὲ διαπρὸ<br>Ἄψυρτος Κόλχοι τε θοώτερον ὡρμήθησαν·<br>οἱ δ’ ὑψοῦ νήσοιο κατ’ ἀκροτάτης ἐνέοντο<br>τηλόθεν. εἱαμενῇσι δ’ ἐν ἄσπετα πώεα λεῖπον<br>ποιμένες ἄγραυλοι νηῶν φόβῳ, οἷά τε θῆρας<br>ὀσσόμενοι πόντου μεγακήτεος ἐξανιόντας.<br>οὐ γάρ πω ἁλίας γε πάρος ποθὶ νῆας ἴδοντο,<br>οὔτ’ οὖν Θρήιξιν μιγάδες Σκύθαι, οὐδὲ Σίγυννοι,<br>οὔτ’ οὖν Γραυκένιοι, οὔθ’ οἱ περὶ Λαύριον ἤδη<br>Σίνδοι ἐρημαῖον πεδίον μέγα ναιετάοντες.<br>αὐτὰρ ἐπεί τ’ Ἄγγουρον ὄρος, καὶ ἄπωθεν ἐόντα<br>Ἀγγούρου ὄρεος σκόπελον πάρα Καυλιακοῖο,<br>ᾧ πέρι δὴ σχίζων Ἴστρος ῥόον ἔνθα καὶ ἔνθα<br>βάλλει ἁλός, πεδίον τε τὸ Λαύριον ἠμείψαντο,<br>δή ῥα τότε Κρονίην Κόλχοι ἅλαδ’ ἐκπρομολόντες<br>πάντῃ, μή σφε λάθοιεν, ὑπετμήξαντο κελεύθους.<br>οἱ δ’ ὄπιθεν ποταμοῖο κατήλυθον, ἐκ δ’ ἐπέρησαν<br>δοιὰς Ἀρτέμιδος Βρυγηίδας ἀγχόθι νήσους.<br>τῶν δ’ ἤτοι ἑτέρῃ μὲν ἐν ἱερὸν ἔσκεν ἔδεθλον·<br>ἐν δ’ ἑτέρῃ, πληθὺν πεφυλαγμένοι Ἀψύρτοιο,<br>βαῖνον· ἐπεὶ κείνας πολέων λίπον ἔνδοθι νήσους<br>αὔτως, ἁζόμενοι κούρην Διός· αἱ δὲ δὴ ἄλλαι<br>στεινόμεναι Κόλχοισι πόρους εἴρυντο θαλάσσης.<br>ὧς δὲ καὶ εἰς ἀκτὰς πληθὺν λίπεν ἀγχόθι νήσων<br>μέσφα Σαλαγγῶνος ποταμοῦ καὶ Νέστιδος αἴης.", "st": "4.303"}, {"sp": "N", "t": "ἔνθα κε λευγαλέῃ Μινύαι τότε δηιοτῆτι<br>παυρότεροι πλεόνεσσιν ὑπείκαθον· ἀλλὰ πάροιθεν<br>συνθεσίην, μέγα νεῖκος ἀλευάμενοι, ἐτάμοντο,<br>κῶας μὲν χρύσειον, ἐπεί σφισιν αὐτὸς ὑπέστη<br>Αἰήτης, εἰ κεῖνοι ἀναπλήσειαν ἀέθλους,<br>ἔμπεδον εὐδικίῃ σφέας ἑξέμεν, εἴτε δόλοισιν,<br>εἴτε καὶ ἀμφαδίην αὔτως ἀέκοντος ἀπηύρων·<br>αὐτὰρ Μήδειάν γε—τὸ γὰρ πέλεν ἀμφήριστον—<br>παρθέσθαι κούρῃ Λητωίδι νόσφιν ὁμίλου,<br>εἰσόκε τις δικάσῃσι θεμιστούχων βασιλήων,<br>εἴτε μιν εἰς πατρὸς χρειὼ δόμον αὖτις ἱκάνειν,<br>εἴτε μεθ’ Ἑλλάδα γαῖαν ἀριστήεσσιν ἕπεσθαι.", "st": "4.338"}, {"sp": "N", "t": "ἔνθα δ’ ἐπεὶ τὰ ἕκαστα νόῳ πεμπάσσατο κούρη,<br>δή ῥά μιν ὀξεῖαι κραδίην ἐλέλιξαν ἀνῖαι<br>νωλεμές· αἶψα δὲ νόσφιν Ἰήσονα μοῦνον ἑταίρων<br>ἐκπροκαλεσσαμένη ἄγεν ἄλλυδις, ὄφρ’ ἐλίασθεν<br>πολλὸν ἑκάς, στονόεντα δ’ ἐνωπαδὶς ἔκφατο μῦθον·", "st": "4.350"}, {"sp": "N", "t": "“Αἰσονίδη, τίνα τήνδε συναρτύνασθε μενοινὴν<br>ἀμφ’ ἐμοί; ἦέ σε πάγχυ λαθιφροσύναις ἐνέηκαν<br>ἀγλαΐαι, τῶν δ’ οὔτι μετατρέπῃ, ὅσσ’ ἀγόρευες<br>χρειοῖ ἐνισχόμενος; ποῦ τοι Διὸς Ἱκεσίοιο<br>ὅρκια, ποῦ δὲ μελιχραὶ ὑποσχεσίαι βεβάασιν;<br>ᾗς ἐγὼ οὐ κατὰ κόσμον ἀναιδήτῳ ἰότητι<br>πάτρην τε κλέα τε μεγάρων αὐτούς τε τοκῆας<br>νοσφισάμην, τά μοι ἦεν ὑπέρτατα· τηλόθι δ’ οἴη<br>λυγρῇσιν κατὰ πόντον ἅμ’ ἀλκυόνεσσι φορεῦμαι<br>σῶν ἕνεκεν καμάτων, ἵνα μοι σόος ἀμφί τε βουσὶν<br>ἀμφί τε γηγενέεσσιν ἀναπλήσειας ἀέθλους.<br>ὕστατον αὖ καὶ κῶας, ἐπεί τ’ ἐπαϊστὸν ἐτύχθη,<br>εἷλες ἐμῇ ματίῃ· κατὰ δ’ οὐλοὸν αἶσχος ἔχευα<br>θηλυτέραις. τῶ φημὶ τεὴ κούρη τε δάμαρ τε<br>αὐτοκασιγνήτη τε μεθ’ Ἑλλάδα γαῖαν ἕπεσθαι.<br>πάντῃ νυν πρόφρων ὑπερίστασο, μηδέ με μούνην<br>σεῖο λίπῃς ἀπάνευθεν, ἐποιχόμενος βασιλῆας.<br>ἀλλ’ αὔτως εἴρυσο· δίκη δέ τοι ἔμπεδος ἔστω<br>καὶ θέμις, ἣν ἄμφω συναρέσσαμεν· ἢ σύγ’ ἔπειτα<br>φασγάνῳ αὐτίκα τόνδε μέσον διὰ λαιμὸν ἀμῆσαι,<br>ὄφρ’ ἐπίηρα φέρωμαι ἐοικότα μαργοσύνῃσιν.<br>σχετλίη, εἴ κεν δή με κασιγνήτοιο δικάσσῃ<br>ἔμμεναι οὗτος ἄναξ, τῷ ἐπίσχετε τάσδ’ ἀλεγεινὰς<br>ἄμφω συνθεσίας. πῶς ἵξομαι ὄμματα πατρός;<br>ἦ μάλ’ ἐυκλειής; τίνα δ’ οὐ τίσιν, ἠὲ βαρεῖαν<br>ἄτην οὐ σμυγερῶς δεινῶν ὕπερ, οἷα ἔοργα,<br>ὀτλήσω; σὺ δέ κεν θυμηδέα νόστον ἕλοιο;<br>μὴ τόγε παμβασίλεια Διὸς τελέσειεν ἄκοιτις,<br>ᾗ ἐπικυδιάεις. μνήσαιο δὲ καί ποτ’ ἐμεῖο,<br>στρευγόμενος καμάτοισι· δέρος δέ τοι ἶσον ὀνείροις<br>οἴχοιτ’ εἰς ἔρεβος μεταμώνιον. ἐκ δέ σε πάτρης<br>αὐτίκ’ ἐμαί σ’ ἐλάσειαν Ἐρινύες· οἷα καὶ αὐτὴ<br>σῇ πάθον ἀτροπίῃ. τὰ μὲν οὐ θέμις ἀκράαντα<br>ἐν γαίῃ πεσέειν. μάλα γὰρ μέγαν ἤλιτες ὅρκον,<br>νηλεές· ἀλλ’ οὔ θήν μοι ἐπιλλίζοντες ὀπίσσω<br>δὴν ἔσσεσθ’ εὔκηλοι ἕκητί γε συνθεσιάων.”", "st": "4.355"}, {"sp": "N", "t": "ὧς φάτ’ ἀναζείουσα βαρὺν χόλον· ἵετο δ’ ἥγε<br>νῆα καταφλέξαι, διά τ’ ἔμπεδα πάντα κεάσσαι,<br>ἐν δὲ πεσεῖν αὐτὴ μαλερῷ πυρί. τοῖα δ’ Ἰήσων<br>μειλιχίοις ἐπέεσσιν ὑποδδείσας προσέειπεν·", "st": "4.391"}, {"sp": "N", "t": "“ἴσχεο, δαιμονίη· τὰ μὲν ἁνδάνει οὐδ’ ἐμοὶ αὐτῷ.<br>ἀλλά τιν’ ἀμβολίην διζήμεθα δηιοτῆτος,<br>ὅσσον δυσμενέων ἀνδρῶν νέφος ἀμφιδέδηεν<br>εἵνεκα σεῦ. πάντες γάρ, ὅσοι χθόνα τήνδε νέμονται,<br>Ἀψύρτῳ μεμάασιν ἀμυνέμεν, ὄφρα σε πατρί,<br>οἷά τε ληισθεῖσαν, ὑπότροπον οἴκαδ’ ἄγοιντο.<br>αὐτοὶ δὲ στυγερῷ κεν ὀλοίμεθα πάντες ὀλέθρῳ,<br>μίξαντες δαῒ χεῖρας· ὅ τοι καὶ ῥίγιον ἄλγος<br>ἔσσεται, εἴ σε θανόντες ἕλωρ κείνοισι λίποιμεν.<br>ἥδε δὲ συνθεσίη κρανέει δόλον, ᾧ μιν ἐς ἄτην<br>βήσομεν. οὐδ’ ἂν ὁμῶς περιναιέται ἀντιόωσιν<br>Κόλχοις ἦρα φέροντες ὑπὲρ σέο νόσφιν ἄνακτος,<br>ὅς τοι ἀοσσητήρ τε κασίγνητός τε τέτυκται·<br>οὐδ’ ἂν ἐγὼ Κόλχοισιν ὑπείξω μὴ πολεμίζειν<br>ἀντιβίην, ὅτε μή με διὲξ εἰῶσι νέεσθαι.”", "st": "4.395"}, {"sp": "N", "t": "Ἴσκεν ὑποσσαίνων· ἡ δ’ οὐλοὸν ἔκφατο μῦθον·<br>“φράζεο νῦν. χρειὼ γὰρ ἀεικελίοισιν ἐπ’ ἔργοις<br>καὶ τόδε μητίσασθαι, ἐπεὶ τὸ πρῶτον ἀάσθην<br>ἀμπλακίῃ, θεόθεν δὲ κακὰς ἤνυσσα μενοινάς.<br>τύνη μὲν κατὰ μῶλον ἀλέξεο δούρατα Κόλχων·<br>αὐτὰρ ἐγὼ κεῖνόν γε τεὰς ἐς χεῖρας ἱκέσθαι<br>μειλίξω· σὺ δέ μιν φαιδροῖς ἀγαπάζεο δώροις.<br>εἴ κέν πως κήρυκας ἀπερχομένους πεπίθοιμι<br>οἰόθεν οἶον ἐμοῖσι συναρθμῆσαι ἐπέεσσιν,<br>ἔνθ’ εἴ τοι τόδε ἔργον ἐφανδάνει, οὔτι μεγαίρω,<br>κτεῖνέ τε, καὶ Κόλχοισιν ἀείρεο δηιοτῆτα.”", "st": "4.410"}, {"sp": "N", "t": "ὧς τώγε ξυμβάντε μέγαν δόλον ἠρτύνοντο<br>Ἀψύρτῳ, καὶ πολλὰ πόρον ξεινήια δῶρα,<br>οἷς μέτα καὶ πέπλον δόσαν ἱερὸν Ὑψιπυλείης<br>πορφύρεον. τὸν μέν ῥα Διωνύσῳ κάμον αὐταὶ<br>Δίῃ ἐν ἀμφιάλῳ Χάριτες θεαί· αὐτὰρ ὁ παιδὶ<br>δῶκε Θόαντι μεταῦτις· ὁ δ’ αὖ λίπεν Ὑψιπυλείῃ·<br>ἡ δ’ ἔπορ’ Αἰσονίδῃ πολέσιν μετὰ καὶ τὸ φέρεσθαι<br>γλήνεσιν εὐεργὲς ξεινήιον. οὔ μιν ἀφάσσων,<br>οὔτε κεν εἰσορόων γλυκὺν ἵμερον ἐμπλήσειας.<br>τοῦ δὲ καὶ ἀμβροσίη ὀδμὴ πέλεν ἐξέτι κείνου,<br>ἐξ οὗ ἄναξ αὐτὸς Νυσήιος ἐγκατέλεκτο<br>ἀκροχάλιξ οἴνῳ καὶ νέκταρι, καλὰ μεμαρπὼς<br>στήθεα παρθενικῆς Μινωίδος, ἥν ποτε Θησεὺς<br>Κνωσσόθεν ἑσπομένην Δίῃ ἔνι κάλλιπε νήσῳ.<br>ἡ δ’ ὅτε κηρύκεσσιν ἐπεξυνώσατο μύθους,<br>θελγέμεν, εὖτ’ ἂν πρῶτα θεᾶς περὶ νηὸν ἵκηται<br>συνθεσίῃ, νυκτός τε μέλαν κνέφας ἀμφιβάλῃσιν,<br>ἐλθέμεν, ὄφρα δόλον συμφράσσεται, ὥς κεν ἑλοῦσα<br>χρύσειον μέγα κῶας ὑπότροπος αὖτις ὀπίσσω<br>βαίη ἐς Αἰήταο δόμους· πέρι γάρ μιν ἀνάγκῃ<br>υἱῆες Φρίξοιο δόσαν ξείνοισιν ἄγεσθαι·<br>τοῖα παραιφαμένη θελκτήρια φάρμακ’ ἔπασσεν<br>αἰθέρι καὶ πνοιῇσι, τά κεν καὶ ἄπωθεν ἐόντα<br>ἄγριον ἠλιβάτοιο κατ’ οὔρεος ἤγαγε θῆρα.", "st": "4.421"}, {"sp": "N", "t": "σχέτλι’ Ἔρως, μέγα πῆμα, μέγα στύγος ἀνθρώποισιν,<br>ἐκ σέθεν οὐλόμεναί τ’ ἔριδες στοναχαί τε γόοι τε,<br>ἄλγεά τ’ ἄλλ’ ἐπὶ τοῖσιν ἀπείρονα τετρήχασιν.<br>δυσμενέων ἐπὶ παισὶ κορύσσεο, δαῖμον, ἀερθείς,<br>οἷος Μηδείῃ στυγερὴν φρεσὶν ἔμβαλες ἄτην.<br>πῶς γὰρ δὴ μετιόντα κακῷ ἐδάμασσεν ὀλέθρῳ<br>Ἄψυρτον; τὸ γὰρ ἧμιν ἐπισχερὼ ἦεν ἀοιδῆς.", "st": "4.445"}, {"sp": "N", "t": "ἦμος ὅτ’ Ἀρτέμιδος νήσῳ ἔνι τήνγ’ ἐλίποντο<br>συνθεσίῃ. τοὶ μέν ῥα διάνδιχα νηυσὶν ἔκελσαν<br>σφωιτέραις κρινθέντες· ὁ δ’ ἐς λόχον ᾖεν Ἰήσων<br>δέγμενος Ἄψυρτόν τε καὶ οὓς ἐξαῦτις ἑταίρους.<br>αὐτὰρ ὅγ’ αἰνοτάτῃσιν ὑποσχεσίῃσι δολωθεὶς<br>καρπαλίμως ᾗ νηὶ διὲξ ἁλὸς οἶδμα περήσας,<br>νύχθ’ ὕπο λυγαίην ἱερῆς ἐπεβήσατο νήσου·<br>οἰόθι δ’ ἀντικρὺ μετιὼν πειρήσατο μύθοις<br>εἷο κασιγνήτης, ἀταλὸς πάις οἷα χαράδρης<br>χειμερίης, ἣν οὐδὲ δι’ αἰζηοὶ περόωσιν.<br>εἴ κε δόλον ξείνοισιν ἐπ’ ἀνδράσι τεχνήσαιτο.<br>καὶ τὼ μὲν τὰ ἕκαστα συνῄνεον ἀλλήλοισιν·<br>αὐτίκα δ’ Αἰσονίδης πυκινοῦ ἐξᾶλτο λόχοιο,<br>γυμνὸν ἀνασχόμενος παλάμῃ ξίφος· αἶψα δὲ κούρη<br>ἔμπαλιν ὄμματ’ ἔνεικε, καλυψαμένη ὀθόνῃσιν,<br>μὴ φόνον ἀθρήσειε κασιγνήτοιο τυπέντος.<br>τὸν δ’ ὅγε, βουτύπος ὥστε μέγαν κερεαλκέα ταῦρον,<br>πλῆξεν ὀπιπεύσας νηοῦ σχεδόν, ὅν ποτ’ ἔδειμαν<br>Ἀρτέμιδι Βρυγοὶ περιναιέται ἀντιπέρηθεν.<br>τοῦ ὅγ’ ἐνὶ προδόμῳ γνὺξ ἤριπε· λοίσθια δ’ ἥρως<br>θυμὸν ἀναπνείων χερσὶν μέλαν ἀμφοτέρῃσιν<br>αἷμα κατ’ ὠτειλὴν ὑποΐσχετο· τῆς δὲ καλύπτρην<br>ἀργυφέην καὶ πέπλον ἀλευομένης ἐρύθηνεν.<br>ὀξὺ δὲ πανδαμάτωρ λοξῷ ἴδεν οἷον ἔρεξαν<br>ὄμματι νηλειὴς ὀλοφώιον ἔργον Ἐρινύς.<br>ἥρως δ’ Αἰσονίδης ἐξάργματα τάμνε θανόντος,<br>τρὶς δ’ ἀπέλειξε φόνου, τρὶς δ’ ἐξ ἄγος ἔπτυσ’ ὀδόντων,<br>ἣ θέμις αὐθέντῃσι δολοκτασίας ἱλάεσθαι.<br>ὑγρὸν δ’ ἐν γαίῃ κρύψεν νέκυν, ἔνθ’ ἔτι νῦν περ<br>κείαται ὀστέα κεῖνα μετ’ ἀνδράσιν Ἀψυρτεῦσιν.", "st": "4.452"}, {"sp": "N", "t": "οἱ δ’ ἄμυδις πυρσοῖο σέλας προπάροιθεν ἰδόντες,<br>τό σφιν παρθενικὴ τέκμαρ μετιοῦσιν ἄειρεν,<br>Κολχίδος ἀγχόθι νηὸς ἑὴν παρὰ νῆ’ ἐβάλοντο<br>ἥρωες· Κόλχον δ’ ὄλεκον στόλον, ἠύτε κίρκοι<br>φῦλα πελειάων, ἠὲ μέγα πῶυ λέοντες<br>ἀγρότεροι κλονέουσιν ἐνὶ σταθμοῖσι θορόντες.<br>οὐδ’ ἄρα τις κείνων θάνατον φύγε, πάντα δ’ ὅμιλον<br>πῦρ ἅ τε δηιόωντες ἐπέδραμον· ὀψὲ δ’ Ἰήσων<br>ἤντησεν, μεμαὼς ἐπαμυνέμεν οὐ μάλ’ ἀρωγῆς<br>δευομένοις· ἤδη δὲ καὶ ἀμφ’ αὐτοῖο μέλοντο.<br>ἔνθα δὲ ναυτιλίης πυκινὴν περὶ μητιάασκον<br>ἑζόμενοι βουλήν· ἐπὶ δέ σφισιν ἤλυθε κούρη<br>φραζομένοις· Πηλεὺς δὲ παροίτατος ἔκφατο μῦθον·", "st": "4.482"}, {"sp": "N", "t": "“ἤδη νῦν κέλομαι νύκτωρ ἔτι νῆ’ ἐπιβάντας<br>εἰρεσίῃ περάαν πλόον ἀντίον, ᾧ ἐπέχουσιν<br>δήιοι· ἠῶθεν γὰρ ἐπαθρήσαντας ἕκαστα<br>ἔλπομαι οὐχ ἕνα μῦθον, ὅτις προτέρωσε δίεσθαι<br>ἡμέας ὀτρυνέει, τοὺς πεισέμεν· οἷα δ’ ἄνακτος<br>εὔνιδες, ἀργαλέῃσι διχοστασίῃς κεδόωνται.<br>ῥηιδίη δέ κεν ἄμμι, κεδασθέντων δίχα λαῶν,<br>ἤ τ’ εἴη μετέπειτα κατερχομένοισι κέλευθος.”", "st": "4.495"}, {"sp": "N", "t": "ὧς ἔφατ’· ᾔνησαν δὲ νέοι ἔπος Αἰακίδαο.<br>ῥίμφα δὲ νῆ’ ἐπιβάντες ἐπερρώοντ’ ἐλάτῃσιν<br>νωλεμές, ὄφρ’ ἱερὴν Ἠλεκτρίδα νῆσον ἵκοντο,<br>ἀλλάων ὑπάτην, ποταμοῦ σχεδὸν Ἠριδανοῖο.", "st": "4.503"}, {"sp": "N", "t": "Κόλχοι δ’ ὁππότ’ ὄλεθρον ἐπεφράσθησαν ἄνακτος,<br>ἤτοι μὲν δίζεσθαι ἐπέχραον ἔνδοθι πάσης<br>Ἀργὼ καὶ Μινύας Κρονίης ἁλός. ἀλλ’ ἀπέρυκεν<br>Ἥρη σμερδαλέῃσι κατ’ αἰθέρος ἀστεροπῇσιν.<br>ὕστατον αὐτοὶ δ’ αὖτε Κυταιίδος ἤθεα γαίης<br>στύξαν, ἀτυζόμενοι χόλον ἄγριον Αἰήταο,<br>ἔμπεδα δ’ ἄλλυδις ἄλλοι ἐφορμηθέντες ἔνασθεν.<br>οἱ μὲν ἐπ’ αὐτάων νήσων ἔβαν, ᾗσιν ἐπέσχον<br>ἥρωες, ναίουσι δ’ ἐπώνυμοι Ἀψύρτοιο·<br>οἱ δ’ ἄρ’ ἐπ’ Ἰλλυρικοῖο μελαμβαθέος ποταμοῖο,<br>τύμβος ἵν’ Ἁρμονίης Κάδμοιό τε, πύργον ἔδειμαν,<br>ἀνδράσιν Ἐγχελέεσσιν ἐφέστιοι· οἱ δ’ ἐν ὄρεσσιν<br>ἐνναίουσιν, ἅπερ τε Κεραύνια κικλήσκονται,<br>ἐκ τόθεν, ἐξότε τούσγε Διὸς Κρονίδαο κεραυνοὶ<br>νῆσον ἐς ἀντιπέραιαν ἀπέτραπον ὁρμηθῆναι.", "st": "4.507"}, {"sp": "N", "t": "ἥρωες δ’, ὅτε δή σφιν ἐείσατο νόστος ἀπήμων,<br>δή ῥα τότε προμολόντες ἐπὶ χθονὶ πείσματ’ ἔδησαν<br>Ὑλλήων. νῆσοι γὰρ ἐπιπρούχοντο θαμειαὶ<br>ἀργαλέην πλώουσιν ὁδὸν μεσσηγὺς ἔχουσαι<br>οὐδέ σφιν, ὡς καὶ πρίν, ἀνάρσια μητιάασκον<br>Ὑλλῆες· πρὸς δ’ αὐτοὶ ἐμηχανόωντο κέλευθον,<br>μισθὸν ἀειρόμενοι τρίποδα μέγαν Ἀπόλλωνος.<br>δοιοὺς γὰρ τρίποδας τηλοῦ πόρε Φοῖβος ἄγεσθαι<br>Αἰσονίδῃ περόωντι κατὰ χρέος, ὁππότε Πυθὼ<br>ἱρὴν πευσόμενος μετεκίαθε τῆσδ’ ὑπὲρ αὐτῆς<br>ναυτιλίης· πέπρωτο δ’, ὅπῃ χθονὸς ἱδρυνθεῖεν,<br>μήποτε τὴν δῄοισιν ἀναστήσεσθαι ἰοῦσιν.<br>τούνεκεν εἰσέτι νῦν κείνῃ ὅδε κεύθεται αἴῃ<br>ἀμφὶ πόλιν ἀγανὴν Ὑλληίδα, πολλὸν ἔνερθεν<br>οὔδεος, ὥς κεν ἄφαντος ἀεὶ μερόπεσσι πέλοιτο.<br>οὐ μὲν ἔτι ζώοντα καταυτόθι τέτμον ἄνακτα<br>Ὕλλον, ὃν εὐειδὴς Μελίτη τέκεν Ἡρακλῆι<br>δήμῳ Φαιήκων. ὁ γὰρ οἰκία Ναυσιθόοιο<br>Μάκριν τ’ εἰσαφίκανε, Διωνύσοιο τιθήνην,<br>νιψόμενος παίδων ὀλοὸν φόνον· ἔνθ’ ὅγε κούρην<br>Αἰγαίου ἐδάμασσεν ἐρασσάμενος ποταμοῖο,<br>νηιάδα Μελίτην· ἡ δὲ σθεναρὸν τέκεν Ὕλλον.<br>οὐδ’ ἄρ’ ὅγ’ ἡβήσας αὐτῇ ἐνὶ ἔλδετο νήσῳ<br>ναίειν, κοιρανέοντος ὑπ’ ὀφρύσι Ναυσιθόοιο·<br>βῆ δ’ ἅλαδε Κρονίην, αὐτόχθονα λαὸν ἀγείρας<br>Φαιήκων· σὺν γάρ οἱ ἄναξ πόρσυνε κέλευθον<br>ἥρως Ναυσίθοος· τόθι δ’ εἵσατο, καί μιν ἔπεφνον<br>Μέντορες, ἀγραύλοισιν ἀλεξόμενον περὶ βουσίν.", "st": "4.522"}, {"sp": "N", "t": "ἀλλά, θεαί, πῶς τῆσδε παρὲξ ἁλός, ἀμφί τε γαῖαν<br>Αὐσονίην νήσους τε Λιγυστίδας, αἳ καλέονται<br>Στοιχάδες, Ἀργῴης περιώσια σήματα νηὸς<br>νημερτὲς πέφαται; τίς ἀπόπροθι τόσσον ἀνάγκη<br>καὶ χρειώ σφ’ ἐκόμισσε; τίνες σφέας ἤγαγον αὖραι;", "st": "4.552"}, {"sp": "N", "t": "αὐτόν που μεγαλωστὶ δεδουπότος Ἀψύρτοιο<br>Ζῆνα, θεῶν βασιλῆα, χόλος λάβεν, οἷον ἔρεξαν.<br>Αἰαίης δ’ ὀλοὸν τεκμήρατο δήνεσι Κίρκης<br>αἷμ’ ἀπονιψαμένους, πρό τε μυρία πημανθέντας,<br>νοστήσειν. τὸ μὲν οὔτις ἀριστήων ἐνόησεν·<br>ἀλλ’ ἔθεον γαίης Ὑλληίδος ἐξανιόντες<br>τηλόθι· τὰς δ’ ἀπέλειπον, ὅσαι Κόλχοισι πάροιθεν<br>ἑξείης πλήθοντο Λιβυρνίδες εἰν ἁλὶ νῆσοι,<br>Ἴσσα τε Δυσκέλαδός τε καὶ ἱμερτὴ Πιτύεια.<br>αὐτὰρ ἔπειτ’ ἐπὶ τῇσι παραὶ Κέρκυραν ἵκοντο,<br>ἔνθα Ποσειδάων Ἀσωπίδα νάσσατο κούρην,<br>ἠύκομον Κέρκυραν, ἑκὰς Φλιουντίδος αἴης,<br>ἁρπάξας ὑπ’ ἔρωτι· μελαινομένην δέ μιν ἄνδρες<br>ναυτίλοι ἐκ πόντοιο κελαινῇ πάντοθεν ὕλῃ<br>δερκόμενοι Κέρκυραν ἐπικλείουσι Μέλαιναν.<br>τῇ δ’ ἐπὶ καὶ Μελίτην, λιαρῷ περιγηθέες οὔρῳ,<br>αἰπεινήν τε Κερωσσόν, ὕπερθε δὲ πολλὸν ἐοῦσαν<br>Νυμφαίην παράμειβον, ἵνα κρείουσα Καλυψὼ<br>Ἀτλαντὶς ναίεσκε· τὰ δ’ ἠεροειδέα λεύσσειν<br>οὔρεα δοιάζοντο Κεραύνια. καὶ τότε βουλὰς<br>ἀμφ’ αὐτοῖς Ζηνός τε μέγαν χόλον ἐφράσαθ’ Ἥρη.<br>μηδομένη δ’ ἄνυσιν τοῖο πλόου, ὦρσεν ἀέλλας<br>ἀντικρύ, ταῖς αὖτις ἀναρπάγδην φορέοντο<br>νήσου ἔπι κραναῆς Ἠλεκτρίδος. αὐτίκα δ’ ἄφνω<br>ἴαχεν ἀνδρομέῃ ἐνοπῇ μεσσηγὺ θεόντων<br>αὐδῆεν γλαφυρῆς νηὸς δόρυ, τό ῥ’ ἀνὰ μέσσην<br>στεῖραν Ἀθηναίη Δωδωνίδος ἥρμοσε φηγοῦ.<br>τοὺς δ’ ὀλοὸν μεσσηγὺ δέος λάβεν εἰσαΐοντας<br>φθογγήν τε Ζηνός τε βαρὺν χόλον. οὐ γὰρ ἀλύξειν<br>ἔννεπεν οὔτε πόρους δολιχῆς ἁλός, οὔτε θυέλλας<br>ἀργαλέας, ὅτε μὴ Κίρκη φόνον Ἀψύρτοιο<br>νηλέα νίψειεν· Πολυδεύκεα δ’ εὐχετάασθαι<br>Κάστορά τ’ ἀθανάτοισι θεοῖς ἤνωγε κελεύθους<br>Αὐσονίης ἔμπροσθε πορεῖν ἁλός, ᾗ ἔνι Κίρκην<br>δήουσιν, Πέρσης τε καὶ Ἠελίοιο θύγατρα.", "st": "4.557"}, {"sp": "N", "t": "ὧς Ἀργὼ ἰάχησεν ὑπὸ κνέφας· οἱ δ’ ἀνόρουσαν<br>Τυνδαρίδαι, καὶ χεῖρας ἀνέσχεθον ἀθανάτοισιν<br>εὐχόμενοι τὰ ἕκαστα· κατηφείη δ’ ἔχεν ἄλλους<br>ἥρωας Μινύας. ἡ δ’ ἔσσυτο πολλὸν ἐπιπρὸ<br>λαίφεσιν, ἐς δ’ ἔβαλον μύχατον ῥόον Ἠριδανοῖο·<br>ἔνθα ποτ’ αἰθαλόεντι τυπεὶς πρὸς στέρνα κεραυνῷ<br>ἡμιδαὴς Φαέθων πέσεν ἅρματος Ἠελίοιο<br>λίμνης ἐς προχοὰς πολυβενθέος· ἡ δ’ ἔτι νῦν περ<br>τραύματος αἰθομένοιο βαρὺν ἀνακηκίει ἀτμόν.<br>οὐδέ τις ὕδωρ κεῖνο διὰ πτερὰ κοῦφα τανύσσας<br>οἰωνὸς δύναται βαλέειν ὕπερ· ἀλλὰ μεσηγὺς<br>φλογμῷ ἐπιθρώσκει πεποτημένος. ἀμφὶ δὲ κοῦραι<br>Ἡλιάδες ταναῇσιν ἐελμέναι αἰγείροισιν,<br>μύρονται κινυρὸν μέλεαι γόον· ἐκ δὲ φαεινὰς<br>ἠλέκτρου λιβάδας βλεφάρων προχέουσιν ἔραζε,<br>αἱ μέν τ’ ἠελίῳ ψαμάθοις ἔπι τερσαίνονται·<br>εὖτ’ ἂν δὲ κλύζῃσι κελαινῆς ὕδατα λίμνης<br>ἠιόνας πνοιῇ πολυηχέος ἐξ ἀνέμοιο,<br>δὴ τότ’ ἐς Ἠριδανὸν προκυλίνδεται ἀθρόα πάντα<br>κυμαίνοντι ῥόῳ. Κελτοὶ δ’ ἐπὶ βάξιν ἔθεντο,<br>ὡς ἄρ’ Ἀπόλλωνος τάδε δάκρυα Λητοΐδαο<br>ἐμφέρεται δίναις, ἅ τε μυρία χεῦε πάροιθεν,<br>ἦμος Ὑπερβορέων ἱερὸν γένος εἰσαφίκανεν,<br>οὐρανὸν αἰγλήεντα λιπὼν ἐκ πατρὸς ἐνιπῆς,<br>χωόμενος περὶ παιδί, τὸν ἐν λιπαρῇ Λακερείῃ<br>δῖα Κορωνὶς ἔτικτεν ἐπὶ προχοῇς Ἀμύροιο.<br>καὶ τὰ μὲν ὧς κείνοισι μετ’ ἀνδράσι κεκλήισται.<br>τοὺς δ’ οὔτε βρώμης ᾕρει πόθος, οὐδὲ ποτοῖο,<br>οὔτ’ ἐπὶ γηθοσύνας τράπετο νόος. ἀλλ’ ἄρα τοίγε<br>ἤματα μὲν στρεύγοντο περιβληχρὸν βαρύθοντες<br>ὀδμῇ λευγαλέῃ, τήν ῥ’ ἄσχετον ἐξανίεσκον<br>τυφομένου Φαέθοντος ἐπιρροαὶ Ἠριδανοῖο·<br>νύκτας δ’ αὖ γόον ὀξὺν ὀδυρομένων ἐσάκουον<br>Ἡλιάδων λιγέως· τὰ δὲ δάκρυα μυρομένῃσιν<br>οἷον ἐλαιηραὶ στάγες ὕδασιν ἐμφορέοντο.", "st": "4.592"}, {"sp": "N", "t": "ἐκ δὲ τόθεν Ῥοδανοῖο βαθὺν ῥόον εἰσαπέβησαν,<br>ὅς τ’ εἰς Ἠριδανὸν μετανίσσεται· ἄμμιγα δ’ ὕδωρ<br>ἐν ξυνοχῇ βέβρυκε κυκώμενον. αὐτὰρ ὁ γαίης<br>ἐκ μυχάτης, ἵνα τ’ εἰσὶ πύλαι καὶ ἐδέθλια Νυκτός,<br>ἔνθεν ἀπορνύμενος τῇ μέν τ’ ἐπερεύγεται ἀκτὰς<br>Ὠκεανοῦ, τῇ δ’ αὖτε μετ’ Ἰονίην ἅλα βάλλει,<br>τῇ δ’ ἐπὶ Σαρδόνιον πέλαγος καὶ ἀπείρονα κόλπον<br>ἑπτὰ διὰ στομάτων ἵει ῥόον. ἐκ δ’ ἄρα τοῖο<br>λίμνας εἰσέλασαν δυσχείμονας, αἵ τ’ ἀνὰ Κελτῶν<br>ἤπειρον πέπτανται ἀθέσφατον· ἔνθα κεν οἵγε<br>ἄτῃ ἀεικελίῃ πέλασαν. φέρε γάρ τις ἀπορρὼξ<br>κόλπον ἐς Ὠκεανοῖο, τὸν οὐ προδαέντες ἔμελλον<br>εἰσβαλέειν, τόθεν οὔ κεν ὑπότροποι ἐξεσάωθεν.<br>ἀλλ’ Ἥρη σκοπέλοιο καθ’ Ἑρκυνίου ἰάχησεν<br>οὐρανόθεν προθοροῦσα· φόβῳ δ’ ἐτίναχθεν ἀυτῆς<br>πάντες ὁμῶς· δεινὸν γὰρ ἐπὶ μέγας ἔβραχεν αἰθήρ.<br>ἂψ δὲ παλιντροπόωντο θεᾶς ὕπο, καί ῥ’ ἐνόησαν<br>τὴν οἶμον, τῇπέρ τε καὶ ἔπλετο νόστος ἰοῦσιν.<br>δηναιοὶ δ’ ἀκτὰς ἁλιμυρέας εἰσαφίκοντο<br>Ἥρης ἐννεσίῃσι, δι’ ἔθνεα μυρία Κελτῶν<br>καὶ Λιγύων περόωντες ἀδήιοι. ἀμφὶ γὰρ αἰνὴν<br>ἠέρα χεῦε θεὰ πάντ’ ἤματα νισσομένοισιν.<br>μεσσότατον δ’ ἄρα τοίγε διὰ στόμα νηὶ βαλόντες<br>Στοιχάδας εἰσαπέβαν νήσους σόοι εἵνεκα κούρων<br>Ζηνός· ὃ δὴ βωμοί τε καὶ ἱερὰ τοῖσι τέτυκται<br>ἔμπεδον· οὐδ’ οἶον κείνης ἐπίκουροι ἕποντο<br>ναυτιλίης· Ζεὺς δέ σφι καὶ ὀψιγόνων πόρε νῆας.<br>Στοιχάδας αὖτε λιπόντες ἐς Αἰθαλίην ἐπέρησαν<br>νῆσον, ἵνα ψηφῖσιν ἀπωμόρξαντο καμόντες<br>ἱδρῶ ἅλις· χροιῇ δὲ κατ’ αἰγιαλοῖο κέχυνται<br>εἴκελαι· ἐν δὲ σόλοι καὶ τεύχεα θέσκελα κείνων·<br>ἐν δὲ λιμὴν Ἀργῷος ἐπωνυμίην πεφάτισται.", "st": "4.627"}, {"sp": "N", "t": "καρπαλίμως δ’ ἐνθένδε διὲξ ἁλὸς οἶδμα νέοντο<br>Αὐσονίης ἀκτὰς Τυρσηνίδας εἰσορόωντες·<br>ἷξον δ’ Αἰαίης λιμένα κλυτόν· ἐκ δ’ ἄρα νηὸς<br>πείσματ’ ἐπ’ ἠιόνων σχεδόθεν βάλον. ἔνθα δὲ Κίρκην<br>εὗρον ἁλὸς νοτίδεσσι κάρη ἐπιφαιδρύνουσαν·<br>τοῖον γὰρ νυχίοισιν ὀνείρασιν ἐπτοίητο.<br>αἵματί οἱ θάλαμοί τε καὶ ἕρκεα πάντα δόμοιο<br>μύρεσθαι δόκεον· φλὸξ δ’ ἀθρόα φάρμακ’ ἔδαπτεν,<br>οἷσι πάρος ξείνους θέλγ’ ἀνέρας, ὅστις ἵκοιτο·<br>τὴν δ’ αὐτὴ φονίῳ σβέσεν αἵματι πορφύρουσαν,<br>χερσὶν ἀφυσσαμένη· λῆξεν δ’ ὀλοοῖο φόβοιο.<br>τῶ καὶ ἐπιπλομένης ἠοῦς νοτίδεσσι θαλάσσης<br>ἐγρομένη πλοκάμους τε καὶ εἵματα φαιδρύνεσκεν.<br>θῆρες δ’ οὐ θήρεσσιν ἐοικότες ὠμηστῇσιν,<br>οὐδὲ μὲν οὐδ’ ἄνδρεσσιν ὁμὸν δέμας, ἄλλο δ’ ἀπ’ ἄλλων<br>συμμιγέες μελέων, κίον ἀθρόοι, ἠύτε μῆλα<br>ἐκ σταθμῶν ἅλις εἶσιν ὀπηδεύοντα νομῆι.<br>τοίους καὶ προτέρης ἐξ ἰλύος ἐβλάστησε<br>χθὼν αὐτὴ μικτοῖσιν ἀρηρεμένους μελέεσσιν,<br>οὔπω διψαλέῳ μάλ’ ὑπ’ ἠέρι πιληθεῖσα,<br>οὐδέ πω ἀζαλέοιο βολαῖς τόσον ἠελίοιο<br>ἰκμάδας αἰνυμένη· τὰ δ’ ἐπὶ στίχας ἤγαγεν αἰὼν<br>συγκρίνας· τὼς οἵγε φυὴν ἀίδηλοι ἕποντο.<br>ἥρωας δ’ ἕλε θάμβος ἀπείριτον· αἶψα δ’ ἕκαστος<br>Κίρκης εἴς τε φυήν, εἴς τ’ ὄμματα παπταίνοντες<br>ῥεῖα κασιγνήτην φάσαν ἔμμεναι Αἰήταο.", "st": "4.659"}, {"sp": "N", "t": "ἡ δ’ ὅτε δὴ νυχίων ἀπὸ δείματα πέμψεν ὀνείρων,<br>αὐτίκ’ ἔπειτ’ ἄψορρον ἀπέστιχε· τοὺς δ’ ἅμ’ ἕπεσθαι,<br>χειρὶ καταρρέξασα, δολοφροσύνῃσιν ἄνωγεν.<br>ἔνθ’ ἤτοι πληθὺς μὲν ἐφετμαῖς Αἰσονίδαο<br>μίμνεν ἀπηλεγέως· ὁ δ’ ἐρύσσατο Κολχίδα κούρην.<br>ἄμφω δ’ ἑσπέσθην αὐτὴν ὁδόν, ἔστ’ ἀφίκοντο<br>Κίρκης ἐς μέγαρον· τοὺς δ’ ἐν λιπαροῖσι κέλευεν<br>ἥγε θρόνοις ἕζεσθαι, ἀμηχανέουσα κιόντων.<br>τὼ δ’ ἄνεῳ καὶ ἄναυδοι ἐφ’ ἑστίῃ ἀίξαντε<br>ἵζανον, ἥ τε δίκη λυγροῖς ἱκέτῃσι τέτυκται,<br>ἡ μὲν ἐπ’ ἀμφοτέραις θεμένη χείρεσσι μέτωπα,<br>αὐτὰρ ὁ κωπῆεν μέγα φάσγανον ἐν χθονὶ πήξας,<br>ᾧπέρ τ’ Αἰήταο πάιν κτάνεν· οὐδέ ποτ’ ὄσσε<br>ἰθὺς ἐνὶ βλεφάροισιν ἀνέσχεθον. αὐτίκα δ’ ἔγνω<br>Κίρκη φύξιον οἶτον ἀλιτροσύνας τε φόνοιο.<br>τῶ καὶ ὀπιζομένη Ζηνὸς θέμιν Ἱκεσίοιο,<br>ὃς μέγα μὲν κοτέει, μέγα δ’ ἀνδροφόνοισιν ἀρήγει,<br>ῥέζε θυηπολίην, οἵῃ τ’ ἀπολυμαίνονται<br>νηλειεῖς ἱκέται, ὅτ’ ἐφέστιοι ἀντιόωσιν.<br>πρῶτα μὲν ἀτρέπτοιο λυτήριον ἥγε φόνοιο<br>τειναμένη καθύπερθε συὸς τέκος, ἧς ἔτι μαζοὶ<br>πλήμμυρον λοχίης ἐκ νηδύος, αἵματι χεῖρας<br>τέγγεν, ἐπιτμήγουσα δέρην· αὖτις δὲ καὶ ἄλλοις<br>μείλισσεν χύτλοισι, καθάρσιον ἀγκαλέουσα<br>Ζῆνα, παλαμναίων τιμήορον ἱκεσιάων.<br>καὶ τὰ μὲν ἀθρόα πάντα δόμων ἐκ λύματ’ ἔνεικαν<br>νηιάδες πρόπολοι, ταί οἱ πόρσυνον ἕκαστα.<br>ἡ δ’ εἴσω πελάνους μείλικτρά τε νηφαλίῃσιν<br>καῖεν ἐπ’ εὐχωλῇσι παρέστιος, ὄφρα χόλοιο<br>σμερδαλέας παύσειεν Ἐρινύας, ἠδὲ καὶ αὐτὸς<br>εὐμειδής τε πέλοιτο καὶ ἤπιος ἀμφοτέροισιν,<br>εἴτ’ οὖν ὀθνείῳ μεμιασμένοι αἵματι χεῖρας,<br>εἴτε καὶ ἐμφύλῳ προσκηδέες ἀντιόωσιν.", "st": "4.685"}, {"sp": "N", "t": "αὐτὰρ ἐπεὶ μάλα πάντα πονήσατο, δή τότ’ ἔπειτα<br>εἷσεν ἐπὶ ξεστοῖσιν ἀναστήσασα θρόνοισιν,<br>καὶ δ’ αὐτὴ πέλας ἷζεν ἐνωπαδίς. αἶψα δὲ μύθῳ<br>χρειὼ ναυτιλίην τε διακριδὸν ἐξερέεινεν.<br>ἠδ’ ὁπόθεν μετὰ γαῖαν ἑὴν καὶ δώματ’ ἰόντες<br>αὔτως ἱδρύνθησαν ἐφέστιοι. ἦ γὰρ ὀνείρων<br>μνῆστις ἀεικελίη δῦνεν φρένας ὁρμαίνουσαν·<br>ἵετο δ’ αὖ κούρης ἐμφύλιον ἴδμεναι ὀμφήν,<br>αὐτίχ’ ὅπως ἐνόησεν ἀπ’ οὔδεος ὄσσε βαλοῦσαν.<br>πᾶσα γὰρ Ἠελίου γενεὴ ἀρίδηλος ἰδέσθαι<br>ἦεν, ἐπεὶ βλεφάρων ἀποτηλόθι μαρμαρυγῇσιν<br>οἷόν τε χρυσέην ἀντώπιον ἵεσαν αἴγλην.<br>ἡ δ’ ἄρα τῇ τὰ ἕκαστα διειρομένῃ κατέλεξεν,<br>Κολχίδα γῆρυν ἱεῖσα, βαρύφρονος Αἰήταο<br>κούρη μειλιχίως, ἠμὲν στόλον ἠδὲ κελεύθους<br>ἡρώων, ὅσα τ’ ἀμφὶ θοοῖς ἐμόγησαν ἀέθλοις,<br>ὥς τε κασιγνήτης πολυκηδέος ἤλιτε βουλαῖς,<br>ὥς τ’ ἀπονόσφιν ἄλυξεν ὑπέρβια δείματα πατρὸς<br>σὺν παισὶν Φρίξοιο· φόνον δ’ ἀλέεινεν ἐνισπεῖν<br>Ἀψύρτου. τὴν δ’ οὔτι νόῳ λάθεν· ἀλλὰ καὶ ἔμπης<br>μυρομένην ἐλέαιρεν, ἔπος δ’ ἐπὶ τοῖον ἔειπεν·", "st": "4.718"}, {"sp": "N", "t": "“σχετλίη, ἦ ῥα κακὸν καὶ ἀεικέα μήσαο νόστον.<br>ἔλπομαι οὐκ ἐπὶ δήν σε βαρὺν χόλον Αἰήταο<br>ἐκφυγέειν· τάχα δ’ εἶσι καὶ Ἑλλάδος ἤθεα γαίης<br>τισόμενος φόνον υἷος, ὅτ’ ἄσχετα ἔργ’ ἐτέλεσσας.<br>ἀλλ’ ἐπεὶ οὖν ἱκέτις καὶ ὁμόγνιος ἔπλευ ἐμεῖο,<br>ἄλλο μὲν οὔτι κακὸν μητίσομαι ἐνθάδ’ ἰούσῃ·<br>ἔρχεο δ’ ἐκ μεγάρων ξείνῳ συνοπηδὸς ἐοῦσα,<br>ὅντινα τοῦτον ἄιστον ἀείραο πατρὸς ἄνευθεν·<br>μηδέ με γουνάσσηαι ἐφέστιος, οὐ γὰρ ἔγωγε<br>αἰνήσω βουλάς τε σέθεν καὶ ἀεικέα φύξιν.”", "st": "4.739"}, {"sp": "N", "t": "ὧς φάτο· τὴν δ’ ἀμέγαρτον ἄχος λάβεν· ἀμφὶ δὲ πέπλον<br>ὀφθαλμοῖσι βαλοῦσα γόον χέεν, ὄφρα μιν ἥρως<br>χειρὸς ἐπισχόμενος μεγάρων ἐξῆγε θύραζε<br>δείματι παλλομένην· λεῖπον δ’ ἀπὸ δώματα Κίρκης.", "st": "4.749"}, {"sp": "N", "t": "οὐδ’ ἄλοχον Κρονίδαο Διὸς λάθον· ἀλλά οἱ Ἶρις<br>πέφραδεν, εὖτ’ ἐνόησεν ἀπὸ μεγάροιο κιόντας.<br>αὐτὴ γάρ μιν ἄνωγε δοκευέμεν, ὁππότε νῆα<br>στείχοιεν· τὸ καὶ αὖτις ἐποτρύνουσ’ ἀγόρευεν·", "st": "4.753"}, {"sp": "N", "t": "“Ἶρι φίλη, νῦν, εἴ ποτ’ ἐμὰς ἐτέλεσσας ἐφετμάς,<br>εἰ δ’ ἄγε λαιψηρῇσι μετοιχομένη πτερύγεσσιν,<br>δεῦρο Θέτιν μοι ἄνωχθι μολεῖν ἁλὸς ἐξανιοῦσαν.<br>κείνης γὰρ χρειώ με κιχάνεται. αὐτὰρ ἔπειτα<br>ἐλθεῖν εἰς ἀκτάς, ὅθι τ’ ἄκμονες Ἡφαίστοιο<br>χάλκειοι στιβαρῇσιν ἀράσσονται τυπίδεσσιν·<br>εἰπὲ δὲ κοιμῆσαι φύσας πυρός, εἰσόκεν Ἀργὼ<br>τάσγε παρεξελάσῃσιν. ἀτὰρ καὶ ἐς Αἴολον ἐλθεῖν,<br>Αἴολον, ὅς τ’ ἀνέμοις αἰθρηγενέεσσιν ἀνάσσει·<br>καὶ δὲ τῷ εἰπέμεναι τὸν ἐμὸν νόον, ὥς κεν ἀήτας<br>πάντας ἀπολλήξειεν ὑπ’ ἠέρι, μηδέ τις αὔρη<br>τρηχύνοι πέλαγος· Ζεφύρου γε μὲν οὖρος ἀήτω,<br>ὄφρ’ οἵγ’ Ἀλκινόου Φαιηκίδα νῆσον ἵκωνται.”", "st": "4.757"}, {"sp": "N", "t": "ὧς ἔφατ’· αὐτίκα δ’ Ἶρις ἀπ’ Οὐλύμποιο θοροῦσα<br>τέμνε, τανυσσαμένη κοῦφα πτερά. δῦ δ’ ἐνὶ πόντῳ<br>Αἰγαίῳ, τόθι πέρ τε δόμοι Νηρῆος ἔασιν.<br>πρώτην δ’ εἰσαφίκανε Θέτιν, καὶ ἐπέφραδε μῦθον<br>Ἥρης ἐννεσίῃς, ὦρσέν τέ μιν εἰς ἓ νέεσθαι.<br>δεύτερα δ’ εἰς Ἥφαιστον ἐβήσατο· παῦσε δὲ τόνγε<br>ῥίμφα σιδηρείων τυπίδων· ἔσχοντο δ’ ἀυτμῆς<br>αἰθαλέοι πρηστῆρες. ἀτὰρ τρίτον εἰσαφίκανεν<br>Αἴολον Ἱππότεω παῖδα κλυτόν. ὄφρα δὲ καὶ τῷ<br>ἀγγελίην φαμένη θοὰ γούνατα παῦσεν ὁδοῖο,<br>τόφρα Θέτις Νηρῆα κασιγνήτας τε λιποῦσα<br>ἐξ ἁλὸς Οὔλυμπόνδε θεὰν μετεκίαθεν Ἥρην·<br>ἡ δέ μιν ἆσσον ἑοῖο παρεῖσέ τε, φαῖνέ τε μῦθον·", "st": "4.770"}, {"sp": "N", "t": "“κέκλυθι νῦν, Θέτι δῖα, τά τοι ἐπιέλδομ’ ἐνισπεῖν.<br>οἶσθα μέν, ὅσσον ἐμῇσιν ἐνὶ φρεσὶ τίεται ἥρως<br>Αἰσονίδης, οἱ δ’ ἄλλοι ἀοσσητῆρες ἀέθλου,<br>οἵως τέ σφ’ ἐσάωσα διὰ πλαγκτὰς περόωντας<br>πέτρας, ἔνθα πάρος δειναὶ βρομέουσι θύελλαι,<br>κύματά τε σκληρῇσι περιβλύει σπιλάδεσσιν.<br>νῦν δὲ παρὰ Σκύλλης σκόπελον μέγαν ἠδὲ Χάρυβδιν<br>δεινὸν ἐρευγομένην δέχεται ὁδός. ἀλλά σε γὰρ δὴ<br>ἐξέτι νηπυτίης αὐτὴ τρέφον ἠδ’ ἀγάπησα<br>ἔξοχον ἀλλάων, αἵ τ’ εἰν ἁλὶ ναιετάουσιν,<br>οὕνεκεν οὐκ ἔτλης εὐνῇ Διὸς ἱεμένοιο<br>λέξασθαι. κείνῳ γὰρ ἀεὶ τάδε ἔργα μέμηλεν,<br>ἠὲ σὺν ἀθανάταις ἠὲ θνητῇσιν ἰαύειν.<br>ἀλλ’ ἐμὲ αἰδομένη καὶ ἐνὶ φρεσὶ δειμαίνουσα,<br>ἠλεύω· ὁ δ’ ἔπειτα πελώριον ὅρκον ὄμοσσεν,<br>μήποτέ σ’ ἀθανάτοιο θεοῦ καλέεσθαι ἄκοιτιν.<br>ἔμπης δ’ οὐ μεθίεσκεν ὀπιπεύων ἀέκουσαν,<br>εἰσότε οἱ πρέσβειρα Θέμις κατέλεξεν ἅπαντα,<br>ὡς δή τοι πέπρωται ἀμείνονα πατρὸς ἑοῖο<br>παῖδα τεκεῖν· τῶ καί σε λιλαιόμενος μεθέηκεν,<br>δείματι, μή τις ἑοῦ ἀντάξιος ἄλλος ἀνάσσοι<br>ἀθανάτων, ἀλλ’ αἰὲν ἑὸν κράτος εἰρύοιτο.<br>αὐτὰρ ἐγὼ τὸν ἄριστον ἐπιχθονίων πόσιν εἶναι<br>δῶκά τοι, ὄφρα γάμου θυμηδέος ἀντιάσειας,<br>τέκνα τε φιτύσαιο· θεοὺς δ’ ἐς δαῖτ’ ἐκάλεσσα<br>πάντας ὁμῶς· αὐτὴ δὲ σέλας χείρεσσιν ἀνέσχον<br>νυμφίδιον, κείνης ἀγανόφρονος εἵνεκα τιμῆς.<br>ἀλλ’ ἄγε καί τινά τοι νημερτέα μῦθον ἐνίψω.<br>εὖτ’ ἂν ἐς Ἠλύσιον πεδίον τεὸς υἱὸς ἵκηται,<br>ὃν δὴ νῦν Χείρωνος ἐν ἤθεσι Κενταύροιο<br>νηιάδες κομέουσι τεοῦ λίπτοντα γάλακτος,<br>χρειώ μιν κούρης πόσιν ἔμμεναι Αἰήταο<br>Μηδείης· σὺ δ’ ἄρηγε νυῷ ἑκυρή περ ἐοῦσα,<br>ἠδ’ αὐτῷ Πηλῆι. τί τοι χόλος ἐστήρικται;<br>ἀάσθη. καὶ γάρ τε θεοὺς ἐπινίσσεται ἄτη.<br>ναὶ μὲν ἐφημοσύνῃσιν ἐμαῖς Ἥφαιστον ὀίω<br>λωφήσειν πρήσοντα πυρὸς μένος, Ἱπποτάδην δὲ<br>Αἴολον ὠκείας ἀνέμων ἄικας ἐρύξειν,<br>νόσφιν ἐυσταθέος ζεφύρου, τείως κεν ἵκωνται<br>Φαιήκων λιμένας· σὺ δ’ ἀκηδέα μήδεο νόστον.<br>δεῖμα δέ τοι πέτραι καὶ ὑπέρβια κύματ’ ἔασιν<br>μοῦνον, ἅ κεν τρέψαιο κασιγνήτῃσι σὺν ἄλλαις.<br>μηδὲ σύγ’ ἠὲ Χάρυβδιν ἀμηχανέοντας ἐάσῃς<br>ἐσβαλέειν, μὴ πάντας ἀναβρόξασα φέρῃσιν,<br>ἠὲ παρὰ Σκύλλης στυγερὸν κευθμῶνα νέεσθαι,<br>Σκύλλης Αὐσονίης ὀλοόφρονος, ἣν τέκε Φόρκυι<br>νυκτιπόλος Ἑκάτη, τήν τε κλείουσι Κράταιιν,<br>μή πως σμερδαλέῃσιν ἐπαΐξασα γένυσσιν<br>λεκτοὺς ἡρώων δηλήσεται. ἀλλ’ ἔχε νῆα<br>κεῖσ’, ὅθι περ τυτθή γε παραίβασις ἔσσετ’ ὀλέθρου.”", "st": "4.783"}, {"sp": "N", "t": "ὧς φάτο· τὴν δὲ Θέτις τοίῳ προσελέξατο μύθῳ·<br>“εἰ μὲν δὴ μαλεροῖο πυρὸς μένος ἠδὲ θύελλαι<br>ζαχρηεῖς λήξουσιν ἐτήτυμον, ἦ τ’ ἂν ἔγωγε<br>θαρσαλέη φαίην, καὶ κύματος ἀντιόωντος<br>νῆα σαωσέμεναι, ζεφύρου λίγα κινυμένοιο.<br>ἀλλ’ ὥρη δολιχήν τε καὶ ἄσπετον οἶμον ὁδεύειν,<br>ὄφρα κασιγνήτας μετελεύσομαι, αἵ μοι ἀρωγοὶ<br>ἔσσονται, καὶ νηὸς ὅθι πρυμνήσι’ ἀνῆπται,<br>ὥς κεν ὑπηῷοι μνησαίατο νόστον ἑλέσθαι.”", "st": "4.833"}, {"sp": "N", "t": "ἦ, καὶ ἀναΐξασα κατ’ αἰθέρος ἔμπεσε δίναις<br>κυανέου πόντοιο· κάλει δ’ ἐπαμυνέμεν ἄλλας<br>αὐτοκασιγνήτας Νηρηίδας· αἱ δ’ ἀίουσαι<br>ἤντεον ἀλλήλῃσι· Θέτις δ’ ἀγόρευεν ἐφετμὰς<br>Ἥρης· αἶψα δ’ ἴαλλε μετ’ Αὐσονίην ἅλα πάσας.<br>αὐτὴ δ’ ὠκυτέρη ἀμαρύγματος ἠὲ βολάων<br>ἠελίου, ὅτ’ ἄνεισι περαίης ὑψόθι γαίης,<br>σεύατ’ ἴμεν λαιψηρὰ δι’ ὕδατος, ἔστ’ ἀφίκανεν<br>ἀκτὴν Αἰαίην Τυρσηνίδος ἠπείροιο.<br>τοὺς δ’ εὗρεν παρὰ νηὶ σόλῳ ῥιπῇσί τ’ ὀιστῶν<br>τερπομένους· ἡ δ’ ἆσσον ὀρεξαμένη χερὸς ἄκρης<br>Αἰακίδεω Πηλῆος· ὁ γάρ ῥά οἱ ἦεν ἀκοίτης·<br>οὐδέ τις εἰσιδέειν δύνατ’ ἔμπεδον, ἀλλ’ ἄρα τῷγε<br>οἴῳ ἐν ὀφθαλμοῖσιν ἐείσατο, φώνησέν τε·", "st": "4.842"}, {"sp": "N", "t": "“μηκέτι νῦν ἀκταῖς Τυρσηνίσιν ἧσθε μένοντες,<br>ἠῶθεν δὲ θοῆς πρυμνήσια λύετε νηός,<br>Ἥρῃ πειθόμενοι ἐπαρηγόνι. τῆς γὰρ ἐφετμῇς<br>πασσυδίῃ κοῦραι Νηρηίδες ἀντιόωσιν,<br>νῆα διὲκ πέτρας, αἵ τε Πλαγκταὶ καλέονται,<br>ῥυσόμεναι. κείνη γὰρ ἐναίσιμος ὔμμι κέλευθος.<br>ἀλλὰ σὺ μή τῳ ἐμὸν δείξῃς δέμας, εὖτ’ ἂν ἴδηαι<br>ἀντομένην σὺν τῇσι· νόῳ δ’ ἔχε, μή με χολώσῃς<br>πλεῖον ἔτ’, ἢ τὸ πάροιθεν ἀπηλεγέως ἐχόλωσας.”", "st": "4.856"}, {"sp": "N", "t": "ἦ, καὶ ἔπειτ’ ἀίδηλος ἐδύσατο βένθεα πόντου·<br>τὸν δ’ ἄχος αἰνὸν ἔτυψεν, ἐπεὶ πάρος οὐκέτ’ ἰοῦσαν<br>ἔδρακεν, ἐξότε πρῶτα λίπεν θάλαμόν τε καὶ εὐνὴν<br>χωσαμένη Ἀχιλῆος ἀγαυοῦ νηπιάχοντος.<br>ἡ μὲν γὰρ βροτέας αἰεὶ περὶ σάρκας ἔδαιεν<br>νύκτα διὰ μέσσην φλογμῷ πυρός· ἤματα δ’ αὖτε<br>ἀμβροσίῃ χρίεσκε τέρεν δέμας, ὄφρα πέλοιτο<br>ἀθάνατος, καί οἱ στυγερὸν χροῒ γῆρας ἀλάλκοι.<br>αὐτὰρ ὅγ’ ἐξ εὐνῆς ἀνεπάλμενος εἰσενόησεν<br>παῖδα φίλον σπαίροντα διὰ φλογός· ἧκε δ’ ἀυτὴν<br>σμερδαλέην ἐσιδών, μέγα νήπιος· ἡ δ’ ἀίουσα<br>τὸν μὲν ἄρ’ ἁρπάγδην χαμάδις βάλε κεκληγῶτα,<br>αὐτὴ δὲ πνοιῇ ἰκέλη δέμας, ἠύτ’ ὄνειρος,<br>βῆ ῥ’ ἴμεν ἐκ μεγάροιο θοῶς, καὶ ἐσήλατο πόντον<br>χωσαμένη· μετὰ δ’ οὔτι παλίσσυτος ἵκετ’ ὀπίσσω.<br>τῶ μιν ἀμηχανίη δῆσεν φρένας· ἀλλὰ καὶ ἔμπης<br>πᾶσαν ἐφημοσύνην Θέτιδος μετέειπεν ἑταίροις.<br>οἱ δ’ ἄρα μεσσηγὺς λῆξαν καὶ ἔπαυσαν ἀέθλους<br>ἐσσυμένως, δόρπον τε χαμεύνας τ’ ἀμφεπένοντο,<br>τῇς ἔνι δαισάμενοι νύκτ’ ἄεσαν, ὡς τὸ πάροιθεν.", "st": "4.865"}, {"sp": "N", "t": "ἦμος δ’ ἄκρον ἔβαλλε φαεσφόρος οὐρανὸν Ἠώς,<br>δὴ τότε λαιψηροῖο κατηλυσίῃ ζεφύροιο<br>βαῖνον ἐπὶ κληῖδας ἀπὸ χθονός· ἐκ δὲ βυθοῖο<br>εὐναίας εἷλκον περιγηθέες ἄλλα τε πάντα<br>ἄρμενα μηρύοντο κατὰ χρέος· ὕψι δὲ λαῖφος<br>εἴρυσσαν τανύσαντες ἐν ἱμάντεσσι κεραίης.<br>νῆα δ’ ἐυκραὴς ἄνεμος φέρεν. αἶψα δὲ νῆσον<br>καλήν, Ἀνθεμόεσσαν ἐσέδρακον, ἔνθα λίγειαι<br>Σειρῆνες σίνοντ’ Ἀχελωίδες ἡδείῃσιν<br>θέλγουσαι μολπῇσιν, ὅτις παρὰ πεῖσμα βάλοιτο.<br>τὰς μὲν ἄρ’ εὐειδὴς Ἀχελωίῳ εὐνηθεῖσα<br>γείνατο Τερψιχόρη, Μουσέων μία· καί ποτε Δηοῦς<br>θυγατέρ’ ἰφθίμην ἀδμῆτ’ ἔτι πορσαίνεσκον<br>ἄμμιγα μελπόμεναι· τότε δ’ ἄλλο μὲν οἰωνοῖσιν,<br>ἄλλο δὲ παρθενικῇς ἐναλίγκιαι ἔσκον ἰδέσθαι.<br>αἰεὶ δ’ εὐόρμου δεδοκημέναι ἐκ περιωπῆς<br>ἦ θαμὰ δὴ πολέων μελιηδέα νόστον ἕλοντο,<br>τηκεδόνι φθινύθουσαι· ἀπηλεγέως δ’ ἄρα καὶ τοῖς<br>ἵεσαν ἐκ στομάτων ὄπα λείριον. οἱ δ’ ἀπὸ νηὸς<br>ἤδη πείσματ’ ἔμελλον ἐπ’ ἠιόνεσσι βαλέσθαι,<br>εἰ μὴ ἄρ’ Οἰάγροιο πάις Θρηίκιος Ὀρφεὺς<br>Βιστονίην ἐνὶ χερσὶν ἑαῖς φόρμιγγα τανύσσας<br>κραιπνὸν ἐυτροχάλοιο μέλος κανάχησεν ἀοιδῆς,<br>ὄφρ’ ἄμυδις κλονέοντος ἐπιβρομέωνται ἀκουαὶ<br>κρεγμῷ· παρθενικὴν δ’ ἐνοπὴν ἐβιήσατο φόρμιγξ.<br>νῆα δ’ ὁμοῦ ζέφυρός τε καὶ ἠχῆεν φέρε κῦμα<br>πρυμνόθεν ὀρνύμενον· ταὶ δ’ ἄκριτον ἵεσαν αὐδήν.<br>ἀλλὰ καὶ ὧς Τελέοντος ἐὺς πάις, οἶος ἑταίρων<br>προφθάμενος, ξεστοῖο κατὰ ζυγοῦ ἔνθορε πόντῳ<br>Βούτης, Σειρήνων λιγυρῇ ὀπὶ θυμὸν ἰανθείς·<br>νῆχε δὲ πορφυρέοιο δι’ οἴδματος, ὄφρ’ ἐπιβαίη,<br>σχέτλιος. ἦ τέ οἱ αἶψα καταυτόθι νόστον ἀπηύρων,<br>ἀλλά μιν οἰκτείρασα θεὰ Ἔρυκος μεδέουσα<br>Κύπρις ἔτ’ ἐν δίναις ἀνερέψατο, καί ῥ’ ἐσάωσεν<br>πρόφρων ἀντομένη Λιλυβηίδα ναιέμεν ἄκρην.<br>οἱ δ’ ἄχεϊ σχόμενοι τὰς μὲν λίπον, ἄλλα δ’ ὄπαζον<br>κύντερα μιξοδίῃσιν ἁλὸς ῥαιστήρια νηῶν.", "st": "4.885"}, {"sp": "N", "t": "τῇ μὲν γὰρ Σκύλλης λισσὴ προυφαίνετο πέτρη·<br>τῇ δ’ ἄμοτον βοάασκεν ἀναβλύζουσα Χάρυβδις·<br>ἄλλοθι δὲ Πλαγκταὶ μεγάλῳ ὑπὸ κύματι πέτραι<br>ῥόχθεον, ᾗχι πάροιθεν ἀπέπτυεν αἰθομένη φλὸξ<br>ἄκρων ἐκ σκοπέλων, πυριθαλπέος ὑψόθι πέτρης,<br>καπνῷ δ’ ἀχλυόεις αἰθὴρ πέλεν, οὐδέ κεν αὐγὰς<br>ἔδρακες ἠελίοιο. τότ’ αὖ λήξαντος ἀπ’ ἔργων<br>Ἡφαίστου θερμὴν ἔτι κήκιε πόντος ἀυτμήν.<br>ἔνθα σφιν κοῦραι Νηρηίδες ἄλλοθεν ἄλλαι<br>ἤντεον· ἡ δ’ ὄπιθεν πτέρυγος θίγε πηδαλίοιο<br>δῖα Θέτις, Πλαγκτῇσιν ἐνὶ σπιλάδεσσιν ἐρύσσαι.<br>ὡς δ’ ὁπόταν δελφῖνες ὑπὲξ ἁλὸς εὐδιόωντες<br>σπερχομένην ἀγεληδὸν ἑλίσσωνται περὶ νῆα,<br>ἄλλοτε μὲν προπάροιθεν ὁρώμενοι, ἄλλοτ’ ὄπισθεν,<br>ἄλλοτε παρβολάδην, ναύτῃσι δὲ χάρμα τέτυκται·<br>ὧς αἱ ὑπεκπροθέουσαι ἐπήτριμοι εἱλίσσοντο<br>Ἀργῴῃ περὶ νηί, Θέτις δ’ ἴθυνε κέλευθον.<br>καί ῥ’ ὅτε δὴ Πλαγκτῇσιν ἐνιχρίμψεσθαι ἔμελλον,<br>αὐτίκ’ ἀνασχόμεναι λευκοῖς ἐπὶ γούνασι πέζας,<br>ὑψοῦ ἐπ’ αὐτάων σπιλάδων καὶ κύματος ἀγῆς<br>ῥώοντ’ ἔνθα καὶ ἔνθα διασταδὸν ἀλλήλῃσιν.<br>τὴν δὲ παρηορίην κόπτεν ῥόος· ἀμφὶ δὲ κῦμα<br>λάβρον ἀειρόμενον πέτραις ἐπικαχλάζεσκεν,<br>αἵ θ’ ὁτὲ μὲν κρημνοῖς ἐναλίγκιαι ἠέρι κῦρον,<br>ἄλλοτε δὲ βρύχιαι νεάτῳ ὑπὸ πυθμένι πόντου<br>ἠρήρειν, τὸ δὲ πολλὸν ὑπείρεχεν ἄγριον οἶδμα.<br>αἱ δ’, ὥστ’ ἠμαθόεντος ἐπισχεδὸν αἰγιαλοῖο<br>παρθενικαί, δίχα κόλπον ἐπ’ ἰξύας εἱλίξασαι<br>σφαίρῃ ἀθύρουσιν περιηγέι· αἱ μὲν ἔπειτα<br>ἄλλη ὑπ’ ἐξ ἄλλης δέχεται καὶ ἐς ἠέρα πέμπει<br>ὕψι μεταχρονίην· ἡ δ’ οὔποτε πίλναται οὔδει·<br>ὧς αἱ νῆα θέουσαν ἀμοιβαδὶς ἄλλοθεν ἄλλη<br>πέμπε διηερίην ἐπὶ κύμασιν, αἰὲν ἄπωθεν<br>πετράων· περὶ δέ σφιν ἐρευγόμενον ζέεν ὕδωρ.<br>τὰς δὲ καὶ αὐτὸς ἄναξ κορυφῆς ἔπι λισσάδος ἄκρης<br>ὀρθὸς ἐπὶ στελεῇ τυπίδος βαρὺν ὦμον ἐρείσας<br>Ἥφαιστος θηεῖτο, καὶ αἰγλήεντος ὕπερθεν<br>οὐρανοῦ ἑστηυῖα Διὸς δάμαρ· ἀμφὶ δ’ Ἀθήνῃ<br>βάλλε χέρας, τοῖόν μιν ἔχεν δέος εἰσορόωσαν.<br>ὅσση δ’ εἰαρινοῦ μηκύνεται ἤματος αἶσα,<br>τοσσάτιον μογέεσκον ἐπὶ χρόνον, ὀχλίζουσαι<br>νῆα διὲκ πέτρας πολυηχέας· οἱ δ’ ἀνέμοιο<br>αὖτις ἐπαυρόμενοι προτέρω θέον· ὦκα δ’ ἄμειβον<br>Θρινακίης λειμῶνα, βοῶν τροφὸν Ἠελίοιο.<br>ἔνθ’ αἱ μὲν κατὰ βένθος ἀλίγκιαι αἰθυίῃσιν<br>δῦνον, ἐπεί ῥ’ ἀλόχοιο Διὸς πόρσυνον ἐφετμάς.<br>τοὺς δ’ ἄμυδις βληχή τε δι’ ἠέρος ἵκετο μήλων,<br>μυκηθμός τε βοῶν αὐτοσχεδὸν οὔατ’ ἔβαλλεν.<br>καὶ τὰ μὲν ἑρσήεντα κατὰ δρία ποιμαίνεσκεν<br>ὁπλοτέρη Φαέθουσα θυγατρῶν Ἠελίοιο,<br>ἀργύρεον χαῖον παλάμῃ ἔνι πηχύνουσα·<br>Λαμπετίη δ’ ἐπὶ βουσὶν ὀρειχάλκοιο φαεινοῦ<br>πάλλεν ὀπηδεύουσα καλαύροπα. τὰς δὲ καὶ αὐτοὶ<br>βοσκομένας ποταμοῖο παρ’ ὕδασιν εἰσορόωντο<br>ἂμ πεδίον καὶ ἕλος λειμώνιον· οὐδέ τις ἦεν<br>κυανέη μετὰ τῇσι δέμας, πᾶσαι δὲ γάλακτι<br>εἰδόμεναι, χρυσέοισι κεράασι κυδιάασκον.<br>καὶ μὲν τὰς παράμειβον ἐπ’ ἤματι· νυκτὶ δ’ ἰούσῃ<br>πεῖρον ἁλὸς μέγα λαῖτμα κεχαρμένοι, ὄφρα καὶ αὖτις<br>Ἠὼς ἠριγενὴς φέγγος βάλε νισσομένοισιν.", "st": "4.922"}, {"sp": "N", "t": "ἔστι δέ τις πορθμοῖο παροιτέρη Ἰονίοιο<br>ἀμφιλαφὴς πίειρα Κεραυνίῃ εἰν ἁλὶ νῆσος,<br>ᾗ ὕπο δὴ κεῖσθαι δρέπανον φάτις—ἵλατε Μοῦσαι,<br>οὐκ ἐθέλων ἐνέπω προτέρων ἔπος—ᾧ ἀπὸ πατρὸς<br>μήδεα νηλειῶς ἔταμεν Κρόνος· οἱ δέ ἑ Δηοῦς<br>κλείουσι χθονίης καλαμητόμον ἔμμεναι ἅρπην.<br>Δηὼ γὰρ κείνῃ ἐνὶ δή ποτε νάσσατο γαίῃ,<br>Τιτῆνας δ’ ἔδαε στάχυν ὄμπνιον ἀμήσασθαι,<br>Μάκριδα φιλαμένη. Δρεπάνη τόθεν ἐκλήισται<br>οὔνομα, Φαιήκων ἱερὴ τροφός· ὧς δὲ καὶ αὐτοὶ<br>αἵματος Οὐρανίοιο γένος Φαίηκες ἔασιν.<br>τοὺς Ἀργὼ πολέεσσιν ἐνισχομένη καμάτοισιν<br>Θρινακίης αὔρῃς ἵκετ’ ἐξ ἁλός· οἱ δ’ ἀγανῇσιν<br>Ἀλκίνοος λαοί τε θυηπολίῃσιν ἰόντας<br>δειδέχατ’ ἀσπασίως· ἐπὶ δέ σφισι καγχαλάασκεν<br>πᾶσα πόλις· φαίης κεν ἑοῖς ἐπὶ παισὶ γάνυσθαι.<br>καὶ δ’ αὐτοὶ ἥρωες ἀνὰ πληθὺν κεχάροντο,<br>τῷ ἴκελοι, οἷόν τε μεσαιτάτῃ ἐμβεβαῶτες<br>Αἱμονίῃ· μέλλον δὲ βοῇ ἔνι θωρήξεσθαι·<br>ὧδε μάλ’ ἀγχίμολον στρατὸς ἄσπετος ἐξεφαάνθη<br>Κόλχων, οἳ Πόντοιο κατὰ στόμα καὶ διὰ πέτρας<br>Κυανέας μαστῆρες ἀριστήων ἐπέρησαν.<br>Μήδειαν δ’ ἔξαιτον ἑοῦ ἐς πατρὸς ἄγεσθαι<br>ἵεντ’ ἀπροφάτως, ἠὲ στονόεσσαν ἀυτὴν<br>νωμήσειν χαλεπῇσιν ὁμόκλεον ἀτροπίῃσιν<br>αὖθί τε καὶ μετέπειτα σὺν Αἰήταο κελεύθῳ.<br>ἀλλά σφεας κατέρυκεν ἐπειγομένους πολέμοιο<br>κρείων Ἀλκίνοος. λελίητο γὰρ ἀμφοτέροισιν<br>δηιοτῆτος ἄνευθεν ὑπέρβια νείκεα λῦσαι.<br>κούρη δ’ οὐλομένῳ ὑπὸ δείματι πολλὰ μὲν αὐτοὺς<br>Αἰσονίδεω ἑτάρους μειλίσσετο, πολλὰ δὲ χερσὶν<br>Ἀρήτης γούνων ἀλόχου θίγεν Ἀλκινόοιο·", "st": "4.982"}, {"sp": "N", "t": "“γουνοῦμαι, βασίλεια· σὺ δ’ ἵλαθι, μηδέ με Κόλχοις<br>ἐκδώῃς ᾧ πατρὶ κομιζέμεν, εἴ νυ καὶ αὐτὴ<br>ἀνθρώπων γενεῆς μία φέρβεαι, οἷσιν ἐς ἄτην<br>ὠκύτατος κούφῃσι θέει νόος ἀμπλακίῃσιν.<br>ὡς ἐμοὶ ἐκ πυκιναὶ ἔπεσον φρένες, οὐ μὲν ἕκητι<br>μαργοσύνης. ἴστω δ’ ἱερὸν φάος Ἠελίοιο,<br>ἴστω νυκτιπόλου Περσηίδος ὄργια κούρης,<br>μὴ μὲν ἐγὼν ἐθέλουσα σὺν ἀνδράσιν ἀλλοδαποῖσιν<br>κεῖθεν ἀφωρμήθην· στυγερὸν δέ με τάρβος ἔπεισεν<br>τῆσγε φυγῆς μνήσασθαι, ὅτ’ ἤλιτον· οὐδέ τις ἄλλη<br>μῆτις ἔην. ἔτι μοι μίτρη μένει, ὡς ἐνὶ πατρὸς<br>δώμασιν, ἄχραντος καὶ ἀκήρατος. ἀλλ’ ἐλέαιρε,<br>πότνα, τεόν τε πόσιν μειλίσσεο· σοὶ δ’ ὀπάσειαν<br>ἀθάνατοι βίοτόν τε τελεσφόρον ἀγλαΐην τε<br>καὶ παῖδας καὶ κῦδος ἀπορθήτοιο πόληος.”", "st": "4.1014"}, {"sp": "N", "t": "τοῖα μὲν Ἀρήτην γουνάζετο δάκρυ χέουσα·<br>τοῖα δ’ ἀριστήων ἐπαμοιβαδὶς ἄνδρα ἕκαστον·", "st": "4.1029"}, {"sp": "N", "t": "“ὑμέων, ὦ πέρι δὴ μέγα φέρτατοι, ἀμφί τ’ ἀέθλοις<br>ὧν κάμον ὑμετέροισιν, ἀτύζομαι· ἧς ἰότητι<br>ταύρους τ’ ἐζεύξασθε, καὶ ἐκ θέρος οὐλοὸν ἀνδρῶν<br>κείρατε γηγενέων· ἧς εἵνεκεν Αἱμονίηνδε<br>χρύσεον αὐτίκα κῶας ἀνάξετε νοστήσαντες.<br>ἥδ’ ἐγώ, ἣ πάτρην τε καὶ οὓς ὤλεσσα τοκῆας,<br>ἣ δόμον, ἣ σύμπασαν ἐυφροσύνην βιότοιο·<br>ὔμμι δὲ καὶ πάτρην καὶ δώματα ναιέμεν αὖτις<br>ἤνυσα· καὶ γλυκεροῖσιν ἔτ’ εἰσόψεσθε τοκῆας<br>ὄμμασιν· αὐτὰρ ἐμοὶ ἀπὸ δὴ βαρὺς εἵλετο δαίμων<br>ἀγλαΐας· στυγερὴ δὲ σὺν ὀθνείοις ἀλάλημαι.<br>δείσατε συνθεσίας τε καὶ ὅρκια, δείσατ’ Ἐρινὺν<br>Ἱκεσίην, νέμεσίν τε θεῶν, ἐς χεῖρας ἰοῦσαν<br>Αἰήτεω λώβῃ πολυπήμονι δῃωθῆναι.<br>οὐ νηούς, οὐ πύργον ἐπίρροθον, οὐκ ἀλεωρὴν<br>ἄλλην, οἰόθι δὲ προτιβάλλομαι ὑμέας αὐτούς.<br>σχέτλιοι ἀτροπίης καὶ ἀνηλέες· οὐδ’ ἐνὶ θυμῷ<br>αἰδεῖσθε ξείνης μ’ ἐπὶ γούνατα χεῖρας ἀνάσσης<br>δερκόμενοι τείνουσαν ἀμήχανον· ἀλλά κε πᾶσιν,<br>κῶας ἑλεῖν μεμαῶτες, ἐμίξατε δούρατα Κόλχοις<br>αὐτῷ τ’ Αἰήτῃ ὑπερήνορι· νῦν δ’ ἐλάθεσθε<br>ἠνορέης, ὅτε μοῦνοι ἀποτμηγέντες ἔασιν.”", "st": "4.1031"}, {"sp": "N", "t": "ὧς φάτο λισσομένη· τῶν δ’ ὅντινα γουνάζοιτο,<br>ὅς μιν θαρσύνεσκεν ἐρητύων ἀχέουσαν.<br>σεῖον δ’ ἐγχείας εὐήκεας ἐν παλάμῃσιν,<br>φάσγανά τ’ ἐκ κολεῶν. οὐδὲ σχήσεσθαι ἀρωγῆς<br>ἔννεπον, εἴ κε δίκης ἀλιτήμονος ἀντιάσειεν.<br>στρευγομένοις δ’ ἀν’ ὅμιλον ἐπήλυθεν εὐνήτειρα<br>νὺξ ἔργων ἄνδρεσσι, κατευκήλησε δὲ πᾶσαν<br>γαῖαν ὁμῶς· τὴν δ’ οὔτι μίνυνθά περ εὔνασεν ὕπνος,<br>ἀλλά οἱ ἐν στέρνοις ἀχέων εἱλίσσετο θυμός.<br>οἷον ὅτε κλωστῆρα γυνὴ ταλαεργὸς ἑλίσσει<br>ἐννυχίη· τῇ δ’ ἀμφὶ κινύρεται ὀρφανὰ τέκνα<br>χηροσύνῃ πόσιος· σταλάει δ’ ὑπὸ δάκρυ παρειὰς<br>μνωομένης, οἵη μιν ἐπὶ σμυγερὴ λάβεν αἶσα·<br>ὧς τῆς ἰκμαίνοντο παρηίδες· ἐν δέ οἱ ἦτορ<br>ὀξείῃς εἰλεῖτο πεπαρμένον ἀμφ’ ὀδύνῃσιν.", "st": "4.1053"}, {"sp": "N", "t": "τὼ δ’ ἔντοσθε δόμοιο κατὰ πτόλιν, ὡς τὸ πάροιθεν,<br>κρείων Ἀλκίνοος πολυπότνιά τ’ Ἀλκινόοιο<br>Ἀρήτη ἄλοχος, κούρης πέρι μητιάασκον<br>οἷσιν ἐνὶ λεχέεσσι διὰ κνέφας· οἷα δ’ ἀκοίτην<br>κουρίδιον θαλεροῖσι δάμαρ προσπτύσσετο μύθοις·", "st": "4.1068"}, {"sp": "N", "t": "“ναὶ φίλος, εἰ δ’ ἄγε μοι πολυκηδέα ῥύεο Κόλχων<br>παρθενικήν, Μινύῃσι φέρων χάριν. ἐγγύθι δ’ Ἄργος<br>ἡμετέρης νήσοιο καὶ ἀνέρες Αἱμονιῆες·<br>Αἰήτης δ’ οὔτ’ ἂρ ναίει σχεδόν, οὐδέ τι ἴδμεν<br>Αἰήτην, ἀλλ’ οἶον ἀκούομεν· ἥδε δὲ κούρη<br>αἰνοπαθὴς κατά μοι νόον ἔκλασεν ἀντιόωσα.<br>μή μιν, ἄναξ, Κόλχοισι πόροις ἐς πατρὸς ἄγεσθαι.<br>ἀάσθη, ὅτε πρῶτα βοῶν θελκτήρια δῶκεν<br>φάρμακά οἱ· σχεδόθεν δὲ κακῷ κακόν, οἷά τε πολλὰ<br>ῥέζομεν ἀμπλακίῃσιν, ἀκειομένη ὑπάλυξεν<br>πατρὸς ὑπερφιάλοιο βαρὺν χόλον. αὐτὰρ Ἰήσων,<br>ὡς ἀίω, μεγάλοισιν ἐνίσχεται ἐξ ἕθεν ὅρκοις,<br>κουριδίην θήσεσθαι ἐνὶ μεγάροισιν ἄκοιτιν,<br>τῶ, φίλε, μήτ’ οὖν αὐτὸν ἑκὼν ἐπίορκον ὀμόσσαι<br>θείης Αἰσονίδην, μήτ’ ἄσχετα σεῖο ἕκητι<br>παῖδα πατὴρ θυμῷ κεκοτηότι δηλήσαιτο.<br>λίην γὰρ δύσζηλοι ἑαῖς ἐπὶ παισὶ τοκῆες·<br>οἷα μὲν Ἀντιόπην εὐώπιδα μήσατο Νυκτεύς·<br>οἷα δὲ καὶ Δανάη πόντῳ ἔνι πήματ’ ἀνέτλη,<br>πατρὸς ἀτασθαλίῃσι· νέον γε μέν, οὐδ’ ἀποτηλοῦ,<br>ὑβριστὴς Ἔχετος γλήναις ἔνι χάλκεα κέντρα<br>πῆξε θυγατρὸς ἑῆς· στονόεντι δὲ κάρφεται οἴτῳ<br>ὀρφναίῃ ἐνὶ χαλκὸν ἀλετρεύουσα καλιῇ.”", "st": "4.1073"}, {"sp": "N", "t": "ὧς ἔφατ’ ἀντομένη· τοῦ δὲ φρένες ἰαίνοντο<br>ἧς ἀλόχου μύθοισιν, ἔπος δ’ ἐπὶ τοῖον ἔειπεν·", "st": "4.1096"}, {"sp": "N", "t": "“Ἀρήτη, καί κεν σὺν τεύχεσιν ἐξελάσαιμι<br>Κόλχους, ἡρώεσσι φέρων χάριν, εἵνεκα κούρης.<br>ἀλλὰ Διὸς δείδοικα δίκην ἰθεῖαν ἀτίσσαι.<br>οὐδὲ μὲν Αἰήτην ἀθεριζέμεν, ὡς ἀγορεύεις,<br>λώιον· οὐ γάρ τις βασιλεύτερος Αἰήταο.<br>καί κ’ ἐθέλων, ἕκαθέν περ, ἐφ’ Ἑλλάδι νεῖκος ἄγοιτο.<br>τῶ μ’ ἐπέοικε δίκην, ἥτις μετὰ πᾶσιν ἀρίστη<br>ἔσσεται ἀνθρώποισι, δικαζέμεν· οὐδέ σε κεύσω.<br>παρθενικὴν μὲν ἐοῦσαν ἑῷ ἀπὸ πατρὶ κομίσσαι<br>ἰθύνω· λέκτρον δὲ σὺν ἀνέρι πορσαίνουσαν<br>οὔ μιν ἑοῦ πόσιος νοσφίσσομαι· οὐδέ, γενέθλην<br>εἴ τιν’ ὑπὸ σπλάγχνοισι φέρει, δῄοισιν ὀπάσσω.”", "st": "4.1098"}, {"sp": "N", "t": "ὧς ἄρ’ ἔφη· καὶ τὸν μὲν ἐπισχεδὸν εὔνασεν ὕπνος.<br>ἡ δ’ ἔπος ἐν θυμῷ πυκινὸν βάλετ’· αὐτίκα δ’ ὦρτο<br>ἐκ λεχέων ἀνὰ δῶμα· συνήιξαν δὲ γυναῖκες<br>ἀμφίπολοι, δέσποιναν ἑὴν μέτα ποιπνύουσαι.<br>σῖγα δ’ ἑὸν κήρυκα καλεσσαμένη προσέειπεν,<br>ᾗσιν ἐπιφροσύνῃσιν ἐποτρυνέουσα μιγῆναι<br>Αἰσονίδην κούρῃ, μηδ’ Ἀλκίνοον βασιλῆα<br>λίσσεσθαι· τὸ γὰρ αὐτὸς ἰὼν Κόλχοισι δικάσσει,<br>παρθενικὴν μὲν ἐοῦσαν ἑοῦ ποτὶ δώματα πατρὸς<br>ἐκδώσειν, λέκτρον δὲ σὺν ἀνέρι πορσαίνουσαν<br>οὐκέτι κουριδίης μιν ἀποτμήξειν φιλότητος.", "st": "4.1110"}, {"sp": "N", "t": "ὧς ἄρ’ ἔφη· τὸν δ’ αἶψα πόδες φέρον ἐκ μεγάροιο,<br>ὥς κεν Ἰήσονι μῦθον ἐναίσιμον ἀγγείλειεν<br>Ἀρήτης βουλάς τε θεουδέος Ἀλκινόοιο.<br>τοὺς δ’ εὗρεν παρὰ νηὶ σὺν ἔντεσιν ἐγρήσσοντας<br>Ὑλλικῷ ἐν λιμένι, σχεδὸν ἄστεος· ἐκ δ’ ἄρα πᾶσαν<br>πέφραδεν ἀγγελίην· γήθησε δὲ θυμὸς ἑκάστου<br>ἡρώων· μάλα γάρ σφιν ἑαδότα μῦθον ἔειπεν.", "st": "4.1121"}, {"sp": "N", "t": "αὐτίκα δὲ κρητῆρα κερασσάμενοι μακάρεσσιν,<br>ἣ θέμις, εὐαγέως ἐπιβώμια μῆλ’ ἐρύσαντες,<br>αὐτονυχὶ κούρῃ θαλαμήιον ἔντυον εὐνὴν<br>ἄντρῳ ἐν ἠγαθέῳ, τόθι δή ποτε Μάκρις ἔναιεν,<br>κούρη Ἀρισταίοιο μελίφρονος, ὅς ῥα μελισσέων<br>ἔργα πολυκμήτοιό τ’ ἀνεύρατο πῖαρ ἐλαίης.<br>κείνη δὴ πάμπρωτα Διὸς Νυσήιον υἷα<br>Εὐβοίης ἔντοσθεν Ἀβαντίδος ᾧ ἐνὶ κόλπῳ<br>δέξατο, καὶ μέλιτι ξηρὸν περὶ χεῖλος ἔδευσεν,<br>εὖτέ μιν Ἑρμείας φέρεν ἐκ πυρός· ἔδρακε δ’ Ἥρη,<br>καί ἑ χολωσαμένη πάσης ἐξήλασε νήσου.<br>ἡ δ’ ἄρα Φαιήκων ἱερῷ ἐνὶ τηλόθεν ἄντρῳ<br>νάσσατο, καὶ πόρεν ὄλβον ἀθέσφατον ἐνναέτῃσιν.<br>ἔνθα τότ’ ἐστόρεσαν λέκτρον μέγα· τοῖο δ’ ὕπερθεν<br>χρύσεον αἰγλῆεν κῶας βάλον, ὄφρα πέλοιτο<br>τιμήεις τε γάμος καὶ ἀοίδιμος. ἄνθεα δέ σφιν<br>νύμφαι ἀμεργόμεναι λευκοῖς ἐνὶ ποικίλα κόλποις<br>ἐσφόρεον· πάσας δὲ πυρὸς ὣς ἄμφεπεν αἴγλη·<br>τοῖον ἀπὸ χρυσέων θυσάνων ἀμαρύσσετο φέγγος.<br>δαῖε δ’ ἐν ὀφθαλμοῖς γλυκερὸν πόθον· ἴσχε δ’ ἑκάστην<br>αἰδὼς ἱεμένην περ ὅμως ἐπὶ χεῖρα βαλέσθαι.<br>αἱ μέν τ’ Αἰγαίου ποταμοῦ καλέοντο θύγατρες·<br>αἱ δ’ ὄρεος κορυφὰς Μελιτηίου ἀμφενέμοντο·<br>αἱ δ’ ἔσαν ἐκ πεδίων ἀλσηίδες. ὦρσε γὰρ αὐτὴ<br>Ἥρη Ζηνὸς ἄκοιτις, Ἰήσονα κυδαίνουσα.<br>κεῖνο καὶ εἰσέτι νῦν ἱερὸν κληίζεται ἄντρον<br>Μηδείης, ὅθι τούσγε σὺν ἀλλήλοισιν ἔμιξαν<br>τεινάμεναι ἑανοὺς εὐώδεας. οἱ δ’ ἐνὶ χερσὶν<br>δούρατα νωμήσαντες ἀρήια, μὴ πρὶν ἐς ἀλκὴν<br>δυσμενέων ἀίδηλος ἐπιβρίσειεν ὅμιλος,<br>κράατα δ’ εὐφύλλοις ἐστεμμένοι ἀκρεμόνεσσιν,<br>ἐμμελέως, Ὀρφῆος ὑπαὶ λίγα φορμίζοντος<br>νυμφιδίαις ὑμέναιον ἐπὶ προμολῇσιν ἄειδον.<br>οὐ μὲν ἐν Ἀλκινόοιο γάμον μενέαινε τελέσσαι<br>ἥρως Αἰσονίδης, μεγάροις δ’ ἐνὶ πατρὸς ἑοῖο,<br>νοστήσας ἐς Ἰωλκὸν ὑπότροπος· ὧς δὲ καὶ αὐτὴ<br>Μήδεια φρονέεσκε· τότ’ αὖ χρεὼ ἦγε μιγῆναι.<br>ἀλλὰ γὰρ οὔποτε φῦλα δυηπαθέων ἀνθρώπων<br>τερπωλῆς ἐπέβημεν ὅλῳ ποδί· σὺν δέ τις αἰεὶ<br>πικρὴ παρμέμβλωκεν ἐυφροσύνῃσιν ἀνίη.<br>τῶ καὶ τοὺς γλυκερῇ περ ἰαινομένους φιλότητι<br>δεῖμ’ ἔχεν, εἰ τελέοιτο διάκρισις Ἀλκινόοιο.", "st": "4.1128"}, {"sp": "N", "t": "Ἠὼς δ’ ἀμβροσίοισιν ἀνερχομένη φαέεσσιν<br>λῦε κελαινὴν νύκτα δι’ ἠέρος· αἱ δ’ ἐγέλασσαν<br>ἠιόνες νήσοιο καὶ ἑρσήεσσαι ἄπωθεν<br>ἀτραπιτοὶ πεδίων· ἐν δὲ θρόος ἔσκεν ἀγυιαῖς·<br>κίνυντ’ ἐνναέται μὲν ἀνὰ πτόλιν, οἱ δ’ ἀποτηλοῦ<br>Κόλχοι Μακριδίης ἐπὶ πείρασι χερνήσοιο.<br>αὐτίκα δ’ Ἀλκίνοος μετεβήσετο συνθεσίῃσιν<br>ὃν νόον ἐξερέων κούρης ὕπερ· ἐν δ’ ὅγε χειρὶ<br>σκῆπτρον ἔχεν χρυσοῖο δικασπόλον, ᾧ ὕπο λαοὶ<br>ἰθείας ἀνὰ ἄστυ διεκρίνοντο θέμιστας.<br>τῷ δὲ καὶ ἑξείης πολεμήια τεύχεα δύντες<br>Φαιήκων οἱ ἄριστοι ὁμιλαδὸν ἐστιχόωντο.<br>ἥρωας δὲ γυναῖκες ἀολλέες ἔκτοθι πύργων<br>βαῖνον ἐποψόμεναι· σὺν δ’ ἀνέρες ἀγροιῶται<br>ἤντεον εἰσαΐοντες, ἐπεὶ νημερτέα βάξιν<br>Ἥρη ἐπιπροέηκεν. ἄγεν δ’ ὁ μὲν ἔκκριτον ἄλλων<br>ἀρνειὸν μήλων, ὁ δ’ ἀεργηλὴν ἔτι πόρτιν·<br>ἄλλοι δ’ ἀμφιφορῆας ἐπισχεδὸν ἵστασαν οἴνου<br>κίρνασθαι· θυέων δ’ ἀποτηλόθι κήκιε λιγνύς.<br>αἱ δὲ πολυκμήτους ἑανοὺς φέρον, οἷα γυναῖκες,<br>μείλιά τε χρυσοῖο καὶ ἀλλοίην ἐπὶ τοῖσιν<br>ἀγλαΐην, οἵην τε νεόζυγες ἐντύνονται·<br>θάμβευν δ’ εἰσορόωσαι ἀριπρεπέων ἡρώων<br>εἴδεα καὶ μορφάς, ἐν δέ σφισιν Οἰάγροιο<br>υἱὸν ὑπαὶ φόρμιγγος ἐυκρέκτου καὶ ἀοιδῆς<br>ταρφέα σιγαλόεντι πέδον κροτέοντα πεδίλῳ.<br>νύμφαι δ’ ἄμμιγα πᾶσαι, ὅτε μνήσαιτο γάμοιο,<br>ἱμερόενθ’ ὑμέναιον ἀνήπυον· ἄλλοτε δ’ αὖτε<br>οἰόθεν οἶαι ἄειδον ἑλισσόμεναι περὶ κύκλον,<br>Ἥρη, σεῖο ἕκητι· σὺ γὰρ καὶ ἐπὶ φρεσὶ θῆκας<br>Ἀρήτῃ, πυκινὸν φάσθαι ἔπος Ἀλκινόοιο.<br>αὐτὰρ ὅγ’ ὡς τὰ πρῶτα δίκης ἀνὰ πείρατ’ ἔειπεν<br>ἰθείης, ἤδη δὲ γάμου τέλος ἐκλήιστο,<br>ἔμπεδον ὧς ἀλέγυνε διαμπερές· οὐδέ ἑ τάρβος<br>οὐλοόν, οὐδὲ βαρεῖαι ἐπήλυθον Αἰήταο<br>μήνιες, ἀρρήκτοισι δ’ ἐνιζεύξας ἔχεν ὅρκοις.<br>τῶ καὶ ὅτ’ ἠλεμάτως Κόλχοι μάθον ἀντιόωντες,<br>καί σφεας ἠὲ θέμιστας ἑὰς εἴρυσθαι ἄνωγεν,<br>ἢ λιμένων γαίης τ’ ἀποτηλόθι νῆας ἐέργειν,<br>δὴ τότε μιν βασιλῆος ἑοῦ τρομέοντας ἐνιπὰς<br>δέχθαι μειλίξαντο συνήμονας· αὖθι δὲ νήσῳ<br>δὴν μάλα Φαιήκεσσι μετ’ ἀνδράσι ναιετάασκον,<br>εἰσότε Βακχιάδαι, γενεὴν Ἐφύρηθεν ἐόντες,<br>ἀνέρες ἐννάσσαντο μετὰ χρόνον· οἱ δὲ περαίην<br>νῆσον ἔβαν· κεῖθεν δὲ Κεραύνια μέλλον Ἀβάντων<br>οὔρεα, Νεσταίους τε καὶ Ὤρικον εἰσαφικέσθαι·<br>ἀλλὰ τὰ μὲν στείχοντος ἄδην αἰῶνος ἐτύχθη.<br>Μοιράων δ’ ἔτι κεῖσε θύη ἐπέτεια δέχονται<br>καὶ Νυμφέων Νομίοιο καθ’ ἱερὸν Ἀπόλλωνος<br>βωμοί, τοὺς Μήδεια καθίσσατο. πολλὰ δ’ ἰοῦσιν<br>Ἀλκίνοος Μινύαις ξεινήια, πολλὰ δ’ ὄπασσεν<br>Ἀρήτη· μετὰ δ’ αὖτε δυώδεκα δῶκεν ἕπεσθαι<br>Μηδείῃ δμωὰς Φαιηκίδας ἐκ μεγάροιο.<br>ἤματι δ’ ἑβδομάτῳ Δρεπάνην λίπον· ἤλυθε δ’ οὖρος<br>ἀκραὴς ἠῶθεν ὑπὲκ Διός· οἱ δ’ ἀνέμοιο<br>πνοιῇ ἐπειγόμενοι προτέρω θέον. ἀλλὰ γὰρ οὔπω<br>αἴσιμον ἦν ἐπιβῆναι Ἀχαιίδος ἡρώεσσιν,<br>ὄφρ’ ἔτι καὶ Λιβύης ἐπὶ πείρασιν ὀτλήσειαν.", "st": "4.1170"}, {"sp": "N", "t": "ἤδη μέν ποθι κόλπον ἐπώνυμον Ἀμβρακιήων,<br>ἤδη Κουρῆτιν ἔλιπον χθόνα πεπταμένοισιν<br>λαίφεσι καὶ στεινὰς αὐταῖς σὺν Ἐχινάσι νήσους<br>ἑξείης, Πέλοπος δὲ νέον κατεφαίνετο γαῖα·<br>καὶ τότ’ ἀναρπάγδην ὀλοὴ βορέαο θύελλα<br>μεσσηγὺς πέλαγόσδε Λιβυστικὸν ἐννέα πάσας<br>νύκτας ὁμῶς καὶ τόσσα φέρ’ ἤματα, μέχρις ἵκοντο<br>προπρὸ μάλ’ ἔνδοθι Σύρτιν, ὅθ’ οὐκέτι νόστος ὀπίσσω<br>νηυσὶ πέλει, ὅτε τόνγε βιῴατο κόλπον ἱκέσθαι.<br>πάντῃ γὰρ τέναγος, πάντῃ μνιόεντα βυθοῖο<br>τάρφεα· κωφὴ δέ σφιν ἐπιβλύει ὕδατος ἄχνη·<br>ἠερίη δ’ ἄμαθος παρακέκλιται· οὐδέ τι κεῖσε<br>ἑρπετόν, οὐδὲ ποτητὸν ἀείρεται. ἔνθ’ ἄρα τούσγε<br>πλυμμυρίς—καὶ γάρ τ’ ἀναχάζεται ἠπείροιο<br>ἦ θαμὰ δὴ τόδε χεῦμα, καὶ ἂψ ἐπερεύγεται ἀκτὰς<br>λάβρον ἐποιχόμενον—μυχάτῃ ἐνέωσε τάχιστα<br>ἠιόνι, τρόπιος δὲ μάλ’ ὕδασι παῦρον ἔλειπτο.<br>οἱ δ’ ἀπὸ νηὸς ὄρουσαν, ἄχος δ’ ἕλεν εἰσορόωντας<br>ἠέρα καὶ μεγάλης νῶτα χθονὸς ἠέρι ἶσα,<br>τηλοῦ ὑπερτείνοντα διηνεκές· οὐδέ τιν’ ἀρδμόν,<br>οὐ πάτον, οὐκ ἀπάνευθε κατηυγάσσαντο βοτήρων<br>αὔλιον, εὐκήλῳ δὲ κατείχετο πάντα γαλήνῃ.<br>ἄλλος δ’ αὖτ’ ἄλλον τετιημένος ἐξερέεινεν·", "st": "4.1228"}, {"sp": "N", "t": "“τίς χθὼν εὔχεται ἥδε; πόθι ξυνέωσαν ἄελλαι<br>ἡμέας; αἴθ’ ἔτλημεν, ἀφειδέες οὐλομένοιο<br>δείματος, αὐτὰ κέλευθα διαμπερὲς ὁρμηθῆναι<br>πετράων. ἦ τ’ ἂν καὶ ὑπὲρ Διὸς αἶσαν ἰοῦσιν<br>βέλτερον ἦν μέγα δή τι μενοινώοντας ὀλέσθαι.<br>νῦν δὲ τί κεν ῥέξαιμεν, ἐρυκόμενοι ἀνέμοισιν<br>αὖθι μένειν τυτθόν περ ἐπὶ χρόνον; οἷον ἐρήμη<br>πέζα διωλυγίης ἀναπέπταται ἠπείροιο.”", "st": "4.1251"}, {"sp": "N", "t": "ὧς ἄρ’ ἔφη· μετὰ δ’ αὐτὸς ἀμηχανίῃ κακότητος<br>ἰθυντὴρ Ἀγκαῖος ἀκηχέμενος ἀγόρευσεν·<br>“Ὠλόμεθ’ αἰνότατον δῆθεν μόρον, οὐδ’ ὑπάλυξις<br>ἔστ’ ἄτης· πάρα δ’ ἄμμι τὰ κύντατα πημανθῆναι<br>τῇδ’ ἐπ’ ἐρημαίῃ πεπτηότας, εἰ καὶ ἀῆται<br>χερσόθεν ἀμπνεύσειαν· ἐπεὶ τεναγώδεα λεύσσω<br>τῆλε περισκοπέων ἅλα πάντοθεν· ἤλιθα δ’ ὕδωρ<br>ξαινόμενον πολιῇσιν ἐπιτροχάει ψαμάθοισιν.<br>καί κεν ἐπισμυγερῶς διὰ δὴ πάλαι ἥδ’ ἐκεάσθη<br>νηῦς ἱερὴ χέρσου πολλὸν πρόσω· ἀλλά μιν αὐτὴ<br>πλημμυρὶς ἐκ πόντοιο μεταχθονίην ἐκόμισσεν.<br>νῦν δ’ ἡ μὲν πέλαγόσδε μετέσσυται, οἰόθι δ’ ἅλμη<br>ἄπλοος εἰλεῖται, γαίης ὕπερ ὅσσον ἔχουσα.<br>τούνεκ’ ἐγὼ πᾶσαν μὲν ἀπ’ ἐλπίδα φημὶ κεκόφθαι<br>ναυτιλίης νόστου τε. δαημοσύνην δέ τις ἄλλος<br>φαίνοι ἑήν· πάρα γάρ οἱ ἐπ’ οἰήκεσσι θαάσσειν<br>μαιομένῳ κομιδῆς. ἀλλ’ οὐ μάλα νόστιμον ἦμαρ<br>Ζεὺς ἐθέλει καμάτοισιν ἐφ’ ἡμετέροισι τελέσσαι.”", "st": "4.1259"}, {"sp": "N", "t": "ὧς φάτο δακρυόεις· σὺν δ’ ἔννεπον ἀσχαλόωντι<br>ὅσσοι ἔσαν νηῶν δεδαημένοι· ἐν δ’ ἄρα πᾶσιν<br>παχνώθη κραδίη, χύτο δὲ χλόος ἀμφὶ παρειάς.<br>οἷον δ’ ἀψύχοισιν ἐοικότες εἰδώλοισιν<br>ἀνέρες εἱλίσσονται ἀνὰ πτόλιν, ἢ πολέμοιο<br>ἢ λοιμοῖο τέλος ποτιδέγμενοι, ἠέ τιν’ ὄμβρον<br>ἄσπετον, ὅς τε βοῶν κατὰ μυρία ἔκλυσεν ἔργα,<br>ἢ ὅταν αὐτόματα ξόανα ῥέῃ ἱδρώοντα<br>αἵματι, καὶ μυκαὶ σηκοῖς ἔνι φαντάζωνται,<br>ἠὲ καὶ ἠέλιος μέσῳ ἤματι νύκτ’ ἐπάγῃσιν<br>οὐρανόθεν, τὰ δὲ λαμπρὰ δι’ ἠέρος ἄστρα φαείνοι·<br>ὧς τότ’ ἀριστῆες δολιχοῦ πρόπαρ αἰγιαλοῖο<br>ἤλυον ἑρπύζοντες. ἐπήλυθε δ’ αὐτίκ’ ἐρεμνὴ<br>ἕσπερος. οἱ δ’ ἐλεεινὰ χεροῖν σφέας ἀμφιβαλόντες<br>δακρυόειν ἀγάπαζον, ἵν’ ἄνδιχα δῆθεν ἕκαστος<br>θυμὸν ἀποφθίσειαν ἐνὶ ψαμάθοισι πεσόντες.<br>βὰν δ’ ἴμεν ἄλλυδις ἄλλος ἑκαστέρω αὖλιν ἑλέσθαι·<br>ἐν δὲ κάρη πέπλοισι καλυψάμενοι σφετέροισιν<br>ἄκμηνοι καὶ ἄπαστοι ἐκείατο νύκτ’ ἔπι πᾶσαν<br>καὶ φάος, οἰκτίστῳ θανάτῳ ἔπι. νόσφι δὲ κοῦραι<br>ἀθρόαι Αἰήταο παρεστενάχοντο θυγατρί.<br>ὡς δ’ ὅτ’ ἐρημαῖοι πεπτηότες ἔκτοθι πέτρης<br>χηραμοῦ ἀπτῆνες λιγέα κλάζουσι νεοσσοί·<br>ἢ ὅτε καλὰ νάοντος ἐπ’ ὀφρύσι Πακτωλοῖο<br>κύκνοι κινήσωσιν ἑὸν μέλος, ἀμφὶ δὲ λειμὼν<br>ἑρσήεις βρέμεται ποταμοῖό τε καλὰ ῥέεθρα·<br>ὧς αἱ ἐπὶ ξανθὰς θέμεναι κονίῃσιν ἐθείρας<br>παννύχιαι ἐλεεινὸν ἰήλεμον ὠδύροντο.<br>καί νύ κεν αὐτοῦ πάντες ἀπὸ ζωῆς ἐλίασθεν<br>νώνυμνοι καὶ ἄφαντοι ἐπιχθονίοισι δαῆναι<br>ἡρώων οἱ ἄριστοι ἀνηνύστῳ ἐπ’ ἀέθλῳ·<br>ἀλλά σφεας ἐλέηραν ἀμηχανίῃ μινύθοντας<br>ἡρῷσσαι, Λιβύης τιμήοροι, αἵ ποτ’ Ἀθήνην,<br>ἦμος ὅτ’ ἐκ πατρὸς κεφαλῆς θόρε παμφαίνουσα,<br>ἀντόμεναι Τρίτωνος ἐφ’ ὕδασι χυτλώσαντο.<br>ἔνδιον ἦμαρ ἔην, περὶ δ’ ὀξύταται θέρον αὐγαὶ<br>ἠελίου Λιβύην· αἱ δὲ σχεδὸν Αἰσονίδαο<br>ἔσταν, ἕλον δ’ ἀπὸ χερσὶ καρήατος ἠρέμα πέπλον.<br>αὐτὰρ ὅγ’ εἰς ἑτέρωσε παλιμπετὲς ὄμματ’ ἔνεικεν,<br>δαίμονας αἰδεσθείς· αὐτὸν δέ μιν ἀμφαδὸν οἶον<br>μειλιχίοις ἐπέεσσιν ἀτυζόμενον προσέειπον·", "st": "4.1277"}, {"sp": "N", "t": "“κάμμορε, τίπτ’ ἐπὶ τόσσον ἀμηχανίῃ βεβόλησαι;<br>ἴδμεν ἐποιχομένους χρύσεον δέρος· ἴδμεν ἕκαστα<br>ὑμετέρων καμάτων, ὅσ’ ἐπὶ χθονός, ὅσσα τ’ ἐφ’ ὑγρὴν<br>πλαζόμενοι κατὰ πόντον ὑπέρβια ἔργ’ ἐκάμεσθε.<br>οἰοπόλοι δ’ εἰμὲν χθόνιαι θεαὶ αὐδήεσσαι,<br>ἡρῷσσαι, Λιβύης τιμήοροι ἠδὲ θύγατρες.<br>ἀλλ’ ἄνα· μηδ’ ἔτι τοῖον ὀιζύων ἀκάχησο·<br>ἄνστησον δ’ ἑτάρους. εὖτ’ ἂν δέ τοι Ἀμφιτρίτη<br>ἅρμα Ποσειδάωνος ἐύτροχον αὐτίκα λύσῃ,<br>δή ῥα τότε σφετέρῃ ἀπὸ μητέρι τίνετ’ ἀμοιβὴν<br>ὧν ἔκαμεν δηρὸν κατὰ νηδύος ὔμμε φέρουσα·<br>καί κεν ἔτ’ ἠγαθέην ἐς Ἀχαιίδα νοστήσαιτε.”", "st": "4.1318"}, {"sp": "N", "t": "ὧς ἄρ’ ἔφαν, καὶ ἄφαντοι ἵν’ ἔσταθεν, ἔνθ’ ἄρα ταίγε<br>φθογγῇ ὁμοῦ ἐγένοντο παρασχεδόν. αὐτὰρ Ἰήσων<br>παπτήνας ἀν’ ἄρ’ ἕζετ’ ἐπὶ χθονός, ὧδέ τ’ ἔειπεν·", "st": "4.1330"}, {"sp": "N", "t": "“Ἵλατ’ ἐρημονόμοι κυδραὶ θεαί· ἀμφὶ δὲ νόστῳ<br>οὔτι μαλ’ ἀντικρὺ νοέω φάτιν. ἦ μὲν ἑταίρους<br>εἰς ἓν ἀγειράμενος μυθήσομαι, εἴ νύ τι τέκμωρ<br>δήωμεν κομιδῆς· πολέων δέ τε μῆτις ἀρείων.”", "st": "4.1333"}, {"sp": "N", "t": "ἦ, καὶ ἀναΐξας ἑτάρους ἐπὶ μακρὸν ἀύτει,<br>αὐσταλέος κονίῃσι, λέων ὥς, ὅς ῥά τ’ ἀν’ ὕλην<br>σύννομον ἣν μεθέπων ὠρύεται· αἱ δὲ βαρείῃ<br>φθογγῇ ὑποτρομέουσιν ἀν’ οὔρεα τηλόθι βῆσσαι·<br>δείματι δ’ ἄγραυλοί τε βόες μέγα πεφρίκασιν<br>βουπελάται τε βοῶν· τοῖς δ’ οὔ νύ τι γῆρυς ἐτύχθη<br>ῥιγεδανὴ ἑτάροιο φίλους ἐπικεκλομένοιο.<br>ἀγχοῦ δ’ ἠγερέθοντο κατηφέες· αὐτὰρ ὁ τούσγε<br>ἀχνυμένους ὅρμοιο πέλας μίγα θηλυτέρῃσιν<br>ἱδρύσας, μυθεῖτο πιφαυσκόμενος τὰ ἕκαστα·", "st": "4.1337"}, {"sp": "N", "t": "“κλῦτε, φίλοι· τρεῖς γάρ μοι ἀνιάζοντι θεάων,<br>στέρφεσιν αἰγείοις ἐζωσμέναι ἐξ ὑπάτοιο<br>αὐχένος ἀμφί τε νῶτα καὶ ἰξύας, ἠύτε κοῦραι,<br>ἔσταν ὑπὲρ κεφαλῆς μάλ’ ἐπισχεδόν· ἂν δ’ ἐκάλυψαν<br>πέπλον ἐρυσσάμεναι κούφῃ χερί, καί μ’ ἐκέλοντο<br>αὐτόν τ’ ἔγρεσθαι, ἀνά θ’ ὑμέας ὄρσαι ἰόντα·<br>μητέρι δὲ σφετέρῃ μενοεικέα τῖσαι ἀμοιβὴν<br>ὧν ἔκαμεν δηρὸν κατὰ νηδύος ἄμμε φέρουσα<br>ὁππότε κεν λύσῃσιν ἐύτροχον Ἀμφιτρίτη<br>ἅρμα Ποσειδάωνος. ἐγὼ δ’ οὐ πάγχυ νοῆσαι<br>τῆσδε θεοπροπίης ἴσχω πέρι. φάν γε μὲν εἶναι<br>ἡρῷσσαι, Λιβύης τιμήοροι ἠδὲ θύγατρες·<br>καὶ δ’ ὁπόσ’ αὐτοὶ πρόσθεν ἐπὶ χθονὸς ἠδ’ ὅσ’ ἐφ’ ὑγρὴν<br>ἔτλημεν, τὰ ἕκαστα διίδμεναι εὐχετόωντο.<br>οὐδ’ ἔτι τάσδ’ ἀνὰ χῶρον ἐσέδρακον, ἀλλά τις ἀχλὺς<br>ἠὲ νέφος μεσσηγὺ φαεινομένας ἐκάλυψεν.”", "st": "4.1347"}, {"sp": "N", "t": "ὧς ἔφαθ’· οἱ δ’ ἄρα πάντες ἐθάμβεον εἰσαΐοντες.<br>ἔνθα τὸ μήκιστον τεράων Μινύῃσιν ἐτύχθη.<br>ἐξ ἁλὸς ἤπειρόνδε πελώριος ἔκθορεν ἵππος,<br>ἀμφιλαφής, χρυσέῃσι μετήορος αὐχένα χαίταις·<br>ῥίμφα δὲ σεισάμενος γυίων ἄπο νήχυτον ἅλμην<br>ὦρτο θέειν, πνοιῇ ἴκελος πόδας. αἶψα δὲ Πηλεὺς<br>γηθήσας ἑτάροισιν ὁμηγερέεσσι μετηύδα·", "st": "4.1363"}, {"sp": "N", "t": "“ἅρματα μὲν δή φημι Ποσειδάωνος ἔγωγε<br>ἤδη νῦν ἀλόχοιο φίλης ὑπὸ χερσὶ λελύσθαι·<br>μητέρα δ’ οὐκ ἄλλην προτιόσσομαι, ἠέ περ αὐτὴν<br>νῆα πέλειν· ἦ γὰρ κατὰ νηδύος ἄμμε φέρουσα<br>νωλεμὲς ἀργαλέοισιν ὀιζύει καμάτοισιν.<br>ἀλλά μιν ἀστεμφεῖ τε βίῃ καὶ ἀτειρέσιν ὤμοις<br>ὑψόθεν ἀνθέμενοι ψαμαθώδεος ἔνδοθι γαίης<br>οἴσομεν, ᾗ προτέρωσε ταχὺς πόδας ἤλασεν ἵππος.<br>οὐ γὰρ ὅγε ξηρὴν ὑποδύσεται· ἴχνια δ’ ἡμῖν<br>σημανέειν τιν’ ἔολπα μυχὸν καθύπερθε θαλάσσης.”", "st": "4.1370"}, {"sp": "N", "t": "ὧς ηὔδα· πάντεσσι δ’ ἐπήβολος ἥνδανε μῆτις·<br>Μουσάων ὅδε μῦθος· ἐγὼ δ’ ὑπακουὸς ἀείδω<br>Πιερίδων, καὶ τήνδε πανατρεκὲς ἔκλυον ὀμφήν,<br>ὑμέας, ὦ πέρι δὴ μέγα φέρτατοι υἷες ἀνάκτων,<br>ᾗ βίῃ ᾗ τ’ ἀρετῇ Λιβύης ἀνὰ θῖνας ἐρήμους<br>νῆα μεταχρονίην ὅσα τ’ ἔνδοθι νηὸς ἄγεσθε,<br>ἀνθεμένους ὤμοισι φέρειν δυοκαίδεκα πάντα<br>ἤμαθ’ ὁμοῦ νύκτας τε. δύην γε μὲν ἢ καὶ ὀιζὺν<br>τίς κ’ ἐνέποι, τὴν κεῖνοι ἀνέπλησαν μογέοντες;<br>ἔμπεδον ἀθανάτων ἔσαν αἵματος, οἷον ὑπέσταν<br>ἔργον, ἀναγκαίῃ βεβιημένοι. αὐτὰρ ἐπιπρὸ<br>τῆλε μάλ’ ἀσπασίως Τριτωνίδος ὕδασι λίμνης<br>ὡς φέρον, ὡς εἰσβάντες ἀπὸ στιβαρῶν θέσαν ὤμων.", "st": "4.1380"}, {"sp": "N", "t": "Λυσσαλέοις δἤπειτ’ ἴκελοι κυσὶν ἀίσσοντες<br>πίδακα μαστεύεσκον· ἐπὶ ξηρὴ γὰρ ἔκειτο<br>δίψα δυηπαθίῃ τε καὶ ἄλγεσιν, οὐδ’ ἐμάτησαν<br>πλαζόμενοι· ἷξον δ’ ἱερὸν πέδον, ᾧ ἔνι Λάδων<br>εἰσέτι που χθιζὸν παγχρύσεα ῥύετο μῆλα<br>χώρῳ ἐν Ἄτλαντος, χθόνιος ὄφις· ἀμφὶ δὲ νύμφαι<br>Ἑσπερίδες ποίπνυον, ἐφίμερον ἀείδουσαι.<br>δὴ τότε δ’ ἤδη τῆμος ὑφ’ Ἡρακλῆι δαϊχθεὶς<br>μήλειον βέβλητο ποτὶ στύπος· οἰόθι δ’ ἄκρῃ<br>οὐρῇ ἔτι σκαίρεσκεν· ἀπὸ κρατὸς δὲ κελαινὴν<br>ἄχρις ἐπ’ ἄκνηστιν κεῖτ’ ἄπνοος· ἐκ δὲ λιπόντων<br>ὕδρης Λερναίης χόλον αἵματι πικρὸν ὀιστῶν<br>μυῖαι πυθομένοισιν ἐφ’ ἕλκεσι τερσαίνοντο.<br>ἀγχοῦ δ’ Ἑσπερίδες κεφαλαῖς ἔπι χεῖρας ἔχουσαι<br>ἀργυφέας ξανθῇσι λίγ’ ἔστενον· οἱ δ’ ἐπέλασσαν<br>ἄφνω ὁμοῦ· ταὶ δ’ αἶψα κόνις καὶ γαῖα, κιόντων<br>ἐσσυμένως, ἐγένοντο καταυτόθι. νώσατο δ’ Ὀρφεὺς<br>θεῖα τέρα, τὰς δέ σφι παρηγορέεσκε λιτῇσιν·<br>“δαίμονες ὦ καλαὶ καὶ ἐύφρονες, ἵλατ’, ἄνασσαι,<br>εἴτ’ οὖν οὐρανίαις ἐναρίθμιοί ἐστε θεῇσιν,<br>εἴτε καταχθονίαις, εἴτ’ οἰοπόλοι καλέεσθε<br>νύμφαι· ἴτ’ ὦ νύμφαι, ἱερὸν γένος Ὠκεανοῖο,<br>δείξατ’ ἐελδομένοισιν ἐνωπαδὶς ἄμμι φανεῖσαι<br>ἤ τινα πετραίην χύσιν ὕδατος, ἤ τινα γαίης<br>ἱερὸν ἐκβλύοντα, θεαί, ῥόον, ᾧ ἀπὸ δίψαν<br>αἰθομένην ἄμοτον λωφήσομεν. εἰ δέ κεν αὖτις<br>δή ποτ’ Ἀχαιίδα γαῖαν ἱκώμεθα ναυτιλίῃσιν,<br>δὴ τότε μυρία δῶρα μετὰ πρώτῃσι θεάων<br>λοιβάς τ’ εἰλαπίνας τε παρέξομεν εὐμενέοντες.”", "st": "4.1393"}, {"sp": "N", "t": "ὧς φάτο λισσόμενος ἀδινῇ ὀπί· ταὶ δ’ ἐλέαιρον<br>ἐγγύθεν ἀχνυμένους· καὶ δὴ χθονὸς ἐξανέτειλαν<br>ποίην πάμπρωτον· ποίης γε μὲν ὑψόθι μακροὶ<br>βλάστεον ὅρπηκες· μετὰ δ’ ἔρνεα τηλεθάοντα<br>πολλὸν ὑπὲρ γαίης ὀρθοσταδὸν ἠέξοντο.<br>Ἑσπέρη αἴγειρος, πτελέη δ’ Ἐρυθηὶς ἔγεντο·<br>Αἴγλη δ’ ἰτείης ἱερὸν στύπος. ἐκ δέ νυ κείνων<br>δενδρέων, οἷαι ἔσαν, τοῖαι πάλιν ἔμπεδον αὔτως<br>ἐξέφανεν, θάμβος περιώσιον, ἔκφατο δ’ Αἴγλη<br>μειλιχίοις ἐπέεσσιν ἀμειβομένη χατέοντας·", "st": "4.1422"}, {"sp": "N", "t": "“ἦ ἄρα δὴ μέγα πάμπαν ἐφ’ ὑμετέροισιν ὄνειαρ<br>δεῦρ’ ἔμολεν καμάτοισιν ὁ κύντατος, ὅστις ἀπούρας<br>φρουρὸν ὄφιν ζωῆς παγχρύσεα μῆλα θεάων<br>οἴχετ’ ἀειράμενος· στυγερὸν δ’ ἄχος ἄμμι λέλειπται.<br>ἤλυθε γὰρ χθιζός τις ἀνὴρ ὀλοώτατος ὕβριν<br>καὶ δέμας· ὄσσε δέ οἱ βλοσυρῷ ὑπέλαμπε μετώπῳ·<br>νηλής· ἀμφὶ δὲ δέρμα πελωρίου ἕστο λέοντος<br>ὠμόν, ἀδέψητον· στιβαρὸν δ’ ἔχεν ὄζον ἐλαίης<br>τόξα τε, τοῖσι πέλωρ τόδ’ ἀπέφθισεν ἰοβολήσας.<br>ἤλυθε δ’ οὖν κἀκεῖνος, ἅ τε χθόνα πεζὸς ὁδεύων,<br>δίψῃ καρχαλέος· παίφασσε δὲ τόνδ’ ἀνὰ χῶρον,<br>ὕδωρ ἐξερέων, τὸ μὲν οὔ ποθι μέλλεν ἰδέσθαι.<br>ἥδε δέ τις πέτρη Τριτωνίδος ἐγγύθι λίμνης·<br>τὴν ὅγ’ ἐπιφρασθείς, ἢ καὶ θεοῦ ἐννεσίῃσιν,<br>λὰξ ποδὶ τύψεν ἔνερθε· τὸ δ’ ἀθρόον ἔβλυσεν ὕδωρ.<br>αὐτὰρ ὅγ’ ἄμφω χεῖρε πέδῳ καὶ στέρνον ἐρείσας<br>ῥωγάδος ἐκ πέτρης πίεν ἄσπετον, ὄφρα βαθεῖαν<br>νηδύν, φορβάδι ἶσος ἐπιπροπεσών, ἐκορέσθη.”", "st": "4.1432"}, {"sp": "N", "t": "ὧς φάτο· τοὶ δ’ ἀσπαστὸν ἵνα σφίσι πέφραδεν Αἴγλη<br>πίδακα, τῇ θέον αἶψα κεχαρμένοι, ὄφρ’ ἐπέκυρσαν.<br>ὡς δ’ ὁπότε στεινὴν περὶ χηραμὸν εἱλίσσονται<br>γειομόροι μύρμηκες ὁμιλαδόν, ἢ ὅτε μυῖαι<br>ἀμφ’ ὀλίγην μέλιτος γλυκεροῦ λίβα πεπτηυῖαι<br>ἄπλητον μεμάασιν ἐπήτριμοι· ὧς τότ’ ἀολλεῖς<br>πετραίῃ Μινύαι περὶ πίδακι δινεύεσκον.<br>καί πού τις διεροῖς ἐπὶ χείλεσιν εἶπεν ἰανθείς·", "st": "4.1450"}, {"sp": "N", "t": "“ὦ πόποι, ἦ καὶ νόσφιν ἐὼν ἐσάωσεν ἑταίρους<br>Ἡρακλέης δίψῃ κεκμηότας. ἀλλά μιν εἴ πως<br>δήοιμεν στείχοντα δι’ ἠπείροιο κιόντες.”", "st": "4.1458"}, {"sp": "N", "t": "ἦ, καὶ ἀμειβομένων, οἵ τ’ ἄρμενοι ἐς τόδε ἔργον,<br>ἔκριθεν ἄλλυδις ἄλλος ἐπαΐξας ἐρεείνειν.<br>ἴχνια γὰρ νυχίοισιν ἐπηλίνδητ’ ἀνέμοισιν<br>κινυμένης ἀμάθου. Βορέαο μὲν ὡρμήθησαν<br>υἷε δύω, πτερύγεσσι πεποιθότε. ποσσὶ δὲ κούφοις<br>Εὔφημος πίσυνος, Λυγκεύς γε μὲν ὀξέα τηλοῦ<br>ὄσσε βαλεῖν· πέμπτος δὲ μετὰ σφίσιν ἔσσυτο Κάνθος.<br>τὸν μὲν ἄρ’ αἶσα θεῶν κείνην ὁδὸν ἠνορέη τε<br>ὦρσεν, ἵν’ Ἡρακλῆος ἀπηλεγέως πεπύθοιτο,<br>Εἰλατίδην Πολύφημον ὅπῃ λίπε· μέμβλετο γάρ οἱ<br>οὗ ἕθεν ἀμφ’ ἑτάροιο μεταλλῆσαι τὰ ἕκαστα.<br>ἀλλ’ ὁ μὲν οὖν Μυσοῖσιν ἐπικλεὲς ἄστυ πολίσσας<br>νόστου κηδοσύνῃσιν ἔβη διζήμενος Ἀργὼ<br>τῆλε δι’ ἠπείροιο· τέως δ’ ἐξίκετο γαῖαν<br>ἀγχιάλων Χαλύβων· τόθι μιν καὶ Μοῖρ’ ἐδάμασσεν.<br>καί οἱ ὑπὸ βλωθρὴν ἀχερωίδα σῆμα τέτυκται<br>τυτθὸν ἁλὸς προπάροιθεν. ἀτὰρ τότε γ’ Ἡρακλῆα<br>μοῦνον ἀπειρεσίης τηλοῦ χθονὸς εἴσατο Λυγκεὺς<br>τὼς ἰδέειν, ὥς τίς τε νέῳ ἐνὶ ἤματι μήνην<br>ἢ ἴδεν, ἢ ἐδόκησεν ἐπαχλύουσαν ἰδέσθαι.<br>ἐς δ’ ἑτάρους ἀνιὼν μυθήσατο, μή μιν ἔτ’ ἄλλον<br>μαστῆρα στείχοντα κιχησέμεν· οἱ δὲ καὶ αὐτοὶ<br>ἤλυθον, Εὔφημός τε πόδας ταχὺς υἷέ τε δοιὼ<br>Θρηικίου Βορέω, μεταμώνια μοχθήσαντε.", "st": "4.1461"}, {"sp": "N", "t": "Κάνθε, σὲ δ’ οὐλόμεναι Λιβύῃ ἔνι Κῆρες ἕλοντο.<br>πώεσι φερβομένοισι συνήντεες· εἵπετο δ’ ἀνὴρ<br>αὐλίτης, ὅ σ’ ἑῶν μήλων πέρι, τόφρ’ ἑτάροισιν<br>δευομένοις κομίσειας, ἀλεξόμενος κατέπεφνεν<br>λᾶι βαλών· ἐπεὶ οὐ μὲν ἀφαυρότερός γ’ ἐτέτυκτο,<br>υἱωνὸς Φοίβοιο Λυκωρείοιο Κάφαυρος<br>κούρης τ’ αἰδοίης Ἀκακαλλίδος, ἥν ποτε Μίνως<br>ἐς Λιβύην ἀπένασσε θεοῦ βαρὺ κῦμα φέρουσαν,<br>θυγατέρα σφετέρην· ἡ δ’ ἀγλαὸν υἱέα Φοίβῳ<br>τίκτεν, ὃν Ἀμφίθεμιν Γαράμαντά τε κικλήσκουσιν.<br>Ἀμφίθεμις δ’ ἄρ’ ἔπειτα μίγη Τριτωνίδι νύμφῃ·<br>ἡ δ’ ἄρα οἱ Νασάμωνα τέκεν κρατερόν τε Κάφαυρον,<br>ὃς τότε Κάνθον ἔπεφνεν ἐπὶ ῥήνεσσιν ἑοῖσιν.<br>οὐδ’ ὅγ’ ἀριστήων χαλεπὰς ἠλεύατο χεῖρας,<br>ὡς μάθον οἷον ἔρεξε. νέκυν δ’ ἀνάειραν ὀπίσσω<br>πευθόμενοι Μινύαι, γαίῃ δ’ ἐνὶ ταρχύσαντο<br>μυρόμενοι· τὰ δὲ μῆλα μετὰ σφέας οἵγ’ ἐκόμισσαν.", "st": "4.1485"}, {"sp": "N", "t": "ἔνθα καὶ Ἀμπυκίδην αὐτῷ ἐνὶ ἤματι Μόψον<br>νηλειὴς ἕλε πότμος· ἀδευκέα δ’ οὐ φύγεν αἶσαν<br>μαντοσύναις· οὐ γάρ τις ἀποτροπίη θανάτοιο.<br>κεῖτο δ’ ἐπὶ ψαμάθοισι μεσημβρινὸν ἦμαρ ἀλύσκων<br>δεινὸς ὄφις, νωθὴς μὲν ἑκὼν ἀέκοντα χαλέψαι·<br>οὐδ’ ἂν ὑποτρέσσαντος ἐνωπαδὶς ἀίξειεν.<br>ἀλλὰ μὲν ᾧ τὰ πρῶτα μελάγχιμον ἰὸν ἐνείη<br>ζωόντων, ὅσα γαῖα φερέσβιος ἔμπνοα βόσκει,<br>οὐδ’ ὁπόσον πήχυιον ἐς Ἄιδα γίγνεται οἶμος,<br>οὐδ’ εἰ Παιήων, εἴ μοι θέμις ἀμφαδὸν εἰπεῖν,<br>φαρμάσσοι, ὅτε μοῦνον ἐνιχρίμψῃσιν ὀδοῦσιν.<br>εὖτε γὰρ ἰσόθεος Λιβύην ὑπερέπτατο Περσεὺς<br>Εὐρυμέδων—καὶ γὰρ τὸ κάλεσκέ μιν οὔνομα μήτηρ—<br>Γοργόνος ἀρτίτομον κεφαλὴν βασιλῆι κομίζων,<br>ὅσσαι κυανέου στάγες αἵματος οὖδας ἵκοντο,<br>αἱ πᾶσαι κείνων ὀφίων γένος ἐβλάστησαν.<br>τῷ δ’ ἄκρην ἐπ’ ἄκανθαν ἐνεστηρίξατο Μόψος<br>λαιὸν ἐπιπροφέρων ταρσὸν ποδός· αὐτὰρ ὁ μέσσην<br>κερκίδα καὶ μυῶνα, πέριξ ὀδύνῃσιν ἑλιχθείς,<br>σάρκα δακὼν ἐχάραξεν. ἀτὰρ Μήδεια καὶ ἄλλαι<br>ἔτρεσαν ἀμφίπολοι· ὁ δὲ φοίνιον ἕλκος ἄφασσεν<br>θαρσαλέως, ἕνεκ’ οὔ μιν ὑπέρβιον ἄλγος ἔτειρεν.<br>σχέτλιος· ἦ τέ οἱ ἤδη ὑπὸ χροῒ δύετο κῶμα<br>λυσιμελές, πολλὴ δὲ κατ’ ὀφθαλμῶν χέετ’ ἀχλύς.<br>αὐτίκα δὲ κλίνας δαπέδῳ βεβαρηότα γυῖα<br>ψύχετ’ ἀμηχανίῃ· ἕταροι δέ μιν ἀμφαγέροντο<br>ἥρως τ’ Αἰσονίδης, ἀδινῇ περιθαμβέες ἄτῃ.<br>οὐδὲ μὲν οὐδ’ ἐπὶ τυτθὸν ἀποφθίμενός περ ἔμελλεν<br>κεῖσθαι ὑπ’ ἠελίῳ. πύθεσκε γὰρ ἔνδοθι σάρκας<br>ἰὸς ἄφαρ, μυδόωσα δ’ ἀπὸ χροὸς ἔρρεε λάχνη.<br>αἶψα δὲ χαλκείῃσι βαθὺν τάφον ἐξελάχαινον<br>ἐσσυμένως μακέλῃσιν· ἐμοιρήσαντο δὲ χαίτας<br>αὐτοὶ ὁμῶς κοῦραί τε, νέκυν ἐλεεινὰ παθόντα<br>μυρόμενοι· τρὶς δ’ ἀμφὶ σὺν ἔντεσι δινηθέντες<br>εὖ κτερέων ἴσχοντα, χυτὴν ἐπὶ γαῖαν ἔθεντο.", "st": "4.1502"}, {"sp": "N", "t": "ἀλλ’ ὅτε δή ῥ’ ἐπὶ νηὸς ἔβαν, πρήσοντος ἀήτεω<br>ἂμ πέλαγος νοτίοιο, πόρους τ’ ἀπετεκμήραντο<br>λίμνης ἐκπρομολεῖν Τριτωνίδος, οὔτινα μῆτιν<br>δὴν ἔχον, ἀφραδέως δὲ πανημέριοι φορέοντο.<br>ὡς δὲ δράκων σκολιὴν εἱλιγμένος ἔρχεται οἶμον,<br>εὖτέ μιν ὀξύτατον θάλπει σέλας ἠελίοιο·<br>ῥοίζῳ δ’ ἔνθα καὶ ἔνθα κάρη στρέφει, ἐν δέ οἱ ὄσσε<br>σπινθαρύγεσσι πυρὸς ἐναλίγκια μαιμώοντι<br>λάμπεται, ὄφρα μυχόνδε διὰ ῥωχμοῖο δύηται·<br>ὧς Ἀργὼ λίμνης στόμα ναύπορον ἐξερέουσα<br>ἀμφεπόλει δηναιὸν ἐπὶ χρόνον. αὐτίκα δ’ Ὀρφεὺς<br>κέκλετ’ Ἀπόλλωνος τρίποδα μέγαν ἔκτοθι νηὸς<br>δαίμοσιν ἐγγενέταις νόστῳ ἔπι μείλια θέσθαι.<br>καὶ τοὶ μὲν Φοίβου κτέρας ἵδρυον ἐν χθονὶ βάντες·<br>τοῖσιν δ’ αἰζηῷ ἐναλίγκιος ἀντεβόλησεν<br>Τρίτων εὐρυβίης, γαίης δ’ ἀνὰ βῶλον ἀείρας<br>ξείνι’ ἀριστήεσσι προΐσχετο, φώνησέν τε·", "st": "4.1537"}, {"sp": "N", "t": "“Δέχθε, φίλοι· ἐπεὶ οὐ περιώσιον ἐγγυαλίξαι<br>ἐνθάδε νῦν πάρ’ ἐμοὶ ξεινήιον ἀντομένοισιν.<br>εἰ δέ τι τῆσδε πόρους μαίεσθ’ ἁλός, οἷά τε πολλὰ<br>ἄνθρωποι χατέουσιν ἐπ’ ἀλλοδαπῇ περόωντες,<br>ἐξερέω. δὴ γάρ με πατὴρ ἐπιίστορα πόντου<br>θῆκε Ποσειδάων τοῦδ’ ἔμμεναι. αὐτὰρ ἀνάσσω<br>παρραλίης, εἰ δή τιν’ ἀκούετε νόσφιν ἐόντες<br>Εὐρύπυλον Λιβύῃ θηροτρόφῳ ἐγγεγαῶτα.”", "st": "4.1554"}, {"sp": "N", "t": "ὧς ηὔδα· πρόφρων δ’ ὑπερέσχεθε βώλακι χεῖρας<br>Εὔφημος, καὶ τοῖα παραβλήδην προσέειπεν·", "st": "4.1562"}, {"sp": "N", "t": "“Ἀπίδα καὶ πέλαγος Μινώιον εἴ νύ που, ἥρως,<br>ἐξεδάης, νημερτὲς ἀνειρομένοισιν ἔνισπε.<br>δεῦρο γὰρ οὐκ ἐθέλοντες ἱκάνομεν, ἀλλὰ βαρείαις<br>χρίμψαντες γαίης ἐπὶ πείρασι τῆσδε θυέλλαις<br>νῆα μεταχρονίην ἐκομίσσαμεν ἐς τόδε λίμνης<br>χεῦμα δι’ ἠπείρου βεβαρημένοι· οὐδέ τι ἴδμεν,<br>πῇ πλόος ἐξανέχει Πελοπηίδα γαῖαν ἱκέσθαι.”", "st": "4.1564"}, {"sp": "N", "t": "ὧς ἄρ’ ἔφη· ὁ δὲ χεῖρα τανύσσατο, δεῖξε δ’ ἄπωθεν<br>φωνήσας πόντον τε καὶ ἀγχιβαθὲς στόμα λίμνης·<br>“κείνη μὲν πόντοιο διήλυσις, ἔνθα μάλιστα<br>βένθος ἀκίνητον μελανεῖ· ἑκάτερθε δὲ λευκαὶ<br>ῥηγμῖνες φρίσσουσι διαυγέες· ἡ δὲ μεσηγὺ<br>ῥηγμίνων στεινὴ τελέθει ὁδὸς ἐκτὸς ἐλάσσαι.<br>κεῖνο δ’ ὑπηέριον θείην Πελοπηίδα γαῖαν<br>εἰσανέχει πέλαγος Κρήτης ὕπερ· ἀλλ’ ἐπὶ χειρὸς<br>δεξιτερῆς, λίμνηθεν ὅτ’ εἰς ἁλὸς οἶδμα βάλητε,<br>τόφρ’ αὐτὴν παρὰ χέρσον ἐεργμένοι ἰθύνεσθε,<br>ἔστ’ ἂν ἄνω τείνῃσι· περιρρήδην δ’ ἑτέρωσε<br>κλινομένης χέρσοιο, τότε πλόος ὔμμιν ἀπήμων<br>ἀγκῶνος τέτατ’ ἰθὺς ἀπὸ προύχοντος ἰοῦσιν.<br>ἀλλ’ ἴτε γηθόσυνοι, καμάτοιο δὲ μήτις ἀνίη<br>γιγνέσθω, νεότητι κεκασμένα γυῖα μογῆσαι.”", "st": "4.1571"}, {"sp": "N", "t": "Ἴσκεν ἐυφρονέων· οἱ δ’ αἶψ’ ἐπὶ νηὸς ἔβησαν<br>λίμνης ἐκπρομολεῖν λελιημένοι εἰρεσίῃσιν.<br>καὶ δὴ ἐπιπρονέοντο μεμαότες· αὐτὰρ ὁ τείως<br>Τρίτων ἀνθέμενος τρίποδα μέγαν, εἴσατο λίμνην<br>εἰσβαίνειν· μετὰ δ’ οὔτις ἐσέδρακεν, οἷον ἄφαντος<br>αὐτῷ σὺν τρίποδι σχεδὸν ἔπλετο. τοῖσι δ’ ἰάνθη<br>θυμός, ὃ δὴ μακάρων τις ἐναίσιμος ἀντεβόλησεν.<br>καί ῥά οἱ Αἰσονίδην μήλων ὅ τι φέρτατον ἄλλων<br>ἤνωγον ῥέξαι καὶ ἐπευφημῆσαι ἑλόντα.<br>αἶψα δ’ ὅγ’ ἐσσυμένως ἐκρίνατο, καί μιν ἀείρας<br>σφάξε κατὰ πρύμνης, ἐπὶ δ’ ἔννεπεν εὐχωλῇσιν·", "st": "4.1586"}, {"sp": "N", "t": "“δαῖμον, ὅτις λίμνης ἐπὶ πείρασι τῆσδ’ ἐφαάνθης,<br>εἴτε σέγε Τρίτων’, ἅλιον τέρας, εἴτε σε Φόρκυν,<br>ἢ Νηρῆα θύγατρες ἐπικλείουσ’ ἁλοσύδναι,<br>ἵλαθι, καὶ νόστοιο τέλος θυμηδὲς ὄπαζε.”", "st": "4.1597"}, {"sp": "N", "t": "ἦ ῥ’, ἅμα δ’ εὐχωλῇσιν ἐς ὕδατα λαιμοτομήσας<br>ἧκε κατὰ πρύμνης· ὁ δὲ βένθεος ἐξεφαάνθη<br>τοῖος ἐών, οἷός περ ἐτήτυμος ἦεν ἰδέσθαι.<br>ὡς δ’ ὅτ’ ἀνὴρ θοὸν ἵππον ἐς εὐρέα κύκλον ἀγῶνος<br>στέλλῃ, ὀρεξάμενος λασίης εὐπειθέα χαίτης,<br>εἶθαρ ἐπιτροχάων, ὁ δ’ ἐπ’ αὐχένι γαῦρος ἀερθεὶς<br>ἕσπεται, ἀργινόεντα δ’ ἐνὶ στομάτεσσι χαλινὰ<br>ἀμφὶς ὀδακτάζοντι παραβλήδην κροτέονται·<br>ὧς ὅγ’ ἐπισχόμενος γλαφυρῆς ὁλκήιον Ἀργοῦς<br>ἦγ’ ἅλαδε προτέρωσε. δέμας δέ οἱ ἐξ ὑπάτοιο<br>κράατος, ἀμφί τε νῶτα καὶ ἰξύας ἔστ’ ἐπὶ νηδὺν<br>ἀντικρὺ μακάρεσσι φυὴν ἔκπαγλον ἔικτο·<br>αὐτὰρ ὑπαὶ λαγόνων δίκραιρά οἱ ἔνθα καὶ ἔνθα<br>κήτεος ὁλκαίη μηκύνετο· κόπτε δ’ ἀκάνθαις<br>ἄκρον ὕδωρ, αἵ τε σκολιοῖς ἐπινειόθι κέντροις<br>μήνης ὡς κεράεσσιν ἐειδόμεναι διχόωντο.<br>τόφρα δ’ ἄγεν, τείως μιν ἐπιπροέηκε θαλάσσῃ<br>νισσομένην· δῦ δ’ αἶψα μέγαν βυθόν· οἱ δ’ ὁμάδησαν<br>ἥρωες, τέρας αἰνὸν ἐν ὀφθαλμοῖσιν ἰδόντες.<br>ἔνθα μὲν Ἀργῷός τε λιμὴν καὶ σήματα νηὸς<br>ἠδὲ Ποσειδάωνος ἰδὲ Τρίτωνος ἔασιν<br>βωμοί· ἐπεὶ κεῖν’ ἦμαρ ἐπέσχεθον. αὐτὰρ ἐς ἠῶ<br>λαίφεσι πεπταμένοις αὐτὴν ἐπὶ δεξί’ ἔχοντες<br>γαῖαν ἐρημαίην, πνοιῇ ζεφύροιο θέεσκον.<br>ἦρι δ’ ἔπειτ’ ἀγκῶνά θ’ ὁμοῦ μυχάτην τε θάλασσαν<br>κεκλιμένην ἀγκῶνος ὕπερ προύχοντος ἴδοντο.<br>αὐτίκα δὲ ζέφυρος μὲν ἐλώφεεν, ἤλυθε δ’ αὔρη<br>ἀργέσταο νότου· κεχάροντο δὲ θυμὸν ἰωῇ.<br>ἦμος δ’ ἠέλιος μὲν ἔδυ, ἀνὰ δ’ ἤλυθεν ἀστὴρ<br>αὔλιος, ὅς τ’ ἀνέπαυσεν ὀιζυροὺς ἀροτῆρας,<br>δὴ τότ’ ἔπειτ’ ἀνέμοιο κελαινῇ νυκτὶ λιπόντος<br>ἱστία λυσάμενοι περιμήκεά τε κλίναντες<br>ἱστόν, ἐυξέστῃσιν ἐπερρώοντ’ ἐλάτῃσιν<br>παννύχιοι καὶ ἐπ’ ἦμαρ, ἐπ’ ἤματι δ’ αὖτις ἰοῦσαν<br>νύχθ’ ἑτέρην. ὑπέδεκτο δ’ ἀπόπροθι παιπαλόεσσα<br>Κάρπαθος· ἔνθεν δ’ οἵγε περαιώσεσθαι ἔμελλον<br>Κρήτην, ἥ τ’ ἄλλων ὑπερέπλετο εἰν ἁλὶ νήσων.", "st": "4.1601"}, {"sp": "N", "t": "τοὺς δὲ Τάλως χάλκειος, ἀπὸ στιβαροῦ σκοπέλοιο<br>ῥηγνύμενος πέτρας, εἶργε χθονὶ πείσματ’ ἀνάψαι,<br>Δικταίην ὅρμοιο κατερχομένους ἐπιωγήν·<br>τὸν μὲν χαλκείης μελιηγενέων ἀνθρώπων<br>ῥίζης λοιπὸν ἐόντα μετ’ ἀνδράσιν ἡμιθέοισιν<br>Εὐρώπῃ Κρονίδης νήσου πόρεν ἔμμεναι οὖρον,<br>τρὶς περὶ χαλκείοις Κρήτην ποσὶ δινεύοντα.<br>ἀλλ’ ἤτοι τὸ μὲν ἄλλο δέμας καὶ γυῖα τέτυκτο<br>χάλκεος ἠδ’ ἄρρηκτος· ὑπαὶ δέ οἱ ἔσκε τένοντος<br>σύριγξ αἱματόεσσα κατὰ σφυρόν· αὐτὰρ ὅ τ’ ἦγχε<br>λεπτὸς ὑμὴν ζωῆς ἔχε πείρατα καὶ θανάτοιο.<br>οἱ δέ, δύῃ μάλα περ δεδμημένοι, αἶψ’ ἀπὸ χέρσου<br>νῆα περιδδείσαντες ἀνακρούεσκον ἐρετμοῖς.<br>καί νύ κ’ ἐπισμυγερῶς Κρήτης ἑκὰς ἠέρθησαν,<br>ἀμφότερον δίψῃ τε καὶ ἄλγεσι μοχθίζοντες,<br>εἰ μή σφιν Μήδεια λιαζομένοις ἀγόρευσεν·", "st": "4.1638"}, {"sp": "N", "t": "“κέκλυτέ μευ. μούνη γὰρ ὀίομαι ὔμμι δαμάσσειν<br>ἄνδρα τόν, ὅστις ὅδ’ ἐστί, καὶ εἰ παγχάλκεον ἴσχει<br>ὃν δέμας, ὁππότε μή οἱ ἐπ’ ἀκάματος πέλοι αἰών.<br>ἀλλ’ ἔχετ’ αὐτοῦ νῆα θελήμονες ἐκτὸς ἐρωῆς<br>πετράων, εἵως κεν ἐμοὶ εἴξειε δαμῆναι.”", "st": "4.1654"}, {"sp": "N", "t": "ὧς ἄρ’ ἔφη· καὶ τοὶ μὲν ὑπὲκ βελέων ἐρύσαντο<br>νῆ’ ἐπ’ ἐρετμοῖσιν, δεδοκημένοι ἥντινα ῥέξει<br>μῆτιν ἀνωίστως· ἡ δὲ πτύχα πορφυρέοιο<br>προσχομένη πέπλοιο παρειάων ἑκάτερθεν<br>βήσατ’ ἐπ’ ἰκριόφιν· χειρὸς δέ ἑ χειρὶ μεμαρπὼς<br>Αἰσονίδης ἐκόμιζε διὰ κληῖδας ἰοῦσαν.<br>ἔνθα δ’ ἀοιδῇσιν μειλίσσετο, μέλπε δὲ Κῆρας<br>θυμοβόρους, Ἀίδαο θοὰς κύνας, αἳ περὶ πᾶσαν<br>ἠέρα δινεύουσαι ἐπὶ ζωοῖσιν ἄγονται.<br>τὰς γουναζομένη τρὶς μὲν παρεκέκλετ’ ἀοιδαῖς,<br>τρὶς δὲ λιταῖς· θεμένη δὲ κακὸν νόον, ἐχθοδοποῖσιν<br>ὄμμασι χαλκείοιο Τάλω ἐμέγηρεν ὀπωπάς·<br>λευγαλέον δ’ ἐπί οἱ πρῖεν χόλον, ἐκ δ’ ἀίδηλα<br>δείκηλα προΐαλλεν, ἐπιζάφελον κοτέουσα.", "st": "4.1659"}, {"sp": "N", "t": "Ζεῦ πάτερ, ἦ μέγα δή μοι ἐνὶ φρεσὶ θάμβος ἄηται,<br>εἰ δὴ μὴ νούσοισι τυπῇσί τε μοῦνον ὄλεθρος<br>ἀντιάει, καὶ δή τις ἀπόπροθεν ἄμμε χαλέπτει.<br>ὧς ὅγε χάλκειός περ ἐὼν ὑπόειξε δαμῆναι<br>Μηδείης βρίμῃ πολυφαρμάκου. ἂν δὲ βαρείας<br>ὀχλίζων λάιγγας, ἐρυκέμεν ὅρμον ἱκέσθαι.<br>πετραίῳ στόνυχι χρίμψε σφυρόν· ἐκ δέ οἱ ἰχὼρ<br>τηκομένῳ ἴκελος μολίβῳ ῥέεν· οὐδ’ ἔτι δηρὸν<br>εἱστήκει προβλῆτος ἐπεμβεβαὼς σκοπέλοιο.<br>ἀλλ’ ὥς τίς τ’ ἐν ὄρεσσι πελωρίη ὑψόθι πεύκη,<br>τήν τε θοοῖς πελέκεσσιν ἔθ’ ἡμιπλῆγα λιπόντες<br>ὑλοτόμοι δρυμοῖο κατήλυθον· ἡ δ’ ὑπὸ νυκτὶ<br>ῥιπῇσιν μὲν πρῶτα τινάσσεται, ὕστερον αὖτε<br>πρυμνόθεν ἐξαγεῖσα κατήριπεν· ὧς ὅγε ποσσὶν<br>ἀκαμάτοις τείως μὲν ἐπισταδὸν ᾐωρεῖτο,<br>ὕστερον αὖτ’ ἀμενηνὸς ἀπείρονι κάππεσε δούπῳ.<br>κεῖνο μὲν οὖν Κρήτῃ ἐνὶ δὴ κνέφας ηὐλίζοντο<br>ἥρωες· μετὰ δ’ οἵγε νέον φαέθουσαν ἐς ἠῶ<br>ἱρὸν Ἀθηναίης Μινωίδος ἱδρύσαντο,<br>ὕδωρ τ’ εἰσαφύσαντο καὶ εἰσέβαν, ὥς κεν ἐρετμοῖς<br>παμπρώτιστα βάλοιεν ὑπὲρ Σαλμωνίδος ἄκρης.", "st": "4.1673"}, {"sp": "N", "t": "Αὐτίκα δὲ Κρηταῖον ὑπὲρ μέγα λαῖτμα θέοντας<br>νὺξ ἐφόβει, τήνπερ τε κατουλάδα κικλήσκουσιν·<br>νύκτ’ ὀλοὴν οὐκ ἄστρα διίσχανεν, οὐκ ἀμαρυγαὶ<br>μήνης· οὐρανόθεν δὲ μέλαν χάος, ἠέ τις ἄλλη<br>ὠρώρει σκοτίη μυχάτων ἀνιοῦσα βερέθρων.<br>αὐτοὶ δ’, εἴτ’ Ἀίδῃ, εἴθ’ ὕδασιν ἐμφορέοντο,<br>ἠείδειν οὐδ’ ὅσσον· ἐπέτρεψαν δὲ θαλάσσῃ<br>νόστον, ἀμηχανέοντες, ὅπῃ φέροι. αὐτὰρ Ἰήσων<br>χεῖρας ἀνασχόμενος μεγάλῃ ὀπὶ Φοῖβον ἀύτει,<br>ῥύσασθαι καλέων· κατὰ δ’ ἔρρεεν ἀσχαλόωντι<br>δάκρυα· πολλὰ δὲ Πυθοῖ ὑπέσχετο, πολλὰ δ’ Ἀμύκλαις,<br>πολλὰ δ’ ἐς Ὀρτυγίην ἀπερείσια δῶρα κομίσσειν.<br>Λητοΐδη, τύνη δὲ κατ’ οὐρανοῦ ἵκεο πέτρας<br>ῥίμφα Μελαντίους ἀριήκοος, αἵ τ’ ἐνὶ πόντῳ<br>ἧνται· δοιάων δὲ μιῆς ἐφύπερθεν ὀρούσας,<br>δεξιτερῇ χρύσειον ἀνέσχεθες ὑψόθι τόξον·<br>μαρμαρέην δ’ ἀπέλαμψε βιὸς περὶ πάντοθεν αἴγλην.<br>τοῖσι δέ τις Σποράδων βαιὴ ἀπὸ τόφρ’ ἐφαάνθη<br>νῆσος ἰδεῖν, ὀλίγης Ἱππουρίδος ἀντία νήσου,<br>ἔνθ’ εὐνὰς ἐβάλοντο καὶ ἔσχεθον· αὐτίκα δ’ Ἠὼς<br>φέγγεν ἀνερχομένη· τοὶ δ’ ἀγλαὸν Ἀπόλλωνι<br>ἄλσει ἐνὶ σκιερῷ τέμενος σκιόεντά τε βωμὸν<br>ποίεον, Αἰγλήτην μὲν ἐυσκόπου εἵνεκεν αἴγλης<br>Φοῖβον κεκλόμενοι· Ἀνάφην δέ τε λισσάδα νῆσον<br>ἴσκον, ὃ δὴ Φοῖβός μιν ἀτυζομένοις ἀνέφηνεν.<br>ῥέζον δ’ ὅσσα περ ἄνδρες ἐρημαίῃ ἐνὶ ῥέζειν<br>ἀκτῇ ἐφοπλίσσειαν· ὃ δή σφεας ὁππότε δαλοῖς<br>ὕδωρ αἰθομένοισιν ἐπιλλείβοντας ἴδοντο<br>Μηδείης δμωαὶ Φαιηκίδες, οὐκέτ’ ἔπειτα<br>ἴσχειν ἐν στήθεσσι γέλω σθένον, οἷα θαμειὰς<br>αἰὲν ἐν Ἀλκινόοιο βοοκτασίας ὁρόωσαι.<br>τὰς δ’ αἰσχροῖς ἥρωες ἐπεστοβέεσκον ἔπεσσιν<br>χλεύῃ γηθόσυνοι· γλυκερὴ δ’ ἀνεδαίετο τοῖσιν<br>κερτομίη καὶ νεῖκος ἐπεσβόλον. ἐκ δέ νυ κείνης<br>μολπῆς ἡρώων νήσῳ ἔνι τοῖα γυναῖκες<br>ἀνδράσι δηριόωνται, ὅτ’ Ἀπόλλωνα θυηλαῖς<br>Αἰγλήτην Ἀνάφης τιμήορον ἱλάσκωνται.", "st": "4.1694"}, {"sp": "N", "t": "ἀλλ’ ὅτε δὴ κἀκεῖθεν ὑπεύδια πείσματ’ ἔλυσαν,<br>μνήσατ’ ἔπειτ’ Εὔφημος ὀνείρατος ἐννυχίοιο,<br>ἁζόμενος Μαίης υἷα κλυτόν. εἴσατο γάρ οἱ<br>δαιμονίη βῶλαξ ἐπιμάστιος ᾧ ἐν ἀγοστῷ<br>ἄρδεσθαι λευκῇσιν ὑπαὶ λιβάδεσσι γάλακτος,<br>ἐκ δὲ γυνὴ βώλοιο πέλειν ὀλίγης περ ἐούσης<br>παρθενικῇ ἰκέλη· μίχθη δέ οἱ ἐν φιλότητι<br>ἄσχετον ἱμερθείς· ὀλοφύρετο δ’ ἠύτε κούρην<br>ζευξάμενος, τήν τ’ αὐτὸς ἑῷ ἀτίταλλε γάλακτι·<br>ἡ δέ ἑ μειλιχίοισι παρηγορέεσκ’ ἐπέεσσιν·", "st": "4.1731"}, {"sp": "N", "t": "“Τρίτωνος γένος εἰμί, τεῶν τροφός, ὦ φίλε, παίδων,<br>οὐ κούρη· Τρίτων γὰρ ἐμοὶ Λιβύη τε τοκῆες.<br>ἀλλά με Νηρῆος παρακάτθεο παρθενικῇσιν<br>ἂμ πέλαγος ναίειν Ἀνάφης σχεδόν· εἶμι δ’ ἐς αὐγὰς<br>ἠελίου μετόπισθε, τεοῖς νεπόδεσσιν ἑτοίμη.”", "st": "4.1741"}, {"sp": "N", "t": "τῷ δ’ ἄρ’ ἐπὶ μνῆστιν κραδίη βάλεν, ἔκ τ’ ὀνόμηνεν<br>Αἰσονίδῃ· ὁ δ’ ἔπειτα θεοπροπίας Ἑκάτοιο<br>θυμῷ πεμπάζων ἀνενείκατο φώνησέν τε·", "st": "4.1746"}, {"sp": "N", "t": "“ὦ πέπον, ἦ μέγα δή σε καὶ ἀγλαὸν ἔμμορε κῦδος.<br>βώλακα γὰρ τεύξουσι θεοὶ πόντονδε βαλόντι<br>νῆσον, ἵν’ ὁπλότεροι παίδων σέθεν ἐννάσσονται<br>παῖδες· ἐπεὶ Τρίτων ξεινήιον ἐγγυάλιξεν<br>τήνδε τοι ἠπείροιο Λιβυστίδος. οὔ νύ τις ἄλλος<br>ἀθανάτων, ἢ κεῖνος, ὅ μιν πόρεν ἀντιβολήσας.”", "st": "4.1749"}, {"sp": "N", "t": "ὧς ἔφατ’· οὐδ’ ἁλίωσεν ὑπόκρισιν Αἰσονίδαο<br>Εὔφημος· βῶλον δέ, θεοπροπίῃσιν ἰανθείς,<br>ἧκεν ὑποβρυχίην. τῆς δ’ ἔκτοθι νῆσος ἀέρθη<br>καλλίστη, παίδων ἱερὴ τροφὸς Εὐφήμοιο,<br>οἳ πρὶν μέν ποτε δὴ Σιντηίδα Λῆμνον ἔναιον,<br>Λήμνου τ’ ἐξελαθέντες ὑπ’ ἀνδράσι Τυρσηνοῖσιν<br>Σπάρτην εἰσαφίκανον ἐφέστιοι· ἐκ δὲ λιπόντας<br>Σπάρτην Αὐτεσίωνος ἐὺς πάις ἤγαγε Θήρας<br>καλλίστην ἐπὶ νῆσον, ἀμείψατο δ’ οὔνομα Θήρης<br>ἐξ ἕθεν. ἀλλὰ τὰ μὲν μετόπιν γένετ’ Εὐφήμοιο.", "st": "4.1755"}, {"sp": "N", "t": "κεῖθεν δ’ ἀπτερέως διὰ μυρίον οἶδμα λιπόντες<br>Αἰγίνης ἀκτῇσιν ἐπέσχεθον· αἶψα δὲ τοίγε<br>ὑδρείης πέρι δῆριν ἀμεμφέα δηρίσαντο,<br>ὅς κεν ἀφυσσάμενος φθαίη μετὰ νῆάδ’ ἱκέσθαι.<br>ἄμφω γὰρ χρειώ τε καὶ ἄσπετος οὖρος ἔπειγεν.<br>ἔνθ’ ἔτι νῦν πλήθοντας ἐπωμαδὸν ἀμφιφορῆας<br>ἀνθέμενοι κούφοισιν ἄφαρ κατ’ ἀγῶνα πόδεσσιν<br>κοῦροι Μυρμιδόνων νίκης πέρι δηριόωνται.", "st": "4.1765"}, {"sp": "N", "t": "Ἵλατ’ ἀριστήων μακάρων γένος· αἵδε δ’ ἀοιδαὶ<br>εἰς ἔτος ἐξ ἔτεος γλυκερώτεραι εἶεν ἀείδειν<br>ἀνθρώποις. ἤδη γὰρ ἐπὶ κλυτὰ πείραθ’ ἱκάνω<br>ὑμετέρων καμάτων· ἐπεὶ οὔ νύ τις ὔμμιν ἄεθλος<br>αὖτις ἀπ’ Αἰγίνηθεν ἀνερχομένοισιν ἐτύχθη,<br>οὔτ’ ἀνέμων ἐριῶλαι ἐνέσταθεν· ἀλλὰ ἕκηλοι<br>γαῖαν Κεκροπίην παρά τ’ Αὐλίδα μετρήσαντες<br>Εὐβοίης ἔντοσθεν Ὀπούντιά τ’ ἄστεα Λοκρῶν<br>ἀσπασίως ἀκτὰς Παγασηίδας εἰσαπέβητε.", "st": "4.1773"}], []);})();
